# Reward robot for lifting the swing leg during step 
def swing_leg_lift(env: ManagerBasedRLEnv, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg) -> torch.Tensor:
    """
    Reward lifting the thigh on the non-contact leg using current_air_time.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air_time = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]  # [N, 2]
    asset = env.scene[asset_cfg.name]
    joint_names = asset.joint_names
    joint_pos = asset.data.joint_pos  # [N, num_joints]
    left_index = joint_names.index("leg_left_hip_pitch_joint")
    right_index = joint_names.index("leg_right_hip_pitch_joint")
    left_thigh_pitch = joint_pos[:, left_index]
    right_thigh_pitch = joint_pos[:, right_index]
    left_air = (air_time[:, 0] > 0.0).float()
    right_air = (air_time[:, 1] > 0.0).float()
    lift_score = (left_thigh_pitch * left_air) + (right_thigh_pitch * right_air)
    return torch.clamp(lift_score, min=0.0)


# Reward robot for lifting the swing foot a certain height during step
def swing_foot_plant(
    env: ManagerBasedRLEnv,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    contact_hold_threshold: float = 0.1,  # seconds foot should stay planted
    alignment_tolerance: float = 0.1,     # radians for foot placement direction
    max_reward: float = 0.2,
    cmd_scaling_factor: float = 2.0
) -> torch.Tensor:
    """
    Reward the swing foot for planting in the commanded velocity direction and maintaining contact.

    Parameters:
    - contact_hold_threshold: Minimum duration foot must stay planted (s)
    - alignment_tolerance: Tolerance (rad) for foot landing direction alignment
    - max_reward: Cap per foot plant
    - cmd_scaling_factor: Sensitivity to commanded velocity magnitude
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    asset = env.scene[asset_cfg.name]

    # Get air time and contact time for both feet
    air_time = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]    # [N, 2]
    contact_time = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]  # [N, 2]

    # Mask: foot just transitioned from air to contact and holds for threshold
    planted_mask = (contact_time > contact_hold_threshold).float() * (air_time < 0.05).float()

    # Get foot horizontal landing velocities
    foot_velocities = asset.data.body_lin_vel_w[:, sensor_cfg.body_ids, :2]  # [N, 2, xy]

    # Get commanded horizontal velocity direction
    cmd_vel = env.command_manager.get_command("base_velocity")[:, :2]  # [N, 2]
    cmd_vel_mag = torch.norm(cmd_vel, dim=1, keepdim=True)  # [N, 1]
    cmd_dir = cmd_vel / (cmd_vel_mag + 1e-6)  # Normalize to unit vector [N, 2]

    # Foot horizontal velocity direction
    foot_dir = foot_velocities / (foot_velocities.norm(dim=-1, keepdim=True) + 1e-6)  # [N, 2, xy]

    # Dot product to find alignment (-1 = opposite, 1 = aligned)
    alignment = torch.sum(foot_dir * cmd_dir.unsqueeze(1), dim=-1)  # [N, 2]
    alignment_reward = torch.clamp(alignment, min=0.0)  # Reward only positive alignment

    # Combine planted mask and alignment
    plant_reward_per_foot = alignment_reward * planted_mask

    # Command velocity scaling
    cmd_scaling = torch.tanh(cmd_scaling_factor * cmd_vel_mag.squeeze(-1))  # [N]

    # Total reward: sum feet, scale, clamp
    reward = (plant_reward_per_foot.sum(dim=1) * cmd_scaling).clamp(max=max_reward)

    return reward


# Reward robot for for leaning over stance leg 
def lean_over_stance_leg(env: ManagerBasedRLEnv, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg) -> torch.Tensor:
    """
    Reward the agent for keeping its pelvis over the stance foot (when in single support phase).
    Uses `current_air_time` to infer contact states.
    """
    contact_sensor = env.scene.sensors[sensor_cfg.name]
    air_time = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]  # [num_envs, 2]
    # A foot is in contact if air_time is near zero
    contact_states = air_time < 0.05  # small threshold in seconds
    # Retrieve pelvis position and foot positions
    base_pos_w = env.scene[asset_cfg.name].data.root_pos_w[:, :2]
    foot_positions = env.scene[asset_cfg.name].data.body_pos_w[:, sensor_cfg.body_ids, :2]
    # Compute stance foot midpoint (or average if both in contact)
    contact_mask = contact_states
    mask_sum = torch.sum(contact_mask, dim=1, keepdim=True).clamp(min=1.0)
    weighted_avg = torch.sum(foot_positions * contact_mask.unsqueeze(-1), dim=1) / mask_sum
    # Reward pelvis being near the stance foot (leaning over support leg)
    dist = torch.norm(base_pos_w - weighted_avg, dim=1)
    #sharp curve
    #reward = torch.exp(-5.0 * dist**2)
    #standard weighted average
    reward = 1.0 / (1.0 + dist**2)
    return reward


# Reward robot for maintaining a base height
def maintain_base_height(
    env: ManagerBasedRLEnv,
    desired_height: float = 0.40,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    std: float = 0.05
) -> torch.Tensor:
    """
    Reward keeping the robot's pelvis at a desired height.
    Uses a Gaussian kernel centered at `desired_height`.
    """
    asset = env.scene[asset_cfg.name]
    current_height = asset.data.root_pos_w[:, 2]  # height of base in world frame
    #reward = torch.exp(-((current_height - desired_height) ** 2) / (2 * std**2))
    reward = 0.1 + 0.8 * torch.exp(-((current_height - desired_height) ** 2) / (2 * std**2))
    return reward

#=============================
# === Penalty Definitions  ===
#=============================
# predefined l1- penalize ground contact of key bodies
# predefined l1- penalize deviation from default of the joints that are not essential for locomotion
# predefined l1- penalize deviation of ankle roll joints
# predefined l1- penalize moving into a splits position
#==========================
# ===  Reward / Penalty ===
#==========================



# Reward robot for stepping with one foot lifting off (discourage hopping)
def encourage_stepping_not_hopping_refined(
    env,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    lift_threshold: float = 0.5,
    base_single_leg_reward: float = 0.1,
    hop_penalty_scale: float = -1.0,
    scaling_factor: float = 2.0,
) -> torch.Tensor:
    """
    Encourage stepping with one foot lifting off while the other remains grounded.
    Discourage hopping (both feet airborne), but tolerate it at low commanded velocities.

    Parameters:
    - lift_threshold: Base threshold for upward foot velocity (m/s), scaled by env.step_dt
    - base_single_leg_reward: Reward for single-leg stance without active lift
    - hop_penalty_scale: Base penalty applied when both feet are airborne
    - scaling_factor: Multiplier for command velocity magnitude scaling
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    net_forces = contact_sensor.data.net_forces_w_history[:, -1, sensor_cfg.body_ids, :]
    contact_magnitude = net_forces.norm(dim=-1)

    # Flags: 1 if foot is airborne (low contact force), 0 if in contact
    airborne_flags = (contact_magnitude < 1.0).float()
    num_airborne = airborne_flags.sum(dim=1)  # [num_envs]

    # Get vertical velocity of feet
    asset = env.scene[asset_cfg.name]
    vertical_velocities = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, 2]  # [num_envs, feet]

    # Dynamically scale upward lift threshold by step_dt
    dynamic_lift_threshold = lift_threshold * env.step_dt
    upward_lift = (vertical_velocities > dynamic_lift_threshold).float()

    # Reward if exactly one foot airborne and moving upward
    lift_reward = (num_airborne == 1).float() * upward_lift.sum(dim=1)

    # Base reward for single-leg stance (even without lift)
    single_leg_reward = (num_airborne == 1).float() * base_single_leg_reward

    # Penalty for hopping (both feet airborne), scaled by commanded velocity
    cmd_vel = env.command_manager.get_command("base_velocity")[:, :2]  # [num_envs, 2]
    cmd_vel_mag = torch.norm(cmd_vel, dim=1)  # [num_envs]
    scaling = torch.tanh(scaling_factor * cmd_vel_mag)  # scaling ∈ [0,1]
    hop_penalty = (num_airborne == 2).float() * (hop_penalty_scale * scaling)

    # Combine rewards and penalties
    total_reward = scaling * (lift_reward + single_leg_reward) + hop_penalty

    return total_reward

def encourage_foot_alternation(
    env,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    history_len: int = 5,
    penalty_scale: float = 0.05,
    ignore_double_contact: bool = True,
    scaling_factor: float = 8.0,
    max_reward: float = 1.0,
) -> torch.Tensor:
    """
    Encourage alternating foot contacts over time with rolling history.
    Penalize stalling. Scales reward with commanded velocity magnitude.

    Parameters:
    - history_len: Number of timesteps to consider for alternation
    - penalty_scale: Scale of penalty for no alternation
    - ignore_double_contact: Whether to ignore double-stance transitions
    - scaling_factor: Sensitivity to commanded velocity magnitude
    - max_reward: Cap on the total alternation reward
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_history = (
        contact_sensor.data.net_forces_w_history[:, -history_len:, sensor_cfg.body_ids, :].norm(dim=-1) > 1.0
    ).float()  # [N, T, 2]

    # Encode: 0 = none, 1 = left, 2 = right, 3 = both
    contact_codes = contact_history[..., 0] * 1 + contact_history[..., 1] * 2  # [N, T]
    contact_diff = contact_codes[:, 1:] - contact_codes[:, :-1]  # [N, T-1]
    changed = (contact_diff != 0).float()

    if ignore_double_contact:
        valid_mask = ((contact_codes[:, :-1] < 3) & (contact_codes[:, 1:] < 3)).float()
        changed *= valid_mask

    alternation_score = torch.sum(changed, dim=1) / (history_len - 1)
    stall_penalty = torch.sum((contact_diff == 0).float(), dim=1) * penalty_scale

    # Scale reward based on commanded velocity magnitude
    cmd_vel = env.command_manager.get_command("base_velocity")[:, :2]
    cmd_vel_mag = torch.norm(cmd_vel, dim=1)
    cmd_scaling = torch.tanh(cmd_vel_mag * scaling_factor)

    total_reward = (alternation_score - stall_penalty) * cmd_scaling
    return total_reward.clamp(max=max_reward)

def moving_no_support_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.12,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize flight/hopping under clear movement commands.

    v1.4.4 discovered alternation but allowed a high no-support fraction. A
    walking gait should pass through single support while keeping at least one
    foot grounded.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    in_contact = forces.norm(dim=-1).max(dim=1)[0] > force_threshold
    no_support = torch.sum(in_contact.int(), dim=1) == 0
    return no_support * _moving_command_mask(env, command_name, command_threshold)


def moving_swing_clearance_window_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.12,
    max_clearance_m: float = 0.060,
) -> torch.Tensor:
    """Penalize excessive swing height so alternation becomes step-like, not hopping."""
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_time = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    in_contact = contact_time > 0.0
    single_support = torch.sum(in_contact.int(), dim=1) == 1

    asset = env.scene[asset_cfg.name]
    foot_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    stance_z = torch.sum(foot_z * in_contact.float(), dim=1) / torch.clamp(
        torch.sum(in_contact.float(), dim=1), min=1.0
    )
    swing_clearance = torch.relu(foot_z - stance_z.unsqueeze(-1))
    swing_clearance = torch.where(~in_contact, swing_clearance, torch.zeros_like(swing_clearance))
    max_clearance = torch.max(swing_clearance, dim=1)[0]
    penalty = torch.square(torch.relu(max_clearance - max_clearance_m))
    return penalty * single_support * _moving_command_mask(env, command_name, command_threshold)


def moving_knee_flexion_band_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.12,
    lower_rad: float = 0.55,
    upper_rad: float = 1.15,
    std: float = 0.20,
) -> torch.Tensor:
    """Reward a mild athletic knee-flexion band while moving.

    This is intentionally bounded: it gives the policy permission to bend the
    knees for balance and stepping, without paying it to collapse into a deep squat.
    """
    asset: Articulation = env.scene[asset_cfg.name]
    q = asset.data.joint_pos[:, asset_cfg.joint_ids]
    below = torch.relu(lower_rad - q)
    above = torch.relu(q - upper_rad)
    band_error = torch.sum(torch.square(below + above), dim=1)
    reward = torch.exp(-0.5 * band_error / (std * std))
    return reward * _moving_command_mask(env, command_name, command_threshold)


def moving_com_over_stance_foot_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.12,
    force_threshold: float = 1.0,
    std: float = 0.14,
) -> torch.Tensor:
    """Reward shifting the COM over the planted/balance foot during single support.

    This addresses the real-robot observation that the policy tries to balance
    without committing its center of mass over the stance foot. It is command-
    agnostic, so it works for forward/reverse/strafe/diagonal movement.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    in_contact = forces.norm(dim=-1).max(dim=1)[0] > force_threshold
    single_support = torch.sum(in_contact.int(), dim=1) == 1

    asset = env.scene[asset_cfg.name]
    foot_xy = asset.data.body_pos_w[:, asset_cfg.body_ids, :2]
    stance_xy = torch.sum(foot_xy * in_contact.float().unsqueeze(-1), dim=1) / torch.clamp(
        torch.sum(in_contact.float(), dim=1, keepdim=True), min=1.0
    )
    com_xy = asset.data.root_com_pos_w[:, :2]
    distance = torch.linalg.vector_norm(com_xy - stance_xy, dim=1)
    reward = torch.exp(-0.5 * torch.square(distance / std))
    return reward * single_support * _moving_command_mask(env, command_name, command_threshold)


def moving_soft_torque_utilization_l2(
    env: ManagerBasedRLEnv,
    command_name: str,
    torque_limit_nm: float,
    soft_ratio: float = 0.70,
    command_threshold: float = 0.12,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Soft torque utilization only while moving, for targeted joint-health shaping."""
    if torque_limit_nm <= 0.0:
        raise ValueError("torque_limit_nm must be positive")
    if not 0.0 <= soft_ratio < 1.0:
        raise ValueError("soft_ratio must be in [0, 1)")
    asset: Articulation = env.scene[asset_cfg.name]
    torque = torch.abs(asset.data.applied_torque[:, asset_cfg.joint_ids])
    utilization = torque / torque_limit_nm
    excess = torch.relu(utilization - soft_ratio)
    return torch.sum(torch.square(excess), dim=1) * _moving_command_mask(env, command_name, command_threshold)


def moving_long_double_support_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.22,
    max_double_support_s: float = 0.30,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize long planted double-support under nonzero locomotion commands.

    v1.4.6 specifically targets the planted/braced local optimum observed in
    Hardware-v5s3. Brief double-support transitions are allowed, but remaining
    on both feet for longer than ``max_double_support_s`` while commanded to move
    becomes increasingly expensive.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_time = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    long_double_support_time = torch.relu(torch.min(contact_time, dim=1)[0] - max_double_support_s)
    return long_double_support_time * _moving_command_mask(env, command_name, command_threshold)


def moving_planted_no_progress_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.22,
    min_fraction: float = 0.35,
    max_double_support_s: float = 0.20,
    force_threshold: float = 1.0,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Penalize the exact failure mode: planted double-support with no progress.

    This combines command-aligned velocity deficit with persistent double support.
    It is stronger and more targeted than a generic action/torque penalty: the
    policy can avoid it by actually moving along the command or by entering a
    step-like support transition.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_time = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    planted_time = torch.relu(torch.min(contact_time, dim=1)[0] - max_double_support_s)

    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command, dim=1)
    command_dir = command / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    projected_speed = torch.sum(vel_yaw * command_dir, dim=1)
    required_speed = min_fraction * command_norm
    no_progress = torch.relu(required_speed - projected_speed)
    return planted_time * no_progress * (command_norm > command_threshold)




# -----------------------------------------------------------------------------
# v1.4.7 phase-guided alternating gait scaffold
# -----------------------------------------------------------------------------

def _gait_phase(env: ManagerBasedRLEnv, period_s: float = 0.72, phase_offset_s: float = 0.0) -> torch.Tensor:
    """Per-environment gait phase in [0, 1), derived from episode time.

    This is intentionally simple and reset-safe.  It gives the policy/rewards a
    light alternating scaffold without command bins or a learned gait scheduler.
    """
    if period_s <= 1.0e-6:
        raise ValueError("period_s must be positive")
    if hasattr(env, "episode_length_buf"):
        t = env.episode_length_buf.to(dtype=torch.float32) * float(env.step_dt)
    else:
        # Fallback for API variants: use common step counter for all envs.
        device = env.scene["robot"].data.root_pos_w.device
        t = torch.full((env.num_envs,), float(getattr(env, "common_step_counter", 0)) * float(env.step_dt), device=device)
    return torch.remainder((t + float(phase_offset_s)) / float(period_s), 1.0)


def gait_phase_sin_cos(env: ManagerBasedRLEnv, period_s: float = 0.72, phase_offset_s: float = 0.0) -> torch.Tensor:
    """Observation term: [sin(2*pi*phase), cos(2*pi*phase)].

    Adding this two-value clock changes the Hardware-v1.4.7 policy observation
    contract from 45-D to 47-D.  The stand warm-start loader copies old actor
    weights into the shared observation columns and leaves the new phase columns
    freshly initialized.
    """
    phase = _gait_phase(env, period_s=period_s, phase_offset_s=phase_offset_s)
    angle = 2.0 * math.pi * phase
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def _phase_expected_contacts(
    env: ManagerBasedRLEnv,
    period_s: float = 0.72,
    duty_factor: float = 0.58,
    transition_width: float = 0.08,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Return expected left/right stance booleans and a transition mask.

    Phase convention:
    - phase in [0.0, 0.5): left stance, right swing
    - phase in [0.5, 1.0): right stance, left swing
    Near the 0/0.5 boundaries, brief double support is allowed.
    """
    phase = _gait_phase(env, period_s=period_s)
    # Small double-support windows around phase transitions.
    d0 = torch.minimum(phase, 1.0 - phase)
    d05 = torch.abs(phase - 0.5)
    transition = torch.minimum(d0, d05) < transition_width
    left_stance_half = phase < 0.5
    # Use duty_factor to extend stance slightly around transitions, but keep it simple.
    left_expected = torch.where(transition, torch.ones_like(left_stance_half), left_stance_half)
    right_expected = torch.where(transition, torch.ones_like(left_stance_half), ~left_stance_half)
    return left_expected.bool(), right_expected.bool(), transition


def _foot_contacts(env: ManagerBasedRLEnv, sensor_cfg: SceneEntityCfg, force_threshold: float = 1.0) -> torch.Tensor:
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    return forces.norm(dim=-1).max(dim=1)[0] > force_threshold


def phase_guided_contact_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.08,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward following a simple alternating contact scaffold.

    This gives the policy an explicit rhythm target: one foot stance while the
    other swings, with short double-support transitions.  It distinguishes
    alternating stepping from both previous exploits: planted double support and
    long one-foot-air hopping.
    """
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    # In transition, both feet contacting is best; outside transition, stance foot
    # contact + swing foot air is best.
    transition_score = (left_contact & right_contact).float()
    left_half_score = (left_contact & (~right_contact)).float()
    right_half_score = ((~left_contact) & right_contact).float()
    phase_score = torch.where(
        transition,
        transition_score,
        torch.where(left_expected & (~right_expected), left_half_score, right_half_score),
    )
    return phase_score * _moving_command_mask(env, command_name, command_threshold)


def phase_guided_contact_mismatch_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.08,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize wrong-foot contact pattern under the phase scaffold."""
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    # No support is handled strongly elsewhere; here score contact-pattern mismatch.
    left_err = (left_contact != left_expected).float()
    right_err = (right_contact != right_expected).float()
    # Be gentler in transition windows because contact timing jitter is expected.
    penalty = torch.where(transition, 0.35 * (left_err + right_err), left_err + right_err)
    return penalty * _moving_command_mask(env, command_name, command_threshold)


def phase_guided_swing_clearance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.08,
    target_clearance_m: float = 0.030,
    clearance_std_m: float = 0.018,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward useful swing-foot clearance for the phase-selected swing foot."""
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    asset = env.scene[asset_cfg.name]
    foot_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    left_swing = (~left_expected) & right_contact & (~left_contact) & (~transition)
    right_swing = (~right_expected) & left_contact & (~right_contact) & (~transition)
    # clearance relative to stance foot height
    left_clear = foot_z[:, 0] - foot_z[:, 1]
    right_clear = foot_z[:, 1] - foot_z[:, 0]
    clear = torch.where(left_swing, left_clear, torch.where(right_swing, right_clear, torch.zeros_like(left_clear)))
    reward = torch.exp(-0.5 * torch.square((clear - target_clearance_m) / clearance_std_m))
    reward = reward * (left_swing | right_swing)
    return reward * _moving_command_mask(env, command_name, command_threshold)


def phase_guided_swing_velocity_along_command(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.08,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward the phase-selected swing foot moving in the commanded direction."""
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    left_swing = (~left_expected) & contacts[:, 1] & (~contacts[:, 0]) & (~transition)
    right_swing = (~right_expected) & contacts[:, 0] & (~contacts[:, 1]) & (~transition)

    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command, dim=1)
    command_dir = command / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    foot_vel_yaw = quat_apply_inverse(
        yaw_quat(asset.data.root_quat_w).unsqueeze(1).expand(-1, len(asset_cfg.body_ids), -1),
        asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :3],
    )[:, :, :2]
    left_proj = torch.sum(foot_vel_yaw[:, 0, :] * command_dir, dim=1)
    right_proj = torch.sum(foot_vel_yaw[:, 1, :] * command_dir, dim=1)
    reward = torch.where(left_swing, torch.clamp(left_proj, min=0.0), torch.zeros_like(left_proj))
    reward = reward + torch.where(right_swing, torch.clamp(right_proj, min=0.0), torch.zeros_like(right_proj))
    return reward * (command_norm > command_threshold)


def phase_guided_foot_placement_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.08,
    target_step_m: float = 0.060,
    step_std_m: float = 0.050,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward swing foot placement ahead of the stance foot along command direction."""
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    left_swing = (~left_expected) & contacts[:, 1] & (~transition)
    right_swing = (~right_expected) & contacts[:, 0] & (~transition)

    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    left_delta = foot_pos[:, 0, :] - foot_pos[:, 1, :]
    right_delta = foot_pos[:, 1, :] - foot_pos[:, 0, :]
    left_delta_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), left_delta)[:, :2]
    right_delta_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), right_delta)[:, :2]
    command = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command, dim=1)
    command_dir = command / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    left_step = torch.sum(left_delta_yaw * command_dir, dim=1)
    right_step = torch.sum(right_delta_yaw * command_dir, dim=1)
    projected = torch.where(left_swing, left_step, torch.where(right_swing, right_step, torch.zeros_like(left_step)))
    reward = torch.exp(-0.5 * torch.square((projected - target_step_m) / step_std_m))
    reward = reward * (left_swing | right_swing)
    return reward * (command_norm > command_threshold)


def phase_guided_long_air_hold_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.22,
    max_air_time_s: float = 0.28,
) -> torch.Tensor:
    """Penalize holding either foot in the air too long under moving commands."""
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air_time = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    excess = torch.relu(torch.max(air_time, dim=1)[0] - max_air_time_s)
    return excess * _moving_command_mask(env, command_name, command_threshold)


# -----------------------------------------------------------------------------
# v1.4.8 phase-lift step refinement
# -----------------------------------------------------------------------------

def _phase_swing_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    force_threshold: float = 1.0,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Shared phase-selected swing-foot state for v1.4.8 rewards.

    Returns ``(active, clearance, step_forward, command_norm, projected_base_speed, lateral_speed)``.
    ``active`` means a non-transition moving command where the expected stance foot
    is actually grounded.  The swing foot is *not* required to be contact-free so
    these rewards can shape lift before the contact sensor has declared air time.
    """
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    device = contacts.device
    zeros = torch.zeros(contacts.shape[0], device=device)
    if contacts.shape[1] < 2:
        return zeros.bool(), zeros, zeros, zeros, zeros, zeros

    left_expected, right_expected, transition = _phase_expected_contacts(
        env, period_s=period_s, transition_width=transition_width
    )
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]

    # Phase convention inherited from v1.4.7:
    # left_expected=False => left swing / right stance, and vice versa.
    left_active = (~left_expected) & right_contact & (~transition)
    right_active = (~right_expected) & left_contact & (~transition)
    active = left_active | right_active

    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    left_clearance = foot_pos[:, 0, 2] - foot_pos[:, 1, 2]
    right_clearance = foot_pos[:, 1, 2] - foot_pos[:, 0, 2]
    clearance = torch.where(left_active, left_clearance, torch.where(right_active, right_clearance, zeros))

    left_delta = foot_pos[:, 0, :] - foot_pos[:, 1, :]
    right_delta = foot_pos[:, 1, :] - foot_pos[:, 0, :]
    yaw = yaw_quat(asset.data.root_quat_w)
    left_delta_yaw = quat_apply_inverse(yaw, left_delta)[:, :2]
    right_delta_yaw = quat_apply_inverse(yaw, right_delta)[:, :2]

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    command_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    left_step = torch.sum(left_delta_yaw * command_dir, dim=1)
    right_step = torch.sum(right_delta_yaw * command_dir, dim=1)
    step_forward = torch.where(left_active, left_step, torch.where(right_active, right_step, zeros))

    base_vel_yaw = quat_apply_inverse(yaw, asset.data.root_lin_vel_w[:, :3])[:, :2]
    projected_base_speed = torch.sum(base_vel_yaw * command_dir, dim=1)
    lateral_speed = base_vel_yaw[:, 1]
    active = active & (command_norm > command_threshold)
    return active, clearance, step_forward, command_norm, projected_base_speed, lateral_speed


def phase_guided_expected_swing_clearance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    target_clearance_m: float = 0.030,
    clearance_std_m: float = 0.016,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward phase-selected swing foot for reaching a real clearance target.

    Unlike the v1.4.7 reward, this does not require the swing foot to already be
    contact-free.  That avoids the rocking/unweighting shortcut where the robot
    matched phase contacts while barely lifting its feet.
    """
    active, clearance, _, _, _, _ = _phase_swing_state(
        env,
        command_name,
        sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        period_s=period_s,
        transition_width=transition_width,
        force_threshold=force_threshold,
    )
    reward = torch.exp(-0.5 * torch.square((clearance - target_clearance_m) / clearance_std_m))
    return reward * active.float()


def phase_guided_swing_clearance_shortfall_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    min_clearance_m: float = 0.016,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize phase-matched swing that never gets the foot off the floor."""
    active, clearance, _, _, _, _ = _phase_swing_state(
        env,
        command_name,
        sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        period_s=period_s,
        transition_width=transition_width,
        force_threshold=force_threshold,
    )
    shortfall = torch.relu(float(min_clearance_m) - clearance) / max(float(min_clearance_m), 1.0e-6)
    return shortfall * active.float()


def phase_guided_step_placement_target_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    target_step_m: float = 0.050,
    step_std_m: float = 0.035,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward the phase-selected swing foot for being placed forward of stance."""
    active, _, step_forward, _, _, _ = _phase_swing_state(
        env,
        command_name,
        sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        period_s=period_s,
        transition_width=transition_width,
        force_threshold=force_threshold,
    )
    reward = torch.exp(-0.5 * torch.square((step_forward - target_step_m) / step_std_m))
    return reward * active.float()


def phase_guided_step_shortfall_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    min_step_m: float = 0.025,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize alternating contact with almost no commanded-direction step."""
    active, _, step_forward, _, _, _ = _phase_swing_state(
        env,
        command_name,
        sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        period_s=period_s,
        transition_width=transition_width,
        force_threshold=force_threshold,
    )
    shortfall = torch.relu(float(min_step_m) - step_forward) / max(float(min_step_m), 1.0e-6)
    return shortfall * active.float()


def phase_guided_rocking_no_step_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.22,
    period_s: float = 0.72,
    transition_width: float = 0.09,
    min_clearance_m: float = 0.014,
    min_step_m: float = 0.022,
    min_progress_fraction: float = 0.18,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Penalize the v1.4.7 rocking shortcut under moving commands.

    This term activates when the phase scaffold is present but the swing foot is
    low, the foot is not placed forward, and the base is not making enough
    command-aligned progress.  It is intentionally moderate; it nudges the policy
    away from rocking without destroying the newly learned rhythm.
    """
    active, clearance, step_forward, command_norm, projected_speed, _ = _phase_swing_state(
        env,
        command_name,
        sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        period_s=period_s,
        transition_width=transition_width,
        force_threshold=force_threshold,
    )
    clearance_deficit = torch.relu(float(min_clearance_m) - clearance) / max(float(min_clearance_m), 1.0e-6)
    step_deficit = torch.relu(float(min_step_m) - step_forward) / max(float(min_step_m), 1.0e-6)
    progress_deficit = torch.relu(float(min_progress_fraction) * command_norm - projected_speed)
    return (0.50 * clearance_deficit + 0.50 * step_deficit) * progress_deficit * active.float()


def moving_yaw_stability_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    lin_command_threshold: float = 0.12,
    yaw_command_threshold: float = 0.12,
    yaw_error_std: float = 0.55,
    yaw_overspeed_margin: float = 0.35,
    lateral_velocity_weight: float = 0.45,
    yaw_only_linear_drift_weight: float = 0.35,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Penalize wild yaw/spin behavior while preserving commanded turns.

    Forward-only commands penalize yaw rate away from zero; yaw commands penalize
    yaw-rate tracking error rather than yaw itself.  Yaw-only commands also mildly
    penalize drifting translation, so the robot cannot satisfy turn commands by
    breaking into uncontrolled forward/side motion.
    """
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)
    lin_cmd = command[:, :2]
    yaw_cmd = command[:, 2]
    lin_norm = torch.linalg.vector_norm(lin_cmd, dim=1)
    yaw_abs = torch.abs(yaw_cmd)

    yaw_rate = asset.data.root_ang_vel_w[:, 2]
    yaw_error = yaw_rate - yaw_cmd
    yaw_error_pen = torch.square(yaw_error / max(float(yaw_error_std), 1.0e-6))
    overspeed = torch.relu(torch.abs(yaw_rate) - yaw_abs - float(yaw_overspeed_margin))
    overspeed_pen = torch.square(overspeed)

    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    lateral_pen = torch.square(vel_yaw[:, 1])
    yaw_only = (yaw_abs > yaw_command_threshold) & (lin_norm < lin_command_threshold)
    yaw_only_drift = torch.linalg.vector_norm(vel_yaw, dim=1) ** 2

    active = (lin_norm > lin_command_threshold) | (yaw_abs > yaw_command_threshold)
    return (
        yaw_error_pen
        + overspeed_pen
        + float(lateral_velocity_weight) * lateral_pen * (lin_norm > lin_command_threshold).float()
        + float(yaw_only_linear_drift_weight) * yaw_only_drift * yaw_only.float()
    ) * active.float()


# -----------------------------------------------------------------------------
# Littlegreen v2.0.0 v10 command-synchronized transfer/lift/place scaffold
# -----------------------------------------------------------------------------


def _v10_episode_reset_mask(env: ManagerBasedRLEnv, num_envs: int, device: torch.device) -> torch.Tensor:
    """Best-effort per-environment reset mask without depending on manager internals."""
    episode_length = getattr(env, "episode_length_buf", None)
    if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
        return episode_length.to(device=device) <= 0
    return torch.zeros(num_envs, device=device, dtype=torch.bool)


def _v10_command_synchronized_phase(
    env: ManagerBasedRLEnv,
    command_name: str = "base_velocity",
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Return a movement-synchronized gait phase and moving mask.

    The phase is frozen at a double-support boundary while standing.  On each
    standing-to-moving transition it resets to a boundary and alternates the
    first swing side.  The first movement onset is balanced across environments
    by environment-index parity.  State is advanced at most once per simulator
    step even though observations and several reward terms call this helper.

    Phase convention:
    * phase 0.0 starts left stance / right swing;
    * phase 0.5 starts right stance / left swing.
    """
    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    yaw_abs = torch.abs(command[:, 2]) if command.shape[1] > 2 else torch.zeros_like(linear_norm)
    moving = (linear_norm > linear_command_threshold) | (yaw_abs > yaw_command_threshold)

    num_envs = command.shape[0]
    device = command.device
    phase = getattr(env, "_littlegreen_v10_gait_phase", None)
    was_moving = getattr(env, "_littlegreen_v10_was_moving", None)
    next_first_swing_left = getattr(env, "_littlegreen_v10_next_first_swing_left", None)
    active_first_swing_left = getattr(env, "_littlegreen_v10_active_first_swing_left", None)

    parity_first_swing_left = (torch.arange(num_envs, device=device) % 2) == 0
    if not isinstance(phase, torch.Tensor) or phase.shape[0] != num_envs:
        phase = torch.zeros(num_envs, device=device, dtype=torch.float32)
    if not isinstance(was_moving, torch.Tensor) or was_moving.shape[0] != num_envs:
        was_moving = torch.zeros(num_envs, device=device, dtype=torch.bool)
    if not isinstance(next_first_swing_left, torch.Tensor) or next_first_swing_left.shape[0] != num_envs:
        next_first_swing_left = parity_first_swing_left.clone()
    if not isinstance(active_first_swing_left, torch.Tensor) or active_first_swing_left.shape[0] != num_envs:
        active_first_swing_left = parity_first_swing_left.clone()

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v10_phase_last_common_step", -1))
    if common_step != last_step:
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v10_phase_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v10_phase_last_episode_length = current_episode_length.clone()

        phase = torch.where(reset_mask, torch.zeros_like(phase), phase)
        was_moving = torch.where(reset_mask, torch.zeros_like(was_moving), was_moving)
        next_first_swing_left = torch.where(
            reset_mask, parity_first_swing_left, next_first_swing_left
        )
        active_first_swing_left = torch.where(
            reset_mask, parity_first_swing_left, active_first_swing_left
        )

        onset = moving & (~was_moving)
        active_first_swing_left = torch.where(onset, next_first_swing_left, active_first_swing_left)
        next_first_swing_left = torch.where(onset, ~next_first_swing_left, next_first_swing_left)
        onset_boundary = torch.where(
            active_first_swing_left,
            torch.full_like(phase, 0.5),
            torch.zeros_like(phase),
        )
        phase = torch.where(onset, onset_boundary, phase)

        active_period_s = float(getattr(env, "_littlegreen_v10_gait_period_s", period_s))
        if active_period_s <= 1.0e-6:
            raise ValueError("v10 gait period must be positive")
        dt = float(getattr(env, "step_dt", 0.02))
        advance = dt / active_period_s
        phase = torch.where(
            moving & (~onset),
            torch.remainder(phase + advance, 1.0),
            phase,
        )
        # Standing always exposes the same double-support phase observation.
        phase = torch.where(moving, phase, torch.zeros_like(phase))
        was_moving = moving

        env._littlegreen_v10_gait_phase = phase
        env._littlegreen_v10_was_moving = was_moving
        env._littlegreen_v10_next_first_swing_left = next_first_swing_left
        env._littlegreen_v10_active_first_swing_left = active_first_swing_left
        env._littlegreen_v10_phase_last_common_step = common_step

    return phase, moving


def command_synchronized_gait_phase_sin_cos(
    env: ManagerBasedRLEnv,
    command_name: str = "base_velocity",
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
) -> torch.Tensor:
    """47-D contract observation tail using the v10 command-synchronized phase."""
    phase, _ = _v10_command_synchronized_phase(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
    )
    angle = 2.0 * math.pi * phase
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def _v10_phase_schedule(
    env: ManagerBasedRLEnv,
    command_name: str,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Return v10 phase schedule state.

    Returns ``(phase, moving, transition, left_stance, swing_progress,
    transfer_progress)``.  Unlike the older symmetric transition window, v10
    uses one short double-support/weight-transfer interval at the beginning of
    each half-cycle.  A transition fraction of 0.05 therefore means 10% total
    double support per full cycle rather than 20% on each side of both boundaries.
    """
    phase, moving = _v10_command_synchronized_phase(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
    )
    active_transition_fraction = float(
        getattr(env, "_littlegreen_v10_transition_fraction", transition_fraction)
    )
    if not 0.0 < active_transition_fraction < 0.25:
        raise ValueError("v10 transition_fraction must be in (0, 0.25)")

    left_stance = phase < 0.5
    half_phase = torch.remainder(2.0 * phase, 1.0)
    # The parameter is the fraction of the *full* cycle allocated to each
    # transfer window.  In half-cycle coordinates the width is therefore 2x.
    half_transition_fraction = 2.0 * active_transition_fraction
    transition = half_phase < half_transition_fraction
    swing_progress = torch.clamp(
        (half_phase - half_transition_fraction) / (1.0 - half_transition_fraction),
        min=0.0,
        max=1.0,
    )
    transfer_progress = torch.clamp(
        half_phase / half_transition_fraction,
        min=0.0,
        max=1.0,
    )
    return phase, moving, transition, left_stance, swing_progress, transfer_progress


def _v10_selected_foot_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
) -> tuple[
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
    torch.Tensor,
]:
    """Return v10 selected stance/swing kinematics.

    Returns ``(moving, transition, left_stance, swing_progress, clearance,
    step_forward, foot_pos_w)``.  Clearance is relative to the selected stance
    foot and placement is projected along the commanded horizontal direction.
    """
    _, moving, transition, left_stance, swing_progress, _ = _v10_phase_schedule(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    if foot_pos.shape[1] < 2:
        zeros = torch.zeros(foot_pos.shape[0], device=foot_pos.device)
        return moving, transition, left_stance, swing_progress, zeros, zeros, foot_pos

    left_stance_pos = foot_pos[:, 0, :]
    right_stance_pos = foot_pos[:, 1, :]
    stance_pos = torch.where(left_stance.unsqueeze(-1), left_stance_pos, right_stance_pos)
    swing_pos = torch.where(left_stance.unsqueeze(-1), right_stance_pos, left_stance_pos)
    clearance = swing_pos[:, 2] - stance_pos[:, 2]

    asset_yaw = yaw_quat(asset.data.root_quat_w)
    swing_delta_yaw = quat_apply_inverse(asset_yaw, swing_pos - stance_pos)[:, :2]
    command_xy = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    command_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    step_forward = torch.sum(swing_delta_yaw * command_dir, dim=1)
    return moving, transition, left_stance, swing_progress, clearance, step_forward, foot_pos


def v10_track_lin_vel_xy_yaw_frame_exp(
    env: ManagerBasedRLEnv,
    std: float,
    command_name: str,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    default_stage_scale: float = 0.55,
) -> torch.Tensor:
    """Velocity tracking with stage-dependent pressure during skill acquisition."""
    stage_scale = float(getattr(env, "_littlegreen_v10_tracking_scale", default_stage_scale))
    return stage_scale * track_lin_vel_xy_yaw_frame_exp(
        env, std=std, command_name=command_name, asset_cfg=asset_cfg
    )


def v10_signed_phase_contact_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
    force_threshold: float = 1.0,
    double_support_swing_score: float = -0.40,
) -> torch.Tensor:
    """Signed contact schedule with no reward loophole for planted double support."""
    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        return torch.zeros(contacts.shape[0], device=contacts.device)
    _, moving, transition, left_stance, _, _ = _v10_phase_schedule(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    both = left_contact & right_contact
    none = (~left_contact) & (~right_contact)
    left_only = left_contact & (~right_contact)
    right_only = (~left_contact) & right_contact
    correct_single = torch.where(left_stance, left_only, right_only)
    wrong_single = torch.where(left_stance, right_only, left_only)

    transition_score = torch.where(
        both,
        torch.ones_like(left_contact, dtype=torch.float32),
        torch.where(
            correct_single,
            torch.full_like(left_contact, 0.20, dtype=torch.float32),
            torch.where(
                wrong_single,
                torch.full_like(left_contact, -0.60, dtype=torch.float32),
                torch.full_like(left_contact, -1.0, dtype=torch.float32),
            ),
        ),
    )
    swing_score = torch.where(
        correct_single,
        torch.ones_like(left_contact, dtype=torch.float32),
        torch.where(
            both,
            torch.full_like(left_contact, float(double_support_swing_score), dtype=torch.float32),
            torch.full_like(left_contact, -1.0, dtype=torch.float32),
        ),
    )
    score = torch.where(transition, transition_score, swing_score)
    score = torch.where(none, torch.full_like(score, -1.0), score)
    return score * moving.float()


def v10_support_force_transfer_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
    target_stance_ratio: float = 0.75,
    early_swing_fraction: float = 0.20,
    force_threshold: float = 1.0,
    eps: float = 1.0e-6,
) -> torch.Tensor:
    """Reward alternating load transfer onto the phase-selected stance foot.

    Equal loading is exactly zero reward.  Loading the wrong foot is negative,
    while reaching the target stance-force ratio is +1.  The term is active only
    during the short transfer interval and early swing.
    """
    _, moving, transition, left_stance, swing_progress, _ = _v10_phase_schedule(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.abs(forces[..., 2]).max(dim=1)[0]
    if vertical.shape[1] < 2:
        return torch.zeros(vertical.shape[0], device=vertical.device)
    left_force, right_force = vertical[:, 0], vertical[:, 1]
    stance_force = torch.where(left_stance, left_force, right_force)
    total_force = left_force + right_force
    stance_ratio = stance_force / torch.clamp(total_force, min=eps)

    active_target_ratio = float(
        getattr(env, "_littlegreen_v10_target_stance_force_ratio", target_stance_ratio)
    )
    if active_target_ratio <= 0.5 or active_target_ratio > 1.0:
        raise ValueError("v10 target stance force ratio must be in (0.5, 1.0]")
    signed = torch.clamp(
        (stance_ratio - 0.5) / (active_target_ratio - 0.5),
        min=-1.0,
        max=1.0,
    )
    has_support = total_force > force_threshold
    signed = torch.where(has_support, signed, torch.full_like(signed, -1.0))
    transfer_window = transition | ((~transition) & (swing_progress < early_swing_fraction))
    return signed * transfer_window.float() * moving.float()


def v10_phase_com_shift_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
    target_forward_m: float = 0.080,
    neutral_forward_m: float = 0.070,
    lateral_stance_fraction: float = 0.75,
    forward_std_m: float = 0.035,
    lateral_std_m: float = 0.030,
    early_swing_fraction: float = 0.30,
) -> torch.Tensor:
    """Reward a forward, alternating COM shift toward the expected stance leg.

    The stable stand COM position (neutral forward offset, centered laterally) is
    normalized to zero reward.  Shifting toward the wrong leg becomes negative,
    so one permanent support leg cannot satisfy both half-cycles.
    """
    _, moving, transition, left_stance, swing_progress, _ = _v10_phase_schedule(
        env,
        command_name=command_name,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    if foot_pos.shape[1] < 2:
        return torch.zeros(foot_pos.shape[0], device=foot_pos.device)

    midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
    left_rel = foot_pos[:, 0, :] - midpoint
    right_rel = foot_pos[:, 1, :] - midpoint
    com_rel = asset.data.root_com_pos_w - midpoint
    yaw = yaw_quat(asset.data.root_quat_w)
    left_rel_yaw = quat_apply_inverse(yaw, left_rel)
    right_rel_yaw = quat_apply_inverse(yaw, right_rel)
    com_rel_yaw = quat_apply_inverse(yaw, com_rel)
    stance_rel_yaw = torch.where(left_stance.unsqueeze(-1), left_rel_yaw, right_rel_yaw)

    active_forward = float(getattr(env, "_littlegreen_v10_com_target_forward_m", target_forward_m))
    active_lateral_fraction = float(
        getattr(env, "_littlegreen_v10_com_lateral_stance_fraction", lateral_stance_fraction)
    )
    target_x = torch.full_like(com_rel_yaw[:, 0], active_forward)
    target_y = active_lateral_fraction * stance_rel_yaw[:, 1]
    dx = (com_rel_yaw[:, 0] - target_x) / max(float(forward_std_m), 1.0e-6)
    dy = (com_rel_yaw[:, 1] - target_y) / max(float(lateral_std_m), 1.0e-6)
    raw = torch.exp(-0.5 * (torch.square(dx) + torch.square(dy)))

    neutral_dx = (float(neutral_forward_m) - target_x) / max(float(forward_std_m), 1.0e-6)
    neutral_dy = (0.0 - target_y) / max(float(lateral_std_m), 1.0e-6)
    baseline = torch.exp(-0.5 * (torch.square(neutral_dx) + torch.square(neutral_dy)))
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    transfer_window = transition | ((~transition) & (swing_progress < early_swing_fraction))
    return normalized * transfer_window.float() * moving.float()


def v10_swing_clearance_trajectory_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
    target_clearance_m: float = 0.018,
    clearance_std_m: float = 0.009,
) -> torch.Tensor:
    """Baseline-corrected swing-height trajectory reward.

    The desired trajectory is ``H*sin(pi*s)``.  Zero clearance receives exactly
    zero reward at every swing phase, eliminating the positive Gaussian baseline
    that allowed v9 to remain planted.
    """
    moving, transition, _, swing_progress, clearance, _, _ = _v10_selected_foot_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    active_target = float(
        getattr(env, "_littlegreen_v10_target_clearance_m", target_clearance_m)
    )
    active_std = float(getattr(env, "_littlegreen_v10_clearance_std_m", clearance_std_m))
    shape = torch.sin(math.pi * swing_progress)
    reference = active_target * shape
    raw = torch.exp(-0.5 * torch.square((clearance - reference) / max(active_std, 1.0e-6)))
    zero_baseline = torch.exp(-0.5 * torch.square(reference / max(active_std, 1.0e-6)))
    normalized = (raw - zero_baseline) / torch.clamp(1.0 - zero_baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=0.0, max=1.0)
    active = moving & (~transition)
    return normalized * shape * active.float()


def v10_clearance_gated_placement_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.90,
    transition_fraction: float = 0.08,
    target_step_m: float = 0.025,
    step_std_m: float = 0.025,
    clearance_gate_m: float = 0.008,
    gate_width_m: float = 0.006,
    placement_start_progress: float = 0.35,
    placement_scale: float = 0.15,
) -> torch.Tensor:
    """Reward forward placement only after real swing-foot clearance exists.

    Zero forward displacement is normalized to zero reward, and the term is
    smoothly gated by both swing progress and measured clearance.
    """
    moving, transition, _, swing_progress, clearance, step_forward, _ = _v10_selected_foot_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    active_target = float(getattr(env, "_littlegreen_v10_target_step_m", target_step_m))
    active_gate = float(getattr(env, "_littlegreen_v10_clearance_gate_m", clearance_gate_m))
    active_scale = float(getattr(env, "_littlegreen_v10_placement_scale", placement_scale))

    progress_gate = torch.clamp(
        (swing_progress - placement_start_progress) / max(1.0 - placement_start_progress, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    # Smoothstep avoids a hard discontinuity when placement is enabled.
    progress_gate = progress_gate * progress_gate * (3.0 - 2.0 * progress_gate)
    clearance_gate = torch.clamp(
        (clearance - active_gate) / max(float(gate_width_m), 1.0e-6),
        min=0.0,
        max=1.0,
    )
    clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)

    target = active_target * progress_gate
    raw = torch.exp(-0.5 * torch.square((step_forward - target) / max(float(step_std_m), 1.0e-6)))
    zero_baseline = torch.exp(-0.5 * torch.square(target / max(float(step_std_m), 1.0e-6)))
    normalized = (raw - zero_baseline) / torch.clamp(1.0 - zero_baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=0.0, max=1.0)
    active = moving & (~transition)
    return active_scale * normalized * progress_gate * clearance_gate * active.float()


# -----------------------------------------------------------------------------
# Littlegreen v2.0.0 v11 event-gated step-takeover scaffold
# -----------------------------------------------------------------------------


_V11_STAND = 0
_V11_TRANSFER = 1
_V11_SWING = 2
_V11_TAKEOVER = 3


def _v11_event_gated_gait_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.05,
    takeover_fraction: float = 0.04,
    force_threshold: float = 1.0,
    transfer_hold_s: float = 0.06,
    takeover_hold_s: float = 0.08,
    transfer_max_s: float = 0.20,
    swing_min_s: float = 0.14,
    swing_max_s: float = 0.58,
    takeover_max_s: float = 0.24,
    lift_gate_m: float = 0.010,
    touchdown_height_m: float = 0.006,
    touchdown_vertical_speed_mps: float = 0.20,
    com_lateral_stance_fraction: float = 0.84,
    com_support_forward_offset_m: float = -0.015,
    com_forward_tolerance_m: float = 0.050,
    com_lateral_tolerance_m: float = 0.040,
    min_step_m: float = 0.022,
    max_step_m: float = 0.040,
    step_length_scale: float = 0.12,
) -> dict[str, torch.Tensor]:
    """Update and return the v11 event-gated gait state once per simulator step.

    v10 proved that the robot can alternate load, contact, and swing clearance, but a
    purely time-driven oscillator allowed a fore/aft rocking exploit.  v11 therefore
    advances through a half-cycle only after the relevant physical event:

    ``TRANSFER -> SWING -> TOUCHDOWN -> TAKEOVER -> next TRANSFER``.

    The phase observation remains two-dimensional ``[sin, cos]``.  Its internal
    progression pauses near each state boundary until a kinematic/COM gate succeeds
    or a bounded training timeout is reached.  Phase gates deliberately avoid
    simulator-only force ratios so Track 2 can reproduce them from commanded motion,
    joint-state forward kinematics, base orientation, and a COM estimate.  Contact
    forces remain training rewards and diagnostics, not hidden phase inputs.
    """
    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    yaw_abs = torch.abs(command[:, 2]) if command.shape[1] > 2 else torch.zeros_like(linear_norm)
    moving = (linear_norm > linear_command_threshold) | (yaw_abs > yaw_command_threshold)
    num_envs = command.shape[0]
    device = command.device

    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    if foot_pos.shape[1] < 2:
        raise ValueError("v11 requires two ordered foot bodies (left, right)")

    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        raise ValueError("v11 requires two ordered foot contact channels (left, right)")
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]

    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.abs(forces[..., 2]).max(dim=1)[0]
    left_force = vertical[:, 0]
    right_force = vertical[:, 1]
    total_force = left_force + right_force

    active_period_s = float(getattr(env, "_littlegreen_v11_gait_period_s", period_s))
    active_transition_fraction = float(
        getattr(env, "_littlegreen_v11_transition_fraction", transition_fraction)
    )
    active_takeover_fraction = float(
        getattr(env, "_littlegreen_v11_takeover_fraction", takeover_fraction)
    )
    active_transfer_max_s = float(getattr(env, "_littlegreen_v11_transfer_max_s", transfer_max_s))
    active_swing_max_s = float(getattr(env, "_littlegreen_v11_swing_max_s", swing_max_s))
    active_takeover_max_s = float(getattr(env, "_littlegreen_v11_takeover_max_s", takeover_max_s))
    active_lift_gate_m = float(getattr(env, "_littlegreen_v11_clearance_gate_m", lift_gate_m))
    active_lateral_fraction = float(
        getattr(env, "_littlegreen_v11_com_lateral_stance_fraction", com_lateral_stance_fraction)
    )
    active_support_forward_offset = float(
        getattr(env, "_littlegreen_v11_com_support_forward_offset_m", com_support_forward_offset_m)
    )
    active_min_step = float(getattr(env, "_littlegreen_v11_min_step_m", min_step_m))
    active_max_step = float(getattr(env, "_littlegreen_v11_max_step_m", max_step_m))
    active_step_scale = float(getattr(env, "_littlegreen_v11_step_length_scale", step_length_scale))

    if active_period_s <= 1.0e-6:
        raise ValueError("v11 gait period must be positive")
    if not 0.0 < active_transition_fraction < 0.20:
        raise ValueError("v11 transition_fraction must be in (0, 0.20)")
    if not 0.0 < active_takeover_fraction < 0.20:
        raise ValueError("v11 takeover_fraction must be in (0, 0.20)")
    if active_transition_fraction + active_takeover_fraction >= 0.25:
        raise ValueError("v11 transfer and takeover windows leave insufficient swing phase")

    parity_first_swing_left = (torch.arange(num_envs, device=device) % 2) == 0

    def _tensor(name: str, default: torch.Tensor, dtype: torch.dtype | None = None) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    state = _tensor(
        "_littlegreen_v11_state",
        torch.full((num_envs,), _V11_STAND, device=device, dtype=torch.long),
        torch.long,
    )
    stance_left = _tensor(
        "_littlegreen_v11_stance_left", ~parity_first_swing_left, torch.bool
    )
    next_first_swing_left = _tensor(
        "_littlegreen_v11_next_first_swing_left", parity_first_swing_left, torch.bool
    )
    was_moving = _tensor(
        "_littlegreen_v11_was_moving", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    state_elapsed = _tensor(
        "_littlegreen_v11_state_elapsed_s", torch.zeros(num_envs, device=device), torch.float32
    )
    gate_hold = _tensor(
        "_littlegreen_v11_gate_hold_s", torch.zeros(num_envs, device=device), torch.float32
    )
    lift_seen = _tensor(
        "_littlegreen_v11_lift_seen", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    halfcycle_start_root_pos = _tensor(
        "_littlegreen_v11_halfcycle_start_root_pos_w", asset.data.root_pos_w.clone(), torch.float32
    )

    # Per-step event pulses and values.  These are reset whenever the state is
    # advanced, allowing reward terms and analyzers to consume the same events.
    touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    valid_touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    touchdown_advance_event = torch.zeros(num_envs, device=device)
    touchdown_target_event = torch.ones(num_envs, device=device) * active_min_step
    takeover_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    takeover_success_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    halfcycle_progress_event = torch.zeros(num_envs, device=device)
    halfcycle_target_event = torch.ones(num_envs, device=device) * active_min_step

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where((linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir)
    target_step = torch.clamp(
        linear_norm * active_period_s * active_step_scale,
        min=active_min_step,
        max=active_max_step,
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11_last_common_step", -1))
    if common_step != last_step:
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v11_last_episode_length = current_episode_length.clone()

        state = torch.where(reset_mask, torch.full_like(state, _V11_STAND), state)
        stance_left = torch.where(reset_mask, ~parity_first_swing_left, stance_left)
        next_first_swing_left = torch.where(
            reset_mask, parity_first_swing_left, next_first_swing_left
        )
        was_moving = torch.where(reset_mask, torch.zeros_like(was_moving), was_moving)
        state_elapsed = torch.where(reset_mask, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(reset_mask, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(reset_mask, torch.zeros_like(lift_seen), lift_seen)
        halfcycle_start_root_pos = torch.where(
            reset_mask.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )

        onset = moving & (~was_moving)
        first_swing_left = next_first_swing_left
        stance_left = torch.where(onset, ~first_swing_left, stance_left)
        next_first_swing_left = torch.where(onset, ~next_first_swing_left, next_first_swing_left)
        state = torch.where(onset, torch.full_like(state, _V11_TRANSFER), state)
        state_elapsed = torch.where(onset, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(onset, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(onset, torch.zeros_like(lift_seen), lift_seen)
        halfcycle_start_root_pos = torch.where(
            onset.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )

        # Commands returning to stand always cancel an unfinished half-cycle.
        state = torch.where(~moving, torch.full_like(state, _V11_STAND), state)
        state_elapsed = torch.where(~moving, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(~moving, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(~moving, torch.zeros_like(lift_seen), lift_seen)

        state_before = state.clone()
        dt = float(getattr(env, "step_dt", 0.02))
        active_non_onset = moving & (~onset) & (state_before != _V11_STAND)
        state_elapsed = torch.where(active_non_onset, state_elapsed + dt, state_elapsed)

        midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
        root_yaw = yaw_quat(asset.data.root_quat_w)
        left_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 0, :] - midpoint)
        right_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 1, :] - midpoint)
        com_rel_yaw = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)

        current_support_rel = torch.where(
            stance_left.unsqueeze(-1), left_rel_yaw, right_rel_yaw
        )
        new_stance_left = ~stance_left
        new_support_rel = torch.where(
            new_stance_left.unsqueeze(-1), left_rel_yaw, right_rel_yaw
        )

        current_stance_force = torch.where(stance_left, left_force, right_force)
        new_stance_force = torch.where(new_stance_left, left_force, right_force)
        current_ratio = current_stance_force / torch.clamp(total_force, min=1.0e-6)
        new_ratio = new_stance_force / torch.clamp(total_force, min=1.0e-6)

        current_target_x = current_support_rel[:, 0] + active_support_forward_offset
        current_target_y = active_lateral_fraction * current_support_rel[:, 1]
        new_target_x = new_support_rel[:, 0] + active_support_forward_offset
        new_target_y = active_lateral_fraction * new_support_rel[:, 1]
        current_com_ok = (
            (torch.abs(com_rel_yaw[:, 0] - current_target_x) <= com_forward_tolerance_m)
            & (torch.abs(com_rel_yaw[:, 1] - current_target_y) <= com_lateral_tolerance_m)
        )
        new_com_ok = (
            (torch.abs(com_rel_yaw[:, 0] - new_target_x) <= com_forward_tolerance_m)
            & (torch.abs(com_rel_yaw[:, 1] - new_target_y) <= com_lateral_tolerance_m)
        )

        # Current swing kinematics relative to the current stance foot.
        current_stance_pos = torch.where(
            stance_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        current_swing_pos = torch.where(
            stance_left.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        swing_delta_yaw = quat_apply_inverse(root_yaw, current_swing_pos - current_stance_pos)[:, :2]
        current_step_forward = torch.sum(swing_delta_yaw * command_dir, dim=1)
        current_clearance = current_swing_pos[:, 2] - current_stance_pos[:, 2]

        transfer_mask = state_before == _V11_TRANSFER
        # Phase gates intentionally use kinematics/COM rather than simulator-only
        # force ratios.  Track 2 can reproduce these semantics from joint-state FK,
        # base orientation, and the deployed COM estimate.  Force ratios remain
        # training rewards, but are not hidden inputs to the 47-D phase observation.
        transfer_ok = current_com_ok
        gate_hold = torch.where(
            transfer_mask & transfer_ok,
            gate_hold + dt,
            torch.where(transfer_mask, torch.zeros_like(gate_hold), gate_hold),
        )
        transfer_complete = transfer_mask & (
            (gate_hold >= transfer_hold_s) | (state_elapsed >= active_transfer_max_s)
        )
        state = torch.where(transfer_complete, torch.full_like(state, _V11_SWING), state)
        state_elapsed = torch.where(transfer_complete, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(transfer_complete, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(transfer_complete, torch.zeros_like(lift_seen), lift_seen)

        swing_mask = state_before == _V11_SWING
        updated_lift_seen = lift_seen | (swing_mask & (current_clearance >= active_lift_gate_m))
        selected_swing_vel_z = torch.where(
            stance_left,
            asset.data.body_lin_vel_w[:, asset_cfg.body_ids[1], 2],
            asset.data.body_lin_vel_w[:, asset_cfg.body_ids[0], 2],
        )
        kinematic_touchdown = (
            current_clearance <= float(touchdown_height_m)
        ) & (torch.abs(selected_swing_vel_z) <= float(touchdown_vertical_speed_mps))
        valid_touchdown = (
            swing_mask
            & updated_lift_seen
            & kinematic_touchdown
            & (state_elapsed >= swing_min_s)
        )
        timeout_touchdown = (
            swing_mask
            & kinematic_touchdown
            & (state_elapsed >= active_swing_max_s)
            & (~valid_touchdown)
        )
        touchdown = valid_touchdown | timeout_touchdown
        touchdown_event = touchdown
        valid_touchdown_event = valid_touchdown
        touchdown_advance_event = torch.where(
            touchdown, current_step_forward, touchdown_advance_event
        )
        touchdown_target_event = torch.where(touchdown, target_step, touchdown_target_event)
        state = torch.where(touchdown, torch.full_like(state, _V11_TAKEOVER), state)
        state_elapsed = torch.where(touchdown, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(touchdown, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(touchdown, updated_lift_seen, updated_lift_seen)

        takeover_mask = state_before == _V11_TAKEOVER
        takeover_ok = new_com_ok
        gate_hold = torch.where(
            takeover_mask & takeover_ok,
            gate_hold + dt,
            torch.where(takeover_mask, torch.zeros_like(gate_hold), gate_hold),
        )
        takeover_success = takeover_mask & (gate_hold >= takeover_hold_s)
        takeover_timeout = takeover_mask & (state_elapsed >= active_takeover_max_s)
        takeover_complete = takeover_success | takeover_timeout

        root_displacement_yaw = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - halfcycle_start_root_pos
        )[:, :2]
        halfcycle_progress = torch.sum(root_displacement_yaw * command_dir, dim=1)
        takeover_event = takeover_complete
        takeover_success_event = takeover_success
        halfcycle_progress_event = torch.where(
            takeover_complete, halfcycle_progress, halfcycle_progress_event
        )
        halfcycle_target_event = torch.where(
            takeover_complete, 0.75 * target_step, halfcycle_target_event
        )

        # A completed takeover makes the landed swing foot the new stance foot.
        stance_left = torch.where(takeover_complete, new_stance_left, stance_left)
        state = torch.where(takeover_complete, torch.full_like(state, _V11_TRANSFER), state)
        state_elapsed = torch.where(takeover_complete, torch.zeros_like(state_elapsed), state_elapsed)
        gate_hold = torch.where(takeover_complete, torch.zeros_like(gate_hold), gate_hold)
        lift_seen = torch.where(takeover_complete, torch.zeros_like(lift_seen), lift_seen)
        halfcycle_start_root_pos = torch.where(
            takeover_complete.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )

        was_moving = moving
        env._littlegreen_v11_state = state
        env._littlegreen_v11_stance_left = stance_left
        env._littlegreen_v11_next_first_swing_left = next_first_swing_left
        env._littlegreen_v11_was_moving = was_moving
        env._littlegreen_v11_state_elapsed_s = state_elapsed
        env._littlegreen_v11_gate_hold_s = gate_hold
        env._littlegreen_v11_lift_seen = lift_seen
        env._littlegreen_v11_halfcycle_start_root_pos_w = halfcycle_start_root_pos
        env._littlegreen_v11_touchdown_event = touchdown_event
        env._littlegreen_v11_valid_touchdown_event = valid_touchdown_event
        env._littlegreen_v11_touchdown_advance_event_m = touchdown_advance_event
        env._littlegreen_v11_touchdown_target_event_m = touchdown_target_event
        env._littlegreen_v11_takeover_event = takeover_event
        env._littlegreen_v11_takeover_success_event = takeover_success_event
        env._littlegreen_v11_halfcycle_progress_event_m = halfcycle_progress_event
        env._littlegreen_v11_halfcycle_target_event_m = halfcycle_target_event
        env._littlegreen_v11_last_common_step = common_step
    else:
        touchdown_event = _tensor(
            "_littlegreen_v11_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        valid_touchdown_event = _tensor(
            "_littlegreen_v11_valid_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        touchdown_advance_event = _tensor(
            "_littlegreen_v11_touchdown_advance_event_m",
            torch.zeros(num_envs, device=device),
            torch.float32,
        )
        touchdown_target_event = _tensor(
            "_littlegreen_v11_touchdown_target_event_m",
            torch.ones(num_envs, device=device) * active_min_step,
            torch.float32,
        )
        takeover_event = _tensor(
            "_littlegreen_v11_takeover_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        takeover_success_event = _tensor(
            "_littlegreen_v11_takeover_success_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        halfcycle_progress_event = _tensor(
            "_littlegreen_v11_halfcycle_progress_event_m",
            torch.zeros(num_envs, device=device),
            torch.float32,
        )
        halfcycle_target_event = _tensor(
            "_littlegreen_v11_halfcycle_target_event_m",
            torch.ones(num_envs, device=device) * active_min_step,
            torch.float32,
        )

    # Recompute kinematics from the post-transition state for all reward consumers.
    root_yaw = yaw_quat(asset.data.root_quat_w)
    midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
    left_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 0, :] - midpoint)
    right_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 1, :] - midpoint)
    com_rel_yaw = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
    current_stance_pos = torch.where(
        stance_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
    )
    current_swing_pos = torch.where(
        stance_left.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
    )
    swing_delta_yaw = quat_apply_inverse(root_yaw, current_swing_pos - current_stance_pos)[:, :2]
    step_forward = torch.sum(swing_delta_yaw * command_dir, dim=1)
    clearance = current_swing_pos[:, 2] - current_stance_pos[:, 2]

    current_stance_force = torch.where(stance_left, left_force, right_force)
    new_stance_left = ~stance_left
    new_stance_force = torch.where(new_stance_left, left_force, right_force)
    current_ratio = current_stance_force / torch.clamp(total_force, min=1.0e-6)
    new_ratio = new_stance_force / torch.clamp(total_force, min=1.0e-6)

    transfer_progress = torch.clamp(
        state_elapsed / max(active_transfer_max_s, 1.0e-6), min=0.0, max=1.0
    )
    swing_progress = torch.clamp(
        state_elapsed / max(active_swing_max_s, 1.0e-6), min=0.0, max=1.0
    )
    takeover_progress = torch.clamp(
        state_elapsed / max(active_takeover_max_s, 1.0e-6), min=0.0, max=1.0
    )

    boundary = torch.where(stance_left, torch.zeros_like(state_elapsed), torch.full_like(state_elapsed, 0.5))
    swing_span = 0.5 - active_transition_fraction - active_takeover_fraction
    local_phase = torch.where(
        state == _V11_TRANSFER,
        active_transition_fraction * transfer_progress,
        torch.where(
            state == _V11_SWING,
            active_transition_fraction + swing_span * swing_progress,
            torch.where(
                state == _V11_TAKEOVER,
                0.5 - active_takeover_fraction + active_takeover_fraction * takeover_progress,
                torch.zeros_like(state_elapsed),
            ),
        ),
    )
    phase = torch.remainder(boundary + local_phase, 1.0)
    phase = torch.where(moving, phase, torch.zeros_like(phase))

    return {
        "phase": phase,
        "moving": moving,
        "state": state,
        "stance_left": stance_left,
        "new_stance_left": new_stance_left,
        "left_contact": left_contact,
        "right_contact": right_contact,
        "left_force": left_force,
        "right_force": right_force,
        "total_force": total_force,
        "current_stance_ratio": current_ratio,
        "new_stance_ratio": new_ratio,
        "foot_pos_w": foot_pos,
        "midpoint_w": midpoint,
        "left_rel_yaw": left_rel_yaw,
        "right_rel_yaw": right_rel_yaw,
        "com_rel_yaw": com_rel_yaw,
        "clearance": clearance,
        "step_forward": step_forward,
        "target_step": target_step,
        "transfer_progress": transfer_progress,
        "swing_progress": swing_progress,
        "takeover_progress": takeover_progress,
        "touchdown_event": touchdown_event,
        "valid_touchdown_event": valid_touchdown_event,
        "touchdown_advance_event": touchdown_advance_event,
        "touchdown_target_event": touchdown_target_event,
        "takeover_event": takeover_event,
        "takeover_success_event": takeover_success_event,
        "halfcycle_progress_event": halfcycle_progress_event,
        "halfcycle_target_event": halfcycle_target_event,
    }


def event_gated_gait_phase_sin_cos_v11(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.05,
    takeover_fraction: float = 0.04,
) -> torch.Tensor:
    """Return the unchanged two-value phase tail using v11 event-gated semantics."""
    data = _v11_event_gated_gait_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
        takeover_fraction=takeover_fraction,
    )
    angle = 2.0 * math.pi * data["phase"]
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def v11_baseline_corrected_track_lin_vel_xy_yaw_frame_exp(
    env: ManagerBasedRLEnv,
    std: float,
    command_name: str,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.20,
    default_stage_scale: float = 0.65,
) -> torch.Tensor:
    """Velocity tracking whose moving-command reward is exactly zero at zero speed.

    For moving commands, the Gaussian value at measured zero velocity is subtracted
    and the result is normalized.  Rocking backward can therefore become negative,
    while standing commands retain the mature zero-command tracking behavior.
    """
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    measured = quat_apply_inverse(
        yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3]
    )[:, :2]
    error = torch.sum(torch.square(command - measured), dim=1)
    raw = torch.exp(-error / max(float(std) ** 2, 1.0e-8))
    baseline = torch.exp(
        -torch.sum(torch.square(command), dim=1) / max(float(std) ** 2, 1.0e-8)
    )
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > command_threshold
    stage_scale = float(getattr(env, "_littlegreen_v11_tracking_scale", default_stage_scale))
    return torch.where(moving, stage_scale * normalized, raw)


def v11_event_gated_contact_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Signed contact objective for transfer, swing, and post-touchdown takeover."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    left = data["left_contact"]
    right = data["right_contact"]
    both = left & right
    none = (~left) & (~right)
    old_stance_only = torch.where(data["stance_left"], left & (~right), right & (~left))
    new_stance_only = torch.where(data["new_stance_left"], left & (~right), right & (~left))
    state = data["state"]

    transfer_score = torch.where(
        both,
        torch.ones_like(data["phase"]),
        torch.where(old_stance_only, torch.full_like(data["phase"], 0.20), torch.full_like(data["phase"], -0.80)),
    )
    swing_score = torch.where(
        old_stance_only,
        torch.ones_like(data["phase"]),
        torch.where(both, torch.full_like(data["phase"], -0.45), torch.full_like(data["phase"], -1.0)),
    )
    takeover_score = torch.where(
        new_stance_only,
        torch.ones_like(data["phase"]),
        torch.where(both, torch.full_like(data["phase"], 0.35), torch.full_like(data["phase"], -0.90)),
    )
    score = torch.where(
        state == _V11_TRANSFER,
        transfer_score,
        torch.where(state == _V11_SWING, swing_score, takeover_score),
    )
    score = torch.where(none, torch.full_like(score, -1.0), score)
    return score * data["moving"].float()


def v11_support_takeover_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    target_ratio: float = 0.78,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward load on the old stance during swing and on the new foot after touchdown."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    state = data["state"]
    ratio = torch.where(
        state == _V11_TAKEOVER,
        data["new_stance_ratio"],
        data["current_stance_ratio"],
    )
    active_target = float(getattr(env, "_littlegreen_v11_reward_force_ratio", target_ratio))
    signed = torch.clamp((ratio - 0.5) / max(active_target - 0.5, 1.0e-6), min=-1.0, max=1.0)
    signed = torch.where(
        data["total_force"] > force_threshold,
        signed,
        torch.full_like(signed, -1.0),
    )
    return signed * data["moving"].float()


def v11_com_takeover_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    neutral_forward_m: float = 0.070,
    lateral_stance_fraction: float = 0.84,
    support_forward_offset_m: float = -0.015,
    forward_std_m: float = 0.050,
    lateral_std_m: float = 0.040,
) -> torch.Tensor:
    """Move COM with the advancing support foot rather than around the foot midpoint."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    state = data["state"]
    support_left = torch.where(
        state == _V11_TAKEOVER, data["new_stance_left"], data["stance_left"]
    )
    support_rel = torch.where(
        support_left.unsqueeze(-1), data["left_rel_yaw"], data["right_rel_yaw"]
    )
    active_lateral_fraction = float(
        getattr(env, "_littlegreen_v11_com_lateral_stance_fraction", lateral_stance_fraction)
    )
    active_forward_offset = float(
        getattr(env, "_littlegreen_v11_com_support_forward_offset_m", support_forward_offset_m)
    )
    target_x = support_rel[:, 0] + active_forward_offset
    target_y = active_lateral_fraction * support_rel[:, 1]
    dx = (data["com_rel_yaw"][:, 0] - target_x) / max(float(forward_std_m), 1.0e-6)
    dy = (data["com_rel_yaw"][:, 1] - target_y) / max(float(lateral_std_m), 1.0e-6)
    raw = torch.exp(-0.5 * (torch.square(dx) + torch.square(dy)))
    neutral_dx = (float(neutral_forward_m) - target_x) / max(float(forward_std_m), 1.0e-6)
    neutral_dy = (0.0 - target_y) / max(float(lateral_std_m), 1.0e-6)
    baseline = torch.exp(-0.5 * (torch.square(neutral_dx) + torch.square(neutral_dy)))
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    active = (state == _V11_TRANSFER) | (state == _V11_TAKEOVER) | (
        (state == _V11_SWING) & (data["swing_progress"] < 0.20)
    )
    return normalized * active.float() * data["moving"].float()


def v11_swing_clearance_trajectory_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    target_clearance_m: float = 0.026,
    clearance_std_m: float = 0.012,
) -> torch.Tensor:
    """Preserve v10 swing clearance while the state machine waits for touchdown."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    active_target = float(
        getattr(env, "_littlegreen_v11_target_clearance_m", target_clearance_m)
    )
    active_std = float(getattr(env, "_littlegreen_v11_clearance_std_m", clearance_std_m))
    shape = torch.sin(math.pi * data["swing_progress"])
    reference = active_target * shape
    raw = torch.exp(-0.5 * torch.square((data["clearance"] - reference) / max(active_std, 1.0e-6)))
    zero_baseline = torch.exp(-0.5 * torch.square(reference / max(active_std, 1.0e-6)))
    normalized = (raw - zero_baseline) / torch.clamp(1.0 - zero_baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=0.0, max=1.0)
    return normalized * shape * (data["state"] == _V11_SWING).float() * data["moving"].float()


def v11_swing_advance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    clearance_gate_m: float = 0.010,
    gate_width_m: float = 0.006,
    placement_start_progress: float = 0.25,
) -> torch.Tensor:
    """Signed trailing-foot recovery: the swing foot must pass the stance foot."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    active_gate = float(getattr(env, "_littlegreen_v11_clearance_gate_m", clearance_gate_m))
    clearance_gate = torch.clamp(
        (data["clearance"] - active_gate) / max(float(gate_width_m), 1.0e-6), min=0.0, max=1.0
    )
    clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)
    progress_gate = torch.clamp(
        (data["swing_progress"] - placement_start_progress)
        / max(1.0 - placement_start_progress, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    progress_gate = progress_gate * progress_gate * (3.0 - 2.0 * progress_gate)
    signed = torch.clamp(
        data["step_forward"] / torch.clamp(data["target_step"], min=1.0e-6),
        min=-1.0,
        max=1.0,
    )
    active = (data["state"] == _V11_SWING) & data["moving"]
    return signed * clearance_gate * progress_gate * active.float()


def v11_touchdown_advance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Pulse signed reward when a lifted foot lands ahead of the opposite foot."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    signed = torch.clamp(
        data["touchdown_advance_event"]
        / torch.clamp(data["touchdown_target_event"], min=1.0e-6),
        min=-1.0,
        max=1.0,
    )
    signed = torch.where(
        data["valid_touchdown_event"], signed, torch.full_like(signed, -1.0)
    )
    return signed * data["touchdown_event"].float()


def v11_takeover_completion_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Pulse +1 for a real COM/load takeover and -1 for a takeover timeout."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    score = torch.where(
        data["takeover_success_event"],
        torch.ones_like(data["phase"]),
        torch.full_like(data["phase"], -1.0),
    )
    return score * data["takeover_event"].float()


def v11_halfcycle_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Pulse signed base displacement when the new foot accepts body weight."""
    data = _v11_event_gated_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    score = torch.clamp(
        data["halfcycle_progress_event"]
        / torch.clamp(data["halfcycle_target_event"], min=1.0e-6),
        min=-1.0,
        max=1.0,
    )
    return score * data["takeover_event"].float()


# -----------------------------------------------------------------------------
# Littlegreen v2.0.0 v11a bounded hybrid gait scaffold
# -----------------------------------------------------------------------------


def _v11a_hybrid_gait_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.06,
    force_threshold: float = 1.0,
    soft_gate_floor: float = 1.0,
    late_swing_start: float = 0.78,
    event_hold_s: float = 0.10,
    lift_gate_m: float = 0.010,
    touchdown_min_progress: float = 0.28,
    target_stance_force_ratio: float = 0.76,
    takeover_hold_s: float = 0.06,
    takeover_deadline_progress: float = 0.24,
    com_lateral_stance_fraction: float = 0.85,
    com_support_forward_offset_m: float = -0.015,
    com_forward_tolerance_m: float = 0.055,
    com_lateral_tolerance_m: float = 0.045,
    min_step_m: float = 0.018,
    max_step_m: float = 0.050,
    step_length_scale: float = 0.10,
) -> dict[str, torch.Tensor]:
    """Return v11a's v10-compatible phase plus bounded progression events.

    Stage 0 is mathematically identical to the v10 command-synchronized phase:
    the phase advances at one clock rate and never waits for a physical event.
    Later curriculum stages may *slow* the clock when transfer/lift/advance gates
    are incomplete, but ``soft_gate_floor`` is always positive, so phase can never
    freeze and the permanent-one-foot-up v11 exploit is unavailable.

    Touchdown, takeover, and half-cycle progress are measured independently from
    the observation clock.  Successful event rewards are held briefly rather than
    emitted for only one 20 ms step.  A failed swing enters a bounded recovery flag;
    it does not change the stance side or award step credit.
    """
    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    yaw_abs = torch.abs(command[:, 2]) if command.shape[1] > 2 else torch.zeros_like(linear_norm)
    moving = (linear_norm > linear_command_threshold) | (yaw_abs > yaw_command_threshold)
    num_envs = command.shape[0]
    device = command.device

    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    if foot_pos.shape[1] < 2:
        raise ValueError("v11a requires two ordered foot bodies (left, right)")

    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        raise ValueError("v11a requires two ordered foot contact channels (left, right)")
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]

    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.abs(forces[..., 2]).max(dim=1)[0]
    left_force = vertical[:, 0]
    right_force = vertical[:, 1]
    total_force = left_force + right_force

    active_period_s = float(getattr(env, "_littlegreen_v11a_gait_period_s", period_s))
    active_transition_fraction = float(
        getattr(env, "_littlegreen_v11a_transition_fraction", transition_fraction)
    )
    active_soft_gate_floor = float(
        getattr(env, "_littlegreen_v11a_soft_gate_floor", soft_gate_floor)
    )
    active_late_swing_start = float(
        getattr(env, "_littlegreen_v11a_late_swing_start", late_swing_start)
    )
    active_event_hold_s = float(getattr(env, "_littlegreen_v11a_event_hold_s", event_hold_s))
    active_lift_gate_m = float(getattr(env, "_littlegreen_v11a_clearance_gate_m", lift_gate_m))
    active_force_ratio = float(
        getattr(env, "_littlegreen_v11a_target_stance_force_ratio", target_stance_force_ratio)
    )
    active_lateral_fraction = float(
        getattr(env, "_littlegreen_v11a_com_lateral_stance_fraction", com_lateral_stance_fraction)
    )
    active_support_forward_offset = float(
        getattr(env, "_littlegreen_v11a_com_support_forward_offset_m", com_support_forward_offset_m)
    )
    active_min_step = float(getattr(env, "_littlegreen_v11a_min_step_m", min_step_m))
    active_max_step = float(getattr(env, "_littlegreen_v11a_max_step_m", max_step_m))
    active_step_scale = float(
        getattr(env, "_littlegreen_v11a_step_length_scale", step_length_scale)
    )
    progression_scale = float(getattr(env, "_littlegreen_v11a_progression_scale", 0.20))
    contact_scale = float(getattr(env, "_littlegreen_v11a_contact_scale", 1.0))

    if active_period_s <= 1.0e-6:
        raise ValueError("v11a gait period must be positive")
    if not 0.0 < active_transition_fraction < 0.25:
        raise ValueError("v11a transition_fraction must be in (0, 0.25)")
    if not 0.0 < active_soft_gate_floor <= 1.0:
        raise ValueError("v11a soft_gate_floor must be in (0, 1]")
    if not 0.50 < active_late_swing_start < 1.0:
        raise ValueError("v11a late_swing_start must be in (0.50, 1.0)")

    parity_first_swing_left = (torch.arange(num_envs, device=device) % 2) == 0

    def _tensor(name: str, default: torch.Tensor, dtype: torch.dtype | None = None) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    phase = _tensor("_littlegreen_v11a_gait_phase", torch.zeros(num_envs, device=device))
    was_moving = _tensor(
        "_littlegreen_v11a_was_moving", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    next_first_swing_left = _tensor(
        "_littlegreen_v11a_next_first_swing_left", parity_first_swing_left, torch.bool
    )
    active_first_swing_left = _tensor(
        "_littlegreen_v11a_active_first_swing_left", parity_first_swing_left, torch.bool
    )
    prev_left_stance = _tensor(
        "_littlegreen_v11a_prev_left_stance", phase < 0.5, torch.bool
    )
    lift_seen = _tensor(
        "_littlegreen_v11a_lift_seen", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    touchdown_seen = _tensor(
        "_littlegreen_v11a_touchdown_seen", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    prev_swing_contact = _tensor(
        "_littlegreen_v11a_prev_swing_contact", torch.ones(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    takeover_pending = _tensor(
        "_littlegreen_v11a_takeover_pending", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    takeover_gate_hold = _tensor(
        "_littlegreen_v11a_takeover_gate_hold_s", torch.zeros(num_envs, device=device)
    )
    recovery_needed = _tensor(
        "_littlegreen_v11a_recovery_needed", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
    )
    halfcycle_start_root_pos = _tensor(
        "_littlegreen_v11a_halfcycle_start_root_pos_w", asset.data.root_pos_w.clone()
    )

    touchdown_hold = _tensor("_littlegreen_v11a_touchdown_hold_s", torch.zeros(num_envs, device=device))
    touchdown_score = _tensor("_littlegreen_v11a_touchdown_score", torch.zeros(num_envs, device=device))
    takeover_hold = _tensor("_littlegreen_v11a_takeover_hold_s", torch.zeros(num_envs, device=device))
    takeover_score = _tensor("_littlegreen_v11a_takeover_score", torch.zeros(num_envs, device=device))
    progress_hold = _tensor("_littlegreen_v11a_progress_hold_s", torch.zeros(num_envs, device=device))
    progress_score = _tensor("_littlegreen_v11a_progress_score", torch.zeros(num_envs, device=device))
    failure_hold = _tensor("_littlegreen_v11a_failure_hold_s", torch.zeros(num_envs, device=device))
    failure_score = _tensor("_littlegreen_v11a_failure_score", torch.zeros(num_envs, device=device))
    recovery_hold = _tensor("_littlegreen_v11a_recovery_hold_s", torch.zeros(num_envs, device=device))

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where((linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir)
    target_step = torch.clamp(
        linear_norm * active_period_s * active_step_scale,
        min=active_min_step,
        max=active_max_step,
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11a_last_common_step", -1))
    touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    takeover_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    halfcycle_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    failed_halfcycle_event = torch.zeros(num_envs, device=device, dtype=torch.bool)

    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11a_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v11a_last_episode_length = current_episode_length.clone()

        # Decay held event credit before any new event refreshes it.
        touchdown_hold = torch.clamp(touchdown_hold - dt, min=0.0)
        takeover_hold = torch.clamp(takeover_hold - dt, min=0.0)
        progress_hold = torch.clamp(progress_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        recovery_hold = torch.clamp(recovery_hold - dt, min=0.0)

        phase = torch.where(reset_mask, torch.zeros_like(phase), phase)
        was_moving = torch.where(reset_mask, torch.zeros_like(was_moving), was_moving)
        next_first_swing_left = torch.where(reset_mask, parity_first_swing_left, next_first_swing_left)
        active_first_swing_left = torch.where(reset_mask, parity_first_swing_left, active_first_swing_left)
        prev_left_stance = torch.where(reset_mask, torch.ones_like(prev_left_stance), prev_left_stance)
        lift_seen = torch.where(reset_mask, torch.zeros_like(lift_seen), lift_seen)
        touchdown_seen = torch.where(reset_mask, torch.zeros_like(touchdown_seen), touchdown_seen)
        takeover_pending = torch.where(reset_mask, torch.zeros_like(takeover_pending), takeover_pending)
        takeover_gate_hold = torch.where(reset_mask, torch.zeros_like(takeover_gate_hold), takeover_gate_hold)
        recovery_needed = torch.where(reset_mask, torch.zeros_like(recovery_needed), recovery_needed)
        halfcycle_start_root_pos = torch.where(
            reset_mask.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        touchdown_hold = torch.where(reset_mask, torch.zeros_like(touchdown_hold), touchdown_hold)
        takeover_hold = torch.where(reset_mask, torch.zeros_like(takeover_hold), takeover_hold)
        progress_hold = torch.where(reset_mask, torch.zeros_like(progress_hold), progress_hold)
        failure_hold = torch.where(reset_mask, torch.zeros_like(failure_hold), failure_hold)
        recovery_hold = torch.where(reset_mask, torch.zeros_like(recovery_hold), recovery_hold)
        touchdown_score = torch.where(reset_mask, torch.zeros_like(touchdown_score), touchdown_score)
        takeover_score = torch.where(reset_mask, torch.zeros_like(takeover_score), takeover_score)
        progress_score = torch.where(reset_mask, torch.zeros_like(progress_score), progress_score)
        failure_score = torch.where(reset_mask, torch.zeros_like(failure_score), failure_score)

        onset = moving & (~was_moving)
        active_first_swing_left = torch.where(onset, next_first_swing_left, active_first_swing_left)
        next_first_swing_left = torch.where(onset, ~next_first_swing_left, next_first_swing_left)
        onset_boundary = torch.where(
            active_first_swing_left,
            torch.full_like(phase, 0.5),
            torch.zeros_like(phase),
        )
        phase = torch.where(onset, onset_boundary, phase)
        halfcycle_start_root_pos = torch.where(
            onset.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        lift_seen = torch.where(onset, torch.zeros_like(lift_seen), lift_seen)
        touchdown_seen = torch.where(onset, torch.zeros_like(touchdown_seen), touchdown_seen)
        takeover_pending = torch.where(onset, torch.zeros_like(takeover_pending), takeover_pending)
        recovery_needed = torch.where(onset, torch.zeros_like(recovery_needed), recovery_needed)

        # Current schedule and kinematics determine only a bounded clock slowdown.
        current_left_stance = phase < 0.5
        half_phase = torch.remainder(2.0 * phase, 1.0)
        half_transition = 2.0 * active_transition_fraction
        current_transition = half_phase < half_transition
        current_swing_progress = torch.clamp(
            (half_phase - half_transition) / max(1.0 - half_transition, 1.0e-6),
            min=0.0,
            max=1.0,
        )
        root_yaw = yaw_quat(asset.data.root_quat_w)
        midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
        left_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 0, :] - midpoint)
        right_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 1, :] - midpoint)
        com_rel_yaw = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
        stance_rel = torch.where(current_left_stance.unsqueeze(-1), left_rel_yaw, right_rel_yaw)
        target_x = stance_rel[:, 0] + active_support_forward_offset
        target_y = active_lateral_fraction * stance_rel[:, 1]
        com_gate = (
            (torch.abs(com_rel_yaw[:, 0] - target_x) <= com_forward_tolerance_m)
            & (torch.abs(com_rel_yaw[:, 1] - target_y) <= com_lateral_tolerance_m)
        )
        stance_pos = torch.where(
            current_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        swing_pos = torch.where(
            current_left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        swing_delta = quat_apply_inverse(root_yaw, swing_pos - stance_pos)[:, :2]
        step_forward_now = torch.sum(swing_delta * command_dir, dim=1)
        clearance_now = swing_pos[:, 2] - stance_pos[:, 2]
        swing_contact_now = torch.where(current_left_stance, right_contact, left_contact)
        both_contact_now = left_contact & right_contact

        lift_seen = lift_seen | (
            moving & (~current_transition) & (clearance_now >= active_lift_gate_m)
        )
        contact_rise = swing_contact_now & (~prev_swing_contact)
        valid_touchdown = (
            moving
            & (~current_transition)
            & lift_seen
            & contact_rise
            & (current_swing_progress >= touchdown_min_progress)
        )
        touchdown_event = valid_touchdown & (~touchdown_seen)
        touchdown_seen = touchdown_seen | touchdown_event
        touchdown_new_score = torch.clamp(
            step_forward_now / torch.clamp(target_step, min=1.0e-6), min=-1.0, max=1.0
        )
        touchdown_score = torch.where(touchdown_event, touchdown_new_score, touchdown_score)
        touchdown_hold = torch.where(
            touchdown_event, torch.full_like(touchdown_hold, active_event_hold_s), touchdown_hold
        )

        transfer_gate_ok = com_gate
        late_swing = (~current_transition) & (current_swing_progress >= active_late_swing_start)
        swing_gate_ok = lift_seen & (
            (step_forward_now >= 0.35 * target_step) | touchdown_seen
        )
        gate_ok = torch.where(current_transition, transfer_gate_ok, (~late_swing) | swing_gate_ok)
        speed_scale = torch.where(
            moving & (~gate_ok),
            torch.full_like(phase, active_soft_gate_floor),
            torch.ones_like(phase),
        )
        # No state may freeze: floor is strictly positive and Stage 0 uses 1.0.
        advance = dt / active_period_s
        phase = torch.where(
            moving & (~onset),
            torch.remainder(phase + advance * speed_scale, 1.0),
            phase,
        )
        phase = torch.where(moving, phase, torch.zeros_like(phase))

        new_left_stance = phase < 0.5
        halfcycle_changed = moving & (~onset) & (new_left_stance != current_left_stance)
        halfcycle_event = halfcycle_changed
        root_displacement = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - halfcycle_start_root_pos
        )[:, :2]
        halfcycle_progress = torch.sum(root_displacement * command_dir, dim=1)
        halfcycle_target = torch.clamp(0.75 * target_step, min=active_min_step * 0.60)
        progress_new_score = torch.clamp(
            halfcycle_progress / torch.clamp(halfcycle_target, min=1.0e-6), min=-1.0, max=1.0
        )
        progress_score = torch.where(halfcycle_changed, progress_new_score, progress_score)
        progress_hold = torch.where(
            halfcycle_changed, torch.full_like(progress_hold, active_event_hold_s), progress_hold
        )

        successful_halfcycle = halfcycle_changed & touchdown_seen
        failed_halfcycle_event = halfcycle_changed & (~touchdown_seen)
        failure_score = torch.where(failed_halfcycle_event, torch.full_like(failure_score, -1.0), failure_score)
        failure_hold = torch.where(
            failed_halfcycle_event, torch.full_like(failure_hold, active_event_hold_s), failure_hold
        )
        takeover_pending = torch.where(halfcycle_changed, successful_halfcycle, takeover_pending)
        recovery_needed = torch.where(halfcycle_changed, failed_halfcycle_event, recovery_needed)
        halfcycle_start_root_pos = torch.where(
            halfcycle_changed.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        lift_seen = torch.where(halfcycle_changed, torch.zeros_like(lift_seen), lift_seen)
        touchdown_seen = torch.where(halfcycle_changed, torch.zeros_like(touchdown_seen), touchdown_seen)

        # Newly landed foot is now the scheduled stance foot.  Confirm load/COM takeover
        # during the bounded transition/early-swing interval; never stop the phase clock.
        post_half_phase = torch.remainder(2.0 * phase, 1.0)
        post_transition = post_half_phase < half_transition
        post_swing_progress = torch.clamp(
            (post_half_phase - half_transition) / max(1.0 - half_transition, 1.0e-6),
            min=0.0,
            max=1.0,
        )
        post_stance_force = torch.where(new_left_stance, left_force, right_force)
        post_ratio = post_stance_force / torch.clamp(total_force, min=1.0e-6)
        post_stance_rel = torch.where(new_left_stance.unsqueeze(-1), left_rel_yaw, right_rel_yaw)
        post_target_x = post_stance_rel[:, 0] + active_support_forward_offset
        post_target_y = active_lateral_fraction * post_stance_rel[:, 1]
        post_com_ok = (
            (torch.abs(com_rel_yaw[:, 0] - post_target_x) <= com_forward_tolerance_m)
            & (torch.abs(com_rel_yaw[:, 1] - post_target_y) <= com_lateral_tolerance_m)
        )
        takeover_ok = (post_ratio >= active_force_ratio) & post_com_ok
        takeover_gate_hold = torch.where(
            takeover_pending & takeover_ok,
            takeover_gate_hold + dt,
            torch.where(takeover_pending, torch.zeros_like(takeover_gate_hold), takeover_gate_hold),
        )
        takeover_success = takeover_pending & (takeover_gate_hold >= takeover_hold_s)
        takeover_deadline = takeover_pending & (~post_transition) & (
            post_swing_progress >= takeover_deadline_progress
        )
        takeover_failure = takeover_deadline & (~takeover_success)
        takeover_event = takeover_success | takeover_failure
        takeover_score = torch.where(
            takeover_success,
            torch.ones_like(takeover_score),
            torch.where(takeover_failure, torch.full_like(takeover_score, -1.0), takeover_score),
        )
        takeover_hold = torch.where(
            takeover_event, torch.full_like(takeover_hold, active_event_hold_s), takeover_hold
        )
        takeover_pending = torch.where(takeover_event, torch.zeros_like(takeover_pending), takeover_pending)
        takeover_gate_hold = torch.where(takeover_event, torch.zeros_like(takeover_gate_hold), takeover_gate_hold)

        # Recovery is successful only when both feet return to contact during the next
        # transfer window.  This credit is bounded and never grants touchdown progress.
        recovery_success = recovery_needed & post_transition & both_contact_now
        recovery_hold = torch.where(
            recovery_success, torch.full_like(recovery_hold, active_event_hold_s), recovery_hold
        )
        recovery_needed = torch.where(recovery_success, torch.zeros_like(recovery_needed), recovery_needed)

        prev_swing_contact = torch.where(
            halfcycle_changed,
            torch.where(new_left_stance, right_contact, left_contact),
            swing_contact_now,
        )
        prev_left_stance = new_left_stance
        was_moving = moving

        # Standing cancels all unfinished progression state but preserves event holds
        # only for the current simulator step.
        phase = torch.where(moving, phase, torch.zeros_like(phase))
        lift_seen = torch.where(moving, lift_seen, torch.zeros_like(lift_seen))
        touchdown_seen = torch.where(moving, touchdown_seen, torch.zeros_like(touchdown_seen))
        takeover_pending = torch.where(moving, takeover_pending, torch.zeros_like(takeover_pending))
        recovery_needed = torch.where(moving, recovery_needed, torch.zeros_like(recovery_needed))
        takeover_gate_hold = torch.where(moving, takeover_gate_hold, torch.zeros_like(takeover_gate_hold))

        env._littlegreen_v11a_gait_phase = phase
        env._littlegreen_v11a_was_moving = was_moving
        env._littlegreen_v11a_next_first_swing_left = next_first_swing_left
        env._littlegreen_v11a_active_first_swing_left = active_first_swing_left
        env._littlegreen_v11a_prev_left_stance = prev_left_stance
        env._littlegreen_v11a_lift_seen = lift_seen
        env._littlegreen_v11a_touchdown_seen = touchdown_seen
        env._littlegreen_v11a_prev_swing_contact = prev_swing_contact
        env._littlegreen_v11a_takeover_pending = takeover_pending
        env._littlegreen_v11a_takeover_gate_hold_s = takeover_gate_hold
        env._littlegreen_v11a_recovery_needed = recovery_needed
        env._littlegreen_v11a_halfcycle_start_root_pos_w = halfcycle_start_root_pos
        env._littlegreen_v11a_touchdown_hold_s = touchdown_hold
        env._littlegreen_v11a_touchdown_score = touchdown_score
        env._littlegreen_v11a_takeover_hold_s = takeover_hold
        env._littlegreen_v11a_takeover_score = takeover_score
        env._littlegreen_v11a_progress_hold_s = progress_hold
        env._littlegreen_v11a_progress_score = progress_score
        env._littlegreen_v11a_failure_hold_s = failure_hold
        env._littlegreen_v11a_failure_score = failure_score
        env._littlegreen_v11a_recovery_hold_s = recovery_hold
        env._littlegreen_v11a_touchdown_event = touchdown_event
        env._littlegreen_v11a_takeover_event = takeover_event
        env._littlegreen_v11a_halfcycle_event = halfcycle_event
        env._littlegreen_v11a_failed_halfcycle_event = failed_halfcycle_event
        env._littlegreen_v11a_last_common_step = common_step
    else:
        touchdown_event = _tensor(
            "_littlegreen_v11a_touchdown_event", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
        )
        takeover_event = _tensor(
            "_littlegreen_v11a_takeover_event", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
        )
        halfcycle_event = _tensor(
            "_littlegreen_v11a_halfcycle_event", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
        )
        failed_halfcycle_event = _tensor(
            "_littlegreen_v11a_failed_halfcycle_event", torch.zeros(num_envs, device=device, dtype=torch.bool), torch.bool
        )

    # Post-update schedule/kinematics shared by every reward term.
    left_stance = phase < 0.5
    half_phase = torch.remainder(2.0 * phase, 1.0)
    half_transition = 2.0 * active_transition_fraction
    transition = half_phase < half_transition
    swing_progress = torch.clamp(
        (half_phase - half_transition) / max(1.0 - half_transition, 1.0e-6), min=0.0, max=1.0
    )
    transfer_progress = torch.clamp(half_phase / max(half_transition, 1.0e-6), min=0.0, max=1.0)
    root_yaw = yaw_quat(asset.data.root_quat_w)
    midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
    left_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 0, :] - midpoint)
    right_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 1, :] - midpoint)
    com_rel_yaw = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
    stance_pos = torch.where(left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :])
    swing_pos = torch.where(left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :])
    swing_delta = quat_apply_inverse(root_yaw, swing_pos - stance_pos)[:, :2]
    step_forward = torch.sum(swing_delta * command_dir, dim=1)
    clearance = swing_pos[:, 2] - stance_pos[:, 2]
    stance_force = torch.where(left_stance, left_force, right_force)
    stance_ratio = stance_force / torch.clamp(total_force, min=1.0e-6)
    swing_contact = torch.where(left_stance, right_contact, left_contact)
    late_swing = (~transition) & (swing_progress >= active_late_swing_start)
    swing_overrun = late_swing & (~swing_contact) & (~touchdown_seen)

    return {
        "phase": phase,
        "moving": moving,
        "transition": transition,
        "left_stance": left_stance,
        "swing_progress": swing_progress,
        "transfer_progress": transfer_progress,
        "left_contact": left_contact,
        "right_contact": right_contact,
        "swing_contact": swing_contact,
        "left_force": left_force,
        "right_force": right_force,
        "total_force": total_force,
        "stance_ratio": stance_ratio,
        "foot_pos_w": foot_pos,
        "left_rel_yaw": left_rel_yaw,
        "right_rel_yaw": right_rel_yaw,
        "com_rel_yaw": com_rel_yaw,
        "clearance": clearance,
        "step_forward": step_forward,
        "target_step": target_step,
        "lift_seen": lift_seen,
        "touchdown_seen": touchdown_seen,
        "takeover_pending": takeover_pending,
        "recovery_needed": recovery_needed,
        "swing_overrun": swing_overrun,
        "touchdown_event": touchdown_event,
        "takeover_event": takeover_event,
        "halfcycle_event": halfcycle_event,
        "failed_halfcycle_event": failed_halfcycle_event,
        "touchdown_held_score": torch.where(touchdown_hold > 0.0, touchdown_score, torch.zeros_like(touchdown_score)),
        "takeover_held_score": torch.where(takeover_hold > 0.0, takeover_score, torch.zeros_like(takeover_score)),
        "progress_held_score": torch.where(progress_hold > 0.0, progress_score, torch.zeros_like(progress_score)),
        "failure_held_score": torch.where(failure_hold > 0.0, failure_score, torch.zeros_like(failure_score)),
        "recovery_held": recovery_hold > 0.0,
        "progression_scale": torch.full_like(phase, progression_scale),
        "contact_scale": torch.full_like(phase, contact_scale),
    }


def hybrid_gait_phase_sin_cos_v11a(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.06,
) -> torch.Tensor:
    """Return the unchanged 2-D phase tail with bounded v10-compatible semantics."""
    data = _v11a_hybrid_gait_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    angle = 2.0 * math.pi * data["phase"]
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def v11a_baseline_corrected_track_lin_vel_xy_yaw_frame_exp(
    env: ManagerBasedRLEnv,
    std: float,
    command_name: str,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.20,
    default_stage_scale: float = 0.70,
) -> torch.Tensor:
    """v11 zero-motion-corrected velocity reward with the v11a curriculum scale."""
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    measured = quat_apply_inverse(
        yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3]
    )[:, :2]
    error = torch.sum(torch.square(command - measured), dim=1)
    raw = torch.exp(-error / max(float(std) ** 2, 1.0e-8))
    baseline = torch.exp(
        -torch.sum(torch.square(command), dim=1) / max(float(std) ** 2, 1.0e-8)
    )
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > command_threshold
    stage_scale = float(getattr(env, "_littlegreen_v11a_tracking_scale", default_stage_scale))
    return torch.where(moving, stage_scale * normalized, raw)


def v11a_signed_phase_contact_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """v10 contact rhythm with late-swing credit decay and no indefinite single support."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    left = data["left_contact"]
    right = data["right_contact"]
    both = left & right
    none = (~left) & (~right)
    stance_only = torch.where(data["left_stance"], left & (~right), right & (~left))
    wrong_only = torch.where(data["left_stance"], right & (~left), left & (~right))
    transition_score = torch.where(
        both, torch.ones_like(data["phase"]),
        torch.where(stance_only, torch.full_like(data["phase"], 0.20), torch.full_like(data["phase"], -0.80)),
    )
    late_decay = torch.clamp((1.0 - data["swing_progress"]) / 0.22, min=0.0, max=1.0)
    stance_credit = torch.where(data["touchdown_seen"], torch.zeros_like(late_decay), late_decay)
    swing_score = torch.where(
        stance_only,
        stance_credit,
        torch.where(both, torch.full_like(data["phase"], -0.45), torch.full_like(data["phase"], -1.0)),
    )
    swing_score = torch.where(wrong_only, torch.full_like(swing_score, -1.0), swing_score)
    score = torch.where(data["transition"], transition_score, swing_score)
    score = torch.where(none, torch.full_like(score, -1.0), score)
    return data["contact_scale"] * score * data["moving"].float()


def v11a_support_force_transfer_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    force_threshold: float = 1.0,
    early_swing_fraction: float = 0.22,
) -> torch.Tensor:
    """Reward transfer only during the transfer window and early swing."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    target = float(getattr(env, "_littlegreen_v11a_target_stance_force_ratio", 0.76))
    signed = torch.clamp((data["stance_ratio"] - 0.5) / max(target - 0.5, 1.0e-6), min=-1.0, max=1.0)
    signed = torch.where(
        data["total_force"] > force_threshold, signed, torch.full_like(signed, -1.0)
    )
    active = data["transition"] | ((~data["transition"]) & (data["swing_progress"] < early_swing_fraction))
    return signed * active.float() * data["moving"].float()


def v11a_phase_com_shift_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    neutral_forward_m: float = 0.070,
    forward_std_m: float = 0.040,
    lateral_std_m: float = 0.034,
    early_swing_fraction: float = 0.28,
) -> torch.Tensor:
    """Preserve v10's alternating COM transfer with a bounded active window."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    support_rel = torch.where(
        data["left_stance"].unsqueeze(-1), data["left_rel_yaw"], data["right_rel_yaw"]
    )
    lateral_fraction = float(getattr(env, "_littlegreen_v11a_com_lateral_stance_fraction", 0.85))
    forward_offset = float(getattr(env, "_littlegreen_v11a_com_support_forward_offset_m", -0.015))
    target_x = support_rel[:, 0] + forward_offset
    target_y = lateral_fraction * support_rel[:, 1]
    dx = (data["com_rel_yaw"][:, 0] - target_x) / max(float(forward_std_m), 1.0e-6)
    dy = (data["com_rel_yaw"][:, 1] - target_y) / max(float(lateral_std_m), 1.0e-6)
    raw = torch.exp(-0.5 * (torch.square(dx) + torch.square(dy)))
    neutral_dx = (float(neutral_forward_m) - target_x) / max(float(forward_std_m), 1.0e-6)
    neutral_dy = (0.0 - target_y) / max(float(lateral_std_m), 1.0e-6)
    baseline = torch.exp(-0.5 * (torch.square(neutral_dx) + torch.square(neutral_dy)))
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    active = data["transition"] | ((~data["transition"]) & (data["swing_progress"] < early_swing_fraction))
    return normalized * active.float() * data["moving"].float()


def v11a_swing_clearance_trajectory_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    target_clearance_m: float = 0.028,
    clearance_std_m: float = 0.012,
) -> torch.Tensor:
    """Preserve v10's zero-baseline clearance trajectory."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    active_target = float(getattr(env, "_littlegreen_v11a_target_clearance_m", target_clearance_m))
    active_std = float(getattr(env, "_littlegreen_v11a_clearance_std_m", clearance_std_m))
    shape = torch.sin(math.pi * data["swing_progress"])
    reference = active_target * shape
    raw = torch.exp(-0.5 * torch.square((data["clearance"] - reference) / max(active_std, 1.0e-6)))
    zero_baseline = torch.exp(-0.5 * torch.square(reference / max(active_std, 1.0e-6)))
    normalized = (raw - zero_baseline) / torch.clamp(1.0 - zero_baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=0.0, max=1.0)
    return normalized * shape * (~data["transition"]).float() * data["moving"].float()


def v11a_clearance_gated_step_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    gate_width_m: float = 0.006,
    placement_start_progress: float = 0.30,
) -> torch.Tensor:
    """Signed, command-relative swing advance gated by actual clearance."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    gate = float(getattr(env, "_littlegreen_v11a_clearance_gate_m", 0.010))
    clearance_gate = torch.clamp(
        (data["clearance"] - gate) / max(float(gate_width_m), 1.0e-6), min=0.0, max=1.0
    )
    clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)
    progress_gate = torch.clamp(
        (data["swing_progress"] - placement_start_progress) / max(1.0 - placement_start_progress, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    progress_gate = progress_gate * progress_gate * (3.0 - 2.0 * progress_gate)
    signed = torch.clamp(
        data["step_forward"] / torch.clamp(data["target_step"], min=1.0e-6), min=-1.0, max=1.0
    )
    active = (~data["transition"]) & data["moving"]
    return data["progression_scale"] * signed * clearance_gate * progress_gate * active.float()


def v11a_touchdown_advance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held signed touchdown advance; no contact means no touchdown credit."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["touchdown_held_score"] * data["moving"].float()


def v11a_takeover_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held +1/-1 signal for bounded new-foot COM/load takeover."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["takeover_held_score"] * data["moving"].float()


def v11a_halfcycle_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held signed base displacement at every bounded half-cycle boundary."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["progress_held_score"] * data["moving"].float()


def v11a_swing_deadline_recovery_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Close the v11 loophole: penalize overrun/failure and reward bounded recovery contact."""
    data = _v11a_hybrid_gait_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    overrun = -torch.clamp(
        (data["swing_progress"] - 0.78) / 0.22, min=0.0, max=1.0
    ) * data["swing_overrun"].float()
    failure = data["failure_held_score"]
    recovery = data["recovery_held"].float()
    return (overrun + failure + 0.50 * recovery) * data["moving"].float()


# -----------------------------------------------------------------------------
# Littlegreen v2.0.0 v11b confirmed-stance takeover scaffold
# -----------------------------------------------------------------------------


def _v11b_confirmed_takeover_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.055,
    force_threshold: float = 1.0,
    clean_flight_s: float = 0.05,
    lift_gate_m: float = 0.011,
    touchdown_min_progress: float = 0.30,
    min_pass_m: float = 0.012,
    valid_step_fraction: float = 0.55,
    target_stance_force_ratio: float = 0.80,
    takeover_gate_hold_s: float = 0.08,
    takeover_max_s: float = 0.14,
    recovery_contact_hold_s: float = 0.06,
    recovery_max_s: float = 0.20,
    com_takeover_forward_offset_m: float = 0.008,
    com_takeover_forward_tolerance_m: float = 0.028,
    com_takeover_lateral_tolerance_m: float = 0.030,
    min_step_m: float = 0.018,
    max_step_m: float = 0.045,
    step_length_scale: float = 0.11,
    event_hold_s: float = 0.10,
) -> dict[str, torch.Tensor]:
    """Return v11b confirmed-stance gait state and held progression events.

    The phase clock advances normally through transfer and swing, but a foot is
    not promoted to stance merely because the clock crossed a half-cycle.  The
    selected swing foot must complete clean contact-free flight, land ahead of
    the stance-foot anchor, and then accept COM/load for a bounded hold.  A
    same-place/backward touchdown or missing touchdown enters a short recovery;
    the previous confirmed stance remains authoritative and the same trailing
    foot is retried.  Takeover and recovery holds are bounded, so no phase state
    can freeze indefinitely.
    """
    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    yaw_abs = torch.abs(command[:, 2]) if command.shape[1] > 2 else torch.zeros_like(linear_norm)
    moving = (linear_norm > linear_command_threshold) | (yaw_abs > yaw_command_threshold)
    num_envs = command.shape[0]
    device = command.device

    asset = env.scene[asset_cfg.name]
    foot_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :3]
    if foot_pos.shape[1] < 2:
        raise ValueError("v11b requires two ordered foot bodies (left, right)")

    contacts = _foot_contacts(env, sensor_cfg, force_threshold=force_threshold)
    if contacts.shape[1] < 2:
        raise ValueError("v11b requires two ordered foot contact channels (left, right)")
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    both_contact = left_contact & right_contact
    no_contact = (~left_contact) & (~right_contact)

    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.abs(forces[..., 2]).max(dim=1)[0]
    left_force = vertical[:, 0]
    right_force = vertical[:, 1]
    total_force = left_force + right_force

    active_period_s = float(getattr(env, "_littlegreen_v11b_gait_period_s", period_s))
    active_transition_fraction = float(
        getattr(env, "_littlegreen_v11b_transition_fraction", transition_fraction)
    )
    active_clean_flight_s = float(
        getattr(env, "_littlegreen_v11b_clean_flight_s", clean_flight_s)
    )
    active_lift_gate_m = float(getattr(env, "_littlegreen_v11b_clearance_gate_m", lift_gate_m))
    active_min_pass_m = float(getattr(env, "_littlegreen_v11b_min_pass_m", min_pass_m))
    active_valid_step_fraction = float(
        getattr(env, "_littlegreen_v11b_valid_step_fraction", valid_step_fraction)
    )
    active_force_ratio = float(
        getattr(env, "_littlegreen_v11b_target_stance_force_ratio", target_stance_force_ratio)
    )
    active_takeover_gate_hold_s = float(
        getattr(env, "_littlegreen_v11b_takeover_gate_hold_s", takeover_gate_hold_s)
    )
    active_takeover_max_s = float(
        getattr(env, "_littlegreen_v11b_takeover_max_s", takeover_max_s)
    )
    active_recovery_contact_hold_s = float(
        getattr(env, "_littlegreen_v11b_recovery_contact_hold_s", recovery_contact_hold_s)
    )
    active_recovery_max_s = float(
        getattr(env, "_littlegreen_v11b_recovery_max_s", recovery_max_s)
    )
    active_com_forward_offset = float(
        getattr(env, "_littlegreen_v11b_com_takeover_forward_offset_m", com_takeover_forward_offset_m)
    )
    active_com_forward_tolerance = float(
        getattr(
            env,
            "_littlegreen_v11b_com_takeover_forward_tolerance_m",
            com_takeover_forward_tolerance_m,
        )
    )
    active_com_lateral_tolerance = float(
        getattr(
            env,
            "_littlegreen_v11b_com_takeover_lateral_tolerance_m",
            com_takeover_lateral_tolerance_m,
        )
    )
    active_min_step = float(getattr(env, "_littlegreen_v11b_min_step_m", min_step_m))
    active_max_step = float(getattr(env, "_littlegreen_v11b_max_step_m", max_step_m))
    active_step_scale = float(
        getattr(env, "_littlegreen_v11b_step_length_scale", step_length_scale)
    )
    active_event_hold_s = float(getattr(env, "_littlegreen_v11b_event_hold_s", event_hold_s))
    progression_scale = float(getattr(env, "_littlegreen_v11b_progression_scale", 0.75))
    contact_scale = float(getattr(env, "_littlegreen_v11b_contact_scale", 0.75))

    if active_period_s <= 1.0e-6:
        raise ValueError("v11b gait period must be positive")
    if not 0.0 < active_transition_fraction < 0.25:
        raise ValueError("v11b transition_fraction must be in (0, 0.25)")
    if active_clean_flight_s <= 0.0:
        raise ValueError("v11b clean_flight_s must be positive")
    if not 0.0 < active_valid_step_fraction <= 1.0:
        raise ValueError("v11b valid_step_fraction must be in (0, 1]")

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where((linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir)
    target_step = torch.clamp(
        linear_norm * active_period_s * active_step_scale,
        min=active_min_step,
        max=active_max_step,
    )
    valid_advance_threshold = torch.maximum(
        torch.full_like(target_step, active_min_pass_m), active_valid_step_fraction * target_step
    )

    parity_first_swing_left = (torch.arange(num_envs, device=device) % 2) == 0

    def _tensor(name: str, default: torch.Tensor, dtype: torch.dtype | None = None) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    phase = _tensor("_littlegreen_v11b_gait_phase", torch.zeros(num_envs, device=device))
    half_progress = _tensor(
        "_littlegreen_v11b_half_progress", torch.zeros(num_envs, device=device)
    )
    confirmed_left_stance = _tensor(
        "_littlegreen_v11b_confirmed_left_stance",
        torch.ones(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    next_first_swing_left = _tensor(
        "_littlegreen_v11b_next_first_swing_left", parity_first_swing_left, torch.bool
    )
    was_moving = _tensor(
        "_littlegreen_v11b_was_moving",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    mode = _tensor(
        "_littlegreen_v11b_mode", torch.zeros(num_envs, device=device, dtype=torch.long), torch.long
    )
    mode_elapsed = _tensor(
        "_littlegreen_v11b_mode_elapsed_s", torch.zeros(num_envs, device=device)
    )
    clean_flight_time = _tensor(
        "_littlegreen_v11b_clean_flight_time_s", torch.zeros(num_envs, device=device)
    )
    lift_peak = _tensor("_littlegreen_v11b_lift_peak_m", torch.zeros(num_envs, device=device))
    prev_swing_contact = _tensor(
        "_littlegreen_v11b_prev_swing_contact",
        torch.ones(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    stance_anchor_w = _tensor(
        "_littlegreen_v11b_stance_anchor_w", foot_pos[:, 0, :].clone()
    )
    halfcycle_start_root_pos = _tensor(
        "_littlegreen_v11b_halfcycle_start_root_pos_w", asset.data.root_pos_w.clone()
    )
    cycle_start_root_pos = _tensor(
        "_littlegreen_v11b_cycle_start_root_pos_w", asset.data.root_pos_w.clone()
    )
    landed_left = _tensor(
        "_littlegreen_v11b_landed_left",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    takeover_gate_time = _tensor(
        "_littlegreen_v11b_takeover_gate_time_s", torch.zeros(num_envs, device=device)
    )
    recovery_contact_time = _tensor(
        "_littlegreen_v11b_recovery_contact_time_s", torch.zeros(num_envs, device=device)
    )
    promotion_count = _tensor(
        "_littlegreen_v11b_promotion_count",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )

    touchdown_hold = _tensor("_littlegreen_v11b_touchdown_hold_s", torch.zeros(num_envs, device=device))
    touchdown_score = _tensor("_littlegreen_v11b_touchdown_score", torch.zeros(num_envs, device=device))
    takeover_hold = _tensor("_littlegreen_v11b_takeover_hold_s", torch.zeros(num_envs, device=device))
    takeover_score = _tensor("_littlegreen_v11b_takeover_score", torch.zeros(num_envs, device=device))
    halfcycle_hold = _tensor("_littlegreen_v11b_halfcycle_hold_s", torch.zeros(num_envs, device=device))
    halfcycle_score = _tensor("_littlegreen_v11b_halfcycle_score", torch.zeros(num_envs, device=device))
    fullcycle_hold = _tensor("_littlegreen_v11b_fullcycle_hold_s", torch.zeros(num_envs, device=device))
    fullcycle_score = _tensor("_littlegreen_v11b_fullcycle_score", torch.zeros(num_envs, device=device))
    failure_hold = _tensor("_littlegreen_v11b_failure_hold_s", torch.zeros(num_envs, device=device))
    failure_score = _tensor("_littlegreen_v11b_failure_score", torch.zeros(num_envs, device=device))
    recovery_hold = _tensor("_littlegreen_v11b_recovery_hold_s", torch.zeros(num_envs, device=device))

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11b_last_common_step", -1))
    touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    valid_touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    invalid_touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    takeover_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    promotion_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    halfcycle_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    fullcycle_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    recovery_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    failure_event = torch.zeros(num_envs, device=device, dtype=torch.bool)

    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11b_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v11b_last_episode_length = current_episode_length.clone()

        for hold_name, hold_value in (
            ("touchdown", touchdown_hold),
            ("takeover", takeover_hold),
            ("halfcycle", halfcycle_hold),
            ("fullcycle", fullcycle_hold),
            ("failure", failure_hold),
            ("recovery", recovery_hold),
        ):
            del hold_name
            hold_value.sub_(dt).clamp_(min=0.0)

        phase = torch.where(reset_mask, torch.zeros_like(phase), phase)
        half_progress = torch.where(reset_mask, torch.zeros_like(half_progress), half_progress)
        confirmed_left_stance = torch.where(
            reset_mask, torch.ones_like(confirmed_left_stance), confirmed_left_stance
        )
        next_first_swing_left = torch.where(
            reset_mask, parity_first_swing_left, next_first_swing_left
        )
        was_moving = torch.where(reset_mask, torch.zeros_like(was_moving), was_moving)
        mode = torch.where(reset_mask, torch.zeros_like(mode), mode)
        mode_elapsed = torch.where(reset_mask, torch.zeros_like(mode_elapsed), mode_elapsed)
        clean_flight_time = torch.where(
            reset_mask, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(reset_mask, torch.zeros_like(lift_peak), lift_peak)
        takeover_gate_time = torch.where(
            reset_mask, torch.zeros_like(takeover_gate_time), takeover_gate_time
        )
        recovery_contact_time = torch.where(
            reset_mask, torch.zeros_like(recovery_contact_time), recovery_contact_time
        )
        promotion_count = torch.where(reset_mask, torch.zeros_like(promotion_count), promotion_count)
        halfcycle_start_root_pos = torch.where(
            reset_mask.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        cycle_start_root_pos = torch.where(
            reset_mask.unsqueeze(-1), asset.data.root_pos_w, cycle_start_root_pos
        )
        stance_anchor_w = torch.where(
            reset_mask.unsqueeze(-1), foot_pos[:, 0, :], stance_anchor_w
        )
        for score in (
            touchdown_score,
            takeover_score,
            halfcycle_score,
            fullcycle_score,
            failure_score,
        ):
            score.masked_fill_(reset_mask, 0.0)
        for hold in (
            touchdown_hold,
            takeover_hold,
            halfcycle_hold,
            fullcycle_hold,
            failure_hold,
            recovery_hold,
        ):
            hold.masked_fill_(reset_mask, 0.0)

        onset = moving & (~was_moving)
        first_swing_left = next_first_swing_left
        confirmed_left_stance = torch.where(onset, ~first_swing_left, confirmed_left_stance)
        next_first_swing_left = torch.where(onset, ~next_first_swing_left, next_first_swing_left)
        mode = torch.where(onset, torch.zeros_like(mode), mode)
        mode_elapsed = torch.where(onset, torch.zeros_like(mode_elapsed), mode_elapsed)
        half_progress = torch.where(onset, torch.zeros_like(half_progress), half_progress)
        clean_flight_time = torch.where(onset, torch.zeros_like(clean_flight_time), clean_flight_time)
        lift_peak = torch.where(onset, torch.zeros_like(lift_peak), lift_peak)
        takeover_gate_time = torch.where(onset, torch.zeros_like(takeover_gate_time), takeover_gate_time)
        recovery_contact_time = torch.where(onset, torch.zeros_like(recovery_contact_time), recovery_contact_time)
        promotion_count = torch.where(onset, torch.zeros_like(promotion_count), promotion_count)
        halfcycle_start_root_pos = torch.where(
            onset.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        cycle_start_root_pos = torch.where(
            onset.unsqueeze(-1), asset.data.root_pos_w, cycle_start_root_pos
        )
        onset_stance_pos = torch.where(
            confirmed_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        stance_anchor_w = torch.where(onset.unsqueeze(-1), onset_stance_pos, stance_anchor_w)

        root_yaw = yaw_quat(asset.data.root_quat_w)
        stance_pos = torch.where(
            confirmed_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        swing_pos = torch.where(
            confirmed_left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        swing_contact = torch.where(confirmed_left_stance, right_contact, left_contact)
        clearance = swing_pos[:, 2] - stance_pos[:, 2]
        anchor_delta_yaw = quat_apply_inverse(root_yaw, swing_pos - stance_anchor_w)[:, :2]
        anchored_advance = torch.sum(anchor_delta_yaw * command_dir, dim=1)

        normal_mode = mode == 0
        takeover_mode = mode == 1
        recovery_mode = mode == 2

        half_increment = 2.0 * dt / active_period_s
        half_progress = torch.where(
            moving & normal_mode & (~onset),
            torch.clamp(half_progress + half_increment, max=1.0),
            half_progress,
        )
        half_transition = 2.0 * active_transition_fraction
        transition = half_progress < half_transition
        swing_progress = torch.clamp(
            (half_progress - half_transition) / max(1.0 - half_transition, 1.0e-6),
            min=0.0,
            max=1.0,
        )

        # Preserve readiness from the immediately preceding contact-free interval.
        # On the touchdown sample itself ``swing_contact`` is true, so computing
        # readiness after resetting the timer would reject every real touchdown.
        clean_flight_ready_before_contact = (
            (clean_flight_time >= active_clean_flight_s) & (lift_peak >= active_lift_gate_m)
        )
        prev_swing_contact = torch.where(onset, swing_contact, prev_swing_contact)
        contact_rise = swing_contact & (~prev_swing_contact)
        flight_active = moving & normal_mode & (~transition) & (~swing_contact)
        clean_flight_time = torch.where(
            flight_active, clean_flight_time + dt, torch.zeros_like(clean_flight_time)
        )
        lift_peak = torch.where(
            moving & normal_mode & (~transition),
            torch.maximum(lift_peak, clearance),
            lift_peak,
        )
        touchdown_candidate = (
            moving
            & normal_mode
            & (~transition)
            & contact_rise
            & clean_flight_ready_before_contact
            & (swing_progress >= touchdown_min_progress)
        )
        valid_touchdown_event = touchdown_candidate & (
            anchored_advance >= valid_advance_threshold
        )
        invalid_touchdown_event = touchdown_candidate & (~valid_touchdown_event)
        touchdown_event = valid_touchdown_event | invalid_touchdown_event
        touchdown_new_score = torch.clamp(
            anchored_advance / torch.clamp(target_step, min=1.0e-6), min=-1.0, max=1.0
        )
        touchdown_score = torch.where(touchdown_event, touchdown_new_score, touchdown_score)
        touchdown_hold = torch.where(
            touchdown_event,
            torch.full_like(touchdown_hold, active_event_hold_s),
            touchdown_hold,
        )

        swing_timeout = moving & normal_mode & (half_progress >= 1.0) & (~touchdown_event)
        failure_event = invalid_touchdown_event | swing_timeout
        failure_new_score = torch.where(
            invalid_touchdown_event,
            torch.clamp(
                (anchored_advance - valid_advance_threshold)
                / torch.clamp(valid_advance_threshold, min=1.0e-6),
                min=-1.0,
                max=0.0,
            ),
            torch.full_like(anchored_advance, -1.0),
        )
        failure_score = torch.where(failure_event, failure_new_score, failure_score)
        failure_hold = torch.where(
            failure_event, torch.full_like(failure_hold, active_event_hold_s), failure_hold
        )

        landed_left = torch.where(valid_touchdown_event, ~confirmed_left_stance, landed_left)
        mode = torch.where(valid_touchdown_event, torch.ones_like(mode), mode)
        mode = torch.where(failure_event, torch.full_like(mode, 2), mode)
        mode_elapsed = torch.where(
            valid_touchdown_event | failure_event, torch.zeros_like(mode_elapsed), mode_elapsed
        )
        takeover_gate_time = torch.where(
            valid_touchdown_event | failure_event,
            torch.zeros_like(takeover_gate_time),
            takeover_gate_time,
        )
        recovery_contact_time = torch.where(
            valid_touchdown_event | failure_event,
            torch.zeros_like(recovery_contact_time),
            recovery_contact_time,
        )

        # Bounded takeover: the newly landed foot must accept both COM and load.
        takeover_mode = mode == 1
        mode_elapsed = torch.where(takeover_mode | (mode == 2), mode_elapsed + dt, mode_elapsed)
        landed_pos = torch.where(landed_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :])
        landed_force = torch.where(landed_left, left_force, right_force)
        landed_contact = torch.where(landed_left, left_contact, right_contact)
        landed_ratio = landed_force / torch.clamp(total_force, min=1.0e-6)
        com_from_landed = quat_apply_inverse(
            root_yaw, asset.data.root_com_pos_w - landed_pos
        )
        takeover_com_ok = (
            torch.abs(com_from_landed[:, 0] - active_com_forward_offset)
            <= active_com_forward_tolerance
        ) & (torch.abs(com_from_landed[:, 1]) <= active_com_lateral_tolerance)
        takeover_ok = (
            takeover_mode
            & both_contact
            & landed_contact
            & (landed_ratio >= active_force_ratio)
            & takeover_com_ok
        )
        takeover_gate_time = torch.where(
            takeover_ok,
            takeover_gate_time + dt,
            torch.where(takeover_mode, torch.zeros_like(takeover_gate_time), takeover_gate_time),
        )
        takeover_success = takeover_mode & (
            takeover_gate_time >= active_takeover_gate_hold_s
        )
        takeover_timeout = takeover_mode & (mode_elapsed >= active_takeover_max_s) & (~takeover_success)
        takeover_event = takeover_success | takeover_timeout
        takeover_score = torch.where(
            takeover_success,
            torch.ones_like(takeover_score),
            torch.where(takeover_timeout, torch.full_like(takeover_score, -1.0), takeover_score),
        )
        takeover_hold = torch.where(
            takeover_event, torch.full_like(takeover_hold, active_event_hold_s), takeover_hold
        )

        # Promotion only occurs after successful takeover.  This is the critical
        # distinction from v11a: a same-place replant cannot become stance.
        promotion_event = takeover_success
        old_promotion_count = promotion_count.clone()
        confirmed_left_stance = torch.where(
            promotion_event, landed_left, confirmed_left_stance
        )
        promotion_count = torch.where(
            promotion_event, promotion_count + 1, promotion_count
        )
        halfcycle_event = promotion_event
        halfcycle_displacement = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - halfcycle_start_root_pos
        )[:, :2]
        halfcycle_progress = torch.sum(halfcycle_displacement * command_dir, dim=1)
        halfcycle_target = torch.clamp(0.70 * target_step, min=0.60 * active_min_step)
        halfcycle_new_score = torch.clamp(
            halfcycle_progress / torch.clamp(halfcycle_target, min=1.0e-6),
            min=-1.0,
            max=1.0,
        )
        halfcycle_score = torch.where(halfcycle_event, halfcycle_new_score, halfcycle_score)
        halfcycle_hold = torch.where(
            halfcycle_event,
            torch.full_like(halfcycle_hold, active_event_hold_s),
            halfcycle_hold,
        )
        halfcycle_start_root_pos = torch.where(
            promotion_event.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )

        fullcycle_event = promotion_event & ((old_promotion_count % 2) == 1)
        fullcycle_displacement = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - cycle_start_root_pos
        )[:, :2]
        fullcycle_progress = torch.sum(fullcycle_displacement * command_dir, dim=1)
        fullcycle_target = torch.clamp(1.40 * target_step, min=1.20 * active_min_step)
        fullcycle_new_score = torch.clamp(
            fullcycle_progress / torch.clamp(fullcycle_target, min=1.0e-6),
            min=-1.0,
            max=1.0,
        )
        fullcycle_score = torch.where(fullcycle_event, fullcycle_new_score, fullcycle_score)
        fullcycle_hold = torch.where(
            fullcycle_event,
            torch.full_like(fullcycle_hold, active_event_hold_s),
            fullcycle_hold,
        )
        cycle_start_root_pos = torch.where(
            fullcycle_event.unsqueeze(-1), asset.data.root_pos_w, cycle_start_root_pos
        )

        # Failed takeover returns to the old confirmed stance and retries the same
        # trailing foot after a bounded double-support recovery.
        mode = torch.where(promotion_event, torch.zeros_like(mode), mode)
        mode = torch.where(takeover_timeout, torch.full_like(mode, 2), mode)
        mode_elapsed = torch.where(
            promotion_event | takeover_timeout, torch.zeros_like(mode_elapsed), mode_elapsed
        )
        failure_event = failure_event | takeover_timeout
        failure_score = torch.where(
            takeover_timeout, torch.full_like(failure_score, -1.0), failure_score
        )
        failure_hold = torch.where(
            takeover_timeout, torch.full_like(failure_hold, active_event_hold_s), failure_hold
        )

        recovery_mode = mode == 2
        recovery_contact_time = torch.where(
            recovery_mode & both_contact,
            recovery_contact_time + dt,
            torch.where(recovery_mode, torch.zeros_like(recovery_contact_time), recovery_contact_time),
        )
        recovery_success = recovery_mode & (
            recovery_contact_time >= active_recovery_contact_hold_s
        )
        recovery_timeout = recovery_mode & (mode_elapsed >= active_recovery_max_s) & (~recovery_success)
        recovery_event = recovery_success | recovery_timeout
        recovery_hold = torch.where(
            recovery_success,
            torch.full_like(recovery_hold, active_event_hold_s),
            recovery_hold,
        )
        failure_event = failure_event | recovery_timeout
        failure_score = torch.where(
            recovery_timeout, torch.full_like(failure_score, -1.0), failure_score
        )
        failure_hold = torch.where(
            recovery_timeout, torch.full_like(failure_hold, active_event_hold_s), failure_hold
        )
        mode = torch.where(recovery_event, torch.zeros_like(mode), mode)
        mode_elapsed = torch.where(recovery_event, torch.zeros_like(mode_elapsed), mode_elapsed)
        half_progress = torch.where(
            promotion_event | recovery_event, torch.zeros_like(half_progress), half_progress
        )
        clean_flight_time = torch.where(
            promotion_event | recovery_event, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(
            promotion_event | recovery_event, torch.zeros_like(lift_peak), lift_peak
        )
        takeover_gate_time = torch.where(
            promotion_event | recovery_event, torch.zeros_like(takeover_gate_time), takeover_gate_time
        )
        recovery_contact_time = torch.where(
            recovery_event, torch.zeros_like(recovery_contact_time), recovery_contact_time
        )
        refreshed_stance_pos = torch.where(
            confirmed_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        stance_anchor_w = torch.where(
            (promotion_event | recovery_event).unsqueeze(-1),
            refreshed_stance_pos,
            stance_anchor_w,
        )

        normal_mode = mode == 0
        takeover_mode = mode == 1
        recovery_mode = mode == 2
        base_phase = torch.where(
            confirmed_left_stance, torch.zeros_like(phase), torch.full_like(phase, 0.5)
        )
        normal_phase = torch.remainder(base_phase + 0.5 * half_progress, 1.0)
        pending_phase = torch.where(
            landed_left, torch.zeros_like(phase), torch.full_like(phase, 0.5)
        )
        phase = torch.where(normal_mode, normal_phase, base_phase)
        phase = torch.where(takeover_mode, pending_phase, phase)
        phase = torch.where(moving, phase, torch.zeros_like(phase))

        # Use the current selected swing foot after all state changes.
        current_swing_contact = torch.where(
            confirmed_left_stance, right_contact, left_contact
        )
        prev_swing_contact = torch.where(
            promotion_event | recovery_event,
            current_swing_contact,
            swing_contact,
        )
        was_moving = moving

        standing = ~moving
        phase = torch.where(standing, torch.zeros_like(phase), phase)
        half_progress = torch.where(standing, torch.zeros_like(half_progress), half_progress)
        mode = torch.where(standing, torch.zeros_like(mode), mode)
        mode_elapsed = torch.where(standing, torch.zeros_like(mode_elapsed), mode_elapsed)
        clean_flight_time = torch.where(
            standing, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(standing, torch.zeros_like(lift_peak), lift_peak)
        takeover_gate_time = torch.where(
            standing, torch.zeros_like(takeover_gate_time), takeover_gate_time
        )
        recovery_contact_time = torch.where(
            standing, torch.zeros_like(recovery_contact_time), recovery_contact_time
        )

        env._littlegreen_v11b_gait_phase = phase
        env._littlegreen_v11b_half_progress = half_progress
        env._littlegreen_v11b_confirmed_left_stance = confirmed_left_stance
        env._littlegreen_v11b_next_first_swing_left = next_first_swing_left
        env._littlegreen_v11b_was_moving = was_moving
        env._littlegreen_v11b_mode = mode
        env._littlegreen_v11b_mode_elapsed_s = mode_elapsed
        env._littlegreen_v11b_clean_flight_time_s = clean_flight_time
        env._littlegreen_v11b_lift_peak_m = lift_peak
        env._littlegreen_v11b_prev_swing_contact = prev_swing_contact
        env._littlegreen_v11b_stance_anchor_w = stance_anchor_w
        env._littlegreen_v11b_halfcycle_start_root_pos_w = halfcycle_start_root_pos
        env._littlegreen_v11b_cycle_start_root_pos_w = cycle_start_root_pos
        env._littlegreen_v11b_landed_left = landed_left
        env._littlegreen_v11b_takeover_gate_time_s = takeover_gate_time
        env._littlegreen_v11b_recovery_contact_time_s = recovery_contact_time
        env._littlegreen_v11b_promotion_count = promotion_count
        env._littlegreen_v11b_touchdown_hold_s = touchdown_hold
        env._littlegreen_v11b_touchdown_score = touchdown_score
        env._littlegreen_v11b_takeover_hold_s = takeover_hold
        env._littlegreen_v11b_takeover_score = takeover_score
        env._littlegreen_v11b_halfcycle_hold_s = halfcycle_hold
        env._littlegreen_v11b_halfcycle_score = halfcycle_score
        env._littlegreen_v11b_fullcycle_hold_s = fullcycle_hold
        env._littlegreen_v11b_fullcycle_score = fullcycle_score
        env._littlegreen_v11b_failure_hold_s = failure_hold
        env._littlegreen_v11b_failure_score = failure_score
        env._littlegreen_v11b_recovery_hold_s = recovery_hold
        env._littlegreen_v11b_touchdown_event = touchdown_event
        env._littlegreen_v11b_valid_touchdown_event = valid_touchdown_event
        env._littlegreen_v11b_invalid_touchdown_event = invalid_touchdown_event
        env._littlegreen_v11b_takeover_event = takeover_event
        env._littlegreen_v11b_promotion_event = promotion_event
        env._littlegreen_v11b_halfcycle_event = halfcycle_event
        env._littlegreen_v11b_fullcycle_event = fullcycle_event
        env._littlegreen_v11b_recovery_event = recovery_event
        env._littlegreen_v11b_failure_event = failure_event
        env._littlegreen_v11b_anchored_advance_m = anchored_advance
        env._littlegreen_v11b_target_step_m = target_step
        env._littlegreen_v11b_valid_advance_threshold_m = valid_advance_threshold
        env._littlegreen_v11b_landed_force_ratio = landed_ratio
        env._littlegreen_v11b_com_from_landed = com_from_landed
        env._littlegreen_v11b_last_common_step = common_step
    else:
        touchdown_event = _tensor(
            "_littlegreen_v11b_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        valid_touchdown_event = _tensor(
            "_littlegreen_v11b_valid_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        invalid_touchdown_event = _tensor(
            "_littlegreen_v11b_invalid_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        takeover_event = _tensor(
            "_littlegreen_v11b_takeover_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        promotion_event = _tensor(
            "_littlegreen_v11b_promotion_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        halfcycle_event = _tensor(
            "_littlegreen_v11b_halfcycle_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        fullcycle_event = _tensor(
            "_littlegreen_v11b_fullcycle_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        recovery_event = _tensor(
            "_littlegreen_v11b_recovery_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        failure_event = _tensor(
            "_littlegreen_v11b_failure_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )

    # Recompute current state for every reward query.
    root_yaw = yaw_quat(asset.data.root_quat_w)
    stance_pos = torch.where(
        confirmed_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
    )
    swing_pos = torch.where(
        confirmed_left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
    )
    swing_contact = torch.where(confirmed_left_stance, right_contact, left_contact)
    stance_force = torch.where(confirmed_left_stance, left_force, right_force)
    stance_ratio = stance_force / torch.clamp(total_force, min=1.0e-6)
    half_transition = 2.0 * active_transition_fraction
    transition = (mode == 0) & (half_progress < half_transition)
    swing_progress = torch.clamp(
        (half_progress - half_transition) / max(1.0 - half_transition, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    clearance = swing_pos[:, 2] - stance_pos[:, 2]
    anchor_delta_yaw = quat_apply_inverse(root_yaw, swing_pos - stance_anchor_w)[:, :2]
    anchored_advance = torch.sum(anchor_delta_yaw * command_dir, dim=1)
    midpoint = 0.5 * (foot_pos[:, 0, :] + foot_pos[:, 1, :])
    left_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 0, :] - midpoint)
    right_rel_yaw = quat_apply_inverse(root_yaw, foot_pos[:, 1, :] - midpoint)
    com_rel_yaw = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
    landed_pos = torch.where(landed_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :])
    landed_force = torch.where(landed_left, left_force, right_force)
    landed_ratio = landed_force / torch.clamp(total_force, min=1.0e-6)
    com_from_landed = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - landed_pos)

    return {
        "phase": phase,
        "moving": moving,
        "mode": mode,
        "normal_mode": mode == 0,
        "takeover_mode": mode == 1,
        "recovery_mode": mode == 2,
        "mode_elapsed_s": mode_elapsed,
        "half_progress": half_progress,
        "transition": transition,
        "swing_progress": swing_progress,
        "confirmed_left_stance": confirmed_left_stance,
        "landed_left": landed_left,
        "left_contact": left_contact,
        "right_contact": right_contact,
        "both_contact": both_contact,
        "no_contact": no_contact,
        "swing_contact": swing_contact,
        "left_force": left_force,
        "right_force": right_force,
        "total_force": total_force,
        "stance_ratio": stance_ratio,
        "landed_ratio": landed_ratio,
        "foot_pos_w": foot_pos,
        "left_rel_yaw": left_rel_yaw,
        "right_rel_yaw": right_rel_yaw,
        "com_rel_yaw": com_rel_yaw,
        "com_from_landed": com_from_landed,
        "clearance": clearance,
        "clean_flight_time_s": clean_flight_time,
        "lift_peak_m": lift_peak,
        "clean_flight_ready": (clean_flight_time >= active_clean_flight_s)
        & (lift_peak >= active_lift_gate_m),
        "anchored_advance": anchored_advance,
        "target_step": target_step,
        "valid_advance_threshold": valid_advance_threshold,
        "touchdown_event": touchdown_event,
        "valid_touchdown_event": valid_touchdown_event,
        "invalid_touchdown_event": invalid_touchdown_event,
        "takeover_event": takeover_event,
        "promotion_event": promotion_event,
        "halfcycle_event": halfcycle_event,
        "fullcycle_event": fullcycle_event,
        "recovery_event": recovery_event,
        "failure_event": failure_event,
        "promotion_count": promotion_count,
        "touchdown_held_score": torch.where(
            touchdown_hold > 0.0, touchdown_score, torch.zeros_like(touchdown_score)
        ),
        "takeover_held_score": torch.where(
            takeover_hold > 0.0, takeover_score, torch.zeros_like(takeover_score)
        ),
        "halfcycle_held_score": torch.where(
            halfcycle_hold > 0.0, halfcycle_score, torch.zeros_like(halfcycle_score)
        ),
        "fullcycle_held_score": torch.where(
            fullcycle_hold > 0.0, fullcycle_score, torch.zeros_like(fullcycle_score)
        ),
        "failure_held_score": torch.where(
            failure_hold > 0.0, failure_score, torch.zeros_like(failure_score)
        ),
        "recovery_held": recovery_hold > 0.0,
        "active_force_ratio": torch.full_like(phase, active_force_ratio),
        "active_com_forward_offset": torch.full_like(phase, active_com_forward_offset),
        "active_com_forward_tolerance": torch.full_like(phase, active_com_forward_tolerance),
        "active_com_lateral_tolerance": torch.full_like(phase, active_com_lateral_tolerance),
        "active_clean_flight_s": torch.full_like(phase, active_clean_flight_s),
        "progression_scale": torch.full_like(phase, progression_scale),
        "contact_scale": torch.full_like(phase, contact_scale),
    }


def confirmed_takeover_gait_phase_sin_cos_v11b(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.055,
) -> torch.Tensor:
    """Return the unchanged 2-D phase tail with bounded confirmed-stance semantics."""
    data = _v11b_confirmed_takeover_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    angle = 2.0 * math.pi * data["phase"]
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def v11b_baseline_corrected_track_lin_vel_xy_yaw_frame_exp(
    env: ManagerBasedRLEnv,
    std: float,
    command_name: str,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.20,
    default_stage_scale: float = 0.85,
) -> torch.Tensor:
    """Zero-motion-corrected moving velocity reward with v11b stage scaling."""
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    measured = quat_apply_inverse(
        yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3]
    )[:, :2]
    error = torch.sum(torch.square(command - measured), dim=1)
    raw = torch.exp(-error / max(float(std) ** 2, 1.0e-8))
    baseline = torch.exp(
        -torch.sum(torch.square(command), dim=1) / max(float(std) ** 2, 1.0e-8)
    )
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > command_threshold
    stage_scale = float(getattr(env, "_littlegreen_v11b_tracking_scale", default_stage_scale))
    return torch.where(moving, stage_scale * normalized, raw)


def v11b_confirmed_contact_schedule_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Reward contact relative to confirmed stance; takeover/recovery require double support."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    left = data["left_contact"]
    right = data["right_contact"]
    stance_only = torch.where(
        data["confirmed_left_stance"], left & (~right), right & (~left)
    )
    wrong_only = torch.where(
        data["confirmed_left_stance"], right & (~left), left & (~right)
    )
    transition_score = torch.where(
        data["both_contact"],
        torch.ones_like(data["phase"]),
        torch.where(stance_only, torch.full_like(data["phase"], 0.15), torch.full_like(data["phase"], -0.8)),
    )
    swing_score = torch.where(
        stance_only,
        torch.ones_like(data["phase"]),
        torch.where(data["both_contact"], torch.full_like(data["phase"], -0.55), torch.full_like(data["phase"], -1.0)),
    )
    swing_score = torch.where(wrong_only, torch.full_like(swing_score, -1.0), swing_score)
    normal_score = torch.where(data["transition"], transition_score, swing_score)
    bounded_hold_score = torch.where(
        data["both_contact"], torch.ones_like(data["phase"]), torch.full_like(data["phase"], -1.0)
    )
    score = torch.where(data["normal_mode"], normal_score, bounded_hold_score)
    score = torch.where(data["no_contact"], torch.full_like(score, -1.0), score)
    return data["contact_scale"] * score * data["moving"].float()


def v11b_confirmed_support_transfer_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    force_threshold: float = 1.0,
    early_swing_fraction: float = 0.24,
) -> torch.Tensor:
    """Reward loading the confirmed stance foot before releasing the trailing foot."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        force_threshold=force_threshold,
    )
    target = float(getattr(env, "_littlegreen_v11b_target_stance_force_ratio", 0.80))
    signed = torch.clamp(
        (data["stance_ratio"] - 0.5) / max(target - 0.5, 1.0e-6), min=-1.0, max=1.0
    )
    signed = torch.where(
        data["total_force"] > force_threshold, signed, torch.full_like(signed, -1.0)
    )
    active = data["normal_mode"] & (
        data["transition"] | (data["swing_progress"] < early_swing_fraction)
    )
    return signed * active.float() * data["moving"].float()


def v11b_confirmed_com_takeover_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    forward_std_m: float = 0.030,
    lateral_std_m: float = 0.030,
    early_swing_fraction: float = 0.28,
) -> torch.Tensor:
    """Shift COM over confirmed stance, then slightly ahead of the landed foot during takeover."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    confirmed_rel = torch.where(
        data["confirmed_left_stance"].unsqueeze(-1), data["left_rel_yaw"], data["right_rel_yaw"]
    )
    support_forward = float(getattr(env, "_littlegreen_v11b_support_forward_offset_m", 0.004))
    lateral_fraction = float(getattr(env, "_littlegreen_v11b_com_lateral_stance_fraction", 0.90))
    normal_target_x = confirmed_rel[:, 0] + support_forward
    normal_target_y = lateral_fraction * confirmed_rel[:, 1]
    normal_dx = (data["com_rel_yaw"][:, 0] - normal_target_x) / max(float(forward_std_m), 1.0e-6)
    normal_dy = (data["com_rel_yaw"][:, 1] - normal_target_y) / max(float(lateral_std_m), 1.0e-6)
    normal_score = torch.exp(-0.5 * (torch.square(normal_dx) + torch.square(normal_dy)))
    normal_active = data["normal_mode"] & (
        data["transition"] | (data["swing_progress"] < early_swing_fraction)
    )

    takeover_dx = (
        data["com_from_landed"][:, 0] - data["active_com_forward_offset"]
    ) / torch.clamp(data["active_com_forward_tolerance"], min=1.0e-6)
    takeover_dy = data["com_from_landed"][:, 1] / torch.clamp(
        data["active_com_lateral_tolerance"], min=1.0e-6
    )
    takeover_score = torch.exp(-0.5 * (torch.square(takeover_dx) + torch.square(takeover_dy)))
    score = normal_score * normal_active.float() + takeover_score * data["takeover_mode"].float()
    return score * data["moving"].float()


def v11b_swing_clearance_trajectory_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    target_clearance_m: float = 0.028,
    clearance_std_m: float = 0.012,
) -> torch.Tensor:
    """Zero-baseline clearance trajectory for the confirmed trailing foot."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    active_target = float(getattr(env, "_littlegreen_v11b_target_clearance_m", target_clearance_m))
    active_std = float(getattr(env, "_littlegreen_v11b_clearance_std_m", clearance_std_m))
    shape = torch.sin(math.pi * data["swing_progress"])
    reference = active_target * shape
    raw = torch.exp(-0.5 * torch.square((data["clearance"] - reference) / max(active_std, 1.0e-6)))
    zero_baseline = torch.exp(-0.5 * torch.square(reference / max(active_std, 1.0e-6)))
    normalized = (raw - zero_baseline) / torch.clamp(1.0 - zero_baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=0.0, max=1.0)
    active = data["normal_mode"] & (~data["transition"])
    return normalized * shape * active.float() * data["moving"].float()


def v11b_anchored_swing_advance_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    gate_width_m: float = 0.006,
    placement_start_progress: float = 0.28,
) -> torch.Tensor:
    """Signed step advance relative to the stance anchor, gated by clean lift."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    gate = float(getattr(env, "_littlegreen_v11b_clearance_gate_m", 0.011))
    clearance_gate = torch.clamp(
        (data["clearance"] - gate) / max(float(gate_width_m), 1.0e-6), min=0.0, max=1.0
    )
    clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)
    flight_gate = torch.clamp(
        data["clean_flight_time_s"] / torch.clamp(data["active_clean_flight_s"], min=1.0e-6),
        min=0.0,
        max=1.0,
    )
    progress_gate = torch.clamp(
        (data["swing_progress"] - placement_start_progress)
        / max(1.0 - placement_start_progress, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    signed = torch.clamp(
        data["anchored_advance"] / torch.clamp(data["target_step"], min=1.0e-6),
        min=-1.0,
        max=1.0,
    )
    active = data["normal_mode"] & (~data["transition"])
    return (
        data["progression_scale"]
        * signed
        * clearance_gate
        * flight_gate
        * progress_gate
        * active.float()
        * data["moving"].float()
    )


def v11b_clean_flight_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Reward a continuously contact-free swing interval; toe chatter earns little."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    score = torch.clamp(
        data["clean_flight_time_s"] / torch.clamp(data["active_clean_flight_s"], min=1.0e-6),
        min=0.0,
        max=1.0,
    )
    active = data["normal_mode"] & (~data["transition"])
    return score * active.float() * data["moving"].float()


def v11b_swing_drag_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize toe contact/dragging through the middle of the swing window."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    mid_swing = (data["swing_progress"] >= 0.20) & (data["swing_progress"] <= 0.82)
    dragging = data["normal_mode"] & mid_swing & data["swing_contact"] & (~data["clean_flight_ready"])
    return dragging.float() * data["moving"].float()


def v11b_advancing_touchdown_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held signed touchdown score; same-place/backward replants remain negative."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["touchdown_held_score"] * data["moving"].float()


def v11b_confirmed_takeover_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held takeover score; only successful COM/load takeover promotes stance."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["takeover_held_score"] * data["moving"].float()


def v11b_halfcycle_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Held signed base progress emitted only on confirmed stance promotion."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["halfcycle_held_score"] * data["moving"].float()


def v11b_fullcycle_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Reward net progress across two promotions; forward/back rocking sums near zero."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["progression_scale"] * data["fullcycle_held_score"] * data["moving"].float()


def v11b_recovery_and_retry_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize invalid steps/takeover failures and reward bounded double-support recovery."""
    data = _v11b_confirmed_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    recovery_dense = torch.where(
        data["recovery_mode"] & data["both_contact"],
        torch.full_like(data["phase"], 0.35),
        torch.where(data["recovery_mode"], torch.full_like(data["phase"], -0.60), torch.zeros_like(data["phase"])),
    )
    held = data["failure_held_score"] + 0.50 * data["recovery_held"].float()
    return (held + recovery_dense) * data["moving"].float()

# -----------------------------------------------------------------------------
# Littlegreen v2.0.0 v11c continuously alternating soft-takeover scaffold
# -----------------------------------------------------------------------------


def _v11c_soft_takeover_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.06,
    force_threshold: float = 1.0,
    clean_flight_s: float = 0.04,
    event_hold_s: float = 0.10,
    takeover_window_s: float = 0.40,
    target_landed_force_ratio: float = 0.56,
    com_takeover_forward_offset_m: float = 0.004,
    com_takeover_forward_tolerance_m: float = 0.050,
    com_takeover_lateral_tolerance_m: float = 0.050,
    min_step_m: float = 0.018,
    max_step_m: float = 0.050,
    step_length_scale: float = 0.10,
) -> dict[str, torch.Tensor]:
    """Layer dense progression measurements onto v11a's non-freezing phase clock.

    The scheduled stance always alternates with the phase.  Touchdown quality and
    COM/load takeover are rewarded continuously, but no condition can withhold the
    next swing.  This intentionally prefers an imperfect or failed step over a
    policy that learns to remain planted waiting for a binary gate.
    """
    base = _v11a_hybrid_gait_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
        force_threshold=force_threshold,
    )

    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    num_envs = command.shape[0]
    device = command.device
    moving = base["moving"]

    asset = env.scene[asset_cfg.name]
    foot_pos = base["foot_pos_w"]
    left_contact = base["left_contact"]
    right_contact = base["right_contact"]
    left_force = base["left_force"]
    right_force = base["right_force"]
    total_force = base["total_force"]
    left_stance = base["left_stance"]

    active_clean_flight_s = float(
        getattr(env, "_littlegreen_v11c_clean_flight_s", clean_flight_s)
    )
    active_event_hold_s = float(
        getattr(env, "_littlegreen_v11c_event_hold_s", event_hold_s)
    )
    active_takeover_window_s = float(
        getattr(env, "_littlegreen_v11c_takeover_window_s", takeover_window_s)
    )
    active_target_force_ratio = float(
        getattr(
            env,
            "_littlegreen_v11c_target_landed_force_ratio",
            target_landed_force_ratio,
        )
    )
    active_takeover_forward_offset = float(
        getattr(
            env,
            "_littlegreen_v11c_com_takeover_forward_offset_m",
            com_takeover_forward_offset_m,
        )
    )
    active_takeover_forward_tolerance = float(
        getattr(
            env,
            "_littlegreen_v11c_com_takeover_forward_tolerance_m",
            com_takeover_forward_tolerance_m,
        )
    )
    active_takeover_lateral_tolerance = float(
        getattr(
            env,
            "_littlegreen_v11c_com_takeover_lateral_tolerance_m",
            com_takeover_lateral_tolerance_m,
        )
    )
    active_min_step = float(getattr(env, "_littlegreen_v11c_min_step_m", min_step_m))
    active_max_step = float(getattr(env, "_littlegreen_v11c_max_step_m", max_step_m))
    active_step_scale = float(
        getattr(env, "_littlegreen_v11c_step_length_scale", step_length_scale)
    )
    active_clearance_gate = float(
        getattr(env, "_littlegreen_v11c_clearance_gate_m", 0.010)
    )
    progression_scale = float(
        getattr(env, "_littlegreen_v11c_progression_scale", 0.25)
    )

    if active_takeover_window_s <= 1.0e-6:
        raise ValueError("v11c takeover_window_s must be positive")
    if not 0.5 < active_target_force_ratio < 1.0:
        raise ValueError("v11c target_landed_force_ratio must be in (0.5, 1.0)")

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where(
        (linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir
    )
    active_period_s = float(getattr(env, "_littlegreen_v11a_gait_period_s", period_s))
    target_step = torch.clamp(
        linear_norm * active_period_s * active_step_scale,
        min=active_min_step,
        max=active_max_step,
    )

    parity_left = (torch.arange(num_envs, device=device) % 2) == 0

    def _tensor(
        name: str,
        default: torch.Tensor,
        dtype: torch.dtype | None = None,
    ) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    was_moving = _tensor(
        "_littlegreen_v11c_was_moving",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    prev_left_stance = _tensor(
        "_littlegreen_v11c_prev_left_stance", left_stance, torch.bool
    )
    stance_anchor_w = _tensor(
        "_littlegreen_v11c_stance_anchor_w", foot_pos[:, 0, :].clone()
    )
    prev_swing_contact = _tensor(
        "_littlegreen_v11c_prev_swing_contact",
        torch.ones(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    clean_flight_time = _tensor(
        "_littlegreen_v11c_clean_flight_time_s", torch.zeros(num_envs, device=device)
    )
    lift_peak = _tensor(
        "_littlegreen_v11c_lift_peak_m", torch.zeros(num_envs, device=device)
    )
    touchdown_seen = _tensor(
        "_littlegreen_v11c_touchdown_seen",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    touchdown_best_score = _tensor(
        "_littlegreen_v11c_touchdown_best_score", torch.full((num_envs,), -1.0, device=device)
    )
    halfcycle_start_root_pos = _tensor(
        "_littlegreen_v11c_halfcycle_start_root_pos_w", asset.data.root_pos_w.clone()
    )
    cycle_start_root_pos = _tensor(
        "_littlegreen_v11c_cycle_start_root_pos_w", asset.data.root_pos_w.clone()
    )
    halfcycle_count = _tensor(
        "_littlegreen_v11c_halfcycle_count",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )
    landed_left = _tensor(
        "_littlegreen_v11c_landed_left", parity_left, torch.bool
    )
    takeover_remaining = _tensor(
        "_littlegreen_v11c_takeover_remaining_s", torch.zeros(num_envs, device=device)
    )
    takeover_success_seen = _tensor(
        "_littlegreen_v11c_takeover_success_seen",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )

    touchdown_hold = _tensor(
        "_littlegreen_v11c_touchdown_hold_s", torch.zeros(num_envs, device=device)
    )
    touchdown_score = _tensor(
        "_littlegreen_v11c_touchdown_score", torch.zeros(num_envs, device=device)
    )
    takeover_success_hold = _tensor(
        "_littlegreen_v11c_takeover_success_hold_s", torch.zeros(num_envs, device=device)
    )
    halfcycle_hold = _tensor(
        "_littlegreen_v11c_halfcycle_hold_s", torch.zeros(num_envs, device=device)
    )
    halfcycle_score = _tensor(
        "_littlegreen_v11c_halfcycle_score", torch.zeros(num_envs, device=device)
    )
    fullcycle_hold = _tensor(
        "_littlegreen_v11c_fullcycle_hold_s", torch.zeros(num_envs, device=device)
    )
    fullcycle_score = _tensor(
        "_littlegreen_v11c_fullcycle_score", torch.zeros(num_envs, device=device)
    )
    failure_hold = _tensor(
        "_littlegreen_v11c_failure_hold_s", torch.zeros(num_envs, device=device)
    )
    failure_score = _tensor(
        "_littlegreen_v11c_failure_score", torch.zeros(num_envs, device=device)
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11c_last_common_step", -1))
    touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    takeover_success_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    halfcycle_event = base["halfcycle_event"]
    fullcycle_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    failure_event = torch.zeros(num_envs, device=device, dtype=torch.bool)

    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11c_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if (
                isinstance(last_episode_length, torch.Tensor)
                and last_episode_length.shape[0] == num_envs
            ):
                reset_mask = reset_mask | (
                    current_episode_length < last_episode_length.to(device=device)
                )
            env._littlegreen_v11c_last_episode_length = current_episode_length.clone()

        touchdown_hold = torch.clamp(touchdown_hold - dt, min=0.0)
        takeover_success_hold = torch.clamp(takeover_success_hold - dt, min=0.0)
        halfcycle_hold = torch.clamp(halfcycle_hold - dt, min=0.0)
        fullcycle_hold = torch.clamp(fullcycle_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)

        onset = moving & (~was_moving)
        clear_mask = reset_mask | onset | (~moving)

        current_stance_pos = torch.where(
            left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        current_swing_contact = torch.where(left_stance, right_contact, left_contact)
        stance_anchor_w = torch.where(
            clear_mask.unsqueeze(-1), current_stance_pos, stance_anchor_w
        )
        prev_left_stance = torch.where(clear_mask, left_stance, prev_left_stance)
        prev_swing_contact = torch.where(
            clear_mask, current_swing_contact, prev_swing_contact
        )
        clean_flight_time = torch.where(
            clear_mask, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(clear_mask, torch.zeros_like(lift_peak), lift_peak)
        touchdown_seen = torch.where(clear_mask, torch.zeros_like(touchdown_seen), touchdown_seen)
        touchdown_best_score = torch.where(
            clear_mask, torch.full_like(touchdown_best_score, -1.0), touchdown_best_score
        )
        halfcycle_start_root_pos = torch.where(
            clear_mask.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        cycle_start_root_pos = torch.where(
            clear_mask.unsqueeze(-1), asset.data.root_pos_w, cycle_start_root_pos
        )
        halfcycle_count = torch.where(
            clear_mask, torch.zeros_like(halfcycle_count), halfcycle_count
        )
        takeover_remaining = torch.where(
            clear_mask, torch.zeros_like(takeover_remaining), takeover_remaining
        )
        takeover_success_seen = torch.where(
            clear_mask, torch.zeros_like(takeover_success_seen), takeover_success_seen
        )
        touchdown_hold = torch.where(clear_mask, torch.zeros_like(touchdown_hold), touchdown_hold)
        takeover_success_hold = torch.where(
            clear_mask, torch.zeros_like(takeover_success_hold), takeover_success_hold
        )
        halfcycle_hold = torch.where(clear_mask, torch.zeros_like(halfcycle_hold), halfcycle_hold)
        fullcycle_hold = torch.where(clear_mask, torch.zeros_like(fullcycle_hold), fullcycle_hold)
        failure_hold = torch.where(clear_mask, torch.zeros_like(failure_hold), failure_hold)

        # Detect the touchdown of the foot that was swinging before this simulator
        # step.  At a half-cycle boundary, the base phase has already switched, so
        # the saved previous stance side is required to score the just-landed foot.
        detect_left_stance = torch.where(halfcycle_event, prev_left_stance, left_stance)
        detect_stance_pos = torch.where(
            detect_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        detect_swing_pos = torch.where(
            detect_left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        detect_swing_contact = torch.where(
            detect_left_stance, right_contact, left_contact
        )
        root_yaw = yaw_quat(asset.data.root_quat_w)
        anchored_delta = quat_apply_inverse(
            root_yaw, detect_swing_pos - stance_anchor_w
        )[:, :2]
        anchored_advance = torch.sum(anchored_delta * command_dir, dim=1)
        detect_clearance = detect_swing_pos[:, 2] - detect_stance_pos[:, 2]

        clean_flight_time = torch.where(
            moving & (~detect_swing_contact),
            clean_flight_time + dt,
            clean_flight_time,
        )
        lift_peak = torch.where(
            moving & (~detect_swing_contact),
            torch.maximum(lift_peak, detect_clearance),
            lift_peak,
        )
        contact_rise = detect_swing_contact & (~prev_swing_contact)
        clean_touchdown = (
            moving
            & contact_rise
            & (clean_flight_time >= active_clean_flight_s)
            & (lift_peak >= active_clearance_gate)
        )
        touchdown_event = clean_touchdown
        touchdown_new_score = torch.clamp(
            anchored_advance / torch.clamp(target_step, min=1.0e-6),
            min=-1.0,
            max=1.0,
        )
        touchdown_score = torch.where(touchdown_event, touchdown_new_score, touchdown_score)
        touchdown_hold = torch.where(
            touchdown_event,
            torch.full_like(touchdown_hold, active_event_hold_s),
            touchdown_hold,
        )
        touchdown_seen = touchdown_seen | touchdown_event
        touchdown_best_score = torch.where(
            touchdown_event,
            torch.maximum(touchdown_best_score, touchdown_new_score),
            touchdown_best_score,
        )

        # A contact edge ends the current flight measurement, valid or not.  This
        # rejects toe chatter as a clean step without stopping the gait clock.
        clean_flight_time = torch.where(
            contact_rise, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(contact_rise, torch.zeros_like(lift_peak), lift_peak)

        root_displacement = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - halfcycle_start_root_pos
        )[:, :2]
        halfcycle_progress_m = torch.sum(root_displacement * command_dir, dim=1)
        halfcycle_target = torch.clamp(
            0.70 * target_step, min=0.55 * active_min_step
        )
        halfcycle_new_score = torch.clamp(
            halfcycle_progress_m / torch.clamp(halfcycle_target, min=1.0e-6),
            min=-1.0,
            max=1.0,
        )
        halfcycle_score = torch.where(
            halfcycle_event, halfcycle_new_score, halfcycle_score
        )
        halfcycle_hold = torch.where(
            halfcycle_event,
            torch.full_like(halfcycle_hold, active_event_hold_s),
            halfcycle_hold,
        )

        failed_halfcycle = halfcycle_event & (
            (~touchdown_seen) | (touchdown_best_score <= 0.0)
        )
        failure_event = failed_halfcycle
        failure_score = torch.where(
            failure_event, torch.full_like(failure_score, -1.0), failure_score
        )
        failure_hold = torch.where(
            failure_event,
            torch.full_like(failure_hold, active_event_hold_s),
            failure_hold,
        )

        # Every half-cycle advances.  The newly scheduled stance foot receives a
        # long dense takeover window, but missing its target never blocks the next
        # leg from swinging.
        landed_left = torch.where(halfcycle_event, left_stance, landed_left)
        takeover_remaining = torch.where(
            halfcycle_event,
            torch.full_like(takeover_remaining, active_takeover_window_s),
            torch.clamp(takeover_remaining - dt, min=0.0),
        )
        takeover_success_seen = torch.where(
            halfcycle_event, torch.zeros_like(takeover_success_seen), takeover_success_seen
        )

        old_halfcycle_count = halfcycle_count
        halfcycle_count = torch.where(
            halfcycle_event, halfcycle_count + 1, halfcycle_count
        )
        fullcycle_event = halfcycle_event & (((old_halfcycle_count + 1) % 2) == 0)
        cycle_displacement = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - cycle_start_root_pos
        )[:, :2]
        fullcycle_progress_m = torch.sum(cycle_displacement * command_dir, dim=1)
        fullcycle_target = torch.clamp(
            1.40 * target_step, min=1.10 * active_min_step
        )
        fullcycle_new_score = torch.clamp(
            fullcycle_progress_m / torch.clamp(fullcycle_target, min=1.0e-6),
            min=-1.0,
            max=1.0,
        )
        fullcycle_score = torch.where(
            fullcycle_event, fullcycle_new_score, fullcycle_score
        )
        fullcycle_hold = torch.where(
            fullcycle_event,
            torch.full_like(fullcycle_hold, active_event_hold_s),
            fullcycle_hold,
        )
        cycle_start_root_pos = torch.where(
            fullcycle_event.unsqueeze(-1), asset.data.root_pos_w, cycle_start_root_pos
        )

        new_stance_pos = torch.where(
            left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        stance_anchor_w = torch.where(
            halfcycle_event.unsqueeze(-1), new_stance_pos, stance_anchor_w
        )
        halfcycle_start_root_pos = torch.where(
            halfcycle_event.unsqueeze(-1), asset.data.root_pos_w, halfcycle_start_root_pos
        )
        touchdown_seen = torch.where(
            halfcycle_event, torch.zeros_like(touchdown_seen), touchdown_seen
        )
        touchdown_best_score = torch.where(
            halfcycle_event,
            torch.full_like(touchdown_best_score, -1.0),
            touchdown_best_score,
        )
        clean_flight_time = torch.where(
            halfcycle_event, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(
            halfcycle_event, torch.zeros_like(lift_peak), lift_peak
        )

        # Dense COM/load trajectory for the newly landed/scheduled stance foot.
        takeover_active = moving & (takeover_remaining > 0.0)
        landed_pos = torch.where(
            landed_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        landed_force = torch.where(landed_left, left_force, right_force)
        landed_ratio = landed_force / torch.clamp(total_force, min=1.0e-6)
        com_from_landed = quat_apply_inverse(
            root_yaw, asset.data.root_com_pos_w - landed_pos
        )
        com_forward = torch.sum(com_from_landed[:, :2] * command_dir, dim=1)
        command_lateral = torch.stack((-command_dir[:, 1], command_dir[:, 0]), dim=1)
        com_lateral = torch.sum(com_from_landed[:, :2] * command_lateral, dim=1)
        takeover_progress = torch.clamp(
            1.0 - takeover_remaining / active_takeover_window_s,
            min=0.0,
            max=1.0,
        )
        instantaneous_force_target = 0.5 + takeover_progress * (
            active_target_force_ratio - 0.5
        )
        force_score = torch.clamp(
            (landed_ratio - 0.5)
            / torch.clamp(instantaneous_force_target - 0.5, min=0.03),
            min=-1.0,
            max=1.0,
        )
        target_forward = takeover_progress * active_takeover_forward_offset
        forward_error = torch.abs(com_forward - target_forward) / max(
            active_takeover_forward_tolerance, 1.0e-6
        )
        lateral_error = torch.abs(com_lateral) / max(
            active_takeover_lateral_tolerance, 1.0e-6
        )
        com_score = torch.clamp(
            1.0 - torch.sqrt(torch.square(forward_error) + torch.square(lateral_error)),
            min=-1.0,
            max=1.0,
        )
        takeover_dense_score = (0.55 * force_score + 0.45 * com_score) * takeover_active.float()
        takeover_ok = (
            takeover_active
            & (takeover_progress >= 0.25)
            & (landed_ratio >= active_target_force_ratio)
            & (torch.abs(com_forward - active_takeover_forward_offset)
               <= active_takeover_forward_tolerance)
            & (torch.abs(com_lateral) <= active_takeover_lateral_tolerance)
        )
        takeover_success_event = takeover_ok & (~takeover_success_seen)
        takeover_success_seen = takeover_success_seen | takeover_success_event
        takeover_success_hold = torch.where(
            takeover_success_event,
            torch.full_like(takeover_success_hold, active_event_hold_s),
            takeover_success_hold,
        )

        # Update the previous contact using the new scheduled swing side after a
        # boundary so the next leg's contact edge is measured correctly.
        next_swing_contact = torch.where(left_stance, right_contact, left_contact)
        prev_swing_contact = torch.where(
            halfcycle_event, next_swing_contact, detect_swing_contact
        )
        prev_left_stance = left_stance
        was_moving = moving

        env._littlegreen_v11c_was_moving = was_moving
        env._littlegreen_v11c_prev_left_stance = prev_left_stance
        env._littlegreen_v11c_stance_anchor_w = stance_anchor_w
        env._littlegreen_v11c_prev_swing_contact = prev_swing_contact
        env._littlegreen_v11c_clean_flight_time_s = clean_flight_time
        env._littlegreen_v11c_lift_peak_m = lift_peak
        env._littlegreen_v11c_touchdown_seen = touchdown_seen
        env._littlegreen_v11c_touchdown_best_score = touchdown_best_score
        env._littlegreen_v11c_halfcycle_start_root_pos_w = halfcycle_start_root_pos
        env._littlegreen_v11c_cycle_start_root_pos_w = cycle_start_root_pos
        env._littlegreen_v11c_halfcycle_count = halfcycle_count
        env._littlegreen_v11c_landed_left = landed_left
        env._littlegreen_v11c_takeover_remaining_s = takeover_remaining
        env._littlegreen_v11c_takeover_success_seen = takeover_success_seen
        env._littlegreen_v11c_touchdown_hold_s = touchdown_hold
        env._littlegreen_v11c_touchdown_score = touchdown_score
        env._littlegreen_v11c_takeover_success_hold_s = takeover_success_hold
        env._littlegreen_v11c_halfcycle_hold_s = halfcycle_hold
        env._littlegreen_v11c_halfcycle_score = halfcycle_score
        env._littlegreen_v11c_fullcycle_hold_s = fullcycle_hold
        env._littlegreen_v11c_fullcycle_score = fullcycle_score
        env._littlegreen_v11c_failure_hold_s = failure_hold
        env._littlegreen_v11c_failure_score = failure_score
        env._littlegreen_v11c_touchdown_event = touchdown_event
        env._littlegreen_v11c_takeover_success_event = takeover_success_event
        env._littlegreen_v11c_fullcycle_event = fullcycle_event
        env._littlegreen_v11c_failure_event = failure_event
        env._littlegreen_v11c_anchored_advance_m = anchored_advance
        env._littlegreen_v11c_target_step_m = target_step
        env._littlegreen_v11c_landed_force_ratio = landed_ratio
        env._littlegreen_v11c_com_forward_from_landed_m = com_forward
        env._littlegreen_v11c_com_lateral_from_landed_m = com_lateral
        env._littlegreen_v11c_takeover_dense_score = takeover_dense_score
        env._littlegreen_v11c_last_common_step = common_step
    else:
        touchdown_event = _tensor(
            "_littlegreen_v11c_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        takeover_success_event = _tensor(
            "_littlegreen_v11c_takeover_success_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        fullcycle_event = _tensor(
            "_littlegreen_v11c_fullcycle_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        failure_event = _tensor(
            "_littlegreen_v11c_failure_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        anchored_advance = _tensor(
            "_littlegreen_v11c_anchored_advance_m", torch.zeros(num_envs, device=device)
        )
        landed_ratio = _tensor(
            "_littlegreen_v11c_landed_force_ratio", torch.full((num_envs,), 0.5, device=device)
        )
        com_forward = _tensor(
            "_littlegreen_v11c_com_forward_from_landed_m", torch.zeros(num_envs, device=device)
        )
        com_lateral = _tensor(
            "_littlegreen_v11c_com_lateral_from_landed_m", torch.zeros(num_envs, device=device)
        )
        takeover_dense_score = _tensor(
            "_littlegreen_v11c_takeover_dense_score", torch.zeros(num_envs, device=device)
        )

    # Current swing geometry for dense pass shaping after the state update.
    root_yaw = yaw_quat(asset.data.root_quat_w)
    swing_pos = torch.where(
        left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
    )
    stance_pos = torch.where(
        left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
    )
    anchored_delta = quat_apply_inverse(root_yaw, swing_pos - stance_anchor_w)[:, :2]
    anchored_advance = torch.sum(anchored_delta * command_dir, dim=1)
    clearance = swing_pos[:, 2] - stance_pos[:, 2]

    return {
        **base,
        "anchored_advance": anchored_advance,
        "target_step_v11c": target_step,
        "clean_flight_time": clean_flight_time,
        "touchdown_event_v11c": touchdown_event,
        "touchdown_held_score_v11c": torch.where(
            touchdown_hold > 0.0, touchdown_score, torch.zeros_like(touchdown_score)
        ),
        "takeover_active": takeover_remaining > 0.0,
        "takeover_progress": torch.clamp(
            1.0 - takeover_remaining / active_takeover_window_s,
            min=0.0,
            max=1.0,
        ),
        "takeover_dense_score": takeover_dense_score,
        "takeover_success_event": takeover_success_event,
        "takeover_success_held": takeover_success_hold > 0.0,
        "landed_force_ratio": landed_ratio,
        "com_forward_from_landed": com_forward,
        "com_lateral_from_landed": com_lateral,
        "halfcycle_held_score_v11c": torch.where(
            halfcycle_hold > 0.0, halfcycle_score, torch.zeros_like(halfcycle_score)
        ),
        "fullcycle_event_v11c": fullcycle_event,
        "fullcycle_held_score_v11c": torch.where(
            fullcycle_hold > 0.0, fullcycle_score, torch.zeros_like(fullcycle_score)
        ),
        "failure_event_v11c": failure_event,
        "failure_held_score_v11c": torch.where(
            failure_hold > 0.0, failure_score, torch.zeros_like(failure_score)
        ),
        "clearance_v11c": clearance,
        "progression_scale_v11c": torch.full_like(base["phase"], progression_scale),
    }


def soft_takeover_gait_phase_sin_cos_v11c(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.06,
) -> torch.Tensor:
    """Return the unchanged 2-D phase tail; phase always continues alternating."""
    data = _v11c_soft_takeover_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
    )
    angle = 2.0 * math.pi * data["phase"]
    return torch.stack((torch.sin(angle), torch.cos(angle)), dim=-1)


def v11c_baseline_corrected_track_lin_vel_xy_yaw_frame_exp(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float,
    command_threshold: float = 0.20,
    default_stage_scale: float = 0.72,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Zero-baseline moving velocity tracking with a v11c curriculum scale."""
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    measured = quat_apply_inverse(
        yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3]
    )[:, :2]
    error = torch.sum(torch.square(command - measured), dim=1)
    raw = torch.exp(-error / max(float(std) ** 2, 1.0e-8))
    baseline = torch.exp(
        -torch.sum(torch.square(command), dim=1) / max(float(std) ** 2, 1.0e-8)
    )
    normalized = (raw - baseline) / torch.clamp(1.0 - baseline, min=1.0e-5)
    normalized = torch.clamp(normalized, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > command_threshold
    stage_scale = float(
        getattr(env, "_littlegreen_v11c_tracking_scale", default_stage_scale)
    )
    return torch.where(moving, stage_scale * normalized, raw)


