def _v11d_true_step_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.055,
    force_threshold: float = 1.0,
    clean_flight_s: float = 0.045,
    clearance_gate_m: float = 0.010,
    lead_margin_m: float = 0.010,
    valid_step_fraction: float = 0.55,
    stance_drift_limit_m: float = 0.018,
    takeover_window_s: float = 0.38,
    takeover_progress_ratio: float = 0.45,
    takeover_progress_min_m: float = 0.008,
    takeover_progress_max_m: float = 0.022,
    support_zone_forward_m: float = 0.018,
    old_foot_behind_m: float = 0.000,
    event_hold_s: float = 0.12,
) -> dict[str, torch.Tensor]:
    """Detect physical alternating steps without changing the 47-D observation.

    The phase observation remains the v11c/v11a continuous clock.  This state is
    reward/diagnostic-only.  A true step is emitted only when:

    1. the scheduled opposite foot completes continuous clean flight;
    2. it lands ahead of the anchored stance foot;
    3. the left/right lead order reverses (or is first established at movement onset);
    4. the base progresses over the newly landed, still-planted foot.

    No condition gates the phase or prevents the other leg from trying.  Invalid
    replants and incomplete takeover attempts receive bounded penalties only.
    """
    base = _v11c_soft_takeover_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
        force_threshold=force_threshold,
    )

    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    num_envs = command.shape[0]
    device = command.device
    moving = base["moving"]
    asset = env.scene[asset_cfg.name]
    foot_pos = base["foot_pos_w"]
    left_contact = base["left_contact"]
    right_contact = base["right_contact"]
    left_stance = base["left_stance"]
    halfcycle_event = base["halfcycle_event"]

    active_clean_flight_s = float(
        getattr(env, "_littlegreen_v11d_clean_flight_s", clean_flight_s)
    )
    active_clearance_gate = float(
        getattr(env, "_littlegreen_v11d_clearance_gate_m", clearance_gate_m)
    )
    active_lead_margin = float(
        getattr(env, "_littlegreen_v11d_lead_margin_m", lead_margin_m)
    )
    active_valid_step_fraction = float(
        getattr(env, "_littlegreen_v11d_valid_step_fraction", valid_step_fraction)
    )
    active_stance_drift_limit = float(
        getattr(env, "_littlegreen_v11d_stance_drift_limit_m", stance_drift_limit_m)
    )
    active_takeover_window = float(
        getattr(env, "_littlegreen_v11d_takeover_window_s", takeover_window_s)
    )
    active_takeover_ratio = float(
        getattr(env, "_littlegreen_v11d_takeover_progress_ratio", takeover_progress_ratio)
    )
    active_takeover_min = float(
        getattr(env, "_littlegreen_v11d_takeover_progress_min_m", takeover_progress_min_m)
    )
    active_takeover_max = float(
        getattr(env, "_littlegreen_v11d_takeover_progress_max_m", takeover_progress_max_m)
    )
    active_support_zone = float(
        getattr(env, "_littlegreen_v11d_support_zone_forward_m", support_zone_forward_m)
    )
    active_old_foot_behind = float(
        getattr(env, "_littlegreen_v11d_old_foot_behind_m", old_foot_behind_m)
    )
    active_event_hold = float(
        getattr(env, "_littlegreen_v11d_event_hold_s", event_hold_s)
    )
    progression_scale = float(
        getattr(env, "_littlegreen_v11d_progression_scale", 0.60)
    )

    if active_takeover_window <= 1.0e-6:
        raise ValueError("v11d takeover_window_s must be positive")
    if not 0.0 < active_valid_step_fraction <= 1.0:
        raise ValueError("v11d valid_step_fraction must be in (0, 1]")

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where(
        (linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir
    )
    root_yaw = yaw_quat(asset.data.root_quat_w)
    target_step = base["target_step_v11c"]
    valid_advance_threshold = torch.maximum(
        active_valid_step_fraction * target_step,
        torch.full_like(target_step, active_lead_margin),
    )
    takeover_target = torch.clamp(
        active_takeover_ratio * target_step,
        min=active_takeover_min,
        max=active_takeover_max,
    )

    parity_left = (torch.arange(num_envs, device=device) % 2) == 0

    def _tensor(
        name: str,
        default: torch.Tensor,
        dtype: torch.dtype | None = None,
    ) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    was_moving = _tensor(
        "_littlegreen_v11d_was_moving",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    prev_left_stance = _tensor(
        "_littlegreen_v11d_prev_left_stance", left_stance, torch.bool
    )
    stance_anchor_w = _tensor(
        "_littlegreen_v11d_stance_anchor_w", foot_pos[:, 0, :].clone()
    )
    prev_swing_contact = _tensor(
        "_littlegreen_v11d_prev_swing_contact",
        torch.ones(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    clean_flight_time = _tensor(
        "_littlegreen_v11d_clean_flight_time_s", torch.zeros(num_envs, device=device)
    )
    lift_peak = _tensor(
        "_littlegreen_v11d_lift_peak_m", torch.zeros(num_envs, device=device)
    )
    confirmed_lead_side = _tensor(
        "_littlegreen_v11d_confirmed_lead_side",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )
    last_true_step_side = _tensor(
        "_littlegreen_v11d_last_true_step_side",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )
    true_step_count = _tensor(
        "_littlegreen_v11d_true_step_count",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )

    candidate_active = _tensor(
        "_littlegreen_v11d_candidate_active",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    candidate_landed_left = _tensor(
        "_littlegreen_v11d_candidate_landed_left", parity_left, torch.bool
    )
    candidate_elapsed = _tensor(
        "_littlegreen_v11d_candidate_elapsed_s", torch.zeros(num_envs, device=device)
    )
    candidate_touchdown_foot_w = _tensor(
        "_littlegreen_v11d_candidate_touchdown_foot_w", foot_pos[:, 0, :].clone()
    )
    candidate_start_foot_rel_base_forward = _tensor(
        "_littlegreen_v11d_candidate_start_foot_rel_base_forward_m",
        torch.zeros(num_envs, device=device),
    )
    candidate_advance = _tensor(
        "_littlegreen_v11d_candidate_advance_m", torch.zeros(num_envs, device=device)
    )
    candidate_lead_gap = _tensor(
        "_littlegreen_v11d_candidate_lead_gap_m", torch.zeros(num_envs, device=device)
    )

    true_step_hold = _tensor(
        "_littlegreen_v11d_true_step_hold_s", torch.zeros(num_envs, device=device)
    )
    true_step_score = _tensor(
        "_littlegreen_v11d_true_step_score", torch.zeros(num_envs, device=device)
    )
    true_stride_hold = _tensor(
        "_littlegreen_v11d_true_stride_hold_s", torch.zeros(num_envs, device=device)
    )
    true_stride_score = _tensor(
        "_littlegreen_v11d_true_stride_score", torch.zeros(num_envs, device=device)
    )
    invalid_replant_hold = _tensor(
        "_littlegreen_v11d_invalid_replant_hold_s", torch.zeros(num_envs, device=device)
    )
    incomplete_takeover_hold = _tensor(
        "_littlegreen_v11d_incomplete_takeover_hold_s", torch.zeros(num_envs, device=device)
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11d_last_common_step", -1))
    clean_touchdown_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    lead_switch_candidate_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    invalid_replant_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    true_step_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    true_stride_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    incomplete_takeover_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    stance_drift = torch.zeros(num_envs, device=device)
    support_odometry = torch.zeros(num_envs, device=device)
    lead_gap = torch.zeros(num_envs, device=device)
    landed_foot_rel_base_forward = torch.zeros(num_envs, device=device)
    old_foot_rel_base_forward = torch.zeros(num_envs, device=device)

    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11d_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if (
                isinstance(last_episode_length, torch.Tensor)
                and last_episode_length.shape[0] == num_envs
            ):
                reset_mask = reset_mask | (
                    current_episode_length < last_episode_length.to(device=device)
                )
            env._littlegreen_v11d_last_episode_length = current_episode_length.clone()

        true_step_hold = torch.clamp(true_step_hold - dt, min=0.0)
        true_stride_hold = torch.clamp(true_stride_hold - dt, min=0.0)
        invalid_replant_hold = torch.clamp(invalid_replant_hold - dt, min=0.0)
        incomplete_takeover_hold = torch.clamp(incomplete_takeover_hold - dt, min=0.0)

        onset = moving & (~was_moving)
        clear_mask = reset_mask | onset | (~moving)

        foot_delta_yaw = quat_apply_inverse(
            root_yaw, foot_pos[:, 0, :] - foot_pos[:, 1, :]
        )[:, :2]
        lead_gap = torch.sum(foot_delta_yaw * command_dir, dim=1)
        measured_lead_side = torch.where(
            lead_gap >= active_lead_margin,
            torch.ones(num_envs, device=device, dtype=torch.long),
            torch.where(
                lead_gap <= -active_lead_margin,
                -torch.ones(num_envs, device=device, dtype=torch.long),
                torch.zeros(num_envs, device=device, dtype=torch.long),
            ),
        )
        confirmed_lead_side = torch.where(
            clear_mask, measured_lead_side, confirmed_lead_side
        )
        last_true_step_side = torch.where(
            clear_mask, torch.zeros_like(last_true_step_side), last_true_step_side
        )
        true_step_count = torch.where(
            clear_mask, torch.zeros_like(true_step_count), true_step_count
        )

        current_stance_pos = torch.where(
            left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        current_swing_contact = torch.where(left_stance, right_contact, left_contact)
        stance_anchor_w = torch.where(
            clear_mask.unsqueeze(-1), current_stance_pos, stance_anchor_w
        )
        prev_left_stance = torch.where(clear_mask, left_stance, prev_left_stance)
        prev_swing_contact = torch.where(
            clear_mask, current_swing_contact, prev_swing_contact
        )
        clean_flight_time = torch.where(
            clear_mask, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(clear_mask, torch.zeros_like(lift_peak), lift_peak)
        candidate_active = torch.where(
            clear_mask, torch.zeros_like(candidate_active), candidate_active
        )
        candidate_elapsed = torch.where(
            clear_mask, torch.zeros_like(candidate_elapsed), candidate_elapsed
        )
        true_step_hold = torch.where(
            clear_mask, torch.zeros_like(true_step_hold), true_step_hold
        )
        true_stride_hold = torch.where(
            clear_mask, torch.zeros_like(true_stride_hold), true_stride_hold
        )
        invalid_replant_hold = torch.where(
            clear_mask, torch.zeros_like(invalid_replant_hold), invalid_replant_hold
        )
        incomplete_takeover_hold = torch.where(
            clear_mask, torch.zeros_like(incomplete_takeover_hold), incomplete_takeover_hold
        )

        # Score the foot that was swinging immediately before a clock boundary.
        detect_left_stance = torch.where(halfcycle_event, prev_left_stance, left_stance)
        detect_stance_pos = torch.where(
            detect_left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        detect_swing_pos = torch.where(
            detect_left_stance.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        detect_swing_contact = torch.where(
            detect_left_stance, right_contact, left_contact
        )
        landed_left_now = ~detect_left_stance
        landed_side_now = torch.where(
            landed_left_now,
            torch.ones(num_envs, device=device, dtype=torch.long),
            -torch.ones(num_envs, device=device, dtype=torch.long),
        )

        anchored_delta = quat_apply_inverse(
            root_yaw, detect_swing_pos - stance_anchor_w
        )[:, :2]
        anchored_advance = torch.sum(anchored_delta * command_dir, dim=1)
        detect_clearance = detect_swing_pos[:, 2] - detect_stance_pos[:, 2]
        stance_drift = torch.linalg.vector_norm(
            detect_stance_pos[:, :2] - stance_anchor_w[:, :2], dim=1
        )

        clean_flight_time = torch.where(
            moving & (~detect_swing_contact),
            clean_flight_time + dt,
            clean_flight_time,
        )
        lift_peak = torch.where(
            moving & (~detect_swing_contact),
            torch.maximum(lift_peak, detect_clearance),
            lift_peak,
        )
        contact_rise = detect_swing_contact & (~prev_swing_contact)
        clean_touchdown_event = (
            moving
            & contact_rise
            & (clean_flight_time >= active_clean_flight_s)
            & (lift_peak >= active_clearance_gate)
        )

        landed_leads = torch.where(
            landed_left_now,
            lead_gap >= active_lead_margin,
            lead_gap <= -active_lead_margin,
        )
        opposite_or_unset = (confirmed_lead_side == 0) | (
            confirmed_lead_side == -landed_side_now
        )
        lead_switch_candidate_event = (
            clean_touchdown_event
            & landed_leads
            & opposite_or_unset
            & (anchored_advance >= valid_advance_threshold)
            & (stance_drift <= active_stance_drift_limit)
        )
        invalid_replant_event = clean_touchdown_event & (~lead_switch_candidate_event)
        invalid_replant_hold = torch.where(
            invalid_replant_event,
            torch.full_like(invalid_replant_hold, active_event_hold),
            invalid_replant_hold,
        )

        # Replacing an unfinished candidate with another touchdown is a bounded
        # failure, never a phase gate.
        replaced_candidate = candidate_active & clean_touchdown_event
        incomplete_takeover_event = replaced_candidate
        incomplete_takeover_hold = torch.where(
            replaced_candidate,
            torch.full_like(incomplete_takeover_hold, active_event_hold),
            incomplete_takeover_hold,
        )
        candidate_active = torch.where(
            clean_touchdown_event, torch.zeros_like(candidate_active), candidate_active
        )

        landed_rel_base = quat_apply_inverse(
            root_yaw, detect_swing_pos - asset.data.root_pos_w
        )[:, :2]
        landed_rel_forward_at_touchdown = torch.sum(
            landed_rel_base * command_dir, dim=1
        )
        candidate_active = candidate_active | lead_switch_candidate_event
        candidate_landed_left = torch.where(
            lead_switch_candidate_event, landed_left_now, candidate_landed_left
        )
        candidate_elapsed = torch.where(
            lead_switch_candidate_event,
            torch.zeros_like(candidate_elapsed),
            candidate_elapsed,
        )
        candidate_touchdown_foot_w = torch.where(
            lead_switch_candidate_event.unsqueeze(-1),
            detect_swing_pos,
            candidate_touchdown_foot_w,
        )
        candidate_start_foot_rel_base_forward = torch.where(
            lead_switch_candidate_event,
            landed_rel_forward_at_touchdown,
            candidate_start_foot_rel_base_forward,
        )
        candidate_advance = torch.where(
            lead_switch_candidate_event, anchored_advance, candidate_advance
        )
        candidate_lead_gap = torch.where(
            lead_switch_candidate_event, torch.abs(lead_gap), candidate_lead_gap
        )

        # Contact edges always end the current flight measurement, including toe
        # chatter and same-place replants.
        clean_flight_time = torch.where(
            contact_rise, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(contact_rise, torch.zeros_like(lift_peak), lift_peak)

        candidate_elapsed = torch.where(
            candidate_active, candidate_elapsed + dt, candidate_elapsed
        )
        candidate_landed_pos = torch.where(
            candidate_landed_left.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        candidate_old_pos = torch.where(
            candidate_landed_left.unsqueeze(-1), foot_pos[:, 1, :], foot_pos[:, 0, :]
        )
        candidate_landed_contact = torch.where(
            candidate_landed_left, left_contact, right_contact
        )
        candidate_rel_base = quat_apply_inverse(
            root_yaw, candidate_landed_pos - asset.data.root_pos_w
        )[:, :2]
        old_rel_base = quat_apply_inverse(
            root_yaw, candidate_old_pos - asset.data.root_pos_w
        )[:, :2]
        landed_foot_rel_base_forward = torch.sum(candidate_rel_base * command_dir, dim=1)
        old_foot_rel_base_forward = torch.sum(old_rel_base * command_dir, dim=1)
        support_odometry = (
            candidate_start_foot_rel_base_forward - landed_foot_rel_base_forward
        )
        candidate_foot_drift = torch.linalg.vector_norm(
            candidate_landed_pos[:, :2] - candidate_touchdown_foot_w[:, :2], dim=1
        )
        lead_still_valid = torch.where(
            candidate_landed_left,
            lead_gap >= active_lead_margin,
            lead_gap <= -active_lead_margin,
        )
        base_progressed_over_new_foot = (
            (support_odometry >= takeover_target)
            & (landed_foot_rel_base_forward <= active_support_zone)
            & (old_foot_rel_base_forward <= -active_old_foot_behind)
        )
        true_step_event = (
            candidate_active
            & candidate_landed_contact
            & lead_still_valid
            & (candidate_foot_drift <= active_stance_drift_limit)
            & base_progressed_over_new_foot
        )

        completed_side = torch.where(
            candidate_landed_left,
            torch.ones(num_envs, device=device, dtype=torch.long),
            -torch.ones(num_envs, device=device, dtype=torch.long),
        )
        advance_score = torch.clamp(
            candidate_advance / torch.clamp(target_step, min=1.0e-6),
            min=0.0,
            max=1.25,
        )
        takeover_score = torch.clamp(
            support_odometry / torch.clamp(takeover_target, min=1.0e-6),
            min=0.0,
            max=1.25,
        )
        event_score = torch.clamp(
            0.5 * advance_score + 0.5 * takeover_score, min=0.0, max=1.0
        )
        true_step_score = torch.where(true_step_event, event_score, true_step_score)
        true_step_hold = torch.where(
            true_step_event,
            torch.full_like(true_step_hold, active_event_hold),
            true_step_hold,
        )

        had_previous_step = true_step_count > 0
        alternates_previous = last_true_step_side == -completed_side
        true_stride_event = true_step_event & had_previous_step & alternates_previous
        true_stride_score = torch.where(
            true_stride_event, event_score, true_stride_score
        )
        true_stride_hold = torch.where(
            true_stride_event,
            torch.full_like(true_stride_hold, active_event_hold),
            true_stride_hold,
        )
        confirmed_lead_side = torch.where(
            true_step_event, completed_side, confirmed_lead_side
        )
        last_true_step_side = torch.where(
            true_step_event, completed_side, last_true_step_side
        )
        true_step_count = torch.where(
            true_step_event, true_step_count + 1, true_step_count
        )
        candidate_active = torch.where(
            true_step_event, torch.zeros_like(candidate_active), candidate_active
        )
        candidate_elapsed = torch.where(
            true_step_event, torch.zeros_like(candidate_elapsed), candidate_elapsed
        )

        candidate_timeout = candidate_active & (
            (candidate_elapsed >= active_takeover_window)
            | (~candidate_landed_contact)
            | (~lead_still_valid)
            | (candidate_foot_drift > active_stance_drift_limit)
        )
        incomplete_takeover_event = incomplete_takeover_event | candidate_timeout
        incomplete_takeover_hold = torch.where(
            candidate_timeout,
            torch.full_like(incomplete_takeover_hold, active_event_hold),
            incomplete_takeover_hold,
        )
        candidate_active = torch.where(
            candidate_timeout, torch.zeros_like(candidate_active), candidate_active
        )
        candidate_elapsed = torch.where(
            candidate_timeout, torch.zeros_like(candidate_elapsed), candidate_elapsed
        )

        new_stance_pos = torch.where(
            left_stance.unsqueeze(-1), foot_pos[:, 0, :], foot_pos[:, 1, :]
        )
        stance_anchor_w = torch.where(
            halfcycle_event.unsqueeze(-1), new_stance_pos, stance_anchor_w
        )
        clean_flight_time = torch.where(
            halfcycle_event, torch.zeros_like(clean_flight_time), clean_flight_time
        )
        lift_peak = torch.where(
            halfcycle_event, torch.zeros_like(lift_peak), lift_peak
        )
        next_swing_contact = torch.where(left_stance, right_contact, left_contact)
        prev_swing_contact = torch.where(
            halfcycle_event, next_swing_contact, detect_swing_contact
        )
        prev_left_stance = left_stance
        was_moving = moving

        env._littlegreen_v11d_was_moving = was_moving
        env._littlegreen_v11d_prev_left_stance = prev_left_stance
        env._littlegreen_v11d_stance_anchor_w = stance_anchor_w
        env._littlegreen_v11d_prev_swing_contact = prev_swing_contact
        env._littlegreen_v11d_clean_flight_time_s = clean_flight_time
        env._littlegreen_v11d_lift_peak_m = lift_peak
        env._littlegreen_v11d_confirmed_lead_side = confirmed_lead_side
        env._littlegreen_v11d_last_true_step_side = last_true_step_side
        env._littlegreen_v11d_true_step_count = true_step_count
        env._littlegreen_v11d_candidate_active = candidate_active
        env._littlegreen_v11d_candidate_landed_left = candidate_landed_left
        env._littlegreen_v11d_candidate_elapsed_s = candidate_elapsed
        env._littlegreen_v11d_candidate_touchdown_foot_w = candidate_touchdown_foot_w
        env._littlegreen_v11d_candidate_start_foot_rel_base_forward_m = (
            candidate_start_foot_rel_base_forward
        )
        env._littlegreen_v11d_candidate_advance_m = candidate_advance
        env._littlegreen_v11d_candidate_lead_gap_m = candidate_lead_gap
        env._littlegreen_v11d_true_step_hold_s = true_step_hold
        env._littlegreen_v11d_true_step_score = true_step_score
        env._littlegreen_v11d_true_stride_hold_s = true_stride_hold
        env._littlegreen_v11d_true_stride_score = true_stride_score
        env._littlegreen_v11d_invalid_replant_hold_s = invalid_replant_hold
        env._littlegreen_v11d_incomplete_takeover_hold_s = incomplete_takeover_hold
        env._littlegreen_v11d_clean_touchdown_event = clean_touchdown_event
        env._littlegreen_v11d_lead_switch_candidate_event = lead_switch_candidate_event
        env._littlegreen_v11d_invalid_replant_event = invalid_replant_event
        env._littlegreen_v11d_true_step_event = true_step_event
        env._littlegreen_v11d_true_stride_event = true_stride_event
        env._littlegreen_v11d_incomplete_takeover_event = incomplete_takeover_event
        env._littlegreen_v11d_lead_gap_m = lead_gap
        env._littlegreen_v11d_stance_drift_m = stance_drift
        env._littlegreen_v11d_support_odometry_m = support_odometry
        env._littlegreen_v11d_landed_foot_rel_base_forward_m = landed_foot_rel_base_forward
        env._littlegreen_v11d_old_foot_rel_base_forward_m = old_foot_rel_base_forward
        env._littlegreen_v11d_target_step_m = target_step
        env._littlegreen_v11d_takeover_target_m = takeover_target
        env._littlegreen_v11d_last_common_step = common_step
    else:
        clean_touchdown_event = _tensor(
            "_littlegreen_v11d_clean_touchdown_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        lead_switch_candidate_event = _tensor(
            "_littlegreen_v11d_lead_switch_candidate_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        invalid_replant_event = _tensor(
            "_littlegreen_v11d_invalid_replant_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        true_step_event = _tensor(
            "_littlegreen_v11d_true_step_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        true_stride_event = _tensor(
            "_littlegreen_v11d_true_stride_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        incomplete_takeover_event = _tensor(
            "_littlegreen_v11d_incomplete_takeover_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        lead_gap = _tensor(
            "_littlegreen_v11d_lead_gap_m", torch.zeros(num_envs, device=device)
        )
        stance_drift = _tensor(
            "_littlegreen_v11d_stance_drift_m", torch.zeros(num_envs, device=device)
        )
        support_odometry = _tensor(
            "_littlegreen_v11d_support_odometry_m", torch.zeros(num_envs, device=device)
        )
        landed_foot_rel_base_forward = _tensor(
            "_littlegreen_v11d_landed_foot_rel_base_forward_m",
            torch.zeros(num_envs, device=device),
        )
        old_foot_rel_base_forward = _tensor(
            "_littlegreen_v11d_old_foot_rel_base_forward_m",
            torch.zeros(num_envs, device=device),
        )

    return {
        **base,
        "clean_touchdown_event_v11d": clean_touchdown_event,
        "lead_switch_candidate_event_v11d": lead_switch_candidate_event,
        "invalid_replant_event_v11d": invalid_replant_event,
        "true_step_event_v11d": true_step_event,
        "true_stride_event_v11d": true_stride_event,
        "incomplete_takeover_event_v11d": incomplete_takeover_event,
        "confirmed_lead_side_v11d": confirmed_lead_side,
        "candidate_active_v11d": candidate_active,
        "lead_gap_v11d": lead_gap,
        "stance_drift_v11d": stance_drift,
        "support_odometry_v11d": support_odometry,
        "landed_foot_rel_base_forward_v11d": landed_foot_rel_base_forward,
        "old_foot_rel_base_forward_v11d": old_foot_rel_base_forward,
        "target_step_v11d": target_step,
        "takeover_target_v11d": takeover_target,
        "true_step_held_score_v11d": torch.where(
            true_step_hold > 0.0, true_step_score, torch.zeros_like(true_step_score)
        ),
        "true_stride_held_score_v11d": torch.where(
            true_stride_hold > 0.0, true_stride_score, torch.zeros_like(true_stride_score)
        ),
        "invalid_replant_held_v11d": invalid_replant_hold > 0.0,
        "incomplete_takeover_held_v11d": incomplete_takeover_hold > 0.0,
        "progression_scale_v11d": torch.full_like(base["phase"], progression_scale),
    }


def v11d_true_step_completion_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Reward only physically completed opposite-foot steps."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return (
        data["progression_scale_v11d"]
        * data["true_step_held_score_v11d"]
        * data["moving"].float()
    )


def v11d_true_stride_completion_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Bonus after two consecutive true steps on opposite feet."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return (
        data["progression_scale_v11d"]
        * data["true_stride_held_score_v11d"]
        * data["moving"].float()
    )


def v11d_invalid_replant_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Bounded penalty for clean but same-place/backward/non-alternating replants."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["invalid_replant_held_v11d"].float() * data["moving"].float()


def v11d_incomplete_takeover_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Bounded penalty when an ahead touchdown is not followed by base takeover."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    return data["incomplete_takeover_held_v11d"].float() * data["moving"].float()


def v11d_stance_anchor_drift_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize dragging the supporting foot to manufacture apparent step advance."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    active_limit = float(
        getattr(env, "_littlegreen_v11d_stance_drift_limit_m", 0.018)
    )
    return (
        torch.clamp(data["stance_drift_v11d"] / max(active_limit, 1.0e-6), min=0.0, max=2.0)
        * data["moving"].float()
    )


def v11e_command_direction_swing_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    backward_ratio: float = 0.20,
) -> torch.Tensor:
    """Dense command-relative swing progress with an early, smooth clearance gate.

    Unlike the v11d sparse true-step event, this term gives the policy useful credit
    while the expected swing foot is still learning to lift and move.  It is defined
    in the commanded planar direction, so the same implementation supports forward,
    backward, lateral, and diagonal commands without adding observations.

    A small clearance is still required before meaningful credit is available.  This
    prevents pure dragging from collecting the full reward while avoiding the old
    all-or-nothing gate that suppressed exploration.
    """
    data = _v11c_soft_takeover_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )

    gate_start = float(
        getattr(env, "_littlegreen_v11e_clearance_gate_start_m", 0.004)
    )
    gate_full = float(
        getattr(env, "_littlegreen_v11e_clearance_gate_full_m", 0.010)
    )
    placement_start = float(
        getattr(env, "_littlegreen_v11e_placement_start_progress", 0.10)
    )
    scale = float(
        getattr(env, "_littlegreen_v11e_swing_progress_scale", 1.0)
    )

    if gate_full <= gate_start:
        raise ValueError("v11e clearance full gate must exceed the start gate")
    if not 0.0 <= placement_start < 1.0:
        raise ValueError("v11e placement_start_progress must be in [0, 1)")

    clearance_gate = torch.clamp(
        (data["clearance_v11c"] - gate_start) / (gate_full - gate_start),
        min=0.0,
        max=1.0,
    )
    clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)

    phase_gate = torch.clamp(
        (data["swing_progress"] - placement_start)
        / max(0.34 - placement_start, 1.0e-6),
        min=0.0,
        max=1.0,
    )
    phase_gate = phase_gate * phase_gate * (3.0 - 2.0 * phase_gate)

    target = torch.clamp(data["target_step_v11c"], min=1.0e-6)
    normalized_advance = torch.clamp(
        data["anchored_advance"] / target, min=-1.0, max=1.25
    )

    # Add a potential-difference component so moving the foot earns more than
    # merely holding it at a partially advanced position.
    num_envs = normalized_advance.shape[0]
    device = normalized_advance.device
    previous = getattr(env, "_littlegreen_v11e_prev_anchored_advance_m", None)
    if not isinstance(previous, torch.Tensor) or previous.shape[0] != num_envs:
        previous = data["anchored_advance"].detach().clone()
    previous = previous.to(device=device)

    previous_left_stance = getattr(env, "_littlegreen_v11e_prev_left_stance", None)
    if (
        not isinstance(previous_left_stance, torch.Tensor)
        or previous_left_stance.shape[0] != num_envs
    ):
        previous_left_stance = data["left_stance"].detach().clone()
    previous_left_stance = previous_left_stance.to(device=device, dtype=torch.bool)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11e_swing_progress_last_step", -1))
    delta_advance = getattr(env, "_littlegreen_v11e_delta_advance_m", None)
    if not isinstance(delta_advance, torch.Tensor) or delta_advance.shape[0] != num_envs:
        delta_advance = torch.zeros(num_envs, device=device)
    delta_advance = delta_advance.to(device=device)

    if common_step != last_step:
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        phase_changed = previous_left_stance != data["left_stance"]
        clear = reset_mask | (~data["moving"]) | data["halfcycle_event"] | phase_changed
        delta_advance = torch.where(
            clear,
            torch.zeros_like(delta_advance),
            data["anchored_advance"] - previous,
        )
        previous = data["anchored_advance"].detach().clone()
        previous_left_stance = data["left_stance"].detach().clone()
        env._littlegreen_v11e_prev_anchored_advance_m = previous
        env._littlegreen_v11e_prev_left_stance = previous_left_stance
        env._littlegreen_v11e_delta_advance_m = delta_advance
        env._littlegreen_v11e_swing_progress_last_step = common_step

    incremental = torch.clamp(
        delta_advance / torch.clamp(0.12 * target, min=0.002),
        min=-1.0,
        max=1.0,
    )
    score = 0.60 * normalized_advance + 0.40 * incremental
    score = torch.where(score >= 0.0, score, float(backward_ratio) * score)

    active = (~data["transition"]) & data["moving"]
    output = scale * score * clearance_gate * phase_gate * active.float()

    env._littlegreen_v11e_dense_swing_advance_m = data["anchored_advance"].detach()
    env._littlegreen_v11e_dense_swing_progress_score = output.detach()
    env._littlegreen_v11e_dense_swing_clearance_gate = clearance_gate.detach()
    return output


def v11e_invalid_replant_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Stage-scaled invalid-replant penalty; nearly disabled during exploration."""
    scale = float(getattr(env, "_littlegreen_v11e_failure_penalty_scale", 0.0))
    return scale * v11d_invalid_replant_penalty(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
    )


def v11e_incomplete_takeover_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Stage-scaled incomplete-takeover penalty that never blocks alternation."""
    scale = float(getattr(env, "_littlegreen_v11e_failure_penalty_scale", 0.0))
    return scale * v11d_incomplete_takeover_penalty(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
    )


def v11e_stance_anchor_drift_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize only stance drift beyond a staged dead zone."""
    data = _v11d_true_step_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    deadzone = float(
        getattr(env, "_littlegreen_v11e_stance_drift_deadzone_m", 0.025)
    )
    limit = float(
        getattr(env, "_littlegreen_v11d_stance_drift_limit_m", 0.040)
    )
    scale = float(getattr(env, "_littlegreen_v11e_stance_drift_scale", 0.0))
    span = max(limit - deadzone, 1.0e-6)
    excess = torch.relu(data["stance_drift_v11d"] - deadzone) / span
    return scale * torch.clamp(excess, min=0.0, max=1.5) * data["moving"].float()


def v11e_moving_stance_foot_slide_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.20,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Stance-slide penalty with a small velocity dead zone for natural foot roll."""
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    in_contact = forces.norm(dim=-1).max(dim=1)[0] > force_threshold
    single_support = torch.sum(in_contact.int(), dim=1) == 1
    asset = env.scene[asset_cfg.name]
    foot_vel_xy = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :2]
    stance_speed = torch.sum(
        torch.linalg.vector_norm(foot_vel_xy, dim=-1) * in_contact.float(), dim=1
    )
    deadzone = float(
        getattr(env, "_littlegreen_v11e_stance_slide_deadzone_m_s", 0.040)
    )
    scale = float(getattr(env, "_littlegreen_v11e_stance_slide_scale", 0.20))
    excess = torch.relu(stance_speed - deadzone)
    return (
        scale
        * excess
        * single_support.float()
        * _moving_command_mask(env, command_name, command_threshold)
    )


def v11e_same_side_airborne_persistence_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.20,
    force_threshold: float = 1.0,
) -> torch.Tensor:
    """Discourage one foot remaining airborne across multiple intended half-cycles."""
    del asset_cfg
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    contacts = forces.norm(dim=-1).max(dim=1)[0] > force_threshold
    left_contact = contacts[:, 0]
    right_contact = contacts[:, 1]
    single_support = left_contact ^ right_contact

    # +1 means left foot airborne, -1 means right foot airborne, 0 otherwise.
    airborne_side = torch.where(
        right_contact & (~left_contact),
        torch.ones_like(left_contact, dtype=torch.long),
        torch.where(
            left_contact & (~right_contact),
            -torch.ones_like(left_contact, dtype=torch.long),
            torch.zeros_like(left_contact, dtype=torch.long),
        ),
    )
    moving = _moving_command_mask(env, command_name, command_threshold).bool()
    num_envs = airborne_side.shape[0]
    device = airborne_side.device

    previous_side = getattr(env, "_littlegreen_v11e_airborne_side", None)
    if not isinstance(previous_side, torch.Tensor) or previous_side.shape[0] != num_envs:
        previous_side = torch.zeros(num_envs, device=device, dtype=torch.long)
    previous_side = previous_side.to(device=device, dtype=torch.long)

    duration = getattr(env, "_littlegreen_v11e_airborne_persistence_s", None)
    if not isinstance(duration, torch.Tensor) or duration.shape[0] != num_envs:
        duration = torch.zeros(num_envs, device=device)
    duration = duration.to(device=device)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11e_airborne_last_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        same_side = single_support & moving & (airborne_side == previous_side)
        duration = torch.where(
            same_side,
            duration + dt,
            torch.where(single_support & moving, torch.full_like(duration, dt), torch.zeros_like(duration)),
        )
        duration = torch.where(reset_mask | (~moving), torch.zeros_like(duration), duration)
        previous_side = torch.where(single_support & moving, airborne_side, torch.zeros_like(airborne_side))
        env._littlegreen_v11e_airborne_side = previous_side
        env._littlegreen_v11e_airborne_persistence_s = duration
        env._littlegreen_v11e_airborne_last_step = common_step

    grace = float(getattr(env, "_littlegreen_v11e_airborne_grace_s", 0.55))
    ramp = float(getattr(env, "_littlegreen_v11e_airborne_ramp_s", 0.25))
    scale = float(getattr(env, "_littlegreen_v11e_airborne_persistence_scale", 0.20))
    score = torch.clamp((duration - grace) / max(ramp, 1.0e-6), min=0.0, max=1.0)
    return scale * score * moving.float()


def _v11f_stride_chain_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    linear_command_threshold: float = 0.20,
    yaw_command_threshold: float = 0.08,
    period_s: float = 0.82,
    transition_fraction: float = 0.055,
    force_threshold: float = 1.0,
    lead_deadband_m: float = 0.006,
    clearance_gate_start_m: float = 0.008,
    clearance_gate_full_m: float = 0.014,
    clean_flight_s: float = 0.040,
    event_hold_s: float = 0.14,
    drag_speed_deadzone_m_s: float = 0.045,
    stall_grace_s: float = 1.40,
    stall_ramp_s: float = 0.90,
) -> dict[str, torch.Tensor]:
    """Reward-only stride chain that makes the opposite trailing foot the priority.

    v11e preserved bilateral phase rhythm but could repeatedly lift the already-leading
    foot because the dense swing reward was defined relative to the clock-selected
    stance foot.  This state separates *phase alternation* from *physical stride
    alternation* without changing the 47-D actor observation.

    A clean lead-switch touchdown starts a chain.  Until the opposite foot completes a
    physical step and takeover, only that trailing foot receives dense pass credit.  A
    repeated swing of the already-leading foot receives a bounded penalty, but the phase
    never freezes and the episode is never terminated by a failed step.
    """
    data = _v11d_true_step_state(
        env,
        command_name=command_name,
        asset_cfg=asset_cfg,
        sensor_cfg=sensor_cfg,
        linear_command_threshold=linear_command_threshold,
        yaw_command_threshold=yaw_command_threshold,
        period_s=period_s,
        transition_fraction=transition_fraction,
        force_threshold=force_threshold,
    )

    command = env.command_manager.get_command(command_name)
    linear_norm = torch.linalg.vector_norm(command[:, :2], dim=1)
    num_envs = command.shape[0]
    device = command.device
    moving = data["moving"]
    asset = env.scene[asset_cfg.name]

    command_dir = command[:, :2] / torch.clamp(linear_norm.unsqueeze(-1), min=1.0e-6)
    fallback_dir = torch.zeros_like(command_dir)
    fallback_dir[:, 0] = 1.0
    command_dir = torch.where(
        (linear_norm > 1.0e-6).unsqueeze(-1), command_dir, fallback_dir
    )

    active_lead_deadband = float(
        getattr(env, "_littlegreen_v11f_lead_deadband_m", lead_deadband_m)
    )
    active_clearance_start = float(
        getattr(
            env,
            "_littlegreen_v11f_clearance_gate_start_m",
            clearance_gate_start_m,
        )
    )
    active_clearance_full = float(
        getattr(
            env,
            "_littlegreen_v11f_clearance_gate_full_m",
            clearance_gate_full_m,
        )
    )
    active_clean_flight = float(
        getattr(env, "_littlegreen_v11f_clean_flight_s", clean_flight_s)
    )
    active_event_hold = float(
        getattr(env, "_littlegreen_v11f_event_hold_s", event_hold_s)
    )
    active_drag_deadzone = float(
        getattr(
            env,
            "_littlegreen_v11f_drag_speed_deadzone_m_s",
            drag_speed_deadzone_m_s,
        )
    )
    active_stall_grace = float(
        getattr(env, "_littlegreen_v11f_stall_grace_s", stall_grace_s)
    )
    active_stall_ramp = float(
        getattr(env, "_littlegreen_v11f_stall_ramp_s", stall_ramp_s)
    )
    if active_clearance_full <= active_clearance_start:
        raise ValueError("v11f clearance full gate must exceed the start gate")

    def _tensor(
        name: str,
        default: torch.Tensor,
        dtype: torch.dtype | None = None,
    ) -> torch.Tensor:
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or value.shape[0] != num_envs:
            value = default.clone()
        value = value.to(device=device)
        if dtype is not None:
            value = value.to(dtype=dtype)
        return value

    scheduled_swing_side = torch.where(
        data["left_stance"],
        -torch.ones(num_envs, device=device, dtype=torch.long),
        torch.ones(num_envs, device=device, dtype=torch.long),
    )
    lead_gap = data["lead_gap_v11d"]
    physical_trailing_side = torch.where(
        lead_gap > active_lead_deadband,
        -torch.ones_like(scheduled_swing_side),
        torch.where(
            lead_gap < -active_lead_deadband,
            torch.ones_like(scheduled_swing_side),
            scheduled_swing_side,
        ),
    )

    chain_active = _tensor(
        "_littlegreen_v11f_chain_active",
        torch.zeros(num_envs, device=device, dtype=torch.bool),
        torch.bool,
    )
    chain_first_side = _tensor(
        "_littlegreen_v11f_chain_first_side",
        torch.zeros(num_envs, device=device, dtype=torch.long),
        torch.long,
    )
    chain_start_root_pos = _tensor(
        "_littlegreen_v11f_chain_start_root_pos_w", asset.data.root_pos_w.clone()
    )
    chain_elapsed = _tensor(
        "_littlegreen_v11f_chain_elapsed_s", torch.zeros(num_envs, device=device)
    )
    previous_due_gap = _tensor(
        "_littlegreen_v11f_previous_due_gap_m", torch.zeros(num_envs, device=device)
    )
    previous_due_side = _tensor(
        "_littlegreen_v11f_previous_due_side",
        scheduled_swing_side.clone(),
        torch.long,
    )

    first_step_hold = _tensor(
        "_littlegreen_v11f_first_step_hold_s", torch.zeros(num_envs, device=device)
    )
    first_step_score = _tensor(
        "_littlegreen_v11f_first_step_score", torch.zeros(num_envs, device=device)
    )
    lead_reversal_hold = _tensor(
        "_littlegreen_v11f_lead_reversal_hold_s", torch.zeros(num_envs, device=device)
    )
    lead_reversal_score = _tensor(
        "_littlegreen_v11f_lead_reversal_score", torch.zeros(num_envs, device=device)
    )
    stride_hold = _tensor(
        "_littlegreen_v11f_stride_hold_s", torch.zeros(num_envs, device=device)
    )
    stride_score = _tensor(
        "_littlegreen_v11f_stride_score", torch.zeros(num_envs, device=device)
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v11f_last_common_step", -1))

    first_step_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    lead_reversal_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    stride_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
    trailing_pass_score = torch.zeros(num_envs, device=device)
    opposite_takeover_score = torch.zeros(num_envs, device=device)
    leading_repeat_score = torch.zeros(num_envs, device=device)
    trailing_drag_score = torch.zeros(num_envs, device=device)
    stall_score = torch.zeros(num_envs, device=device)

    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v11f_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if (
                isinstance(last_episode_length, torch.Tensor)
                and last_episode_length.shape[0] == num_envs
            ):
                reset_mask = reset_mask | (
                    current_episode_length < last_episode_length.to(device=device)
                )
            env._littlegreen_v11f_last_episode_length = current_episode_length.clone()

        first_step_hold = torch.clamp(first_step_hold - dt, min=0.0)
        lead_reversal_hold = torch.clamp(lead_reversal_hold - dt, min=0.0)
        stride_hold = torch.clamp(stride_hold - dt, min=0.0)

        was_moving = _tensor(
            "_littlegreen_v11f_was_moving",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        onset = moving & (~was_moving)
        clear = reset_mask | onset | (~moving)

        candidate_landed_left = _tensor(
            "_littlegreen_v11d_candidate_landed_left",
            torch.ones(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        candidate_side = torch.where(
            candidate_landed_left,
            torch.ones(num_envs, device=device, dtype=torch.long),
            -torch.ones(num_envs, device=device, dtype=torch.long),
        )
        completed_side = data["confirmed_lead_side_v11d"]

        # A clean touchdown that establishes a new lead starts the alternating
        # stride chain even before the stricter base-takeover condition completes.
        seed_event = data["lead_switch_candidate_event_v11d"] & (~chain_active)
        fallback_seed = data["true_step_event_v11d"] & (~chain_active)
        seed_side = torch.where(seed_event, candidate_side, completed_side)
        first_step_event = seed_event | fallback_seed
        chain_active = chain_active | first_step_event
        chain_first_side = torch.where(first_step_event, seed_side, chain_first_side)
        chain_start_root_pos = torch.where(
            first_step_event.unsqueeze(-1), asset.data.root_pos_w, chain_start_root_pos
        )
        chain_elapsed = torch.where(
            first_step_event, torch.zeros_like(chain_elapsed), chain_elapsed
        )
        first_step_score = torch.where(
            first_step_event, torch.ones_like(first_step_score), first_step_score
        )
        first_step_hold = torch.where(
            first_step_event,
            torch.full_like(first_step_hold, active_event_hold),
            first_step_hold,
        )

        due_side_before = torch.where(
            chain_active, -chain_first_side, physical_trailing_side
        )
        opposite_candidate = (
            data["lead_switch_candidate_event_v11d"]
            & chain_active
            & (candidate_side == due_side_before)
        )
        lead_reversal_event = opposite_candidate
        reversal_score = torch.clamp(
            torch.abs(data["lead_gap_v11d"])
            / torch.clamp(data["target_step_v11d"], min=1.0e-6),
            min=0.0,
            max=1.0,
        )
        lead_reversal_score = torch.where(
            lead_reversal_event, reversal_score, lead_reversal_score
        )
        lead_reversal_hold = torch.where(
            lead_reversal_event,
            torch.full_like(lead_reversal_hold, active_event_hold),
            lead_reversal_hold,
        )

        # The stride jackpot is reserved for the opposite clean lead reversal plus
        # physical base takeover.  After completion, that landed foot becomes the
        # first side of the next rolling stride chain.
        stride_event = (
            data["true_step_event_v11d"]
            & chain_active
            & (completed_side == due_side_before)
        )
        root_yaw = yaw_quat(asset.data.root_quat_w)
        cycle_delta = quat_apply_inverse(
            root_yaw, asset.data.root_pos_w - chain_start_root_pos
        )[:, :2]
        cycle_progress = torch.sum(cycle_delta * command_dir, dim=1)
        cycle_target = torch.clamp(
            1.35 * data["target_step_v11d"], min=0.024
        )
        cycle_score = torch.clamp(
            cycle_progress / torch.clamp(cycle_target, min=1.0e-6),
            min=0.0,
            max=1.25,
        )
        takeover_score_at_event = torch.clamp(
            data["support_odometry_v11d"]
            / torch.clamp(data["takeover_target_v11d"], min=1.0e-6),
            min=0.0,
            max=1.25,
        )
        new_stride_score = torch.clamp(
            0.65 * cycle_score + 0.35 * takeover_score_at_event,
            min=0.0,
            max=1.0,
        )
        stride_score = torch.where(stride_event, new_stride_score, stride_score)
        stride_hold = torch.where(
            stride_event,
            torch.full_like(stride_hold, active_event_hold),
            stride_hold,
        )
        chain_first_side = torch.where(stride_event, completed_side, chain_first_side)
        chain_start_root_pos = torch.where(
            stride_event.unsqueeze(-1), asset.data.root_pos_w, chain_start_root_pos
        )
        chain_elapsed = torch.where(stride_event, torch.zeros_like(chain_elapsed), chain_elapsed)

        chain_active = torch.where(clear, torch.zeros_like(chain_active), chain_active)
        chain_first_side = torch.where(clear, torch.zeros_like(chain_first_side), chain_first_side)
        chain_start_root_pos = torch.where(
            clear.unsqueeze(-1), asset.data.root_pos_w, chain_start_root_pos
        )
        chain_elapsed = torch.where(
            clear | first_step_event | stride_event,
            torch.zeros_like(chain_elapsed),
            chain_elapsed + dt * chain_active.float(),
        )
        first_step_hold = torch.where(clear, torch.zeros_like(first_step_hold), first_step_hold)
        lead_reversal_hold = torch.where(
            clear, torch.zeros_like(lead_reversal_hold), lead_reversal_hold
        )
        stride_hold = torch.where(clear, torch.zeros_like(stride_hold), stride_hold)

        due_side = torch.where(chain_active, -chain_first_side, physical_trailing_side)
        due_gap = torch.where(due_side > 0, lead_gap, -lead_gap)
        due_changed = due_side != previous_due_side
        delta_due_gap = torch.where(
            clear | due_changed,
            torch.zeros_like(due_gap),
            due_gap - previous_due_gap,
        )

        scheduled_matches_due = scheduled_swing_side == due_side
        scheduled_contact = torch.where(
            scheduled_swing_side > 0, data["left_contact"], data["right_contact"]
        )
        clean_flight_time_now = _tensor(
            "_littlegreen_v11d_clean_flight_time_s",
            torch.zeros(num_envs, device=device),
        )
        clearance = data["clearance_v11c"]
        clearance_gate = torch.clamp(
            (clearance - active_clearance_start)
            / max(active_clearance_full - active_clearance_start, 1.0e-6),
            min=0.0,
            max=1.0,
        )
        clearance_gate = clearance_gate * clearance_gate * (3.0 - 2.0 * clearance_gate)
        flight_gate = torch.clamp(
            clean_flight_time_now / max(active_clean_flight, 1.0e-6),
            min=0.0,
            max=1.0,
        )
        clean_gate = clearance_gate * flight_gate

        target = torch.clamp(data["target_step_v11d"], min=0.010)
        incremental = torch.clamp(
            delta_due_gap / torch.clamp(0.18 * target, min=0.002),
            min=-1.0,
            max=1.0,
        )
        position = torch.clamp(
            (due_gap + target) / torch.clamp(2.0 * target, min=0.020),
            min=0.0,
            max=1.0,
        )
        pass_raw = 0.82 * incremental + 0.18 * position
        pass_raw = torch.where(pass_raw >= 0.0, pass_raw, 0.25 * pass_raw)
        pass_active = (
            moving
            & (~data["transition"])
            & scheduled_matches_due
        )
        trailing_pass_score = pass_raw * clean_gate * pass_active.float()

        candidate_landed_side = candidate_side
        candidate_matches_due = candidate_landed_side == due_side
        opposite_takeover_score = (
            torch.clamp(
                data["support_odometry_v11d"]
                / torch.clamp(data["takeover_target_v11d"], min=1.0e-6),
                min=0.0,
                max=1.0,
            )
            * data["candidate_active_v11d"].float()
            * candidate_matches_due.float()
            * moving.float()
        )

        # If the phase asks the already-leading foot to swing before the trailing
        # foot completes the stride, do not reward another front-foot rock.
        scheduled_is_leading = chain_active & (scheduled_swing_side == chain_first_side)
        leading_repeat_score = (
            scheduled_is_leading
            & moving
            & (~scheduled_contact)
        ).float() * torch.clamp(
            clearance / max(active_clearance_full, 1.0e-6), min=0.0, max=1.0
        )

        foot_vel_xy = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :2]
        due_vel_xy = torch.where(
            (due_side > 0).unsqueeze(-1), foot_vel_xy[:, 0, :], foot_vel_xy[:, 1, :]
        )
        due_forward_speed = torch.sum(due_vel_xy * command_dir, dim=1)
        due_contact = torch.where(due_side > 0, data["left_contact"], data["right_contact"])
        trailing_drag_score = (
            torch.clamp(
                (due_forward_speed - active_drag_deadzone) / 0.16,
                min=0.0,
                max=1.0,
            )
            * due_contact.float()
            * scheduled_matches_due.float()
            * moving.float()
            * (1.0 - clearance_gate)
        )

        stall_score = (
            torch.clamp(
                (chain_elapsed - active_stall_grace) / max(active_stall_ramp, 1.0e-6),
                min=0.0,
                max=1.0,
            )
            * chain_active.float()
            * moving.float()
        )

        previous_due_gap = due_gap.detach().clone()
        previous_due_side = due_side.detach().clone()
        was_moving = moving.detach().clone()

        env._littlegreen_v11f_chain_active = chain_active
        env._littlegreen_v11f_chain_first_side = chain_first_side
        env._littlegreen_v11f_chain_start_root_pos_w = chain_start_root_pos
        env._littlegreen_v11f_chain_elapsed_s = chain_elapsed
        env._littlegreen_v11f_previous_due_gap_m = previous_due_gap
        env._littlegreen_v11f_previous_due_side = previous_due_side
        env._littlegreen_v11f_was_moving = was_moving
        env._littlegreen_v11f_first_step_hold_s = first_step_hold
        env._littlegreen_v11f_first_step_score = first_step_score
        env._littlegreen_v11f_lead_reversal_hold_s = lead_reversal_hold
        env._littlegreen_v11f_lead_reversal_score = lead_reversal_score
        env._littlegreen_v11f_stride_hold_s = stride_hold
        env._littlegreen_v11f_stride_score = stride_score
        env._littlegreen_v11f_first_step_event = first_step_event
        env._littlegreen_v11f_lead_reversal_event = lead_reversal_event
        env._littlegreen_v11f_stride_event = stride_event
        env._littlegreen_v11f_due_side = due_side
        env._littlegreen_v11f_due_gap_m = due_gap
        env._littlegreen_v11f_scheduled_swing_side = scheduled_swing_side
        env._littlegreen_v11f_scheduled_matches_due = scheduled_matches_due
        env._littlegreen_v11f_trailing_pass_score = trailing_pass_score
        env._littlegreen_v11f_opposite_takeover_score = opposite_takeover_score
        env._littlegreen_v11f_leading_repeat_score = leading_repeat_score
        env._littlegreen_v11f_trailing_drag_score = trailing_drag_score
        env._littlegreen_v11f_stall_score = stall_score
        env._littlegreen_v11f_last_common_step = common_step
    else:
        due_side = _tensor(
            "_littlegreen_v11f_due_side", scheduled_swing_side.clone(), torch.long
        )
        due_gap = _tensor(
            "_littlegreen_v11f_due_gap_m", torch.zeros(num_envs, device=device)
        )
        scheduled_matches_due = _tensor(
            "_littlegreen_v11f_scheduled_matches_due",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        first_step_event = _tensor(
            "_littlegreen_v11f_first_step_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        lead_reversal_event = _tensor(
            "_littlegreen_v11f_lead_reversal_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        stride_event = _tensor(
            "_littlegreen_v11f_stride_event",
            torch.zeros(num_envs, device=device, dtype=torch.bool),
            torch.bool,
        )
        trailing_pass_score = _tensor(
            "_littlegreen_v11f_trailing_pass_score", torch.zeros(num_envs, device=device)
        )
        opposite_takeover_score = _tensor(
            "_littlegreen_v11f_opposite_takeover_score",
            torch.zeros(num_envs, device=device),
        )
        leading_repeat_score = _tensor(
            "_littlegreen_v11f_leading_repeat_score", torch.zeros(num_envs, device=device)
        )
        trailing_drag_score = _tensor(
            "_littlegreen_v11f_trailing_drag_score", torch.zeros(num_envs, device=device)
        )
        stall_score = _tensor(
            "_littlegreen_v11f_stall_score", torch.zeros(num_envs, device=device)
        )

    return {
        **data,
        "chain_active_v11f": chain_active,
        "chain_first_side_v11f": chain_first_side,
        "due_side_v11f": due_side,
        "due_gap_v11f": due_gap,
        "scheduled_swing_side_v11f": scheduled_swing_side,
        "scheduled_matches_due_v11f": scheduled_matches_due,
        "first_step_event_v11f": first_step_event,
        "lead_reversal_event_v11f": lead_reversal_event,
        "stride_event_v11f": stride_event,
        "first_step_held_score_v11f": torch.where(
            first_step_hold > 0.0, first_step_score, torch.zeros_like(first_step_score)
        ),
        "lead_reversal_held_score_v11f": torch.where(
            lead_reversal_hold > 0.0,
            lead_reversal_score,
            torch.zeros_like(lead_reversal_score),
        ),
        "stride_held_score_v11f": torch.where(
            stride_hold > 0.0, stride_score, torch.zeros_like(stride_score)
        ),
        "trailing_pass_score_v11f": trailing_pass_score,
        "opposite_takeover_score_v11f": opposite_takeover_score,
        "leading_repeat_score_v11f": leading_repeat_score,
        "trailing_drag_score_v11f": trailing_drag_score,
        "stall_score_v11f": stall_score,
        "chain_elapsed_v11f": chain_elapsed,
    }


def v11f_first_step_seed_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Small reward for establishing the first clean lead; later stages reduce it."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_first_step_scale", 0.35))
    return scale * data["first_step_held_score_v11f"] * data["moving"].float()


def v11f_trailing_foot_pass_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Dense clean-flight progress only for the physically trailing opposite foot."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_trailing_pass_scale", 1.0))
    return scale * data["trailing_pass_score_v11f"]


def v11f_lead_reversal_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Reward the opposite clean touchdown that reverses the physical lead order."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_lead_reversal_scale", 1.0))
    return scale * data["lead_reversal_held_score_v11f"] * data["moving"].float()


def v11f_opposite_takeover_progress_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Dense base-over-new-foot progress after the opposite lead reversal."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_takeover_scale", 1.0))
    return scale * data["opposite_takeover_score_v11f"]


def v11f_true_stride_chain_reward(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Large rolling reward for opposite lead reversal plus physical base takeover."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_stride_scale", 1.0))
    return scale * data["stride_held_score_v11f"] * data["moving"].float()


def v11f_leading_foot_repeat_swing_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize re-lifting the established leading foot before the rear foot passes."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_leading_repeat_scale", 0.5))
    return scale * data["leading_repeat_score_v11f"]


def v11f_trailing_foot_drag_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Penalize advancing the due trailing foot while it remains in ground contact."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_drag_scale", 0.5))
