def v11f_stride_stall_penalty(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
) -> torch.Tensor:
    """Bounded cost for preserving one lead for too long; never gates or terminates."""
    data = _v11f_stride_chain_state(
        env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg
    )
    scale = float(getattr(env, "_littlegreen_v11f_stall_scale", 0.25))
    return scale * data["stall_score_v11f"]


def moving_prolonged_whole_foot_double_support_v29(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    grace_s: float = 0.24,
    ramp_s: float = 0.20,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Penalize only *prolonged* whole-foot double support during moving commands.

    This is intentionally leg-agnostic and phase-agnostic.  Normal double support is
    free for ``grace_s``.  If both whole feet remain grounded longer, the penalty
    ramps linearly to 1 over ``ramp_s`` and then saturates.  A whole foot is grounded
    when ANY of its grouped bodies is in contact, matching passive-toe semantics.

    The ContactSensor's current contact-time provides the timer directly, so this term
    introduces no hidden gait state or step state machine.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_time = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    if contact_time.shape[1] != 2 * int(bodies_per_foot):
        raise ValueError(
            f"v2.9 prolonged double support expected {2 * int(bodies_per_foot)} bodies, "
            f"got {contact_time.shape[1]}"
        )
    g = int(bodies_per_foot)
    left_contact = torch.any(contact_time[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_time[:, g:] > 0.0, dim=1)
    # Longest active contact in each group represents persistence of whole-foot
    # grounding when either main-foot or passive toe remains planted.
    left_time = torch.max(contact_time[:, :g], dim=1).values
    right_time = torch.max(contact_time[:, g:], dim=1).values
    both_time = torch.minimum(left_time, right_time)
    denom = max(float(ramp_s), 1.0e-6)
    penalty = torch.clamp((both_time - float(grace_s)) / denom, min=0.0, max=1.0)
    both_grounded = left_contact & right_contact
    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return penalty * both_grounded.float() * moving.float()


def whole_foot_air_time_positive_biped_v28(
    env: ManagerBasedRLEnv,
    command_name: str,
    threshold: float,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Reward useful *whole-foot* single stance with a capped duration.

    This is the LittleGreen/passive-toe adaptation of the simple Berkeley biped
    ``feet_air_time_positive_biped`` abstraction.  The sensor bodies must be ordered
    left-foot bodies followed by right-foot bodies (v2.8 uses main-foot + toe for each).

    A foot is considered grounded when ANY body in its group is in contact.  Its air
    time is the MINIMUM current-air-time over the group, so heel-up/toe-down does not
    count as a released swing foot.  Reward is non-zero only when exactly one whole
    foot is grounded, and it saturates at ``threshold`` to avoid rewarding indefinite
    one-leg balance.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    if air.shape[1] != 2 * int(bodies_per_foot):
        raise ValueError(
            f"v2.8 whole-foot air-time expected {2 * int(bodies_per_foot)} bodies, got {air.shape[1]}"
        )
    g = int(bodies_per_foot)
    left_contact_each = contact[:, :g] > 0.0
    right_contact_each = contact[:, g:] > 0.0
    left_contact = torch.any(left_contact_each, dim=1)
    right_contact = torch.any(right_contact_each, dim=1)

    # Conservative group timing: full-foot release time is limited by the last body
    # to leave contact; stance duration uses the longest active contact in the group.
    left_air = torch.min(air[:, :g], dim=1).values
    right_air = torch.min(air[:, g:], dim=1).values
    left_contact_time = torch.max(contact[:, :g], dim=1).values
    right_contact_time = torch.max(contact[:, g:], dim=1).values
    left_mode_time = torch.where(left_contact, left_contact_time, left_air)
    right_mode_time = torch.where(right_contact, right_contact_time, right_air)

    single_stance = torch.logical_xor(left_contact, right_contact)
    useful_time = torch.minimum(left_mode_time, right_mode_time)
    reward = torch.where(single_stance, torch.clamp(useful_time, max=float(threshold)), 0.0)

    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return reward * moving.float()


def whole_foot_clearance_floor_v28(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    floor_m: float,
    command_threshold: float = 0.05,
    force_threshold: float = 1.0,
    body_component: str = "main",
) -> torch.Tensor:
    """Saturating swing-clearance floor gated on true whole-foot single stance.

    ``asset_cfg`` contains exactly one left and one right body for the component being
    measured (main foot or toe).  ``sensor_cfg`` contains four whole-foot contact
    bodies ordered left main/toe then right main/toe.  There is no reward above the
    floor and no upper-clearance penalty.
    """
    del body_component  # documentation-only tag used by config/static tests
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :].norm(dim=-1).max(dim=1).values
    if forces.shape[1] != 4:
        raise ValueError(f"v2.8 clearance floor expected 4 whole-foot contact bodies, got {forces.shape[1]}")
    contact = forces > float(force_threshold)
    left_contact = torch.any(contact[:, :2], dim=1)
    right_contact = torch.any(contact[:, 2:], dim=1)
    single = torch.logical_xor(left_contact, right_contact)

    asset = env.scene[asset_cfg.name]
    z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if z.shape[1] != 2:
        raise ValueError(f"v2.8 clearance floor expected 2 component bodies, got {z.shape[1]}")
    # If left is stance, right is swing; if right is stance, left is swing.
    clearance = torch.where(left_contact & ~right_contact, z[:, 1] - z[:, 0], z[:, 0] - z[:, 1])
    floor = max(float(floor_m), 1.0e-6)
    reward = torch.clamp(clearance / floor, min=0.0, max=1.0)
    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return reward * single.float() * moving.float()


# -----------------------------------------------------------------------------
# LittleGreen v3.0 canonical Walk contact-duration envelope
# -----------------------------------------------------------------------------
def moving_prolonged_whole_foot_single_support_v30(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    grace_s: float = 0.75,
    ramp_s: float = 0.25,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Penalize a whole foot remaining continuously airborne for too long while moving.

    This is symmetric and leg-agnostic.  Normal slow single support is free through
    ``grace_s``; beyond that, the penalty ramps to one over ``ramp_s``.  Whole-foot
    air time is conservative: main foot AND passive toe must both be released, so the
    group air time is the minimum current-air-time over the two bodies.

    This closes the v2.9 permanent-one-leg-balance exploit without scheduling which
    foot must swing or prescribing a gait phase.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    if air.shape[1] != 2 * int(bodies_per_foot):
        raise ValueError(
            f"v3.0 prolonged single support expected {2 * int(bodies_per_foot)} bodies, got {air.shape[1]}"
        )
    g = int(bodies_per_foot)
    left_contact = torch.any(contact[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact[:, g:] > 0.0, dim=1)
    single_support = torch.logical_xor(left_contact, right_contact)
    left_air = torch.min(air[:, :g], dim=1).values
    right_air = torch.min(air[:, g:], dim=1).values
    longest_whole_foot_air = torch.maximum(left_air, right_air)
    denom = max(float(ramp_s), 1.0e-6)
    penalty = torch.clamp((longest_whole_foot_air - float(grace_s)) / denom, min=0.0, max=1.0)
    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return penalty * single_support.float() * moving.float()


def moving_prolonged_whole_foot_stance_v30(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    grace_s: float = 1.10,
    ramp_s: float = 0.35,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Weakly penalize one whole foot staying continuously grounded for too long.

    The large grace window leaves normal slow walking untouched.  This term exists to
    close a subtler loophole where the same swing foot could repeatedly tap down and
    re-lift while the opposite stance foot never changes.  It remains fully symmetric
    and does not identify a required next leg.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    if contact.shape[1] != 2 * int(bodies_per_foot):
        raise ValueError(
            f"v3.0 prolonged stance expected {2 * int(bodies_per_foot)} bodies, got {contact.shape[1]}"
        )
    g = int(bodies_per_foot)
    left_contact = torch.any(contact[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact[:, g:] > 0.0, dim=1)
    # Whole-foot persistence follows the longest continuously grounded component,
    # matching the passive-toe definition used by the rest of the contact envelope.
    left_time = torch.max(contact[:, :g], dim=1).values
    right_time = torch.max(contact[:, g:], dim=1).values
    longest_stance = torch.maximum(left_time, right_time)
    denom = max(float(ramp_s), 1.0e-6)
    penalty = torch.clamp((longest_stance - float(grace_s)) / denom, min=0.0, max=1.0)
    at_least_one_grounded = left_contact | right_contact
    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return penalty * at_least_one_grounded.float() * moving.float()


# -----------------------------------------------------------------------------
# LittleGreen v3.1 command-direction swing passage / lead reversal
# -----------------------------------------------------------------------------
def _moving_airborne_command_passage_state_v31(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
):
    """Return leg-agnostic swing passage state projected onto the live XY command.

    A positive passage projection means the currently airborne whole foot has passed
    the grounded stance foot in the requested planar direction. There is no target
    stride length and no world-forward assumption.
    """
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    if contact_t.shape[1] != 2 * int(bodies_per_foot):
        raise ValueError(
            f"v3.1 swing passage expected {2 * int(bodies_per_foot)} contact bodies, got {contact_t.shape[1]}"
        )
    g = int(bodies_per_foot)
    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    left_stance = left_contact & ~right_contact
    right_stance = right_contact & ~left_contact
    single = left_stance | right_stance

    left_air = torch.min(air_t[:, :g], dim=1).values
    right_air = torch.min(air_t[:, g:], dim=1).values
    swing_air = torch.where(
        left_stance, right_air, torch.where(right_stance, left_air, torch.zeros_like(left_air))
    )

    asset = env.scene[asset_cfg.name]
    pos_xy = asset.data.body_pos_w[:, asset_cfg.body_ids, :2]
    if pos_xy.shape[1] != 2:
        raise ValueError(f"v3.1 swing passage expected 2 foot bodies, got {pos_xy.shape[1]}")
    stance_xy = torch.where(left_stance[:, None], pos_xy[:, 0], pos_xy[:, 1])
    swing_xy = torch.where(left_stance[:, None], pos_xy[:, 1], pos_xy[:, 0])

    command_xy = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.norm(command_xy, dim=1)
    direction = command_xy / torch.clamp(command_norm[:, None], min=1.0e-6)
    passage = torch.sum((swing_xy - stance_xy) * direction, dim=1)
    moving = command_norm > float(command_threshold)
    return moving, single, swing_air, passage


def moving_airborne_command_passage_v31(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    air_grace_s: float = 0.18,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Reward command-direction lead reversal with no prescribed stride distance.

    After a short airborne grace period, full reward is earned once the swing foot is
    simply ahead of the stance foot along the live planar command vector. This makes
    the criterion equally valid for forward, reverse, or lateral commands.
    """
    moving, single, swing_air, passage = _moving_airborne_command_passage_state_v31(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, bodies_per_foot
    )
    active = moving & single & (swing_air >= float(air_grace_s))
    return (passage > 0.0).float() * active.float()


def moving_airborne_command_passage_shortfall_v31(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    grace_s: float = 0.34,
    ramp_s: float = 0.24,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Penalize a late airborne foot that still has not reversed the lead.

    Spatially this is sign-only: no target step length is imposed. Temporally the
    penalty is zero through ``grace_s`` and then ramps to one over ``ramp_s`` while
    the swing foot remains behind the stance foot along the requested direction.
    """
    moving, single, swing_air, passage = _moving_airborne_command_passage_state_v31(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, bodies_per_foot
    )
    time_scale = torch.clamp(
        (swing_air - float(grace_s)) / max(float(ramp_s), 1.0e-6), min=0.0, max=1.0
    )
    incomplete = passage <= 0.0
    return time_scale * incomplete.float() * moving.float() * single.float()


# -----------------------------------------------------------------------------
# LittleGreen v3.3 per-foot liftoff -> touchdown command-direction progress
# -----------------------------------------------------------------------------
def _moving_per_foot_directional_touchdown_state_v33(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
):
    """Track independent left/right completed-step progress without prescribing stride length.

    For each whole foot, the final grounded sample before liftoff is stored together
    with the live planar command direction.  At the next whole-foot touchdown, step
    progress is the XY touchdown-minus-liftoff displacement projected onto that
    captured direction.  ``progress > 0`` is success and ``progress <= 0`` is failure.

    Capturing the direction at liftoff makes reverse walking automatic: for negative
    vx, a physical backward step has positive command-direction progress.  Lateral and
    diagonal commands use the same projection and do not require the feet to cross.
    There is no minimum/target stride distance and no phase-selected left/right foot.
    """
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    expected = 2 * int(bodies_per_foot)
    if contact_t.shape[1] != expected:
        raise ValueError(
            f"v3.3 touchdown progress expected {expected} contact bodies, got {contact_t.shape[1]}"
        )
    g = int(bodies_per_foot)
    grounded = torch.stack((
        torch.any(contact_t[:, :g] > 0.0, dim=1),
        torch.any(contact_t[:, g:] > 0.0, dim=1),
    ), dim=1)

    asset = env.scene[asset_cfg.name]
    pos_xy = asset.data.body_pos_w[:, asset_cfg.body_ids, :2]
    if pos_xy.shape[1] != 2:
        raise ValueError(f"v3.3 touchdown progress expected 2 main-foot bodies, got {pos_xy.shape[1]}")

    command_xy = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    current_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    # Velocity commands are expressed in the robot yaw frame.  Convert the command
    # direction to world XY before storing it so world-frame foot displacement is
    # projected into the correct requested direction, including reverse/lateral cases.
    current_dir_3d = torch.cat((current_dir, torch.zeros_like(current_dir[:, :1])), dim=1)
    current_dir_w = quat_apply(yaw_quat(asset.data.root_quat_w), current_dir_3d)[:, :2]

    num_envs = pos_xy.shape[0]
    device = pos_xy.device

    def _state_tensor(name: str, shape, dtype, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.clone()
        return value.to(device=device, dtype=dtype)

    prev_grounded = _state_tensor(
        "_littlegreen_v33_prev_grounded", grounded.shape, torch.bool, grounded
    )
    prev_pos_xy = _state_tensor(
        "_littlegreen_v33_prev_foot_pos_xy", pos_xy.shape, pos_xy.dtype, pos_xy
    )
    active = _state_tensor(
        "_littlegreen_v33_step_active", grounded.shape, torch.bool,
        torch.zeros_like(grounded, dtype=torch.bool),
    )
    liftoff_pos = _state_tensor(
        "_littlegreen_v33_liftoff_pos_xy", pos_xy.shape, pos_xy.dtype, pos_xy
    )
    liftoff_dir = _state_tensor(
        "_littlegreen_v33_liftoff_command_dir_xy", pos_xy.shape, pos_xy.dtype,
        current_dir_w[:, None, :].expand(-1, 2, -1),
    )
    success_hold = _state_tensor(
        "_littlegreen_v33_touchdown_success_hold_s", grounded.shape, pos_xy.dtype,
        torch.zeros(grounded.shape, device=device, dtype=pos_xy.dtype),
    )
    failure_hold = _state_tensor(
        "_littlegreen_v33_touchdown_failure_hold_s", grounded.shape, pos_xy.dtype,
        torch.zeros(grounded.shape, device=device, dtype=pos_xy.dtype),
    )
    last_progress = _state_tensor(
        "_littlegreen_v33_last_touchdown_progress_m", grounded.shape, pos_xy.dtype,
        torch.zeros(grounded.shape, device=device, dtype=pos_xy.dtype),
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v33_touchdown_last_common_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v33_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v33_last_episode_length = current_episode_length.clone()

        # Held event credit makes the sparse touchdown event visible for a few policy
        # frames without changing the geometric success criterion.
        success_hold = torch.clamp(success_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)

        # Episode reset invalidates unfinished steps and reinitializes edge detection.
        reset2 = reset_mask.unsqueeze(-1)
        active = torch.where(reset2, torch.zeros_like(active), active)
        success_hold = torch.where(reset2, torch.zeros_like(success_hold), success_hold)
        failure_hold = torch.where(reset2, torch.zeros_like(failure_hold), failure_hold)
        last_progress = torch.where(reset2, torch.zeros_like(last_progress), last_progress)
        prev_grounded = torch.where(reset2, grounded, prev_grounded)
        prev_pos_xy = torch.where(reset2.unsqueeze(-1), pos_xy, prev_pos_xy)

        liftoff = prev_grounded & (~grounded) & moving.unsqueeze(-1) & (~reset2)
        # Use the final grounded position from the previous policy frame as liftoff
        # position; this avoids adding a one-frame airborne displacement bias.
        liftoff_pos = torch.where(liftoff.unsqueeze(-1), prev_pos_xy, liftoff_pos)
        captured_dir = current_dir_w[:, None, :].expand(-1, 2, -1)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), captured_dir, liftoff_dir)
        active = torch.where(liftoff, torch.ones_like(active), active)

        touchdown = (~prev_grounded) & grounded & active & moving.unsqueeze(-1) & (~reset2)
        progress = torch.sum((pos_xy - liftoff_pos) * liftoff_dir, dim=-1)
        success = touchdown & (progress > 0.0)
        failure = touchdown & (progress <= 0.0)
        hold = max(float(event_hold_s), dt)
        success_hold = torch.where(success, torch.full_like(success_hold, hold), success_hold)
        failure_hold = torch.where(failure, torch.full_like(failure_hold, hold), failure_hold)
        last_progress = torch.where(touchdown, progress, last_progress)
        active = torch.where(touchdown, torch.zeros_like(active), active)

        # If a locomotion command ends while a foot is airborne, discard that pending
        # step rather than judging it against a stale command.  A new moving liftoff
        # will capture a fresh direction.
        active = active & moving.unsqueeze(-1)

        prev_grounded = grounded.clone()
        prev_pos_xy = pos_xy.clone()

        env._littlegreen_v33_prev_grounded = prev_grounded
        env._littlegreen_v33_prev_foot_pos_xy = prev_pos_xy
        env._littlegreen_v33_step_active = active
        env._littlegreen_v33_liftoff_pos_xy = liftoff_pos
        env._littlegreen_v33_liftoff_command_dir_xy = liftoff_dir
        env._littlegreen_v33_touchdown_success_hold_s = success_hold
        env._littlegreen_v33_touchdown_failure_hold_s = failure_hold
        env._littlegreen_v33_last_touchdown_progress_m = last_progress
        env._littlegreen_v33_touchdown_last_common_step = common_step

    return {
        "success": (success_hold > 0.0).float().sum(dim=1) * moving.float(),
        "failure": (failure_hold > 0.0).float().sum(dim=1) * moving.float(),
        "last_progress_m": last_progress,
        "active": active,
    }


def moving_per_foot_directional_touchdown_success_v33(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
) -> torch.Tensor:
    """Reward each completed footstep whose net displacement follows its liftoff command."""
    return _moving_per_foot_directional_touchdown_state_v33(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, bodies_per_foot, event_hold_s
    )["success"]


def moving_per_foot_directional_touchdown_failure_v33(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
) -> torch.Tensor:
    """Penalize each completed footstep with zero/backward progress vs its liftoff command."""
    return _moving_per_foot_directional_touchdown_state_v33(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, bodies_per_foot, event_hold_s
    )["failure"]

# -----------------------------------------------------------------------------
# LittleGreen v3.4 per-foot airborne progress from own liftoff point
# -----------------------------------------------------------------------------
def moving_per_foot_airborne_directional_progress_v34(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    air_grace_s: float = 0.16,
    command_threshold: float = 0.05,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
) -> torch.Tensor:
    """Reward an airborne foot once it moves in its captured command direction.

    This is deliberately *not* stance-relative passage.  The v3.3 completed-step
    state snapshots each foot's own final grounded XY position and command direction
    at liftoff.  v3.4 reuses those snapshots while the foot is airborne and gives a
    small sign-only shaping reward when::

        dot(current_foot_xy - liftoff_foot_xy, command_direction_at_liftoff) > 0

    No crossing of the stance foot and no target stride distance are required.  A
    lateral trailing foot may therefore follow the lead foot in the same direction,
    while reverse/diagonal commands are handled by the captured command vector.
    Touchdown success/failure remains authoritative in the v3.3 completion terms.
    """
    state = _moving_per_foot_directional_touchdown_state_v33(
        env,
        command_name,
        asset_cfg,
        sensor_cfg,
        command_threshold,
        bodies_per_foot,
        event_hold_s,
    )

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    expected = 2 * int(bodies_per_foot)
    if air_t.shape[1] != expected:
        raise ValueError(
            f"v3.4 airborne progress expected {expected} contact bodies, got {air_t.shape[1]}"
        )
    g = int(bodies_per_foot)
    whole_air = torch.stack((
        torch.min(air_t[:, :g], dim=1).values,
        torch.min(air_t[:, g:], dim=1).values,
    ), dim=1)

    asset = env.scene[asset_cfg.name]
    pos_xy = asset.data.body_pos_w[:, asset_cfg.body_ids, :2]
    if pos_xy.shape[1] != 2:
        raise ValueError(f"v3.4 airborne progress expected 2 main-foot bodies, got {pos_xy.shape[1]}")

    liftoff_pos = getattr(env, "_littlegreen_v33_liftoff_pos_xy", None)
    liftoff_dir = getattr(env, "_littlegreen_v33_liftoff_command_dir_xy", None)
    if not isinstance(liftoff_pos, torch.Tensor) or liftoff_pos.shape != pos_xy.shape:
        return torch.zeros(pos_xy.shape[0], device=pos_xy.device, dtype=pos_xy.dtype)
    if not isinstance(liftoff_dir, torch.Tensor) or liftoff_dir.shape != pos_xy.shape:
        return torch.zeros(pos_xy.shape[0], device=pos_xy.device, dtype=pos_xy.dtype)

    progress = torch.sum((pos_xy - liftoff_pos) * liftoff_dir, dim=-1)
    active = state["active"] & (whole_air >= float(air_grace_s))
    return ((progress > 0.0) & active).float().sum(dim=1)


def whole_foot_slide_v39(
    env: ManagerBasedRLEnv,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    force_threshold: float = 1.0,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Penalize LittleGreen whole-foot sliding without double-counting toe + main foot.

    Bodies must be ordered as all left-foot components followed by all right-foot
    components (v3.9: ankle/main + passive toe for each foot).  A physical foot is
    loaded if ANY grouped component is contacting.  For each loaded foot, the maximum
    planar speed among its contacting components is used as that foot's slide speed.
    The two foot-level values are then summed, matching the scale of the historical
    Berkeley two-foot ``feet_slide`` abstraction while preventing passive-toe skating.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = contact_sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    contacts = forces.norm(dim=-1).max(dim=1).values > float(force_threshold)

    asset = env.scene[asset_cfg.name]
    planar_speed = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :2].norm(dim=-1)

    g = int(bodies_per_foot)
    if g <= 0 or contacts.shape[1] != 2 * g or planar_speed.shape[1] != 2 * g:
        raise ValueError(
            f"v3.9 whole-foot slide expected {2 * g} ordered bodies, "
            f"got contacts={contacts.shape[1]} velocities={planar_speed.shape[1]}"
        )

    component_slide = planar_speed * contacts.float()
    left_slide = torch.max(component_slide[:, :g], dim=1).values
    right_slide = torch.max(component_slide[:, g:], dim=1).values
    return left_slide + right_slide

# -----------------------------------------------------------------------------
# LittleGreen v4.0 Berkeley whole-foot air-time with minimum clearance gating
# -----------------------------------------------------------------------------
def whole_foot_clearance_gated_air_time_positive_biped_v40(
    env: ManagerBasedRLEnv,
    command_name: str,
    threshold: float,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    min_clearance_m: float = 0.020,
    command_threshold: float = 0.10,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Berkeley positive biped air-time, qualified by true whole-foot clearance.

    This preserves the Berkeley ``feet_air_time_positive_biped`` abstraction and
    +time semantics while adapting the definition of useful air time to LittleGreen's
    passive-toe foot. Bodies must be ordered as::

        left main/ankle, left toe, right main/ankle, right toe

    A physical foot is grounded when *any* component remains in contact and its air
    time is limited by the last component to leave contact. Air-time reward is
    available only during true whole-foot single stance AND only when every component
    of the swing foot is at least ``min_clearance_m`` above the matching component of
    the grounded stance foot. The clearance value is a binary qualification only:
    there is no additional reward for 21 mm, 40 mm, or 100 mm of clearance.

    Matching-component relative height avoids introducing an absolute base-height or
    terrain-height target while closing the floor-skimming/skating loophole.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]

    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or air.shape[1] != expected or contact.shape[1] != expected:
        raise ValueError(
            f"v4.0 clearance-gated air-time expected {expected} ordered contact bodies, "
            f"got air={air.shape[1]} contact={contact.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if body_z.shape[1] != expected:
        raise ValueError(
            f"v4.0 clearance-gated air-time expected {expected} ordered robot bodies, "
            f"got {body_z.shape[1]}"
        )

    left_contact = torch.any(contact[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact[:, g:] > 0.0, dim=1)

    # Full-foot release is governed by the last grouped component to leave contact.
    left_air = torch.min(air[:, :g], dim=1).values
    right_air = torch.min(air[:, g:], dim=1).values
    left_contact_time = torch.max(contact[:, :g], dim=1).values
    right_contact_time = torch.max(contact[:, g:], dim=1).values
    left_mode_time = torch.where(left_contact, left_contact_time, left_air)
    right_mode_time = torch.where(right_contact, right_contact_time, right_air)

    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    single_stance = left_stance | right_stance

    # Compare main-to-main and toe-to-toe heights. Both swing components must clear
    # the same permissive floor; clearance above the floor is intentionally unscored.
    right_swing_clearance = body_z[:, g:] - body_z[:, :g]
    left_swing_clearance = body_z[:, :g] - body_z[:, g:]
    right_clear = torch.all(right_swing_clearance >= float(min_clearance_m), dim=1)
    left_clear = torch.all(left_swing_clearance >= float(min_clearance_m), dim=1)
    clearance_ok = (left_stance & right_clear) | (right_stance & left_clear)

    useful_time = torch.minimum(left_mode_time, right_mode_time)
    reward = torch.where(
        single_stance & clearance_ok,
        torch.clamp(useful_time, max=float(threshold)),
        0.0,
    )

    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return reward * moving.float()


# -----------------------------------------------------------------------------
# LittleGreen v4.1 Berkeley whole-foot air-time with smooth clearance bootstrap
# -----------------------------------------------------------------------------
def whole_foot_smooth_clearance_air_time_positive_biped_v41(
    env: ManagerBasedRLEnv,
    command_name: str,
    threshold: float,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    full_clearance_m: float = 0.020,
    command_threshold: float = 0.10,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Berkeley positive biped air-time with a dense LittleGreen clearance factor.

    Bodies must be ordered as left main/ankle, left passive toe, right main/ankle,
    right passive toe.  A physical foot is grounded while *any* grouped component
    remains in contact.  Thus heel-up/toe-down does not count as whole-foot release.

    During true whole-foot single support, normal Berkeley capped mode-time reward is
    multiplied by a smooth clearance factor based on the *least-cleared* swing-foot
    component relative to its matching stance component::

        clearance_factor = clamp(min(main_clearance, toe_clearance) / full_clearance_m, 0, 1)

    This gives imperfect early swings a dense gradient (e.g. 5 mm -> 25% credit,
    10 mm -> 50% credit) while preserving zero additional height incentive beyond
    ``full_clearance_m``.  No phase, stride length, COM, posture, or leg-order target
    is introduced.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]

    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or air.shape[1] != expected or contact.shape[1] != expected:
        raise ValueError(
            f"v4.1 smooth-clearance air-time expected {expected} ordered contact bodies, "
            f"got air={air.shape[1]} contact={contact.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if body_z.shape[1] != expected:
        raise ValueError(
            f"v4.1 smooth-clearance air-time expected {expected} ordered robot bodies, "
            f"got {body_z.shape[1]}"
        )

    left_contact = torch.any(contact[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact[:, g:] > 0.0, dim=1)

    # Conservative grouped timing: the last component to release limits whole-foot
    # air time; the longest active contact represents stance persistence.
    left_air = torch.min(air[:, :g], dim=1).values
    right_air = torch.min(air[:, g:], dim=1).values
    left_contact_time = torch.max(contact[:, :g], dim=1).values
    right_contact_time = torch.max(contact[:, g:], dim=1).values
    left_mode_time = torch.where(left_contact, left_contact_time, left_air)
    right_mode_time = torch.where(right_contact, right_contact_time, right_air)

    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    single_stance = left_stance | right_stance

    # Matching-component relative heights preserve terrain/base-height independence.
    right_swing_clearance = body_z[:, g:] - body_z[:, :g]
    left_swing_clearance = body_z[:, :g] - body_z[:, g:]
    right_min_clearance = torch.min(right_swing_clearance, dim=1).values
    left_min_clearance = torch.min(left_swing_clearance, dim=1).values
    swing_min_clearance = torch.where(left_stance, right_min_clearance, left_min_clearance)

    denom = max(float(full_clearance_m), 1.0e-6)
    clearance_factor = torch.clamp(swing_min_clearance / denom, min=0.0, max=1.0)

    useful_time = torch.minimum(left_mode_time, right_mode_time)
    berkeley_air_time = torch.where(
        single_stance,
        torch.clamp(useful_time, max=float(threshold)),
        0.0,
    )
    reward = berkeley_air_time * clearance_factor

    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return reward * moving.float()

# -----------------------------------------------------------------------------
# LittleGreen v4.2 Berkeley whole-foot air-time with finite useful credit window
# -----------------------------------------------------------------------------
def whole_foot_smooth_clearance_air_time_positive_biped_v42(
    env: ManagerBasedRLEnv,
    command_name: str,
    threshold: float,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    full_clearance_m: float = 0.020,
    command_threshold: float = 0.10,
    full_credit_until_s: float = 0.35,
    fade_out_end_s: float = 0.60,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """v4.1 smooth whole-foot Berkeley air time with finite useful duration.

    The physical-foot and clearance semantics are unchanged from v4.1: bodies are
    ordered left main/toe, right main/toe; a foot is grounded while either component
    remains in contact; and the normal Berkeley reward is multiplied by a smooth
    0..20 mm clearance factor based on the least-cleared swing-foot component.

    v4.2 changes only the *duration economics* of single support.  The Berkeley reward
    ramps normally until ``threshold`` (0.20 s), remains at full capped credit through
    ``full_credit_until_s`` (0.35 s), then is multiplied by a cubic smoothstep fade
    that reaches zero at ``fade_out_end_s`` (0.60 s).  Prolonged one-foot balance is
    still allowed; it simply stops earning air-time income after the useful window.

    No touchdown bonus, long-air penalty, phase schedule, stride target, COM target,
    or left/right ordering is introduced.
    """
    contact_sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air = contact_sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact = contact_sensor.data.current_contact_time[:, sensor_cfg.body_ids]

    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or air.shape[1] != expected or contact.shape[1] != expected:
        raise ValueError(
            f"v4.2 finite-credit air-time expected {expected} ordered contact bodies, "
            f"got air={air.shape[1]} contact={contact.shape[1]}"
        )

    if not (float(threshold) <= float(full_credit_until_s) < float(fade_out_end_s)):
        raise ValueError(
            "v4.2 air-time timing must satisfy threshold <= full_credit_until_s < fade_out_end_s"
        )

    asset = env.scene[asset_cfg.name]
    body_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if body_z.shape[1] != expected:
        raise ValueError(
            f"v4.2 finite-credit air-time expected {expected} ordered robot bodies, "
            f"got {body_z.shape[1]}"
        )

    left_contact = torch.any(contact[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact[:, g:] > 0.0, dim=1)

    left_air = torch.min(air[:, :g], dim=1).values
    right_air = torch.min(air[:, g:], dim=1).values
    left_contact_time = torch.max(contact[:, :g], dim=1).values
    right_contact_time = torch.max(contact[:, g:], dim=1).values
    left_mode_time = torch.where(left_contact, left_contact_time, left_air)
    right_mode_time = torch.where(right_contact, right_contact_time, right_air)

    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    single_stance = left_stance | right_stance

    right_swing_clearance = body_z[:, g:] - body_z[:, :g]
    left_swing_clearance = body_z[:, :g] - body_z[:, g:]
    right_min_clearance = torch.min(right_swing_clearance, dim=1).values
    left_min_clearance = torch.min(left_swing_clearance, dim=1).values
    swing_min_clearance = torch.where(left_stance, right_min_clearance, left_min_clearance)

    clearance_denom = max(float(full_clearance_m), 1.0e-6)
    clearance_factor = torch.clamp(swing_min_clearance / clearance_denom, min=0.0, max=1.0)

    useful_time = torch.minimum(left_mode_time, right_mode_time)
    berkeley_air_time = torch.where(
        single_stance,
        torch.clamp(useful_time, max=float(threshold)),
        0.0,
    )

    # Full timing credit through 0.35 s, followed by a C1-continuous cubic smoothstep
    # fade to zero at 0.60 s.  This preserves the original 0..0.20 s ramp and capped
    # plateau while making indefinite one-leg balance economically neutral afterward.
    fade_span = max(float(fade_out_end_s) - float(full_credit_until_s), 1.0e-6)
    fade_x = torch.clamp((useful_time - float(full_credit_until_s)) / fade_span, min=0.0, max=1.0)
    smoothstep = fade_x * fade_x * (3.0 - 2.0 * fade_x)
    duration_factor = 1.0 - smoothstep

    reward = berkeley_air_time * clearance_factor * duration_factor

    moving = torch.norm(env.command_manager.get_command(command_name)[:, :2], dim=1) > float(command_threshold)
    return reward * moving.float()

# -----------------------------------------------------------------------------
# LittleGreen v4.4 qualifying whole-foot swing alternation + bounded streak bonus
# -----------------------------------------------------------------------------
def alternating_whole_foot_swing_streak_bonus_v44(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.10,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    event_hold_s: float = 0.10,
    base_alternation_bonus: float = 0.85,
    streak_increment: float = 0.05,
    max_streak_increment: float = 0.25,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """Reward a *new* qualifying swing when it alternates from the previous swing foot.

    This is intentionally a small event-level continuation incentive layered on top of
    the Berkeley air-time reward.  It does not prescribe command direction, stride
    length, touchdown location, gait phase, COM motion, or joint posture.

    A qualifying swing requires all of the following:

    * a meaningful planar command (``||cmd_xy|| > command_threshold``),
    * true whole-foot single support (one physical foot grounded, the other fully released),
    * at least ``min_air_time_s`` of conservative whole-foot air time,
    * at least ``min_clearance_m`` clearance for BOTH swing-foot components relative
      to their matching stance-foot components.

    Each physical swing can trigger at most once.  The first qualifying swing only
    initializes the per-environment ``last_swing_foot`` state.  A subsequent swing of
    the opposite foot receives ``base_alternation_bonus``.  Continued alternation earns
    a very small bounded streak increment so that completing another alternating step
    is slightly more valuable than stopping after one pair::

        1st qualifying swing: initialize, no alternation bonus
        2nd (opposite):       +0.85
        3rd (opposite):       +0.90
        4th (opposite):       +0.95
        ...
        capped at             +1.10

    Repeating the same swing foot resets the alternating streak to one and receives no
    alternation bonus.  Episode reset clears all state.  The reward is held briefly for
    ``event_hold_s`` so the sparse event is visible to PPO at the 50 Hz policy rate.

    The counter is deliberately bounded: it encourages a continuing alternating
    sequence without creating an unbounded survival/reward incentive.
    """
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]

    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or air_t.shape[1] != expected or contact_t.shape[1] != expected:
        raise ValueError(
            f"v4.4 alternation expected {expected} ordered contact bodies, "
            f"got air={air_t.shape[1]} contact={contact_t.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if body_z.shape[1] != expected:
        raise ValueError(
            f"v4.4 alternation expected {expected} ordered robot bodies, got {body_z.shape[1]}"
        )

    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    grounded = torch.stack((left_contact, right_contact), dim=1)

    left_air = torch.min(air_t[:, :g], dim=1).values
    right_air = torch.min(air_t[:, g:], dim=1).values
    whole_air = torch.stack((left_air, right_air), dim=1)

    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)

    # Matching-component relative clearance, as in the v4.1/v4.2 air-time term.
    right_min_clearance = torch.min(body_z[:, g:] - body_z[:, :g], dim=1).values
    left_min_clearance = torch.min(body_z[:, :g] - body_z[:, g:], dim=1).values

    command_xy = env.command_manager.get_command(command_name)[:, :2]
    moving = torch.linalg.vector_norm(command_xy, dim=1) > float(command_threshold)

    qualified_left = (
        moving
        & right_stance
        & (left_air >= float(min_air_time_s))
        & (left_min_clearance >= float(min_clearance_m))
    )
    qualified_right = (
        moving
        & left_stance
        & (right_air >= float(min_air_time_s))
        & (right_min_clearance >= float(min_clearance_m))
    )
    qualified = torch.stack((qualified_left, qualified_right), dim=1)

    num_envs = qualified.shape[0]
    device = qualified.device
    dtype = body_z.dtype

    def _tensor_state(name: str, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.clone()
        return value.to(device=device, dtype=dtype_)

    latched = _tensor_state(
        "_littlegreen_v44_swing_latched",
        qualified.shape,
        torch.bool,
        torch.zeros_like(qualified, dtype=torch.bool),
    )
    last_swing_foot = _tensor_state(
        "_littlegreen_v44_last_swing_foot",
        (num_envs,),
        torch.long,
        torch.full((num_envs,), -1, device=device, dtype=torch.long),
    )
    streak = _tensor_state(
        "_littlegreen_v44_alternating_step_streak",
        (num_envs,),
        torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )
    total_qualifying = _tensor_state(
        "_littlegreen_v44_total_qualifying_swings",
        (num_envs,),
        torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )
    total_alternating = _tensor_state(
        "_littlegreen_v44_total_alternating_steps",
        (num_envs,),
        torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )
    event_hold = _tensor_state(
        "_littlegreen_v44_alternation_event_hold_s",
        (num_envs,),
        dtype,
        torch.zeros(num_envs, device=device, dtype=dtype),
    )
    event_value = _tensor_state(
        "_littlegreen_v44_alternation_event_value",
        (num_envs,),
        dtype,
        torch.zeros(num_envs, device=device, dtype=dtype),
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v44_alternation_last_common_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v44_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (
                    current_episode_length < last_episode_length.to(device=device)
                )
            env._littlegreen_v44_last_episode_length = current_episode_length.clone()

        # Sparse event visibility at policy rate.
        event_hold = torch.clamp(event_hold - dt, min=0.0)
        event_value = torch.where(event_hold > 0.0, event_value, torch.zeros_like(event_value))

        # A swing may qualify only once until that physical foot becomes grounded again.
        latched = latched & (~grounded)

        if torch.any(reset_mask):
            reset2 = reset_mask.unsqueeze(-1)
            latched = torch.where(reset2, torch.zeros_like(latched), latched)
            last_swing_foot = torch.where(
                reset_mask, torch.full_like(last_swing_foot, -1), last_swing_foot
            )
            streak = torch.where(reset_mask, torch.zeros_like(streak), streak)
            total_qualifying = torch.where(
                reset_mask, torch.zeros_like(total_qualifying), total_qualifying
            )
            total_alternating = torch.where(
                reset_mask, torch.zeros_like(total_alternating), total_alternating
            )
            event_hold = torch.where(reset_mask, torch.zeros_like(event_hold), event_hold)
            event_value = torch.where(reset_mask, torch.zeros_like(event_value), event_value)

        new_event = qualified & (~latched) & (~reset_mask.unsqueeze(-1))
        any_event = torch.any(new_event, dim=1)
        # True single support guarantees at most one event foot; keep this explicit.
        event_foot = torch.where(
            new_event[:, 0],
            torch.zeros(num_envs, device=device, dtype=torch.long),
            torch.where(
                new_event[:, 1],
                torch.ones(num_envs, device=device, dtype=torch.long),
                torch.full((num_envs,), -1, device=device, dtype=torch.long),
            ),
        )

        has_last = last_swing_foot >= 0
        alternates = any_event & has_last & (event_foot != last_swing_foot)
        repeats = any_event & has_last & (event_foot == last_swing_foot)
        first = any_event & (~has_last)

        next_streak = torch.where(
            first | repeats,
            torch.ones_like(streak),
            torch.where(alternates, streak + 1, streak),
        )
        extra_steps = torch.clamp(next_streak.to(dtype=dtype) - 2.0, min=0.0)
        extra_bonus = torch.clamp(
            extra_steps * float(streak_increment),
            min=0.0,
            max=float(max_streak_increment),
        )
        bonus_value = float(base_alternation_bonus) + extra_bonus

        hold = max(float(event_hold_s), dt)
        event_hold = torch.where(
            alternates, torch.full_like(event_hold, hold), event_hold
        )
        event_value = torch.where(alternates, bonus_value, event_value)

        total_qualifying = torch.where(
            any_event, total_qualifying + 1, total_qualifying
        )
        total_alternating = torch.where(
            alternates, total_alternating + 1, total_alternating
        )
        streak = next_streak
        last_swing_foot = torch.where(any_event, event_foot, last_swing_foot)
        latched = latched | new_event

        env._littlegreen_v44_swing_latched = latched
        env._littlegreen_v44_last_swing_foot = last_swing_foot
        env._littlegreen_v44_alternating_step_streak = streak
        env._littlegreen_v44_total_qualifying_swings = total_qualifying
        env._littlegreen_v44_total_alternating_steps = total_alternating
        env._littlegreen_v44_alternation_event_hold_s = event_hold
        env._littlegreen_v44_alternation_event_value = event_value
        env._littlegreen_v44_alternation_last_common_step = common_step

    return torch.where(event_hold > 0.0, event_value, torch.zeros_like(event_value))

# -----------------------------------------------------------------------------
# LittleGreen v5.1 qualified whole-foot directional step state
# -----------------------------------------------------------------------------
def _moving_per_foot_qualified_directional_step_state_v51(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    full_progress_m: float = 0.025,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
    torque_limit_nm: float = 2.94,
    desired_base_com_height_m: float = 0.470,
    gate_ema_window_s: float = 10.0,
) -> dict[str, torch.Tensor]:
    """Track qualified per-foot steps and update v5.1 acquisition-gate metrics.

    A step becomes *qualified* only after the physical swing foot has been fully
    released for ``min_air_time_s`` and both main/toe components clear their
    matching stance-foot components by ``min_clearance_m``.  Touchdown progress is
    measured from the same foot's final grounded XY position at liftoff and
    projected onto the planar command direction captured at liftoff.

    Positive and negative progress are returned as continuous scores that saturate
    at ``full_progress_m``.  Thus a 1 mm step with a 25 mm saturation distance earns
    4% of full completion credit rather than the same reward as a real step.

    This state also maintains slow EMA acquisition metrics on ``env``.  The v5.1
    curriculum reads those metrics when deciding whether a stage may advance.
    """
    if min_air_time_s < 0.0 or min_clearance_m < 0.0 or full_progress_m <= 0.0:
        raise ValueError("v5.1 qualified-step thresholds must be non-negative and full_progress_m positive")
    if torque_limit_nm <= 0.0 or gate_ema_window_s <= 0.0:
        raise ValueError("v5.1 torque_limit_nm and gate_ema_window_s must be positive")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or contact_t.shape[1] != expected or air_t.shape[1] != expected:
        raise ValueError(
            f"v5.1 qualified step expected {expected} ordered contact bodies, "
            f"got contact={contact_t.shape[1]} air={air_t.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != expected:
        raise ValueError(
            f"v5.1 qualified step expected {expected} ordered robot bodies, got {body_pos.shape[1]}"
        )

    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    grounded = torch.stack((left_contact, right_contact), dim=1)
    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    single_support = left_stance | right_stance

    left_air = torch.min(air_t[:, :g], dim=1).values
    right_air = torch.min(air_t[:, g:], dim=1).values
    whole_air = torch.stack((left_air, right_air), dim=1)

    body_z = body_pos[:, :, 2]
    right_min_clearance = torch.min(body_z[:, g:] - body_z[:, :g], dim=1).values
    left_min_clearance = torch.min(body_z[:, :g] - body_z[:, g:], dim=1).values
    clearance = torch.stack((left_min_clearance, right_min_clearance), dim=1)

    # Main-foot bodies are the first component of each ordered physical-foot group.
    main_xy = torch.stack((body_pos[:, 0, :2], body_pos[:, g, :2]), dim=1)

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    command_dir_w = quat_apply(yaw_quat(asset.data.root_quat_w), command_dir_3d)[:, :2]

    num_envs = grounded.shape[0]
    device = grounded.device
    dtype = main_xy.dtype

    def _state_tensor(name: str, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.clone()
        return value.to(device=device, dtype=dtype_)

    prev_grounded = _state_tensor(
        "_littlegreen_v51_prev_grounded", grounded.shape, torch.bool, grounded.clone()
    )
    prev_main_xy = _state_tensor(
        "_littlegreen_v51_prev_main_xy", main_xy.shape, dtype, main_xy.clone()
    )
    active = _state_tensor(
        "_littlegreen_v51_step_active", grounded.shape, torch.bool,
        torch.zeros_like(grounded, dtype=torch.bool),
    )
    qualified = _state_tensor(
        "_littlegreen_v51_step_qualified", grounded.shape, torch.bool,
        torch.zeros_like(grounded, dtype=torch.bool),
    )
    liftoff_xy = _state_tensor(
        "_littlegreen_v51_liftoff_xy", main_xy.shape, dtype, main_xy.clone()
    )
    liftoff_dir = _state_tensor(
        "_littlegreen_v51_liftoff_dir_xy", main_xy.shape, dtype,
        torch.zeros_like(main_xy),
    )
    success_hold = _state_tensor(
        "_littlegreen_v51_success_hold_s", grounded.shape, dtype,
        torch.zeros(grounded.shape, device=device, dtype=dtype),
    )
    failure_hold = _state_tensor(
        "_littlegreen_v51_failure_hold_s", grounded.shape, dtype,
        torch.zeros(grounded.shape, device=device, dtype=dtype),
    )
    success_value = _state_tensor(
        "_littlegreen_v51_success_value", grounded.shape, dtype,
        torch.zeros(grounded.shape, device=device, dtype=dtype),
    )
    failure_value = _state_tensor(
        "_littlegreen_v51_failure_value", grounded.shape, dtype,
        torch.zeros(grounded.shape, device=device, dtype=dtype),
    )
    last_progress = _state_tensor(
        "_littlegreen_v51_last_progress_m", grounded.shape, dtype,
        torch.zeros(grounded.shape, device=device, dtype=dtype),
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v51_step_state_last_common_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v51_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v51_last_episode_length = current_episode_length.clone()

        # Sparse touchdown credit remains visible for a few policy frames.
        success_hold = torch.clamp(success_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        success_value = torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        reset2 = reset_mask.unsqueeze(-1)
        active = torch.where(reset2, torch.zeros_like(active), active)
        qualified = torch.where(reset2, torch.zeros_like(qualified), qualified)
        success_hold = torch.where(reset2, torch.zeros_like(success_hold), success_hold)
        failure_hold = torch.where(reset2, torch.zeros_like(failure_hold), failure_hold)
        success_value = torch.where(reset2, torch.zeros_like(success_value), success_value)
        failure_value = torch.where(reset2, torch.zeros_like(failure_value), failure_value)
        last_progress = torch.where(reset2, torch.zeros_like(last_progress), last_progress)
        prev_grounded = torch.where(reset2, grounded, prev_grounded)
        prev_main_xy = torch.where(reset2.unsqueeze(-1), main_xy, prev_main_xy)

        liftoff = prev_grounded & (~grounded) & moving.unsqueeze(-1) & (~reset2)
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_main_xy, liftoff_xy)
        captured_dir = command_dir_w[:, None, :].expand(-1, 2, -1)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), captured_dir, liftoff_dir)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)

        # A legitimate swing is whole-foot single support with enough time and
        # clearance.  Qualification latches for the remainder of that swing.
        swing_left = right_stance
        swing_right = left_stance
        swing_mask = torch.stack((swing_left, swing_right), dim=1)
        qualifies_now = (
            active
            & (~grounded)
            & swing_mask
            & (whole_air >= float(min_air_time_s))
            & (clearance >= float(min_clearance_m))
            & moving.unsqueeze(-1)
            & (~reset2)
        )
        qualified = qualified | qualifies_now

        touchdown = (~prev_grounded) & grounded & active & moving.unsqueeze(-1) & (~reset2)
        judged_touchdown = touchdown & qualified
        progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
        positive_score = torch.clamp(progress / float(full_progress_m), min=0.0, max=1.0)
        negative_score = torch.clamp((-progress) / float(full_progress_m), min=0.0, max=1.0)
        hold = max(float(event_hold_s), dt)
        success_hold = torch.where(judged_touchdown, torch.full_like(success_hold, hold), success_hold)
        failure_hold = torch.where(judged_touchdown, torch.full_like(failure_hold, hold), failure_hold)
        success_value = torch.where(judged_touchdown, positive_score, success_value)
        failure_value = torch.where(judged_touchdown, negative_score, failure_value)
        last_progress = torch.where(judged_touchdown, progress, last_progress)
        active = torch.where(touchdown, torch.zeros_like(active), active)
        qualified = torch.where(touchdown, torch.zeros_like(qualified), qualified)

        # Commands ending mid-swing discard the pending event rather than judging
        # against a stale direction.
        active = active & moving.unsqueeze(-1)
        qualified = qualified & active

        # ---------------- v5.1 competency-gate EMAs ----------------
        # Aggregate across thousands of environments every policy step, then filter
        # with a ~10 s EMA.  These are curriculum diagnostics only, never reward.
        def _masked_mean(values: torch.Tensor, mask: torch.Tensor, default: float = 0.0) -> torch.Tensor:
            count = torch.sum(mask.float())
            return torch.where(
                count > 0.0,
                torch.sum(values * mask.float()) / torch.clamp(count, min=1.0),
                torch.tensor(float(default), device=device, dtype=values.dtype),
            )

        standing = torch.linalg.vector_norm(command[:, :3], dim=1) < float(command_threshold)
        both_grounded = left_contact & right_contact
        standing_both = _masked_mean(both_grounded.float(), standing)
        height_error = torch.abs(asset.data.root_com_pos_w[:, 2] - float(desired_base_com_height_m))
        standing_height_error = _masked_mean(height_error, standing, default=1.0)

        action_term = env.action_manager.get_term("joint_pos")
        joint_ids = getattr(action_term, "_joint_ids", None)
        if joint_ids is None:
            torque = torch.abs(asset.data.applied_torque)
        else:
            torque = torch.abs(asset.data.applied_torque[:, joint_ids])
        hard_fraction_env = torch.mean((torque >= 0.95 * float(torque_limit_nm)).float(), dim=1)
        standing_hard_torque = _masked_mean(hard_fraction_env, standing, default=1.0)

        moving_count = torch.clamp(torch.sum(moving.float()), min=1.0)
        current_qualified = (
            swing_mask
            & (~grounded)
            & (whole_air >= float(min_air_time_s))
            & (clearance >= float(min_clearance_m))
            & moving.unsqueeze(-1)
        )
        left_qual = torch.sum(current_qualified[:, 0].float()) / moving_count
        right_qual = torch.sum(current_qualified[:, 1].float()) / moving_count
        left_td_rate = torch.sum(judged_touchdown[:, 0].float()) / moving_count / max(dt, 1.0e-6)
        right_td_rate = torch.sum(judged_touchdown[:, 1].float()) / moving_count / max(dt, 1.0e-6)
        # Count a touchdown as directionally useful for gating once it reaches 20%
        # of full progress (~5 mm for the default 25 mm saturation distance).
        positive_event = judged_touchdown & (positive_score >= 0.20)
        left_positive_rate = torch.sum(positive_event[:, 0].float()) / moving_count / max(dt, 1.0e-6)
        right_positive_rate = torch.sum(positive_event[:, 1].float()) / moving_count / max(dt, 1.0e-6)
        progress_b = torch.sum(asset.data.root_lin_vel_b[:, :2] * command_dir_b, dim=1)
        command_progress = _masked_mean(progress_b, moving, default=-1.0)

        beta = math.exp(-dt / max(float(gate_ema_window_s), dt))
        def _ema(name: str, current: torch.Tensor):
            old = getattr(env, name, None)
            if not isinstance(old, torch.Tensor):
                old = current.detach()
            else:
                old = old.to(device=device, dtype=current.dtype)
            new = beta * old + (1.0 - beta) * current.detach()
            setattr(env, name, new)

        _ema("_littlegreen_v51_ema_standing_both", standing_both)
        _ema("_littlegreen_v51_ema_standing_height_error_m", standing_height_error)
        _ema("_littlegreen_v51_ema_standing_hard_torque_fraction", standing_hard_torque)
        _ema("_littlegreen_v51_ema_left_qualifying_swing_fraction", left_qual)
        _ema("_littlegreen_v51_ema_right_qualifying_swing_fraction", right_qual)
        _ema("_littlegreen_v51_ema_left_qualified_touchdown_rate_hz", left_td_rate)
        _ema("_littlegreen_v51_ema_right_qualified_touchdown_rate_hz", right_td_rate)
        _ema("_littlegreen_v51_ema_left_positive_touchdown_rate_hz", left_positive_rate)
        _ema("_littlegreen_v51_ema_right_positive_touchdown_rate_hz", right_positive_rate)
        _ema("_littlegreen_v51_ema_command_progress_mps", command_progress)

        prev_grounded = grounded.clone()
        prev_main_xy = main_xy.clone()
        env._littlegreen_v51_prev_grounded = prev_grounded
        env._littlegreen_v51_prev_main_xy = prev_main_xy
        env._littlegreen_v51_step_active = active
        env._littlegreen_v51_step_qualified = qualified
        env._littlegreen_v51_liftoff_xy = liftoff_xy
        env._littlegreen_v51_liftoff_dir_xy = liftoff_dir
        env._littlegreen_v51_success_hold_s = success_hold
        env._littlegreen_v51_failure_hold_s = failure_hold
        env._littlegreen_v51_success_value = success_value
        env._littlegreen_v51_failure_value = failure_value
        env._littlegreen_v51_last_progress_m = last_progress
        env._littlegreen_v51_step_state_last_common_step = common_step

    # Dense airborne progress is continuously scaled from the same qualified state.
    current_progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
    airborne_progress = torch.clamp(current_progress / float(full_progress_m), min=0.0, max=1.0)
    airborne_progress = airborne_progress * qualified.float() * (~grounded).float() * moving.unsqueeze(-1).float()

    return {
        "success": torch.sum(torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value)), dim=1) * moving.float(),
        "failure": torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float(),
        "airborne_progress": torch.sum(airborne_progress, dim=1) * moving.float(),
        "last_progress_m": last_progress,
        "active": active,
        "qualified": qualified,
    }


def moving_per_foot_qualified_directional_touchdown_success_v51(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    bodies_per_foot: int = 2, event_hold_s: float = 0.10,
    torque_limit_nm: float = 2.94, desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v51(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, bodies_per_foot, event_hold_s,
        torque_limit_nm, desired_base_com_height_m,
    )["success"]


def moving_per_foot_qualified_directional_touchdown_failure_v51(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    bodies_per_foot: int = 2, event_hold_s: float = 0.10,
    torque_limit_nm: float = 2.94, desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v51(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, bodies_per_foot, event_hold_s,
        torque_limit_nm, desired_base_com_height_m,
    )["failure"]


def moving_per_foot_qualified_airborne_directional_progress_v51(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    bodies_per_foot: int = 2, event_hold_s: float = 0.10,
    torque_limit_nm: float = 2.94, desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v51(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, bodies_per_foot, event_hold_s,
        torque_limit_nm, desired_base_com_height_m,
    )["airborne_progress"]

# -----------------------------------------------------------------------------
# LittleGreen v5.2 bilateral continuation state + repeat-foot attenuation
# -----------------------------------------------------------------------------
def _qualified_swing_sequence_state_v52(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.05,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    repeat_same_foot_credit: float = 0.25,
    event_hold_s: float = 0.10,
    bodies_per_foot: int = 2,
) -> dict[str, torch.Tensor]:
    """Track which physical foot last produced a legitimate qualifying swing.

    v5.2 closes the v5.1 ``permanent stance leg`` loophole without requiring a
    phase-scheduled L/R gait.  At each whole-foot liftoff, the swing is assigned a
    reward multiplier based on the *previous qualifying swing*:

    * first-ever or opposite-foot swing: 1.0 credit;
    * repeated same-foot swing: ``repeat_same_foot_credit`` (default 0.25).

    The multiplier is latched for the whole physical swing, so air-time, dense
    airborne progress and positive touchdown credit can all use the same economics.
    A repeated swing remains legal and is never directly penalized.  Once the
    opposite foot genuinely qualifies (>= air-time and clearance thresholds), it
    regains full credit and emits a small one-shot alternation event.
    """
    if not 0.0 <= repeat_same_foot_credit <= 1.0:
        raise ValueError("v5.2 repeat_same_foot_credit must be in [0, 1]")
    if min_air_time_s < 0.0 or min_clearance_m < 0.0:
        raise ValueError("v5.2 qualifying thresholds must be non-negative")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or contact_t.shape[1] != expected or air_t.shape[1] != expected:
        raise ValueError(
            f"v5.2 sequence expected {expected} ordered contact bodies, "
            f"got contact={contact_t.shape[1]} air={air_t.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_z = asset.data.body_pos_w[:, asset_cfg.body_ids, 2]
    if body_z.shape[1] != expected:
        raise ValueError(
            f"v5.2 sequence expected {expected} ordered robot bodies, got {body_z.shape[1]}"
        )

    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    grounded = torch.stack((left_contact, right_contact), dim=1)
    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    swing_mask = torch.stack((right_stance, left_stance), dim=1)  # [left swing, right swing]

    left_air = torch.min(air_t[:, :g], dim=1).values
    right_air = torch.min(air_t[:, g:], dim=1).values
    whole_air = torch.stack((left_air, right_air), dim=1)
    left_clear = torch.min(body_z[:, :g] - body_z[:, g:], dim=1).values
    right_clear = torch.min(body_z[:, g:] - body_z[:, :g], dim=1).values
    clearance = torch.stack((left_clear, right_clear), dim=1)

    command_xy = env.command_manager.get_command(command_name)[:, :2]
    moving = torch.linalg.vector_norm(command_xy, dim=1) > float(command_threshold)

    num_envs = grounded.shape[0]
    device = grounded.device
    dtype = body_z.dtype
    foot_ids = torch.arange(2, device=device, dtype=torch.long).view(1, 2)

    def _state(name: str, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.clone()
        return value.to(device=device, dtype=dtype_)

    prev_grounded = _state(
        "_littlegreen_v52_sequence_prev_grounded", grounded.shape, torch.bool, grounded.clone()
    )
    swing_active = _state(
        "_littlegreen_v52_sequence_swing_active", grounded.shape, torch.bool,
        torch.zeros_like(grounded, dtype=torch.bool),
    )
    swing_multiplier = _state(
        "_littlegreen_v52_sequence_swing_multiplier", grounded.shape, dtype,
        torch.ones(grounded.shape, device=device, dtype=dtype),
    )
    qualifying_latched = _state(
        "_littlegreen_v52_sequence_qualifying_latched", grounded.shape, torch.bool,
        torch.zeros_like(grounded, dtype=torch.bool),
    )
    last_qualifying_foot = _state(
        "_littlegreen_v52_last_qualifying_foot", (num_envs,), torch.long,
        torch.full((num_envs,), -1, device=device, dtype=torch.long),
    )
    alternation_hold = _state(
        "_littlegreen_v52_alternation_hold_s", (num_envs,), dtype,
        torch.zeros(num_envs, device=device, dtype=dtype),
    )
    alternation_value = _state(
        "_littlegreen_v52_alternation_value", (num_envs,), dtype,
        torch.zeros(num_envs, device=device, dtype=dtype),
    )
    total_qualifying = _state(
        "_littlegreen_v52_total_qualifying_swings", (num_envs,), torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )
    total_alternating = _state(
        "_littlegreen_v52_total_alternating_swings", (num_envs,), torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )
    total_repeat = _state(
        "_littlegreen_v52_total_repeat_swings", (num_envs,), torch.long,
        torch.zeros(num_envs, device=device, dtype=torch.long),
    )

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v52_sequence_last_common_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v52_sequence_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (
                    current_episode_length < last_episode_length.to(device=device)
                )
            env._littlegreen_v52_sequence_last_episode_length = current_episode_length.clone()

        alternation_hold = torch.clamp(alternation_hold - dt, min=0.0)
        alternation_value = torch.where(
            alternation_hold > 0.0, alternation_value, torch.zeros_like(alternation_value)
        )

        reset2 = reset_mask.unsqueeze(-1)
        if torch.any(reset_mask):
            prev_grounded = torch.where(reset2, grounded, prev_grounded)
            swing_active = torch.where(reset2, torch.zeros_like(swing_active), swing_active)
            swing_multiplier = torch.where(reset2, torch.ones_like(swing_multiplier), swing_multiplier)
            qualifying_latched = torch.where(reset2, torch.zeros_like(qualifying_latched), qualifying_latched)
            last_qualifying_foot = torch.where(
                reset_mask, torch.full_like(last_qualifying_foot, -1), last_qualifying_foot
            )
            alternation_hold = torch.where(reset_mask, torch.zeros_like(alternation_hold), alternation_hold)
            alternation_value = torch.where(reset_mask, torch.zeros_like(alternation_value), alternation_value)
            total_qualifying = torch.where(reset_mask, torch.zeros_like(total_qualifying), total_qualifying)
            total_alternating = torch.where(reset_mask, torch.zeros_like(total_alternating), total_alternating)
            total_repeat = torch.where(reset_mask, torch.zeros_like(total_repeat), total_repeat)

        # Whole-foot liftoff starts a new physical swing.  The credit multiplier is
        # decided now from the *previous* qualifying foot and remains latched until
        # touchdown, so an opposite swing never attenuates itself after qualifying.
        liftoff = prev_grounded & (~grounded) & moving.unsqueeze(-1) & (~reset2)
        previous_exists = last_qualifying_foot >= 0
        repeated = previous_exists.unsqueeze(-1) & (foot_ids == last_qualifying_foot.unsqueeze(-1))
        new_multiplier = torch.where(
            repeated,
            torch.full_like(swing_multiplier, float(repeat_same_foot_credit)),
            torch.ones_like(swing_multiplier),
        )
        swing_multiplier = torch.where(liftoff, new_multiplier, swing_multiplier)
        swing_active = torch.where(liftoff, torch.ones_like(swing_active), swing_active)
        qualifying_latched = torch.where(liftoff, torch.zeros_like(qualifying_latched), qualifying_latched)

        qualifies_now = (
            swing_active
            & (~grounded)
            & swing_mask
            & (whole_air >= float(min_air_time_s))
            & (clearance >= float(min_clearance_m))
            & moving.unsqueeze(-1)
            & (~qualifying_latched)
            & (~reset2)
        )
        any_event = torch.any(qualifies_now, dim=1)
        event_foot = torch.argmax(qualifies_now.to(torch.long), dim=1)
        prior_last = last_qualifying_foot.clone()
        alternates = any_event & (prior_last >= 0) & (event_foot != prior_last)
        repeats = any_event & (prior_last >= 0) & (event_foot == prior_last)

        hold = max(float(event_hold_s), dt)
        alternation_hold = torch.where(
            alternates, torch.full_like(alternation_hold, hold), alternation_hold
        )
        alternation_value = torch.where(
            alternates, torch.ones_like(alternation_value), alternation_value
        )
        total_qualifying = torch.where(any_event, total_qualifying + 1, total_qualifying)
        total_alternating = torch.where(alternates, total_alternating + 1, total_alternating)
        total_repeat = torch.where(repeats, total_repeat + 1, total_repeat)
        last_qualifying_foot = torch.where(any_event, event_foot, last_qualifying_foot)
        qualifying_latched = qualifying_latched | qualifies_now

        touchdown = (~prev_grounded) & grounded
        swing_active = torch.where(touchdown, torch.zeros_like(swing_active), swing_active)
        qualifying_latched = torch.where(touchdown, torch.zeros_like(qualifying_latched), qualifying_latched)
        swing_multiplier = torch.where(touchdown, torch.ones_like(swing_multiplier), swing_multiplier)

        # Commands ending mid-swing simply discard the sequence attempt.
        stopped = ~moving.unsqueeze(-1)
        swing_active = swing_active & (~stopped)
        qualifying_latched = qualifying_latched & swing_active
        swing_multiplier = torch.where(stopped, torch.ones_like(swing_multiplier), swing_multiplier)

        prev_grounded = grounded.clone()
        env._littlegreen_v52_sequence_prev_grounded = prev_grounded
        env._littlegreen_v52_sequence_swing_active = swing_active
        env._littlegreen_v52_sequence_swing_multiplier = swing_multiplier
        env._littlegreen_v52_sequence_qualifying_latched = qualifying_latched
        env._littlegreen_v52_last_qualifying_foot = last_qualifying_foot
        env._littlegreen_v52_alternation_hold_s = alternation_hold
        env._littlegreen_v52_alternation_value = alternation_value
        env._littlegreen_v52_total_qualifying_swings = total_qualifying
        env._littlegreen_v52_total_alternating_swings = total_alternating
        env._littlegreen_v52_total_repeat_swings = total_repeat
        env._littlegreen_v52_sequence_last_common_step = common_step

    # Convert the per-foot multiplier into the currently active physical swing's
    # scalar multiplier for the Berkeley-style single-support air-time term.
    current_swing_multiplier = torch.ones(num_envs, device=device, dtype=dtype)
    current_swing_multiplier = torch.where(right_stance, swing_multiplier[:, 0], current_swing_multiplier)
    current_swing_multiplier = torch.where(left_stance, swing_multiplier[:, 1], current_swing_multiplier)

    return {
        "per_foot_credit_multiplier": swing_multiplier,
        "current_swing_credit_multiplier": current_swing_multiplier,
        "alternation_bonus": torch.where(
            alternation_hold > 0.0, alternation_value, torch.zeros_like(alternation_value)
        ),
        "last_qualifying_foot": last_qualifying_foot,
        "total_qualifying_swings": total_qualifying,
        "total_alternating_swings": total_alternating,
        "total_repeat_swings": total_repeat,
    }


def whole_foot_smooth_clearance_air_time_positive_biped_v52(
    env: ManagerBasedRLEnv,
    command_name: str,
    threshold: float,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    full_clearance_m: float = 0.020,
    command_threshold: float = 0.05,
    full_credit_until_s: float = 0.35,
    fade_out_end_s: float = 0.60,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    repeat_same_foot_credit: float = 0.25,
    event_hold_s: float = 0.10,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """v4.2 finite clearance air-time with v5.2 same-foot credit attenuation."""
    sequence = _qualified_swing_sequence_state_v52(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        min_air_time_s, min_clearance_m, repeat_same_foot_credit,
        event_hold_s, bodies_per_foot,
    )
    base = whole_foot_smooth_clearance_air_time_positive_biped_v42(
        env=env,
        command_name=command_name,
        threshold=threshold,
        sensor_cfg=sensor_cfg,
        asset_cfg=asset_cfg,
        full_clearance_m=full_clearance_m,
        command_threshold=command_threshold,
        full_credit_until_s=full_credit_until_s,
        fade_out_end_s=fade_out_end_s,
        bodies_per_foot=bodies_per_foot,
    )
    return base * sequence["current_swing_credit_multiplier"]


def alternating_qualified_swing_bonus_v52(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
    command_threshold: float = 0.05,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    repeat_same_foot_credit: float = 0.25,
    event_hold_s: float = 0.10,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    """One-shot event when the opposite physical foot becomes a qualifying swing."""
    return _qualified_swing_sequence_state_v52(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        min_air_time_s, min_clearance_m, repeat_same_foot_credit,
        event_hold_s, bodies_per_foot,
    )["alternation_bonus"]


def _moving_per_foot_qualified_directional_step_state_v52(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    full_progress_m: float = 0.025,
    repeat_same_foot_credit: float = 0.25,
    bodies_per_foot: int = 2,
    event_hold_s: float = 0.10,
    torque_limit_nm: float = 2.94,
    desired_base_com_height_m: float = 0.470,
    gate_ema_window_s: float = 10.0,
) -> dict[str, torch.Tensor]:
    """v5.1 legitimate step state with v5.2 repeat-foot positive-credit attenuation.

    Qualification and displacement scaling are unchanged from v5.1.  Only positive
    swing economics change: a repeated same-foot swing receives 25% (configurable)
    air/progress/touchdown credit until the opposite foot genuinely qualifies.
    Backward/failed touchdown penalties remain at full strength.
    """
    if min_air_time_s < 0.0 or min_clearance_m < 0.0 or full_progress_m <= 0.0:
        raise ValueError("v5.2 qualified-step thresholds must be non-negative and full_progress_m positive")
    if torque_limit_nm <= 0.0 or gate_ema_window_s <= 0.0:
        raise ValueError("v5.2 torque_limit_nm and gate_ema_window_s must be positive")

    sequence = _qualified_swing_sequence_state_v52(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        min_air_time_s, min_clearance_m, repeat_same_foot_credit,
        event_hold_s, bodies_per_foot,
    )

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or contact_t.shape[1] != expected or air_t.shape[1] != expected:
        raise ValueError(
            f"v5.2 qualified step expected {expected} ordered contact bodies, "
            f"got contact={contact_t.shape[1]} air={air_t.shape[1]}"
        )

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != expected:
        raise ValueError(
            f"v5.2 qualified step expected {expected} ordered robot bodies, got {body_pos.shape[1]}"
        )

    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    grounded = torch.stack((left_contact, right_contact), dim=1)
    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)

    left_air = torch.min(air_t[:, :g], dim=1).values
    right_air = torch.min(air_t[:, g:], dim=1).values
    whole_air = torch.stack((left_air, right_air), dim=1)

    body_z = body_pos[:, :, 2]
    right_min_clearance = torch.min(body_z[:, g:] - body_z[:, :g], dim=1).values
    left_min_clearance = torch.min(body_z[:, :g] - body_z[:, g:], dim=1).values
    clearance = torch.stack((left_min_clearance, right_min_clearance), dim=1)
    main_xy = torch.stack((body_pos[:, 0, :2], body_pos[:, g, :2]), dim=1)

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    command_dir_w = quat_apply(yaw_quat(asset.data.root_quat_w), command_dir_3d)[:, :2]

    num_envs = grounded.shape[0]
    device = grounded.device
    dtype = main_xy.dtype

    def _state_tensor(name: str, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.clone()
        return value.to(device=device, dtype=dtype_)

    prev_grounded = _state_tensor("_littlegreen_v52_prev_grounded", grounded.shape, torch.bool, grounded.clone())
    prev_main_xy = _state_tensor("_littlegreen_v52_prev_main_xy", main_xy.shape, dtype, main_xy.clone())
    active = _state_tensor("_littlegreen_v52_step_active", grounded.shape, torch.bool, torch.zeros_like(grounded, dtype=torch.bool))
    qualified = _state_tensor("_littlegreen_v52_step_qualified", grounded.shape, torch.bool, torch.zeros_like(grounded, dtype=torch.bool))
    liftoff_xy = _state_tensor("_littlegreen_v52_liftoff_xy", main_xy.shape, dtype, main_xy.clone())
    liftoff_dir = _state_tensor("_littlegreen_v52_liftoff_dir_xy", main_xy.shape, dtype, torch.zeros_like(main_xy))
    step_credit = _state_tensor(
        "_littlegreen_v52_step_credit_multiplier", grounded.shape, dtype,
        torch.ones(grounded.shape, device=device, dtype=dtype),
    )
    success_hold = _state_tensor("_littlegreen_v52_success_hold_s", grounded.shape, dtype, torch.zeros(grounded.shape, device=device, dtype=dtype))
    failure_hold = _state_tensor("_littlegreen_v52_failure_hold_s", grounded.shape, dtype, torch.zeros(grounded.shape, device=device, dtype=dtype))
    success_value = _state_tensor("_littlegreen_v52_success_value", grounded.shape, dtype, torch.zeros(grounded.shape, device=device, dtype=dtype))
    failure_value = _state_tensor("_littlegreen_v52_failure_value", grounded.shape, dtype, torch.zeros(grounded.shape, device=device, dtype=dtype))
    last_progress = _state_tensor("_littlegreen_v52_last_progress_m", grounded.shape, dtype, torch.zeros(grounded.shape, device=device, dtype=dtype))

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v52_step_state_last_common_step", -1))
    if common_step != last_step:
        dt = float(getattr(env, "step_dt", 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, "episode_length_buf", None)
        last_episode_length = getattr(env, "_littlegreen_v52_last_episode_length", None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v52_last_episode_length = current_episode_length.clone()

        success_hold = torch.clamp(success_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        success_value = torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        reset2 = reset_mask.unsqueeze(-1)
        active = torch.where(reset2, torch.zeros_like(active), active)
        qualified = torch.where(reset2, torch.zeros_like(qualified), qualified)
        step_credit = torch.where(reset2, torch.ones_like(step_credit), step_credit)
        success_hold = torch.where(reset2, torch.zeros_like(success_hold), success_hold)
        failure_hold = torch.where(reset2, torch.zeros_like(failure_hold), failure_hold)
        success_value = torch.where(reset2, torch.zeros_like(success_value), success_value)
        failure_value = torch.where(reset2, torch.zeros_like(failure_value), failure_value)
        last_progress = torch.where(reset2, torch.zeros_like(last_progress), last_progress)
        prev_grounded = torch.where(reset2, grounded, prev_grounded)
        prev_main_xy = torch.where(reset2.unsqueeze(-1), main_xy, prev_main_xy)

        liftoff = prev_grounded & (~grounded) & moving.unsqueeze(-1) & (~reset2)
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_main_xy, liftoff_xy)
        captured_dir = command_dir_w[:, None, :].expand(-1, 2, -1)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), captured_dir, liftoff_dir)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)
        # Sequence state already classified this liftoff as first/opposite/repeat.
        step_credit = torch.where(liftoff, sequence["per_foot_credit_multiplier"], step_credit)

        swing_mask = torch.stack((right_stance, left_stance), dim=1)
        qualifies_now = (
            active & (~grounded) & swing_mask
            & (whole_air >= float(min_air_time_s))
            & (clearance >= float(min_clearance_m))
            & moving.unsqueeze(-1) & (~reset2)
        )
        qualified = qualified | qualifies_now

        touchdown = (~prev_grounded) & grounded & active & moving.unsqueeze(-1) & (~reset2)
        judged_touchdown = touchdown & qualified
        progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
        positive_score = torch.clamp(progress / float(full_progress_m), min=0.0, max=1.0)
        negative_score = torch.clamp((-progress) / float(full_progress_m), min=0.0, max=1.0)
        hold = max(float(event_hold_s), dt)
        success_hold = torch.where(judged_touchdown, torch.full_like(success_hold, hold), success_hold)
        failure_hold = torch.where(judged_touchdown, torch.full_like(failure_hold, hold), failure_hold)
        # Only positive credit is attenuated.  A repeated same-foot backward step
        # still pays the full failure penalty.
        success_value = torch.where(judged_touchdown, positive_score * step_credit, success_value)
        failure_value = torch.where(judged_touchdown, negative_score, failure_value)
        last_progress = torch.where(judged_touchdown, progress, last_progress)
        active = torch.where(touchdown, torch.zeros_like(active), active)
        qualified = torch.where(touchdown, torch.zeros_like(qualified), qualified)
        step_credit = torch.where(touchdown, torch.ones_like(step_credit), step_credit)

        active = active & moving.unsqueeze(-1)
        qualified = qualified & active

        # ---------------- v5.2 competency-gate EMAs ----------------
        def _masked_mean(values: torch.Tensor, mask: torch.Tensor, default: float = 0.0) -> torch.Tensor:
            count = torch.sum(mask.float())
            return torch.where(
                count > 0.0,
                torch.sum(values * mask.float()) / torch.clamp(count, min=1.0),
                torch.tensor(float(default), device=device, dtype=values.dtype),
            )

        standing = torch.linalg.vector_norm(command[:, :3], dim=1) < float(command_threshold)
        both_grounded = left_contact & right_contact
        standing_both = _masked_mean(both_grounded.float(), standing)
        height_error = torch.abs(asset.data.root_com_pos_w[:, 2] - float(desired_base_com_height_m))
        standing_height_error = _masked_mean(height_error, standing, default=1.0)

        action_term = env.action_manager.get_term("joint_pos")
        joint_ids = getattr(action_term, "_joint_ids", None)
        torque = torch.abs(asset.data.applied_torque if joint_ids is None else asset.data.applied_torque[:, joint_ids])
        hard_fraction_env = torch.mean((torque >= 0.95 * float(torque_limit_nm)).float(), dim=1)
        standing_hard_torque = _masked_mean(hard_fraction_env, standing, default=1.0)

        moving_count = torch.clamp(torch.sum(moving.float()), min=1.0)
        current_qualified = (
            swing_mask & (~grounded)
            & (whole_air >= float(min_air_time_s))
            & (clearance >= float(min_clearance_m))
            & moving.unsqueeze(-1)
        )
        left_qual = torch.sum(current_qualified[:, 0].float()) / moving_count
        right_qual = torch.sum(current_qualified[:, 1].float()) / moving_count
        left_td_rate = torch.sum(judged_touchdown[:, 0].float()) / moving_count / max(dt, 1.0e-6)
        right_td_rate = torch.sum(judged_touchdown[:, 1].float()) / moving_count / max(dt, 1.0e-6)
        positive_event = judged_touchdown & (positive_score >= 0.20)
        left_positive_rate = torch.sum(positive_event[:, 0].float()) / moving_count / max(dt, 1.0e-6)
        right_positive_rate = torch.sum(positive_event[:, 1].float()) / moving_count / max(dt, 1.0e-6)
        progress_b = torch.sum(asset.data.root_lin_vel_b[:, :2] * command_dir_b, dim=1)
        command_progress = _masked_mean(progress_b, moving, default=-1.0)

        beta = math.exp(-dt / max(float(gate_ema_window_s), dt))
        def _ema(name: str, current: torch.Tensor):
            old = getattr(env, name, None)
            if not isinstance(old, torch.Tensor):
                old = current.detach()
            else:
                old = old.to(device=device, dtype=current.dtype)
            setattr(env, name, beta * old + (1.0 - beta) * current.detach())

        _ema("_littlegreen_v52_ema_standing_both", standing_both)
        _ema("_littlegreen_v52_ema_standing_height_error_m", standing_height_error)
        _ema("_littlegreen_v52_ema_standing_hard_torque_fraction", standing_hard_torque)
        _ema("_littlegreen_v52_ema_left_qualifying_swing_fraction", left_qual)
        _ema("_littlegreen_v52_ema_right_qualifying_swing_fraction", right_qual)
        _ema("_littlegreen_v52_ema_left_qualified_touchdown_rate_hz", left_td_rate)
        _ema("_littlegreen_v52_ema_right_qualified_touchdown_rate_hz", right_td_rate)
        _ema("_littlegreen_v52_ema_left_positive_touchdown_rate_hz", left_positive_rate)
        _ema("_littlegreen_v52_ema_right_positive_touchdown_rate_hz", right_positive_rate)
        _ema("_littlegreen_v52_ema_command_progress_mps", command_progress)

        prev_grounded = grounded.clone()
        prev_main_xy = main_xy.clone()
        env._littlegreen_v52_prev_grounded = prev_grounded
        env._littlegreen_v52_prev_main_xy = prev_main_xy
        env._littlegreen_v52_step_active = active
        env._littlegreen_v52_step_qualified = qualified
        env._littlegreen_v52_liftoff_xy = liftoff_xy
        env._littlegreen_v52_liftoff_dir_xy = liftoff_dir
        env._littlegreen_v52_step_credit_multiplier = step_credit
        env._littlegreen_v52_success_hold_s = success_hold
        env._littlegreen_v52_failure_hold_s = failure_hold
        env._littlegreen_v52_success_value = success_value
        env._littlegreen_v52_failure_value = failure_value
        env._littlegreen_v52_last_progress_m = last_progress
        env._littlegreen_v52_step_state_last_common_step = common_step

    current_progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
    airborne_progress = torch.clamp(current_progress / float(full_progress_m), min=0.0, max=1.0)
    airborne_progress = (
        airborne_progress * step_credit * qualified.float() * (~grounded).float()
        * moving.unsqueeze(-1).float()
    )

    return {
        "success": torch.sum(torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value)), dim=1) * moving.float(),
        "failure": torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float(),
        "airborne_progress": torch.sum(airborne_progress, dim=1) * moving.float(),
        "last_progress_m": last_progress,
        "active": active,
        "qualified": qualified,
        "step_credit_multiplier": step_credit,
    }


def moving_per_foot_qualified_directional_touchdown_success_v52(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    repeat_same_foot_credit: float = 0.25, bodies_per_foot: int = 2,
    event_hold_s: float = 0.10, torque_limit_nm: float = 2.94,
    desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v52(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, repeat_same_foot_credit, bodies_per_foot,
        event_hold_s, torque_limit_nm, desired_base_com_height_m,
    )["success"]


def moving_per_foot_qualified_directional_touchdown_failure_v52(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    repeat_same_foot_credit: float = 0.25, bodies_per_foot: int = 2,
    event_hold_s: float = 0.10, torque_limit_nm: float = 2.94,
    desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v52(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, repeat_same_foot_credit, bodies_per_foot,
        event_hold_s, torque_limit_nm, desired_base_com_height_m,
    )["failure"]


def moving_per_foot_qualified_airborne_directional_progress_v52(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05, min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010, full_progress_m: float = 0.025,
    repeat_same_foot_credit: float = 0.25, bodies_per_foot: int = 2,
    event_hold_s: float = 0.10, torque_limit_nm: float = 2.94,
    desired_base_com_height_m: float = 0.470,
) -> torch.Tensor:
    return _moving_per_foot_qualified_directional_step_state_v52(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_clearance_m, full_progress_m, repeat_same_foot_credit, bodies_per_foot,
        event_hold_s, torque_limit_nm, desired_base_com_height_m,
    )["airborne_progress"]


# -----------------------------------------------------------------------------
# LittleGreen v5.4 gait-exploration rewards
# -----------------------------------------------------------------------------
def moving_command_velocity_progress_reward_v54(
    env: ManagerBasedRLEnv,
    command_name: str,
    command_threshold: float = 0.08,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Dense gait-agnostic reward for base velocity along the planar command.

    Positive progress is normalized by requested planar speed and capped at one.
    Standing, sideways motion, and motion opposite the command receive zero rather
    than a negative reward.  This gives a fresh policy immediate evidence that any
    useful translation is better than freezing, without specifying feet, timing,
    posture, stride length, or gait family.
    """
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command, dim=1)
    command_dir = command / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    projected_speed = torch.sum(vel_yaw * command_dir, dim=1)
    ratio = torch.clamp(projected_speed / torch.clamp(command_norm, min=1.0e-3), min=0.0, max=1.0)
    return ratio * (command_norm > float(command_threshold)).float()


def _moving_per_foot_exploratory_step_state_v54(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_air_time_s: float = 0.10,
    min_clearance_m: float = 0.010,
    full_progress_m: float = 0.025,
    repeat_same_foot_credit: float = 0.25,
    event_hold_s: float = 0.10,
    min_alternation_progress_m: float = 0.012,
    min_alternation_velocity_ratio: float = 0.20,
    bodies_per_foot: int = 2,
) -> dict[str, torch.Tensor]:
    """v5.4 completed-step state for open gait exploration.

    The swing may be produced by any gait.  A touchdown is judged only after a
    genuine whole-foot swing (time + clearance).  Positive completed-step credit
    couples foot displacement to *commanded base velocity*: the score is the
    geometric mean of command-direction foot progress and command-direction base
    velocity tracking at touchdown.  This prevents a positive toe tap from being
    treated as locomotion while avoiding any prescribed stride length or cadence.

    Repeat-foot attenuation is applied only to positive completed touchdown credit.
    Air-time and airborne exploration remain unattenuated.  The +alternation event
    is paid only when the opposite foot completes a meaningful qualified touchdown
    (>= ``min_alternation_progress_m`` and >= the configured velocity ratio), so a
    toe tap cannot farm alternation reward.
    """
    if min_air_time_s < 0.0 or min_clearance_m < 0.0 or full_progress_m <= 0.0:
        raise ValueError("v5.4 step thresholds invalid")
    if not 0.0 <= repeat_same_foot_credit <= 1.0:
        raise ValueError("repeat_same_foot_credit must be in [0, 1]")
    if min_alternation_progress_m < 0.0 or min_alternation_velocity_ratio < 0.0:
        raise ValueError("v5.4 alternation qualification must be non-negative")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    expected = 2 * g
    if g <= 0 or contact_t.shape[1] != expected or air_t.shape[1] != expected:
        raise ValueError(f"v5.4 expected {expected} ordered whole-foot contact bodies")

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != expected:
        raise ValueError(f"v5.4 expected {expected} ordered whole-foot robot bodies")

    left_contact = torch.any(contact_t[:, :g] > 0.0, dim=1)
    right_contact = torch.any(contact_t[:, g:] > 0.0, dim=1)
    grounded = torch.stack((left_contact, right_contact), dim=1)
    left_stance = left_contact & (~right_contact)
    right_stance = right_contact & (~left_contact)
    swing_mask = torch.stack((right_stance, left_stance), dim=1)

    whole_air = torch.stack((torch.min(air_t[:, :g], dim=1).values, torch.min(air_t[:, g:], dim=1).values), dim=1)
    body_z = body_pos[:, :, 2]
    left_clearance = torch.min(body_z[:, :g] - body_z[:, g:], dim=1).values
    right_clearance = torch.min(body_z[:, g:] - body_z[:, :g], dim=1).values
    clearance = torch.stack((left_clearance, right_clearance), dim=1)
    main_xy = torch.stack((body_pos[:, 0, :2], body_pos[:, g, :2]), dim=1)

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    command_dir_w = quat_apply(yaw_quat(asset.data.root_quat_w), command_dir_3d)[:, :2]

    num_envs = grounded.shape[0]
    device = grounded.device
    dtype = main_xy.dtype

    def state(name, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.to(device=device, dtype=dtype_)
        else:
            value = value.to(device=device, dtype=dtype_)
        return value

    prev_grounded = state('_littlegreen_v54_prev_grounded', grounded.shape, torch.bool, grounded.clone())
    prev_main_xy = state('_littlegreen_v54_prev_main_xy', main_xy.shape, dtype, main_xy.clone())
    active = state('_littlegreen_v54_active', grounded.shape, torch.bool, torch.zeros_like(grounded))
    qualified = state('_littlegreen_v54_qualified', grounded.shape, torch.bool, torch.zeros_like(grounded))
    liftoff_xy = state('_littlegreen_v54_liftoff_xy', main_xy.shape, dtype, main_xy.clone())
    liftoff_dir = state('_littlegreen_v54_liftoff_dir', main_xy.shape, dtype, torch.zeros_like(main_xy))
    liftoff_cmd_speed = state('_littlegreen_v54_liftoff_cmd_speed', grounded.shape, dtype, torch.ones_like(grounded, dtype=dtype))
    step_credit = state('_littlegreen_v54_step_credit', grounded.shape, dtype, torch.ones_like(grounded, dtype=dtype))
    success_hold = state('_littlegreen_v54_success_hold', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))
    failure_hold = state('_littlegreen_v54_failure_hold', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))
    success_value = state('_littlegreen_v54_success_value', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))
    failure_value = state('_littlegreen_v54_failure_value', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))
    alternation_hold = state('_littlegreen_v54_alternation_hold', (num_envs,), dtype, torch.zeros(num_envs, device=device, dtype=dtype))
    last_completed_foot = state('_littlegreen_v54_last_completed_foot', (num_envs,), torch.long, torch.full((num_envs,), -1, device=device, dtype=torch.long))
    last_progress = state('_littlegreen_v54_last_progress', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))
    last_velocity_ratio = state('_littlegreen_v54_last_velocity_ratio', grounded.shape, dtype, torch.zeros_like(grounded, dtype=dtype))

    common_step = int(getattr(env, 'common_step_counter', 0))
    last_step = int(getattr(env, '_littlegreen_v54_last_common_step', -1))
    if common_step != last_step:
        dt = float(getattr(env, 'step_dt', 0.02))
        reset_mask = _v10_episode_reset_mask(env, num_envs, device)
        episode_length = getattr(env, 'episode_length_buf', None)
        last_episode_length = getattr(env, '_littlegreen_v54_last_episode_length', None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == num_envs:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == num_envs:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v54_last_episode_length = current_episode_length.clone()

        success_hold = torch.clamp(success_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        alternation_hold = torch.clamp(alternation_hold - dt, min=0.0)
        success_value = torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        reset2 = reset_mask.unsqueeze(-1)
        active = torch.where(reset2, torch.zeros_like(active), active)
        qualified = torch.where(reset2, torch.zeros_like(qualified), qualified)
        step_credit = torch.where(reset2, torch.ones_like(step_credit), step_credit)
        success_hold = torch.where(reset2, torch.zeros_like(success_hold), success_hold)
        failure_hold = torch.where(reset2, torch.zeros_like(failure_hold), failure_hold)
        success_value = torch.where(reset2, torch.zeros_like(success_value), success_value)
        failure_value = torch.where(reset2, torch.zeros_like(failure_value), failure_value)
        alternation_hold = torch.where(reset_mask, torch.zeros_like(alternation_hold), alternation_hold)
        last_completed_foot = torch.where(reset_mask, torch.full_like(last_completed_foot, -1), last_completed_foot)
        prev_grounded = torch.where(reset2, grounded, prev_grounded)
        prev_main_xy = torch.where(reset2.unsqueeze(-1), main_xy, prev_main_xy)

        liftoff = prev_grounded & (~grounded) & moving.unsqueeze(-1) & (~reset2)
        foot_ids = torch.arange(2, device=device, dtype=torch.long).view(1, 2).expand(num_envs, -1)
        repeated = (last_completed_foot >= 0).unsqueeze(-1) & (foot_ids == last_completed_foot.unsqueeze(-1))
        new_credit = torch.where(repeated, torch.full_like(step_credit, float(repeat_same_foot_credit)), torch.ones_like(step_credit))
        step_credit = torch.where(liftoff, new_credit, step_credit)
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_main_xy, liftoff_xy)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), command_dir_w[:, None, :].expand(-1, 2, -1), liftoff_dir)
        liftoff_cmd_speed = torch.where(liftoff, command_norm.unsqueeze(-1).expand(-1, 2), liftoff_cmd_speed)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)

        qualifies_now = active & (~grounded) & swing_mask & (whole_air >= float(min_air_time_s)) & (clearance >= float(min_clearance_m)) & moving.unsqueeze(-1) & (~reset2)
        qualified = qualified | qualifies_now

        touchdown = (~prev_grounded) & grounded & active & moving.unsqueeze(-1) & (~reset2)
        judged = touchdown & qualified
        progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
        progress_score = torch.clamp(progress / float(full_progress_m), min=0.0, max=1.0)

        vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
        # liftoff_dir is world-frame; rotate current base velocity into world to compare directly.
        base_vel_w = asset.data.root_lin_vel_w[:, :2]
        projected_speed = torch.sum(base_vel_w[:, None, :] * liftoff_dir, dim=-1)
        velocity_ratio = torch.clamp(projected_speed / torch.clamp(liftoff_cmd_speed, min=1.0e-3), min=0.0, max=1.0)
        # Geometric mean requires both a real positive step and actual command-speed tracking.
        command_tracking_step_score = torch.sqrt(torch.clamp(progress_score * velocity_ratio, min=0.0))
        positive_value = command_tracking_step_score * step_credit
        negative_value = torch.clamp((-progress) / float(full_progress_m), min=0.0, max=1.0)

        hold = max(float(event_hold_s), dt)
        success_hold = torch.where(judged, torch.full_like(success_hold, hold), success_hold)
        failure_hold = torch.where(judged, torch.full_like(failure_hold, hold), failure_hold)
        success_value = torch.where(judged, positive_value, success_value)
        failure_value = torch.where(judged, negative_value, failure_value)
        last_progress = torch.where(judged, progress, last_progress)
        last_velocity_ratio = torch.where(judged, velocity_ratio, last_velocity_ratio)

        meaningful = judged & (progress >= float(min_alternation_progress_m)) & (velocity_ratio >= float(min_alternation_velocity_ratio))
        any_meaningful = torch.any(meaningful, dim=1)
        event_foot = torch.argmax(meaningful.to(torch.long), dim=1)
        alternates = any_meaningful & (last_completed_foot >= 0) & (event_foot != last_completed_foot)
        alternation_hold = torch.where(alternates, torch.full_like(alternation_hold, hold), alternation_hold)
        last_completed_foot = torch.where(any_meaningful, event_foot, last_completed_foot)

        active = torch.where(touchdown, torch.zeros_like(active), active)
        qualified = torch.where(touchdown, torch.zeros_like(qualified), qualified)
        step_credit = torch.where(touchdown, torch.ones_like(step_credit), step_credit)
        active = active & moving.unsqueeze(-1)
        qualified = qualified & active

        prev_grounded = grounded.clone()
        prev_main_xy = main_xy.clone()
        env._littlegreen_v54_prev_grounded = prev_grounded
        env._littlegreen_v54_prev_main_xy = prev_main_xy
        env._littlegreen_v54_active = active
        env._littlegreen_v54_qualified = qualified
        env._littlegreen_v54_liftoff_xy = liftoff_xy
        env._littlegreen_v54_liftoff_dir = liftoff_dir
        env._littlegreen_v54_liftoff_cmd_speed = liftoff_cmd_speed
        env._littlegreen_v54_step_credit = step_credit
        env._littlegreen_v54_success_hold = success_hold
        env._littlegreen_v54_failure_hold = failure_hold
        env._littlegreen_v54_success_value = success_value
        env._littlegreen_v54_failure_value = failure_value
        env._littlegreen_v54_alternation_hold = alternation_hold
        env._littlegreen_v54_last_completed_foot = last_completed_foot
        env._littlegreen_v54_last_progress = last_progress
        env._littlegreen_v54_last_velocity_ratio = last_velocity_ratio
        env._littlegreen_v54_last_common_step = common_step

    current_progress = torch.sum((main_xy - liftoff_xy) * liftoff_dir, dim=-1)
    airborne_progress = torch.clamp(current_progress / float(full_progress_m), min=0.0, max=1.0)
    # Exploration stays fully credited regardless of which foot moved last.
    airborne_progress = airborne_progress * qualified.float() * (~grounded).float() * moving.unsqueeze(-1).float()

    return {
        'success': torch.sum(torch.where(success_hold > 0.0, success_value, torch.zeros_like(success_value)), dim=1) * moving.float(),
        'failure': torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float(),
        'airborne_progress': torch.sum(airborne_progress, dim=1) * moving.float(),
        'alternation_bonus': (alternation_hold > 0.0).float() * moving.float(),
        'last_progress_m': last_progress,
        'last_velocity_ratio': last_velocity_ratio,
        'last_completed_foot': last_completed_foot,
    }


def moving_per_foot_command_tracking_touchdown_success_v54(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, min_air_time_s: float = 0.10, min_clearance_m: float = 0.010,
    full_progress_m: float = 0.025, repeat_same_foot_credit: float = 0.25, event_hold_s: float = 0.10,
    min_alternation_progress_m: float = 0.012, min_alternation_velocity_ratio: float = 0.20,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    return _moving_per_foot_exploratory_step_state_v54(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s, min_clearance_m,
        full_progress_m, repeat_same_foot_credit, event_hold_s, min_alternation_progress_m,
        min_alternation_velocity_ratio, bodies_per_foot,
    )['success']


