# -----------------------------------------------------------------------------
# LittleGreen v6.0 Berkeley-synthesis locomotion rewards
# -----------------------------------------------------------------------------
def track_lin_vel_xy_stationary_baseline_corrected_v60(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float = 0.50,
    command_threshold: float = 0.08,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Velocity tracking improvement relative to the stationary solution.

    The original Berkeley exponential kernel gives a slow physical robot substantial
    positive reward even when it ignores a moderate command.  For nonzero planar
    commands this term subtracts that stationary baseline and normalizes the remaining
    headroom: standing still is exactly zero, exact tracking is approximately one,
    and motion that is worse than standing is negative.  Zero-planar-command examples
    retain the ordinary exponential quiet-velocity reward.
    """
    if std <= 0.0:
        raise ValueError("v6.0 velocity std must be positive")
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    error_now = torch.sum(torch.square(command - vel_yaw), dim=1)
    command_sq = torch.sum(torch.square(command), dim=1)
    score_now = torch.exp(-error_now / float(std) ** 2)
    score_still = torch.exp(-command_sq / float(std) ** 2)
    headroom = torch.clamp(1.0 - score_still, min=0.05)
    improvement = torch.clamp((score_now - score_still) / headroom, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > float(command_threshold)
    return torch.where(moving, improvement, score_now)


def _directional_full_plant_step_state_v60(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010,
    min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035,
    min_sequence_progress_m: float = 0.010,
    first_step_multiplier: float = 0.50,
    opposite_step_multiplier: float = 1.00,
    repeat_same_foot_multiplier: float = 0.10,
    velocity_bootstrap_fraction: float = 0.25,
    coherence_full_diff_m: float = 0.020,
    coherence_zero_diff_m: float = 0.060,
    full_plant_window_s: float = 0.25,
    event_hold_s: float = 0.02,
    bodies_per_foot: int = 2,
) -> dict[str, torch.Tensor]:
    """State machine for a flexible but physically complete biped step.

    A foot must first have been fully planted (main + passive toe).  Liftoff occurs
    only when both components are subsequently clear of contact.  A swing qualifies
    after minimum air time and independent main/toe clearance.  Toe-first, heel-first,
    or simultaneous landing is legal, but the step is not complete until BOTH foot
    components are planted within ``full_plant_window_s`` of first contact.

    The positive value combines directional foot progress, a broad main/toe swing
    coherence factor, and base velocity along the commanded direction.  Sequence
    economics are deliberately strong but timing-free: first meaningful step gets
    half credit, an opposite-foot next step gets full credit, and repeating the same
    foot gets only one tenth.  No phase, cadence, stride schedule, ZMP, or COM-transfer
    target is used.
    """
    if min_air_time_s < 0.0 or min_main_clearance_m < 0.0 or min_toe_clearance_m < 0.0:
        raise ValueError("v6.0 swing thresholds must be non-negative")
    if full_progress_m <= 0.0 or min_sequence_progress_m < 0.0:
        raise ValueError("v6.0 progress thresholds invalid")
    if not (0.0 <= repeat_same_foot_multiplier <= first_step_multiplier <= opposite_step_multiplier):
        raise ValueError("v6.0 step multipliers must satisfy repeat <= first <= opposite")
    if not 0.0 <= velocity_bootstrap_fraction <= 1.0:
        raise ValueError("v6.0 velocity bootstrap must be in [0,1]")
    if not 0.0 <= coherence_full_diff_m < coherence_zero_diff_m:
        raise ValueError("v6.0 coherence thresholds invalid")
    if full_plant_window_s <= 0.0:
        raise ValueError("v6.0 full-plant window must be positive")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    if g != 2 or contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.0 expects ordered L_main,L_toe,R_main,R_toe contact bodies")

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != 4:
        raise ValueError("v6.0 expects ordered L_main,L_toe,R_main,R_toe robot bodies")

    component_contact = contact_t > 0.0
    left_any = torch.any(component_contact[:, :2], dim=1)
    right_any = torch.any(component_contact[:, 2:], dim=1)
    left_full = torch.all(component_contact[:, :2], dim=1)
    right_full = torch.all(component_contact[:, 2:], dim=1)
    any_contact = torch.stack((left_any, right_any), dim=1)
    full_plant = torch.stack((left_full, right_full), dim=1)

    whole_air = torch.stack(
        (torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1
    )
    z = body_pos[:, :, 2]
    # Matching-component relative clearance cancels the ankle/toe bodies' nominal
    # vertical geometry and directly measures swing lift relative to the other foot.
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    clearance_diff = torch.abs(main_clear - toe_clear)
    coherence_span = max(float(coherence_zero_diff_m) - float(coherence_full_diff_m), 1.0e-6)
    coherence = torch.clamp(
        (float(coherence_zero_diff_m) - clearance_diff) / coherence_span, min=0.0, max=1.0
    )

    center_xy = torch.stack(
        (0.5 * (body_pos[:, 0, :2] + body_pos[:, 1, :2]),
         0.5 * (body_pos[:, 2, :2] + body_pos[:, 3, :2])), dim=1
    )

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    command_dir_w = quat_apply(yaw_quat(asset.data.root_quat_w), command_dir_3d)[:, :2]

    n = any_contact.shape[0]
    device = any_contact.device
    dtype = center_xy.dtype

    def state(name, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.to(device=device, dtype=dtype_)
        else:
            value = value.to(device=device, dtype=dtype_)
        return value

    prev_any = state('_littlegreen_v60_prev_any_contact', any_contact.shape, torch.bool, any_contact.clone())
    prev_center = state('_littlegreen_v60_prev_center_xy', center_xy.shape, dtype, center_xy.clone())
    ready = state('_littlegreen_v60_ready_full_plant', full_plant.shape, torch.bool, full_plant.clone())
    active = state('_littlegreen_v60_active', full_plant.shape, torch.bool, torch.zeros_like(full_plant))
    qualified = state('_littlegreen_v60_qualified', full_plant.shape, torch.bool, torch.zeros_like(full_plant))
    liftoff_xy = state('_littlegreen_v60_liftoff_xy', center_xy.shape, dtype, center_xy.clone())
    liftoff_dir = state('_littlegreen_v60_liftoff_dir', center_xy.shape, dtype, torch.zeros_like(center_xy))
    liftoff_cmd_speed = state('_littlegreen_v60_liftoff_cmd_speed', full_plant.shape, dtype, torch.ones_like(full_plant, dtype=dtype))
    last_air_quality = state('_littlegreen_v60_last_air_quality', full_plant.shape, dtype, torch.ones_like(full_plant, dtype=dtype))
    landing_started = state('_littlegreen_v60_landing_started', full_plant.shape, torch.bool, torch.zeros_like(full_plant))
    landing_timer = state('_littlegreen_v60_landing_timer_s', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    reward_hold = state('_littlegreen_v60_reward_hold_s', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    reward_value = state('_littlegreen_v60_reward_value', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    failure_hold = state('_littlegreen_v60_failure_hold_s', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    failure_value = state('_littlegreen_v60_failure_value', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    last_sequence_foot = state('_littlegreen_v60_last_sequence_foot', (n,), torch.long, torch.full((n,), -1, device=device, dtype=torch.long))
    last_progress = state('_littlegreen_v60_last_progress_m', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    last_velocity_ratio = state('_littlegreen_v60_last_velocity_ratio', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    last_coherence = state('_littlegreen_v60_last_coherence', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))
    last_multiplier = state('_littlegreen_v60_last_sequence_multiplier', full_plant.shape, dtype, torch.zeros_like(full_plant, dtype=dtype))

    common_step = int(getattr(env, 'common_step_counter', 0))
    last_step = int(getattr(env, '_littlegreen_v60_last_common_step', -1))
    if common_step != last_step:
        dt = float(getattr(env, 'step_dt', 0.02))
        reset_mask = _v10_episode_reset_mask(env, n, device)
        episode_length = getattr(env, 'episode_length_buf', None)
        last_episode_length = getattr(env, '_littlegreen_v60_last_episode_length', None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == n:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == n:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v60_last_episode_length = current_episode_length.clone()
        reset2 = reset_mask.unsqueeze(-1)

        reward_hold = torch.clamp(reward_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        reward_value = torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        active = torch.where(reset2, torch.zeros_like(active), active)
        qualified = torch.where(reset2, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(reset2, torch.zeros_like(landing_started), landing_started)
        landing_timer = torch.where(reset2, torch.zeros_like(landing_timer), landing_timer)
        ready = torch.where(reset2, full_plant, ready)
        last_sequence_foot = torch.where(reset_mask, torch.full_like(last_sequence_foot, -1), last_sequence_foot)
        prev_any = torch.where(reset2, any_contact, prev_any)
        prev_center = torch.where(reset2.unsqueeze(-1), center_xy, prev_center)

        # A fully planted foot is eligible to start a new step once it leaves the floor.
        ready = ready | (full_plant & (~active))
        liftoff = prev_any & (~any_contact) & ready & moving.unsqueeze(-1) & (~reset2)
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_center, liftoff_xy)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), command_dir_w[:, None, :].expand(-1, 2, -1), liftoff_dir)
        liftoff_cmd_speed = torch.where(liftoff, command_norm.unsqueeze(-1).expand(-1, 2), liftoff_cmd_speed)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(liftoff, torch.zeros_like(landing_started), landing_started)
        landing_timer = torch.where(liftoff, torch.zeros_like(landing_timer), landing_timer)
        ready = torch.where(liftoff, torch.zeros_like(ready), ready)

        airborne = active & (~any_contact) & moving.unsqueeze(-1) & (~reset2)
        last_air_quality = torch.where(airborne, coherence, last_air_quality)
        qualifies_now = (
            airborne
            & (whole_air >= float(min_air_time_s))
            & (main_clear >= float(min_main_clearance_m))
            & (toe_clear >= float(min_toe_clearance_m))
        )
        qualified = qualified | qualifies_now

        first_contact = (~prev_any) & any_contact & active & qualified & moving.unsqueeze(-1) & (~reset2)
        landing_started = landing_started | first_contact
        landing_timer = torch.where(first_contact, torch.zeros_like(landing_timer), landing_timer)
        landing_timer = torch.where(active & landing_started, landing_timer + dt, landing_timer)

        completion = (
            full_plant & active & qualified & landing_started
            & (landing_timer <= float(full_plant_window_s))
            & moving.unsqueeze(-1) & (~reset2)
        )

        progress = torch.sum((center_xy - liftoff_xy) * liftoff_dir, dim=-1)
        progress_score = torch.clamp(progress / float(full_progress_m), min=0.0, max=1.0)
        base_vel_w = asset.data.root_lin_vel_w[:, :2]
        projected_speed = torch.sum(base_vel_w[:, None, :] * liftoff_dir, dim=-1)
        velocity_ratio = torch.clamp(
            projected_speed / torch.clamp(liftoff_cmd_speed, min=1.0e-3), min=0.0, max=1.0
        )
        velocity_factor = float(velocity_bootstrap_fraction) + (1.0 - float(velocity_bootstrap_fraction)) * velocity_ratio
        raw_step_quality = progress_score * last_air_quality * velocity_factor

        foot_ids = torch.arange(2, device=device, dtype=torch.long).view(1, 2).expand(n, -1)
        has_previous = last_sequence_foot >= 0
        same = has_previous.unsqueeze(-1) & (foot_ids == last_sequence_foot.unsqueeze(-1))
        opposite = has_previous.unsqueeze(-1) & (~same)
        multiplier = torch.where(
            same, torch.full_like(raw_step_quality, float(repeat_same_foot_multiplier)),
            torch.where(
                opposite, torch.full_like(raw_step_quality, float(opposite_step_multiplier)),
                torch.full_like(raw_step_quality, float(first_step_multiplier)),
            ),
        )
        positive_value = raw_step_quality * multiplier
        negative_value = torch.clamp((-progress) / float(full_progress_m), min=0.0, max=1.0)

        hold = max(float(event_hold_s), dt)
        reward_hold = torch.where(completion, torch.full_like(reward_hold, hold), reward_hold)
        failure_hold = torch.where(completion, torch.full_like(failure_hold, hold), failure_hold)
        reward_value = torch.where(completion, positive_value, reward_value)
        failure_value = torch.where(completion, negative_value, failure_value)
        last_progress = torch.where(completion, progress, last_progress)
        last_velocity_ratio = torch.where(completion, velocity_ratio, last_velocity_ratio)
        last_coherence = torch.where(completion, last_air_quality, last_coherence)
        last_multiplier = torch.where(completion, multiplier, last_multiplier)

        meaningful = (
            completion
            & (progress >= float(min_sequence_progress_m))
            & (last_air_quality > 0.0)
        )
        # Simultaneous two-foot landing (hop) is valid physically but does not count
        # as a left/right sequence event.
        one_meaningful = torch.sum(meaningful.to(torch.int32), dim=1) == 1
        meaningful_foot = torch.argmax(meaningful.to(torch.long), dim=1)
        last_sequence_foot = torch.where(one_meaningful, meaningful_foot, last_sequence_foot)

        landing_timeout = active & landing_started & (landing_timer > float(full_plant_window_s))
        unqualified_return = active & full_plant & (~qualified)
        finish = completion | landing_timeout | unqualified_return
        active = torch.where(finish, torch.zeros_like(active), active)
        qualified = torch.where(finish, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(finish, torch.zeros_like(landing_started), landing_started)
        landing_timer = torch.where(finish, torch.zeros_like(landing_timer), landing_timer)
        ready = ready | (full_plant & (~active))

        active = active & moving.unsqueeze(-1)
        qualified = qualified & active
        landing_started = landing_started & active

        prev_any = any_contact.clone()
        prev_center = center_xy.clone()
        env._littlegreen_v60_prev_any_contact = prev_any
        env._littlegreen_v60_prev_center_xy = prev_center
        env._littlegreen_v60_ready_full_plant = ready
        env._littlegreen_v60_active = active
        env._littlegreen_v60_qualified = qualified
        env._littlegreen_v60_liftoff_xy = liftoff_xy
        env._littlegreen_v60_liftoff_dir = liftoff_dir
        env._littlegreen_v60_liftoff_cmd_speed = liftoff_cmd_speed
        env._littlegreen_v60_last_air_quality = last_air_quality
        env._littlegreen_v60_landing_started = landing_started
        env._littlegreen_v60_landing_timer_s = landing_timer
        env._littlegreen_v60_reward_hold_s = reward_hold
        env._littlegreen_v60_reward_value = reward_value
        env._littlegreen_v60_failure_hold_s = failure_hold
        env._littlegreen_v60_failure_value = failure_value
        env._littlegreen_v60_last_sequence_foot = last_sequence_foot
        env._littlegreen_v60_last_progress_m = last_progress
        env._littlegreen_v60_last_velocity_ratio = last_velocity_ratio
        env._littlegreen_v60_last_coherence = last_coherence
        env._littlegreen_v60_last_sequence_multiplier = last_multiplier
        env._littlegreen_v60_last_common_step = common_step

    return {
        'success': torch.sum(torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value)), dim=1) * moving.float(),
        'failure': torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float(),
        'last_progress_m': last_progress,
        'last_velocity_ratio': last_velocity_ratio,
        'last_coherence': last_coherence,
        'last_sequence_multiplier': last_multiplier,
        'last_sequence_foot': last_sequence_foot,
    }


def alternating_directional_full_plant_step_reward_v60(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010, min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035, min_sequence_progress_m: float = 0.010,
    first_step_multiplier: float = 0.50, opposite_step_multiplier: float = 1.00,
    repeat_same_foot_multiplier: float = 0.10, velocity_bootstrap_fraction: float = 0.25,
    coherence_full_diff_m: float = 0.020, coherence_zero_diff_m: float = 0.060,
    full_plant_window_s: float = 0.25, event_hold_s: float = 0.02, bodies_per_foot: int = 2,
) -> torch.Tensor:
    return _directional_full_plant_step_state_v60(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_main_clearance_m, min_toe_clearance_m, full_progress_m, min_sequence_progress_m,
        first_step_multiplier, opposite_step_multiplier, repeat_same_foot_multiplier,
        velocity_bootstrap_fraction, coherence_full_diff_m, coherence_zero_diff_m,
        full_plant_window_s, event_hold_s, bodies_per_foot,
    )['success']


def directional_full_plant_step_failure_v60(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010, min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035, min_sequence_progress_m: float = 0.010,
    first_step_multiplier: float = 0.50, opposite_step_multiplier: float = 1.00,
    repeat_same_foot_multiplier: float = 0.10, velocity_bootstrap_fraction: float = 0.25,
    coherence_full_diff_m: float = 0.020, coherence_zero_diff_m: float = 0.060,
    full_plant_window_s: float = 0.25, event_hold_s: float = 0.02, bodies_per_foot: int = 2,
) -> torch.Tensor:
    return _directional_full_plant_step_state_v60(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_main_clearance_m, min_toe_clearance_m, full_progress_m, min_sequence_progress_m,
        first_step_multiplier, opposite_step_multiplier, repeat_same_foot_multiplier,
        velocity_bootstrap_fraction, coherence_full_diff_m, coherence_zero_diff_m,
        full_plant_window_s, event_hold_s, bodies_per_foot,
    )['failure']


# -----------------------------------------------------------------------------
# LittleGreen v6.1 healthy-learning locomotion bridge
# -----------------------------------------------------------------------------
def track_lin_vel_xy_stationary_baseline_normalized_v61(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float = 0.50,
    command_threshold: float = 0.08,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Normalized planar tracking improvement over standing still.

    For a moving command, standing still is exactly 0 and exact command tracking is
    exactly 1 (up to numerical precision), independent of command magnitude.  This
    keeps the Berkeley exponential objective while removing the stationary subsidy.
    Near-zero commands retain the ordinary quiet-velocity exponential.
    """
    if std <= 0.0:
        raise ValueError("v6.1 velocity std must be positive")
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    error_now = torch.sum(torch.square(command - vel_yaw), dim=1)
    command_sq = torch.sum(torch.square(command), dim=1)
    score_now = torch.exp(-error_now / float(std) ** 2)
    score_still = torch.exp(-command_sq / float(std) ** 2)
    headroom = torch.clamp(1.0 - score_still, min=1.0e-6)
    normalized = torch.clamp((score_now - score_still) / headroom, min=-1.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > float(command_threshold)
    return torch.where(moving, normalized, score_now)


def track_ang_vel_z_stationary_baseline_normalized_v61(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float = 0.50,
    command_threshold: float = 0.08,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Yaw analogue of the v6.1 stationary-baseline-normalized tracker."""
    if std <= 0.0:
        raise ValueError("v6.1 yaw std must be positive")
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, 2]
    actual = asset.data.root_ang_vel_w[:, 2]
    score_now = torch.exp(-torch.square(command - actual) / float(std) ** 2)
    score_still = torch.exp(-torch.square(command) / float(std) ** 2)
    headroom = torch.clamp(1.0 - score_still, min=1.0e-6)
    normalized = torch.clamp((score_now - score_still) / headroom, min=-1.0, max=1.0)
    moving = torch.abs(command) > float(command_threshold)
    return torch.where(moving, normalized, score_now)


def _directional_step_and_takeover_state_v61(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010,
    min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035,
    min_sequence_progress_m: float = 0.008,
    first_step_multiplier: float = 1.00,
    opposite_step_multiplier: float = 2.00,
    repeat_same_foot_multiplier: float = 0.10,
    velocity_bootstrap_fraction: float = 0.35,
    coherence_full_diff_m: float = 0.020,
    coherence_zero_diff_m: float = 0.060,
    landing_window_s: float = 0.30,
    event_hold_s: float = 0.08,
    takeover_window_s: float = 0.45,
    takeover_load_start: float = 0.30,
    takeover_load_full: float = 0.55,
    takeover_com_improvement_full_m: float = 0.050,
    bodies_per_foot: int = 2,
) -> dict[str, torch.Tensor]:
    """Flexible whole-foot step plus a short post-landing support-takeover bridge.

    Important v6.1 differences from v6.0:
    - liftoff may begin from *any* normal foot contact; simultaneous main+toe contact
      before liftoff is not required;
    - a genuine swing still requires BOTH main and passive-toe release plus clearance;
    - toe-first or heel-first landing is legal and the two contact components are
      remembered independently during ``landing_window_s``;
    - the step completes once both components have touched during the landing window
      and the foot still has contact, rather than requiring simultaneous contact;
    - after a meaningful landing, a short support-takeover score rewards increasing
      vertical load on the newly landed foot and moving the COM laterally toward it.

    No phase clock, cadence, exact ZMP path, stride trajectory, or joint posture is
    prescribed.
    """
    if min_air_time_s < 0.0 or min_main_clearance_m < 0.0 or min_toe_clearance_m < 0.0:
        raise ValueError("v6.1 swing thresholds must be non-negative")
    if full_progress_m <= 0.0 or min_sequence_progress_m < 0.0:
        raise ValueError("v6.1 progress thresholds invalid")
    if not (0.0 <= repeat_same_foot_multiplier <= first_step_multiplier <= opposite_step_multiplier):
        raise ValueError("v6.1 step multipliers must satisfy repeat <= first <= opposite")
    if not 0.0 <= velocity_bootstrap_fraction <= 1.0:
        raise ValueError("v6.1 velocity bootstrap must be in [0,1]")
    if not 0.0 <= coherence_full_diff_m < coherence_zero_diff_m:
        raise ValueError("v6.1 coherence thresholds invalid")
    if landing_window_s <= 0.0 or takeover_window_s <= 0.0:
        raise ValueError("v6.1 landing/takeover windows must be positive")
    if not 0.0 <= takeover_load_start < takeover_load_full <= 1.0:
        raise ValueError("v6.1 support load thresholds invalid")
    if takeover_com_improvement_full_m <= 0.0:
        raise ValueError("v6.1 COM takeover scale must be positive")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    g = int(bodies_per_foot)
    if g != 2 or contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.1 expects ordered L_main,L_toe,R_main,R_toe contact bodies")

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != 4:
        raise ValueError("v6.1 expects ordered L_main,L_toe,R_main,R_toe robot bodies")

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact

    whole_air = torch.stack(
        (torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1
    )
    z = body_pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    clearance_diff = torch.abs(main_clear - toe_clear)
    coherence_span = max(float(coherence_zero_diff_m) - float(coherence_full_diff_m), 1.0e-6)
    coherence = torch.clamp(
        (float(coherence_zero_diff_m) - clearance_diff) / coherence_span, min=0.0, max=1.0
    )

    centers = torch.stack(
        (0.5 * (body_pos[:, 0, :] + body_pos[:, 1, :]),
         0.5 * (body_pos[:, 2, :] + body_pos[:, 3, :])), dim=1
    )
    center_xy = centers[:, :, :2]
    midpoint = 0.5 * (centers[:, 0, :] + centers[:, 1, :])

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    root_yaw = yaw_quat(asset.data.root_quat_w)
    command_dir_w = quat_apply(root_yaw, command_dir_3d)[:, :2]

    # Vertical-load fraction for the post-landing support takeover bridge.
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    load_share = foot_load / torch.clamp(torch.sum(foot_load, dim=1, keepdim=True), min=1.0e-6)

    com_rel = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
    left_rel = quat_apply_inverse(root_yaw, centers[:, 0, :] - midpoint)
    right_rel = quat_apply_inverse(root_yaw, centers[:, 1, :] - midpoint)
    foot_rel_y = torch.stack((left_rel[:, 1], right_rel[:, 1]), dim=1)
    com_to_foot_lat = torch.abs(com_rel[:, 1].unsqueeze(-1) - foot_rel_y)

    n = any_contact.shape[0]
    device = any_contact.device
    dtype = center_xy.dtype

    def state(name, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.to(device=device, dtype=dtype_)
        else:
            value = value.to(device=device, dtype=dtype_)
        return value

    prev_any = state('_littlegreen_v61_prev_any_contact', any_contact.shape, torch.bool, any_contact.clone())
    prev_center = state('_littlegreen_v61_prev_center_xy', center_xy.shape, dtype, center_xy.clone())
    active = state('_littlegreen_v61_active', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    qualified = state('_littlegreen_v61_qualified', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    liftoff_xy = state('_littlegreen_v61_liftoff_xy', center_xy.shape, dtype, center_xy.clone())
    liftoff_dir = state('_littlegreen_v61_liftoff_dir', center_xy.shape, dtype, torch.zeros_like(center_xy))
    liftoff_cmd_speed = state('_littlegreen_v61_liftoff_cmd_speed', any_contact.shape, dtype, torch.ones_like(any_contact, dtype=dtype))
    last_air_quality = state('_littlegreen_v61_last_air_quality', any_contact.shape, dtype, torch.ones_like(any_contact, dtype=dtype))
    landing_started = state('_littlegreen_v61_landing_started', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_main_seen = state('_littlegreen_v61_landing_main_seen', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_toe_seen = state('_littlegreen_v61_landing_toe_seen', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_timer = state('_littlegreen_v61_landing_timer_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    reward_hold = state('_littlegreen_v61_reward_hold_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    reward_value = state('_littlegreen_v61_reward_value', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    failure_hold = state('_littlegreen_v61_failure_hold_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    failure_value = state('_littlegreen_v61_failure_value', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_sequence_foot = state('_littlegreen_v61_last_sequence_foot', (n,), torch.long, torch.full((n,), -1, device=device, dtype=torch.long))

    takeover_active = state('_littlegreen_v61_takeover_active', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    takeover_timer = state('_littlegreen_v61_takeover_timer_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    takeover_initial_dist = state('_littlegreen_v61_takeover_initial_com_dist_m', any_contact.shape, dtype, com_to_foot_lat.clone())

    last_progress = state('_littlegreen_v61_last_progress_m', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_velocity_ratio = state('_littlegreen_v61_last_velocity_ratio', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_coherence = state('_littlegreen_v61_last_coherence', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_multiplier = state('_littlegreen_v61_last_sequence_multiplier', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))

    common_step = int(getattr(env, 'common_step_counter', 0))
    last_step = int(getattr(env, '_littlegreen_v61_last_common_step', -1))
    if common_step != last_step:
        dt = float(getattr(env, 'step_dt', 0.02))
        reset_mask = _v10_episode_reset_mask(env, n, device)
        episode_length = getattr(env, 'episode_length_buf', None)
        last_episode_length = getattr(env, '_littlegreen_v61_last_episode_length', None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == n:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == n:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v61_last_episode_length = current_episode_length.clone()
        reset2 = reset_mask.unsqueeze(-1)

        reward_hold = torch.clamp(reward_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        reward_value = torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        active = torch.where(reset2, torch.zeros_like(active), active)
        qualified = torch.where(reset2, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(reset2, torch.zeros_like(landing_started), landing_started)
        landing_main_seen = torch.where(reset2, torch.zeros_like(landing_main_seen), landing_main_seen)
        landing_toe_seen = torch.where(reset2, torch.zeros_like(landing_toe_seen), landing_toe_seen)
        landing_timer = torch.where(reset2, torch.zeros_like(landing_timer), landing_timer)
        takeover_active = torch.where(reset2, torch.zeros_like(takeover_active), takeover_active)
        takeover_timer = torch.where(reset2, torch.zeros_like(takeover_timer), takeover_timer)
        last_sequence_foot = torch.where(reset_mask, torch.full_like(last_sequence_foot, -1), last_sequence_foot)
        prev_any = torch.where(reset2, any_contact, prev_any)
        prev_center = torch.where(reset2.unsqueeze(-1), center_xy, prev_center)

        # Healthy-learning liftoff: a previously contacting foot may initiate a step.
        # It still has to become a genuine *whole-foot* airborne swing to qualify.
        liftoff = prev_any & (~any_contact) & (~active) & moving.unsqueeze(-1) & (~reset2)
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_center, liftoff_xy)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), command_dir_w[:, None, :].expand(-1, 2, -1), liftoff_dir)
        liftoff_cmd_speed = torch.where(liftoff, command_norm.unsqueeze(-1).expand(-1, 2), liftoff_cmd_speed)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(liftoff, torch.zeros_like(landing_started), landing_started)
        landing_main_seen = torch.where(liftoff, torch.zeros_like(landing_main_seen), landing_main_seen)
        landing_toe_seen = torch.where(liftoff, torch.zeros_like(landing_toe_seen), landing_toe_seen)
        landing_timer = torch.where(liftoff, torch.zeros_like(landing_timer), landing_timer)

        airborne = active & (~any_contact) & moving.unsqueeze(-1) & (~reset2)
        last_air_quality = torch.where(airborne, coherence, last_air_quality)
        qualifies_now = (
            airborne
            & (whole_air >= float(min_air_time_s))
            & (main_clear >= float(min_main_clearance_m))
            & (toe_clear >= float(min_toe_clearance_m))
        )
        qualified = qualified | qualifies_now

        first_landing_contact = active & qualified & any_contact & (~landing_started) & moving.unsqueeze(-1) & (~reset2)
        landing_started = landing_started | first_landing_contact
        landing_timer = torch.where(first_landing_contact, torch.zeros_like(landing_timer), landing_timer)
        landing_timer = torch.where(active & landing_started, landing_timer + dt, landing_timer)
        landing_main_seen = landing_main_seen | (active & landing_started & main_contact)
        landing_toe_seen = landing_toe_seen | (active & landing_started & toe_contact)

        completion = (
            active & qualified & landing_started & landing_main_seen & landing_toe_seen
            & any_contact & (landing_timer <= float(landing_window_s))
            & moving.unsqueeze(-1) & (~reset2)
        )

        progress = torch.sum((center_xy - liftoff_xy) * liftoff_dir, dim=-1)
        progress_score = torch.clamp(progress / float(full_progress_m), min=0.0, max=1.0)
        base_vel_w = asset.data.root_lin_vel_w[:, :2]
        projected_speed = torch.sum(base_vel_w[:, None, :] * liftoff_dir, dim=-1)
        velocity_ratio = torch.clamp(
            projected_speed / torch.clamp(liftoff_cmd_speed, min=1.0e-3), min=0.0, max=1.0
        )
        velocity_factor = float(velocity_bootstrap_fraction) + (1.0 - float(velocity_bootstrap_fraction)) * velocity_ratio
        raw_step_quality = progress_score * last_air_quality * velocity_factor

        foot_ids = torch.arange(2, device=device, dtype=torch.long).view(1, 2).expand(n, -1)
        has_previous = last_sequence_foot >= 0
        same = has_previous.unsqueeze(-1) & (foot_ids == last_sequence_foot.unsqueeze(-1))
        opposite = has_previous.unsqueeze(-1) & (~same)
        multiplier = torch.where(
            same, torch.full_like(raw_step_quality, float(repeat_same_foot_multiplier)),
            torch.where(
                opposite, torch.full_like(raw_step_quality, float(opposite_step_multiplier)),
                torch.full_like(raw_step_quality, float(first_step_multiplier)),
            ),
        )
        positive_value = raw_step_quality * multiplier
        negative_value = torch.clamp((-progress) / float(full_progress_m), min=0.0, max=1.0)

        hold = max(float(event_hold_s), dt)
        reward_hold = torch.where(completion, torch.full_like(reward_hold, hold), reward_hold)
        failure_hold = torch.where(completion, torch.full_like(failure_hold, hold), failure_hold)
        reward_value = torch.where(completion, positive_value, reward_value)
        failure_value = torch.where(completion, negative_value, failure_value)
        last_progress = torch.where(completion, progress, last_progress)
        last_velocity_ratio = torch.where(completion, velocity_ratio, last_velocity_ratio)
        last_coherence = torch.where(completion, last_air_quality, last_coherence)
        last_multiplier = torch.where(completion, multiplier, last_multiplier)

        meaningful = completion & (progress >= float(min_sequence_progress_m)) & (last_air_quality > 0.0)
        one_meaningful = torch.sum(meaningful.to(torch.int32), dim=1) == 1
        meaningful_foot = torch.argmax(meaningful.to(torch.long), dim=1)
        last_sequence_foot = torch.where(one_meaningful, meaningful_foot, last_sequence_foot)

        # Start a single post-landing takeover bridge on the newly landed foot.
        new_takeover = meaningful & one_meaningful.unsqueeze(-1)
        any_new_takeover = torch.any(new_takeover, dim=1)
        takeover_active = torch.where(any_new_takeover.unsqueeze(-1), new_takeover, takeover_active)
        takeover_timer = torch.where(any_new_takeover.unsqueeze(-1), torch.zeros_like(takeover_timer), takeover_timer)
        takeover_initial_dist = torch.where(new_takeover, com_to_foot_lat, takeover_initial_dist)

        landing_timeout = active & landing_started & (landing_timer > float(landing_window_s))
        unqualified_return = active & any_contact & (~qualified)
        finish = completion | landing_timeout | unqualified_return
        active = torch.where(finish, torch.zeros_like(active), active)
        qualified = torch.where(finish, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(finish, torch.zeros_like(landing_started), landing_started)
        landing_main_seen = torch.where(finish, torch.zeros_like(landing_main_seen), landing_main_seen)
        landing_toe_seen = torch.where(finish, torch.zeros_like(landing_toe_seen), landing_toe_seen)
        landing_timer = torch.where(finish, torch.zeros_like(landing_timer), landing_timer)

        active = active & moving.unsqueeze(-1)
        qualified = qualified & active
        landing_started = landing_started & active

        # Takeover timer advances independently after a completed step.  Losing all
        # contact on that foot simply removes takeover reward; it does not invalidate
        # future stepping or prescribe when the next liftoff must occur.
        takeover_timer = torch.where(takeover_active, takeover_timer + dt, takeover_timer)
        takeover_active = takeover_active & (takeover_timer <= float(takeover_window_s)) & moving.unsqueeze(-1)

        prev_any = any_contact.clone()
        prev_center = center_xy.clone()
        env._littlegreen_v61_prev_any_contact = prev_any
        env._littlegreen_v61_prev_center_xy = prev_center
        env._littlegreen_v61_active = active
        env._littlegreen_v61_qualified = qualified
        env._littlegreen_v61_liftoff_xy = liftoff_xy
        env._littlegreen_v61_liftoff_dir = liftoff_dir
        env._littlegreen_v61_liftoff_cmd_speed = liftoff_cmd_speed
        env._littlegreen_v61_last_air_quality = last_air_quality
        env._littlegreen_v61_landing_started = landing_started
        env._littlegreen_v61_landing_main_seen = landing_main_seen
        env._littlegreen_v61_landing_toe_seen = landing_toe_seen
        env._littlegreen_v61_landing_timer_s = landing_timer
        env._littlegreen_v61_reward_hold_s = reward_hold
        env._littlegreen_v61_reward_value = reward_value
        env._littlegreen_v61_failure_hold_s = failure_hold
        env._littlegreen_v61_failure_value = failure_value
        env._littlegreen_v61_last_sequence_foot = last_sequence_foot
        env._littlegreen_v61_takeover_active = takeover_active
        env._littlegreen_v61_takeover_timer_s = takeover_timer
        env._littlegreen_v61_takeover_initial_com_dist_m = takeover_initial_dist
        env._littlegreen_v61_last_progress_m = last_progress
        env._littlegreen_v61_last_velocity_ratio = last_velocity_ratio
        env._littlegreen_v61_last_coherence = last_coherence
        env._littlegreen_v61_last_sequence_multiplier = last_multiplier
        env._littlegreen_v61_last_common_step = common_step

    load_score = torch.clamp(
        (load_share - float(takeover_load_start)) /
        max(float(takeover_load_full) - float(takeover_load_start), 1.0e-6),
        min=0.0, max=1.0,
    )
    com_improvement = torch.clamp(
        (takeover_initial_dist - com_to_foot_lat) / float(takeover_com_improvement_full_m),
        min=0.0, max=1.0,
    )
    takeover_score_per_foot = (0.70 * load_score + 0.30 * com_improvement) * takeover_active.float() * any_contact.float()
    takeover_score = torch.sum(takeover_score_per_foot, dim=1) * moving.float()

    return {
        'success': torch.sum(torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value)), dim=1) * moving.float(),
        'failure': torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float(),
        'support_takeover': takeover_score,
        'last_progress_m': last_progress,
        'last_velocity_ratio': last_velocity_ratio,
        'last_coherence': last_coherence,
        'last_sequence_multiplier': last_multiplier,
        'last_sequence_foot': last_sequence_foot,
        'takeover_load_share': load_share,
        'takeover_com_distance_m': com_to_foot_lat,
    }


def alternating_directional_landing_sequence_reward_v61(
    env: ManagerBasedRLEnv, command_name: str, asset_cfg: SceneEntityCfg, sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010, min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035, min_sequence_progress_m: float = 0.008,
    first_step_multiplier: float = 1.00, opposite_step_multiplier: float = 2.00,
    repeat_same_foot_multiplier: float = 0.10, velocity_bootstrap_fraction: float = 0.35,
    coherence_full_diff_m: float = 0.020, coherence_zero_diff_m: float = 0.060,
    landing_window_s: float = 0.30, event_hold_s: float = 0.08,
    takeover_window_s: float = 0.45, takeover_load_start: float = 0.30,
    takeover_load_full: float = 0.55, takeover_com_improvement_full_m: float = 0.050,
    bodies_per_foot: int = 2,
) -> torch.Tensor:
    return _directional_step_and_takeover_state_v61(
        env, command_name, asset_cfg, sensor_cfg, command_threshold, min_air_time_s,
        min_main_clearance_m, min_toe_clearance_m, full_progress_m, min_sequence_progress_m,
        first_step_multiplier, opposite_step_multiplier, repeat_same_foot_multiplier,
        velocity_bootstrap_fraction, coherence_full_diff_m, coherence_zero_diff_m,
        landing_window_s, event_hold_s, takeover_window_s, takeover_load_start,
        takeover_load_full, takeover_com_improvement_full_m, bodies_per_foot,
    )['success']


