# -----------------------------------------------------------------------------
# LittleGreen v6.3 acquisition-economy locomotion bridge
# -----------------------------------------------------------------------------
def locomotion_viability_factor_v63(
    env: ManagerBasedRLEnv,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Broad soft factor that fades locomotion reward only when clearly falling.

    This is deliberately *not* a gait posture target.  Normal crouch, support shifts,
    recovery lean, and dynamic gait motion keep full or near-full value.  The factor is
    approximately one while the base tilt is <= ``full_tilt_deg`` and COM height is
    >= ``full_height_m``; it smoothly fades to zero by ``zero_tilt_deg`` or
    ``zero_height_m``.  It is used to make falling reward-neutral, not to punish falls.
    """
    if not (0.0 <= float(full_tilt_deg) < float(zero_tilt_deg) < 90.0):
        raise ValueError("v6.3 viability tilt thresholds must satisfy 0 <= full < zero < 90")
    if not float(zero_height_m) < float(full_height_m):
        raise ValueError("v6.3 viability height thresholds must satisfy zero < full")
    asset = env.scene[asset_cfg.name]
    upright_cos = torch.clamp(-asset.data.projected_gravity_b[:, 2], min=-1.0, max=1.0)
    cos_full = math.cos(math.radians(float(full_tilt_deg)))
    cos_zero = math.cos(math.radians(float(zero_tilt_deg)))
    orient_t = torch.clamp((upright_cos - cos_zero) / max(cos_full - cos_zero, 1.0e-6), 0.0, 1.0)
    orient = orient_t * orient_t * (3.0 - 2.0 * orient_t)

    height = asset.data.root_com_pos_w[:, 2]
    height_t = torch.clamp(
        (height - float(zero_height_m)) / max(float(full_height_m) - float(zero_height_m), 1.0e-6),
        0.0,
        1.0,
    )
    height_factor = height_t * height_t * (3.0 - 2.0 * height_t)
    return orient * height_factor


def base_com_height_deficit_v63(
    env: ManagerBasedRLEnv,
    full_penalty_height_m: float = 0.405,
    zero_penalty_height_m: float = 0.445,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """One-sided anti-collapse deficit used only as a penalty.

    At or above ``zero_penalty_height_m`` the returned deficit is zero, so the
    policy cannot earn positive income merely by standing tall.  Below
    ``full_penalty_height_m`` the deficit is one.
    """
    if not float(full_penalty_height_m) < float(zero_penalty_height_m):
        raise ValueError("v6.3 height deficit requires full_penalty_height_m < zero_penalty_height_m")
    asset = env.scene[asset_cfg.name]
    t = torch.clamp(
        (asset.data.root_com_pos_w[:, 2] - float(full_penalty_height_m)) /
        max(float(zero_penalty_height_m) - float(full_penalty_height_m), 1.0e-6),
        0.0,
        1.0,
    )
    satisfied = t * t * (3.0 - 2.0 * t)
    return 1.0 - satisfied


def track_lin_vel_xy_acquisition_v63(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float = 0.50,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Non-negative stationary-baseline planar acquisition tracking, fall-neutral."""
    if std <= 0.0:
        raise ValueError("v6.3 velocity std must be positive")
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, :2]
    vel_yaw = quat_apply_inverse(yaw_quat(asset.data.root_quat_w), asset.data.root_lin_vel_w[:, :3])[:, :2]
    error_now = torch.sum(torch.square(command - vel_yaw), dim=1)
    command_sq = torch.sum(torch.square(command), dim=1)
    score_now = torch.exp(-error_now / float(std) ** 2)
    score_still = torch.exp(-command_sq / float(std) ** 2)
    headroom = torch.clamp(1.0 - score_still, min=1.0e-6)
    normalized = torch.clamp((score_now - score_still) / headroom, min=0.0, max=1.0)
    moving = torch.linalg.vector_norm(command, dim=1) > float(command_threshold)
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, asset_cfg
    )
    # Falling is reward-neutral for movement: neither forward-fall velocity nor a
    # wrong-direction fall is treated as locomotion performance.
    return torch.where(moving, normalized * viability, torch.zeros_like(score_now))


def track_ang_vel_z_acquisition_v63(
    env: ManagerBasedRLEnv,
    command_name: str,
    std: float = 0.50,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    asset_cfg: SceneEntityCfg = SceneEntityCfg("robot"),
) -> torch.Tensor:
    """Non-negative stationary-baseline yaw acquisition tracking, fall-neutral."""
    if std <= 0.0:
        raise ValueError("v6.3 yaw std must be positive")
    asset = env.scene[asset_cfg.name]
    command = env.command_manager.get_command(command_name)[:, 2]
    actual = asset.data.root_ang_vel_w[:, 2]
    score_now = torch.exp(-torch.square(command - actual) / float(std) ** 2)
    score_still = torch.exp(-torch.square(command) / float(std) ** 2)
    headroom = torch.clamp(1.0 - score_still, min=1.0e-6)
    normalized = torch.clamp((score_now - score_still) / headroom, min=0.0, max=1.0)
    moving = torch.abs(command) > float(command_threshold)
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, asset_cfg
    )
    return torch.where(moving, normalized * viability, torch.zeros_like(score_now))


def whole_foot_air_time_viability_gated_v63(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    threshold: float = 0.20,
    full_clearance_m: float = 0.018,
    command_threshold: float = 0.08,
    full_credit_until_s: float = 0.32,
    fade_out_end_s: float = 0.55,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """v4.2-style exploratory whole-foot air time that stops paying during falls."""
    raw = whole_foot_smooth_clearance_air_time_positive_biped_v42(
        env=env,
        command_name=command_name,
        sensor_cfg=sensor_cfg,
        asset_cfg=asset_cfg,
        threshold=threshold,
        full_clearance_m=full_clearance_m,
        command_threshold=command_threshold,
        full_credit_until_s=full_credit_until_s,
        fade_out_end_s=fade_out_end_s,
        bodies_per_foot=bodies_per_foot,
    )
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )
    return raw * viability


def _directional_confirmed_step_state_v63(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_air_time_s: float = 0.09,
    min_main_clearance_m: float = 0.010,
    min_toe_clearance_m: float = 0.010,
    full_progress_m: float = 0.035,
    min_sequence_progress_m: float = 0.008,
    first_step_multiplier: float = 1.00,
    opposite_step_multiplier: float = 2.00,
    repeat_same_foot_multiplier: float = 0.10,
    velocity_bootstrap_fraction: float = 0.35,
    coherence_full_diff_m: float = 0.020,
    coherence_zero_diff_m: float = 0.060,
    landing_window_s: float = 0.30,
    immediate_credit_fraction: float = 0.30,
    confirmation_duration_s: float = 0.16,
    confirmation_min_viability: float = 0.55,
    min_swing_viability: float = 0.45,
    event_hold_s: float = 0.06,
    takeover_window_s: float = 0.45,
    takeover_load_start: float = 0.30,
    takeover_load_full: float = 0.55,
    takeover_com_improvement_full_m: float = 0.050,
    handoff_load_threshold: float = 0.47,
    handoff_min_viability: float = 0.60,
    handoff_event_hold_s: float = 0.08,
    opposite_release_window_s: float = 0.45,
    opposite_release_min_viability: float = 0.45,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Whole-foot directional step with fall-neutral confirmation and support takeover.

    A landing gets only a small immediate credit.  The large remainder and sequence
    state are released only after the landed foot retains contact for a short period
    while the base remains inside a broad viability envelope.  This makes a genuine
    exploratory step useful, but prevents a terminal forward fall from masquerading as
    command tracking, a completed gait step, or support takeover.
    """
    if min_air_time_s < 0.0 or min_main_clearance_m < 0.0 or min_toe_clearance_m < 0.0:
        raise ValueError("v6.3 swing thresholds must be non-negative")
    if full_progress_m <= 0.0 or min_sequence_progress_m < 0.0:
        raise ValueError("v6.3 progress thresholds invalid")
    if not (0.0 <= repeat_same_foot_multiplier <= first_step_multiplier <= opposite_step_multiplier):
        raise ValueError("v6.3 step multipliers must satisfy repeat <= first <= opposite")
    if not 0.0 <= velocity_bootstrap_fraction <= 1.0:
        raise ValueError("v6.3 velocity bootstrap must be in [0,1]")
    if not 0.0 <= immediate_credit_fraction <= 1.0:
        raise ValueError("v6.3 immediate step fraction must be in [0,1]")
    if confirmation_duration_s <= 0.0 or landing_window_s <= 0.0 or takeover_window_s <= 0.0:
        raise ValueError("v6.3 timing windows must be positive")
    if not 0.0 <= confirmation_min_viability <= 1.0 or not 0.0 <= min_swing_viability <= 1.0:
        raise ValueError("v6.3 viability thresholds must be in [0,1]")
    if not 0.0 <= coherence_full_diff_m < coherence_zero_diff_m:
        raise ValueError("v6.3 coherence thresholds invalid")
    if not 0.0 <= takeover_load_start < takeover_load_full <= 1.0:
        raise ValueError("v6.3 support load thresholds invalid")
    if not 0.0 < handoff_load_threshold <= 1.0:
        raise ValueError("v6.3 handoff load threshold must be in (0,1]")
    if not 0.0 <= handoff_min_viability <= 1.0 or not 0.0 <= opposite_release_min_viability <= 1.0:
        raise ValueError("v6.3 handoff/release viability thresholds must be in [0,1]")
    if handoff_event_hold_s <= 0.0 or opposite_release_window_s <= 0.0:
        raise ValueError("v6.3 handoff/release timing must be positive")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    if int(bodies_per_foot) != 2 or contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.3 expects ordered L_main,L_toe,R_main,R_toe contact bodies")
    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != 4:
        raise ValueError("v6.3 expects ordered L_main,L_toe,R_main,R_toe robot bodies")

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact
    whole_air = torch.stack((torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1)

    z = body_pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    clearance_diff = torch.abs(main_clear - toe_clear)
    coherence_span = max(float(coherence_zero_diff_m) - float(coherence_full_diff_m), 1.0e-6)
    coherence = torch.clamp((float(coherence_zero_diff_m) - clearance_diff) / coherence_span, 0.0, 1.0)

    centers = torch.stack((0.5 * (body_pos[:, 0, :] + body_pos[:, 1, :]), 0.5 * (body_pos[:, 2, :] + body_pos[:, 3, :])), dim=1)
    center_xy = centers[:, :, :2]
    midpoint = 0.5 * (centers[:, 0, :] + centers[:, 1, :])

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir_b = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    command_dir_3d = torch.cat((command_dir_b, torch.zeros_like(command_dir_b[:, :1])), dim=1)
    root_yaw = yaw_quat(asset.data.root_quat_w)
    command_dir_w = quat_apply(root_yaw, command_dir_3d)[:, :2]
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )

    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    load_share = foot_load / torch.clamp(torch.sum(foot_load, dim=1, keepdim=True), min=1.0e-6)
    com_rel = quat_apply_inverse(root_yaw, asset.data.root_com_pos_w - midpoint)
    left_rel = quat_apply_inverse(root_yaw, centers[:, 0, :] - midpoint)
    right_rel = quat_apply_inverse(root_yaw, centers[:, 1, :] - midpoint)
    foot_rel_y = torch.stack((left_rel[:, 1], right_rel[:, 1]), dim=1)
    com_to_foot_lat = torch.abs(com_rel[:, 1].unsqueeze(-1) - foot_rel_y)

    n = any_contact.shape[0]
    device = any_contact.device
    dtype = center_xy.dtype
    def state(name, shape, dtype_, default):
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape):
            value = default.to(device=device, dtype=dtype_)
        else:
            value = value.to(device=device, dtype=dtype_)
        return value

    prev_any = state('_littlegreen_v63_prev_any_contact', any_contact.shape, torch.bool, any_contact.clone())
    prev_center = state('_littlegreen_v63_prev_center_xy', center_xy.shape, dtype, center_xy.clone())
    active = state('_littlegreen_v63_active', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    qualified = state('_littlegreen_v63_qualified', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    swing_min_viability = state('_littlegreen_v63_swing_min_viability', any_contact.shape, dtype, viability.unsqueeze(-1).expand(-1, 2).clone())
    liftoff_xy = state('_littlegreen_v63_liftoff_xy', center_xy.shape, dtype, center_xy.clone())
    liftoff_dir = state('_littlegreen_v63_liftoff_dir', center_xy.shape, dtype, torch.zeros_like(center_xy))
    liftoff_cmd_speed = state('_littlegreen_v63_liftoff_cmd_speed', any_contact.shape, dtype, torch.ones_like(any_contact, dtype=dtype))
    last_air_quality = state('_littlegreen_v63_last_air_quality', any_contact.shape, dtype, torch.ones_like(any_contact, dtype=dtype))
    landing_started = state('_littlegreen_v63_landing_started', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_main_seen = state('_littlegreen_v63_landing_main_seen', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_toe_seen = state('_littlegreen_v63_landing_toe_seen', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    landing_timer = state('_littlegreen_v63_landing_timer_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))

    reward_hold = state('_littlegreen_v63_reward_hold_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    reward_value = state('_littlegreen_v63_reward_value', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    failure_hold = state('_littlegreen_v63_failure_hold_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    failure_value = state('_littlegreen_v63_failure_value', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_sequence_foot = state('_littlegreen_v63_last_sequence_foot', (n,), torch.long, torch.full((n,), -1, device=device, dtype=torch.long))

    confirm_active = state('_littlegreen_v63_confirm_active', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    confirm_timer = state('_littlegreen_v63_confirm_timer_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    confirm_value = state('_littlegreen_v63_confirm_value', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    confirm_min_viability = state('_littlegreen_v63_confirm_min_viability', any_contact.shape, dtype, torch.ones_like(any_contact, dtype=dtype))

    takeover_active = state('_littlegreen_v63_takeover_active', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    takeover_timer = state('_littlegreen_v63_takeover_timer_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    takeover_initial_dist = state('_littlegreen_v63_takeover_initial_com_dist_m', any_contact.shape, dtype, com_to_foot_lat.clone())
    handoff_done = state('_littlegreen_v63_handoff_done', any_contact.shape, torch.bool, torch.zeros_like(any_contact))
    handoff_hold = state('_littlegreen_v63_handoff_hold_s', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    release_watch_active = state('_littlegreen_v63_release_watch_active', (n,), torch.bool, torch.zeros((n,), device=device, dtype=torch.bool))
    release_watch_new_foot = state('_littlegreen_v63_release_watch_new_foot', (n,), torch.long, torch.full((n,), -1, device=device, dtype=torch.long))
    release_watch_timer = state('_littlegreen_v63_release_watch_timer_s', (n,), dtype, torch.zeros((n,), device=device, dtype=dtype))
    release_hold = state('_littlegreen_v63_release_hold_s', (n,), dtype, torch.zeros((n,), device=device, dtype=dtype))

    last_progress = state('_littlegreen_v63_last_progress_m', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_velocity_ratio = state('_littlegreen_v63_last_velocity_ratio', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_coherence = state('_littlegreen_v63_last_coherence', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))
    last_multiplier = state('_littlegreen_v63_last_sequence_multiplier', any_contact.shape, dtype, torch.zeros_like(any_contact, dtype=dtype))

    common_step = int(getattr(env, 'common_step_counter', 0))
    last_step = int(getattr(env, '_littlegreen_v63_last_common_step', -1))
    if common_step != last_step:
        dt = float(getattr(env, 'step_dt', 0.02))
        reset_mask = _v10_episode_reset_mask(env, n, device)
        episode_length = getattr(env, 'episode_length_buf', None)
        last_episode_length = getattr(env, '_littlegreen_v63_last_episode_length', None)
        if isinstance(episode_length, torch.Tensor) and episode_length.shape[0] == n:
            current_episode_length = episode_length.to(device=device)
            if isinstance(last_episode_length, torch.Tensor) and last_episode_length.shape[0] == n:
                reset_mask = reset_mask | (current_episode_length < last_episode_length.to(device=device))
            env._littlegreen_v63_last_episode_length = current_episode_length.clone()
        reset2 = reset_mask.unsqueeze(-1)

        reward_hold = torch.clamp(reward_hold - dt, min=0.0)
        failure_hold = torch.clamp(failure_hold - dt, min=0.0)
        handoff_hold = torch.clamp(handoff_hold - dt, min=0.0)
        release_hold = torch.clamp(release_hold - dt, min=0.0)
        reward_value = torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value))
        failure_value = torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value))

        # Reset all stateful events cleanly at episode boundaries.
        for_name_zero = [active, qualified, landing_started, landing_main_seen, landing_toe_seen,
                         confirm_active, takeover_active]
        active, qualified, landing_started, landing_main_seen, landing_toe_seen, confirm_active, takeover_active = [
            torch.where(reset2, torch.zeros_like(x), x) for x in for_name_zero
        ]
        landing_timer = torch.where(reset2, torch.zeros_like(landing_timer), landing_timer)
        confirm_timer = torch.where(reset2, torch.zeros_like(confirm_timer), confirm_timer)
        takeover_timer = torch.where(reset2, torch.zeros_like(takeover_timer), takeover_timer)
        handoff_done = torch.where(reset2, torch.zeros_like(handoff_done), handoff_done)
        handoff_hold = torch.where(reset2, torch.zeros_like(handoff_hold), handoff_hold)
        release_watch_active = torch.where(reset_mask, torch.zeros_like(release_watch_active), release_watch_active)
        release_watch_new_foot = torch.where(reset_mask, torch.full_like(release_watch_new_foot, -1), release_watch_new_foot)
        release_watch_timer = torch.where(reset_mask, torch.zeros_like(release_watch_timer), release_watch_timer)
        release_hold = torch.where(reset_mask, torch.zeros_like(release_hold), release_hold)
        last_sequence_foot = torch.where(reset_mask, torch.full_like(last_sequence_foot, -1), last_sequence_foot)
        prev_any = torch.where(reset2, any_contact, prev_any)
        prev_center = torch.where(reset2.unsqueeze(-1), center_xy, prev_center)

        viability2 = viability.unsqueeze(-1).expand(-1, 2)
        # Do not classify a foot that leaves during an already-developed fall as a
        # gait swing candidate.  Exploration air-time is handled separately and softly.
        liftoff = (
            prev_any & (~any_contact) & (~active) & moving.unsqueeze(-1) & (~reset2)
            & (viability2 >= float(min_swing_viability))
        )
        liftoff_xy = torch.where(liftoff.unsqueeze(-1), prev_center, liftoff_xy)
        liftoff_dir = torch.where(liftoff.unsqueeze(-1), command_dir_w[:, None, :].expand(-1, 2, -1), liftoff_dir)
        liftoff_cmd_speed = torch.where(liftoff, command_norm.unsqueeze(-1).expand(-1, 2), liftoff_cmd_speed)
        active = torch.where(liftoff, torch.ones_like(active), active)
        qualified = torch.where(liftoff, torch.zeros_like(qualified), qualified)
        swing_min_viability = torch.where(liftoff, viability2, swing_min_viability)
        landing_started = torch.where(liftoff, torch.zeros_like(landing_started), landing_started)
        landing_main_seen = torch.where(liftoff, torch.zeros_like(landing_main_seen), landing_main_seen)
        landing_toe_seen = torch.where(liftoff, torch.zeros_like(landing_toe_seen), landing_toe_seen)
        landing_timer = torch.where(liftoff, torch.zeros_like(landing_timer), landing_timer)

        airborne = active & (~any_contact) & moving.unsqueeze(-1) & (~reset2)
        swing_min_viability = torch.where(airborne, torch.minimum(swing_min_viability, viability2), swing_min_viability)
        last_air_quality = torch.where(airborne, coherence, last_air_quality)
        qualifies_now = (
            airborne
            & (whole_air >= float(min_air_time_s))
            & (main_clear >= float(min_main_clearance_m))
            & (toe_clear >= float(min_toe_clearance_m))
            & (swing_min_viability >= float(min_swing_viability))
        )
        qualified = qualified | qualifies_now

        first_landing_contact = active & qualified & any_contact & (~landing_started) & moving.unsqueeze(-1) & (~reset2)
        landing_started = landing_started | first_landing_contact
        landing_timer = torch.where(first_landing_contact, torch.zeros_like(landing_timer), landing_timer)
        landing_timer = torch.where(active & landing_started, landing_timer + dt, landing_timer)
        landing_main_seen = landing_main_seen | (active & landing_started & main_contact)
        landing_toe_seen = landing_toe_seen | (active & landing_started & toe_contact)
        completion = (
            active & qualified & landing_started & landing_main_seen & landing_toe_seen & any_contact
            & (landing_timer <= float(landing_window_s)) & moving.unsqueeze(-1) & (~reset2)
        )

        progress = torch.sum((center_xy - liftoff_xy) * liftoff_dir, dim=-1)
        progress_score = torch.clamp(progress / float(full_progress_m), 0.0, 1.0)
        projected_speed = torch.sum(asset.data.root_lin_vel_w[:, None, :2] * liftoff_dir, dim=-1)
        velocity_ratio = torch.clamp(projected_speed / torch.clamp(liftoff_cmd_speed, min=1.0e-3), 0.0, 1.0)
        velocity_factor = float(velocity_bootstrap_fraction) + (1.0 - float(velocity_bootstrap_fraction)) * velocity_ratio
        raw_step_quality = progress_score * last_air_quality * velocity_factor

        foot_ids = torch.arange(2, device=device, dtype=torch.long).view(1, 2).expand(n, -1)
        has_previous = last_sequence_foot >= 0
        same = has_previous.unsqueeze(-1) & (foot_ids == last_sequence_foot.unsqueeze(-1))
        opposite = has_previous.unsqueeze(-1) & (~same)
        multiplier = torch.where(
            same, torch.full_like(raw_step_quality, float(repeat_same_foot_multiplier)),
            torch.where(opposite, torch.full_like(raw_step_quality, float(opposite_step_multiplier)),
                        torch.full_like(raw_step_quality, float(first_step_multiplier))),
        )
        positive_value = raw_step_quality * multiplier
        negative_value = torch.clamp((-progress) / float(full_progress_m), 0.0, 1.0)
        hold = max(float(event_hold_s), dt)

        # Small immediate landing credit.  If the landing is already part of a fall,
        # viability smoothly removes it.
        immediate_value = positive_value * float(immediate_credit_fraction) * viability2
        reward_hold = torch.where(completion, torch.full_like(reward_hold, hold), reward_hold)
        reward_value = torch.where(completion, immediate_value, reward_value)
        failure_hold = torch.where(completion, torch.full_like(failure_hold, hold), failure_hold)
        failure_value = torch.where(completion, negative_value * viability2, failure_value)
        last_progress = torch.where(completion, progress, last_progress)
        last_velocity_ratio = torch.where(completion, velocity_ratio, last_velocity_ratio)
        last_coherence = torch.where(completion, last_air_quality, last_coherence)
        last_multiplier = torch.where(completion, multiplier, last_multiplier)

        meaningful_landing = completion & (progress >= float(min_sequence_progress_m)) & (last_air_quality > 0.0)
        # Confirmation begins only for a single-foot meaningful landing.  A hop may
        # receive tiny immediate exploration credit but cannot establish gait sequence.
        one_landing = torch.sum(meaningful_landing.to(torch.int32), dim=1) == 1
        new_confirm = meaningful_landing & one_landing.unsqueeze(-1)
        any_new_confirm = torch.any(new_confirm, dim=1)
        confirm_active = torch.where(any_new_confirm.unsqueeze(-1), new_confirm, confirm_active)
        confirm_timer = torch.where(any_new_confirm.unsqueeze(-1), torch.zeros_like(confirm_timer), confirm_timer)
        confirm_value = torch.where(new_confirm, positive_value, confirm_value)
        confirm_min_viability = torch.where(new_confirm, viability2, confirm_min_viability)

        # Finish the swing state at landing; confirmation is deliberately separate.
        landing_timeout = active & landing_started & (landing_timer > float(landing_window_s))
        unqualified_return = active & any_contact & (~qualified)
        finish = completion | landing_timeout | unqualified_return
        active = torch.where(finish, torch.zeros_like(active), active)
        qualified = torch.where(finish, torch.zeros_like(qualified), qualified)
        landing_started = torch.where(finish, torch.zeros_like(landing_started), landing_started)
        landing_main_seen = torch.where(finish, torch.zeros_like(landing_main_seen), landing_main_seen)
        landing_toe_seen = torch.where(finish, torch.zeros_like(landing_toe_seen), landing_toe_seen)
        landing_timer = torch.where(finish, torch.zeros_like(landing_timer), landing_timer)
        active = active & moving.unsqueeze(-1)
        qualified = qualified & active
        landing_started = landing_started & active

        # Post-landing confirmation: retain contact and a viable body state for a short
        # interval before releasing the large reward remainder and sequence identity.
        confirm_timer = torch.where(confirm_active, confirm_timer + dt, confirm_timer)
        confirm_min_viability = torch.where(confirm_active, torch.minimum(confirm_min_viability, viability2), confirm_min_viability)
        lost_confirm_contact = confirm_active & (~any_contact)
        reached_confirm_time = confirm_active & (confirm_timer >= float(confirmation_duration_s))
        viable_confirm = confirm_min_viability >= float(confirmation_min_viability)
        confirmed_candidate = reached_confirm_time & any_contact & viable_confirm & moving.unsqueeze(-1) & (~reset2)
        one_confirmed = torch.sum(confirmed_candidate.to(torch.int32), dim=1) == 1
        confirmed = confirmed_candidate & one_confirmed.unsqueeze(-1)

        remainder = confirm_value * (1.0 - float(immediate_credit_fraction)) * confirm_min_viability
        reward_hold = torch.where(confirmed, torch.full_like(reward_hold, hold), reward_hold)
        reward_value = torch.where(confirmed, remainder, reward_value)
        confirmed_foot = torch.argmax(confirmed.to(torch.long), dim=1)
        last_sequence_foot = torch.where(one_confirmed, confirmed_foot, last_sequence_foot)

        # Support takeover starts after a first or opposite confirmed step.  A repeated
        # same-foot completion keeps only its 0.1x step value and cannot farm the
        # handoff/release bridge.
        bridge_eligible = confirmed & (last_multiplier > float(repeat_same_foot_multiplier) + 1.0e-6)
        takeover_active = torch.where(one_confirmed.unsqueeze(-1), bridge_eligible, takeover_active)
        takeover_timer = torch.where(one_confirmed.unsqueeze(-1), torch.zeros_like(takeover_timer), takeover_timer)
        takeover_initial_dist = torch.where(bridge_eligible, com_to_foot_lat, takeover_initial_dist)
        handoff_done = torch.where(one_confirmed.unsqueeze(-1), torch.zeros_like(handoff_done), handoff_done)
        release_watch_active = torch.where(one_confirmed, torch.zeros_like(release_watch_active), release_watch_active)
        release_watch_new_foot = torch.where(one_confirmed, torch.full_like(release_watch_new_foot, -1), release_watch_new_foot)
        release_watch_timer = torch.where(one_confirmed, torch.zeros_like(release_watch_timer), release_watch_timer)

        confirm_done = reached_confirm_time | lost_confirm_contact | (~moving.unsqueeze(-1)) | reset2
        confirm_active = torch.where(confirm_done, torch.zeros_like(confirm_active), confirm_active)
        confirm_timer = torch.where(confirm_done, torch.zeros_like(confirm_timer), confirm_timer)

        takeover_timer = torch.where(takeover_active, takeover_timer + dt, takeover_timer)
        takeover_active = takeover_active & (takeover_timer <= float(takeover_window_s)) & moving.unsqueeze(-1) & (~reset2)

        # One-shot mechanical support handoff: the newly landed foot must actually
        # take nearly half the vertical load while the body remains viable.
        handoff_candidate = (
            takeover_active & (~handoff_done) & any_contact
            & (load_share >= float(handoff_load_threshold))
            & (viability2 >= float(handoff_min_viability))
        )
        one_handoff = torch.sum(handoff_candidate.to(torch.int32), dim=1) == 1
        handoff_event = handoff_candidate & one_handoff.unsqueeze(-1)
        handoff_done = handoff_done | handoff_event
        handoff_hold = torch.where(handoff_event, torch.full_like(handoff_hold, max(float(handoff_event_hold_s), dt)), handoff_hold)
        handoff_new_foot = torch.argmax(handoff_event.to(torch.long), dim=1)
        release_watch_active = torch.where(one_handoff, torch.ones_like(release_watch_active), release_watch_active)
        release_watch_new_foot = torch.where(one_handoff, handoff_new_foot, release_watch_new_foot)
        release_watch_timer = torch.where(one_handoff, torch.zeros_like(release_watch_timer), release_watch_timer)

        # After support handoff, reward the old support foot for genuinely leaving
        # the floor.  This is the early bridge to the opposite completed step.
        release_watch_timer = torch.where(release_watch_active, release_watch_timer + dt, release_watch_timer)
        valid_watch = (
            release_watch_active & (release_watch_timer <= float(opposite_release_window_s))
            & moving & (~reset_mask) & (viability >= float(opposite_release_min_viability))
            & (release_watch_new_foot >= 0)
        )
        env_ids = torch.arange(n, device=device)
        new_idx = torch.clamp(release_watch_new_foot, 0, 1)
        old_idx = 1 - new_idx
        new_contact = any_contact[env_ids, new_idx]
        old_released = ~any_contact[env_ids, old_idx]
        opposite_release_event = valid_watch & new_contact & old_released
        release_hold = torch.where(opposite_release_event, torch.full_like(release_hold, max(float(handoff_event_hold_s), dt)), release_hold)
        release_watch_active = release_watch_active & (~opposite_release_event) & (release_watch_timer <= float(opposite_release_window_s))

        prev_any = any_contact.clone()
        prev_center = center_xy.clone()
        env._littlegreen_v63_prev_any_contact = prev_any
        env._littlegreen_v63_prev_center_xy = prev_center
        env._littlegreen_v63_active = active
        env._littlegreen_v63_qualified = qualified
        env._littlegreen_v63_swing_min_viability = swing_min_viability
        env._littlegreen_v63_liftoff_xy = liftoff_xy
        env._littlegreen_v63_liftoff_dir = liftoff_dir
        env._littlegreen_v63_liftoff_cmd_speed = liftoff_cmd_speed
        env._littlegreen_v63_last_air_quality = last_air_quality
        env._littlegreen_v63_landing_started = landing_started
        env._littlegreen_v63_landing_main_seen = landing_main_seen
        env._littlegreen_v63_landing_toe_seen = landing_toe_seen
        env._littlegreen_v63_landing_timer_s = landing_timer
        env._littlegreen_v63_reward_hold_s = reward_hold
        env._littlegreen_v63_reward_value = reward_value
        env._littlegreen_v63_failure_hold_s = failure_hold
        env._littlegreen_v63_failure_value = failure_value
        env._littlegreen_v63_last_sequence_foot = last_sequence_foot
        env._littlegreen_v63_confirm_active = confirm_active
        env._littlegreen_v63_confirm_timer_s = confirm_timer
        env._littlegreen_v63_confirm_value = confirm_value
        env._littlegreen_v63_confirm_min_viability = confirm_min_viability
        env._littlegreen_v63_takeover_active = takeover_active
        env._littlegreen_v63_takeover_timer_s = takeover_timer
        env._littlegreen_v63_takeover_initial_com_dist_m = takeover_initial_dist
        env._littlegreen_v63_handoff_done = handoff_done
        env._littlegreen_v63_handoff_hold_s = handoff_hold
        env._littlegreen_v63_release_watch_active = release_watch_active
        env._littlegreen_v63_release_watch_new_foot = release_watch_new_foot
        env._littlegreen_v63_release_watch_timer_s = release_watch_timer
        env._littlegreen_v63_release_hold_s = release_hold
        env._littlegreen_v63_last_progress_m = last_progress
        env._littlegreen_v63_last_velocity_ratio = last_velocity_ratio
        env._littlegreen_v63_last_coherence = last_coherence
        env._littlegreen_v63_last_sequence_multiplier = last_multiplier
        # v7.6/v7.7 instrumentation only: expose the already-computed, fall-neutral
        # confirmed-step, mechanical handoff, and committed old-support-release
        # pulses.  These do not modify any legacy v6.3 reward output; later
        # translation terms can therefore use exactly the same physical step chain
        # without duplicating the detector.
        env._littlegreen_v63_confirmed_event = confirmed.detach()
        env._littlegreen_v63_handoff_event = handoff_event.detach()
        env._littlegreen_v63_opposite_release_event = opposite_release_event.detach()
        env._littlegreen_v63_opposite_release_new_foot = torch.where(
            opposite_release_event, new_idx, torch.full_like(new_idx, -1)
        ).detach()
        env._littlegreen_v63_last_common_step = common_step

    load_score = torch.clamp((load_share - float(takeover_load_start)) / max(float(takeover_load_full) - float(takeover_load_start), 1.0e-6), 0.0, 1.0)
    com_improvement = torch.clamp((takeover_initial_dist - com_to_foot_lat) / float(takeover_com_improvement_full_m), 0.0, 1.0)
    takeover_per_foot = (0.70 * load_score + 0.30 * com_improvement) * takeover_active.float() * any_contact.float()
    takeover_score = torch.sum(takeover_per_foot, dim=1) * moving.float() * viability
    handoff_score = torch.sum((handoff_hold > 0.0).float(), dim=1) * moving.float() * viability
    opposite_release_score = (release_hold > 0.0).float() * moving.float() * viability

    # Current viability also gates short held events.  If an initially reasonable
    # landing immediately turns into a fall, no additional held reward leaks through.
    success = torch.sum(torch.where(reward_hold > 0.0, reward_value, torch.zeros_like(reward_value)), dim=1) * moving.float() * viability
    failure = torch.sum(torch.where(failure_hold > 0.0, failure_value, torch.zeros_like(failure_value)), dim=1) * moving.float() * viability
    return {
        'success': success,
        'failure': failure,
        'support_takeover': takeover_score,
        'support_handoff_event': handoff_score,
        'opposite_release_event': opposite_release_score,
        'viability': viability,
        'last_progress_m': last_progress,
        'last_velocity_ratio': last_velocity_ratio,
        'last_coherence': last_coherence,
        'last_sequence_multiplier': last_multiplier,
        'last_sequence_foot': last_sequence_foot,
        'takeover_load_share': load_share,
        'takeover_com_distance_m': com_to_foot_lat,
    }


