# -----------------------------------------------------------------------------
# LittleGreen v6.4 upstream whole-foot swing-initiation bridge
# -----------------------------------------------------------------------------
def whole_foot_swing_initiation_v64(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    unload_start_share: float = 0.48,
    unload_full_share: float = 0.15,
    support_start_share: float = 0.48,
    support_full_share: float = 0.68,
    full_whole_clearance_m: float = 0.015,
    full_relative_rise_speed_mps: float = 0.12,
    early_air_max_s: float = 0.12,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Reward the *start* of a coherent physical swing before full liftoff.

    v6.3's first large gait credit begins only after a physical whole-foot release.
    v6.4 deliberately moves a small, bounded bridge upstream.  For a non-zero planar
    command, either foot may become the swing candidate naturally.  It earns credit
    only when the opposite foot is accepting support and BOTH the main-foot body and
    passive toe are moving upward together relative to the opposite foot.

    The term is phase-free and stateless.  It does not select left/right, prescribe a
    hip or knee target, set cadence, or define a trajectory.  Heel-only lift is closed
    by using the minimum main/toe clearance and minimum relative vertical velocity.
    Credit is available while the candidate is still touching or during only the first
    ``early_air_max_s`` after whole-foot release, after which the existing v6.3 air-time
    and confirmed-step terms take over.
    """
    if not 0.0 <= float(unload_full_share) < float(unload_start_share) < 1.0:
        raise ValueError("v6.4 unload shares must satisfy 0 <= full < start < 1")
    if not 0.0 <= float(support_start_share) < float(support_full_share) <= 1.0:
        raise ValueError("v6.4 support shares must satisfy 0 <= start < full <= 1")
    if float(full_whole_clearance_m) <= 0.0 or float(full_relative_rise_speed_mps) <= 0.0:
        raise ValueError("v6.4 lift scales must be positive")
    if float(early_air_max_s) < 0.0:
        raise ValueError("v6.4 early-air window must be non-negative")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    if int(bodies_per_foot) != 2 or contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.4 expects ordered L_main,L_toe,R_main,R_toe contact bodies")

    asset = env.scene[asset_cfg.name]
    body_pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    body_vel = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :]
    if body_pos.shape[1] != 4 or body_vel.shape[1] != 4:
        raise ValueError("v6.4 expects ordered L_main,L_toe,R_main,R_toe robot bodies")

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact
    whole_air = torch.stack(
        (torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1
    )

    # Vertical load share determines which foot is naturally unloading.  No phase or
    # explicit leg identity is used.
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    load_share = foot_load / torch.clamp(torch.sum(foot_load, dim=1, keepdim=True), min=1.0e-6)
    opposite_share = torch.flip(load_share, dims=[1])

    unload_score = torch.clamp(
        (float(unload_start_share) - load_share)
        / max(float(unload_start_share) - float(unload_full_share), 1.0e-6),
        0.0,
        1.0,
    )
    support_score = torch.clamp(
        (opposite_share - float(support_start_share))
        / max(float(support_full_share) - float(support_start_share), 1.0e-6),
        0.0,
        1.0,
    )

    # Compare corresponding main/toe bodies between feet.  The minimum means both the
    # main foot and passive toe must rise; heel-up/toe-down rocking receives no useful
    # clearance signal.
    z = body_pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    whole_clear = torch.minimum(main_clear, toe_clear)
    clearance_score = torch.clamp(whole_clear / float(full_whole_clearance_m), 0.0, 1.0)

    # Relative upward speed supplies a gradient before meaningful clearance exists.
    # Subtracting the opposite foot's mean vertical speed avoids rewarding a whole-body
    # hop or fall as a swing initiation.
    vz = body_vel[:, :, 2]
    opposite_mean_vz = torch.stack((0.5 * (vz[:, 2] + vz[:, 3]), 0.5 * (vz[:, 0] + vz[:, 1])), dim=1)
    main_vz = torch.stack((vz[:, 0], vz[:, 2]), dim=1) - opposite_mean_vz
    toe_vz = torch.stack((vz[:, 1], vz[:, 3]), dim=1) - opposite_mean_vz
    coherent_rise_vz = torch.minimum(main_vz, toe_vz)
    rise_score = torch.clamp(coherent_rise_vz / float(full_relative_rise_speed_mps), 0.0, 1.0)

    # While any part of the foot is still touching, only *ongoing coherent upward
    # velocity* earns initiation credit.  Static tilted/partially-contacting poses cannot
    # farm clearance income indefinitely.  Once the whole foot releases, clearance
    # carries the bridge for only the short early-air window.
    lift_signal = torch.where(any_contact, 0.50 * rise_score, clearance_score)
    load_factor = 0.25 + 0.75 * unload_score

    command = env.command_manager.get_command(command_name)[:, :2]
    moving = torch.linalg.vector_norm(command, dim=1) > float(command_threshold)
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )

    pre_or_early_air = any_contact | (whole_air <= float(early_air_max_s))
    eligible = pre_or_early_air & (opposite_share >= float(support_start_share)) & moving.unsqueeze(-1)
    per_foot = lift_signal * load_factor * support_score * eligible.float() * viability.unsqueeze(-1)
    return torch.clamp(torch.sum(per_foot, dim=1), 0.0, 1.0)

# -----------------------------------------------------------------------------
# LittleGreen v6.5 finite swing / alternation acquisition bridge
# -----------------------------------------------------------------------------
def _v65_finite_swing_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    start_unload_share: float = 0.42,
    start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.015,
    clearance_milestones: tuple[float, float, float, float] = (0.002, 0.005, 0.010, 0.015),
    min_meaningful_clearance_m: float = 0.010,
    min_meaningful_air_time_s: float = 0.08,
    trajectory_start_clearance_m: float = 0.005,
    full_trajectory_progress_m: float = 0.035,
    completion_load_share: float = 0.30,
    completion_replant_s: float = 0.08,
    rearm_load_share: float = 0.40,
    rearm_hold_s: float = 0.12,
    first_swing_multiplier: float = 1.00,
    opposite_swing_multiplier: float = 1.35,
    repeat_same_foot_multiplier: float = 0.10,
    event_hold_s: float = 0.06,
    min_viability: float = 0.45,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Finite, command-gated swing state used by all v6.5 acquisition rewards.

    v6.4 proved that an upstream lift gradient is sufficient to discover true whole-
    foot clearance, but its dense state reward could be revisited by the same foot.
    v6.5 converts that bridge into one-shot progress milestones.  A foot is armed once,
    consumes its initiation credit as it unloads and clears 2/5/10/15 mm, and cannot
    begin another rewarded attempt until it has fully replanted and accepted support.

    The next opposite-foot attempt receives more credit; a repeated same-foot attempt
    receives only a small fraction.  No phase clock, left/right schedule, hip/knee
    target, cadence, COM trajectory, or fixed stride is introduced.
    """
    if int(bodies_per_foot) != 2:
        raise ValueError("v6.5 expects two contact/kinematic bodies per physical foot")
    if not 0.0 < float(start_unload_share) < float(start_support_share) < 1.0:
        raise ValueError("v6.5 start load shares must satisfy 0 < unload < support < 1")
    if not 0.0 < float(completion_load_share) <= float(rearm_load_share) < 1.0:
        raise ValueError("v6.5 completion/rearm load shares are invalid")
    if float(completion_replant_s) <= 0.0 or float(rearm_hold_s) <= 0.0:
        raise ValueError("v6.5 replant/rearm durations must be positive")
    if float(full_trajectory_progress_m) <= 0.0:
        raise ValueError("v6.5 trajectory progress scale must be positive")
    if not (0.0 <= float(repeat_same_foot_multiplier) <= float(first_swing_multiplier) <= float(opposite_swing_multiplier)):
        raise ValueError("v6.5 swing multipliers must satisfy repeat <= first <= opposite")
    milestones = tuple(float(x) for x in clearance_milestones)
    if len(milestones) != 4 or not (0.0 < milestones[0] < milestones[1] < milestones[2] < milestones[3]):
        raise ValueError("v6.5 clearance milestones must be four strictly increasing positive values")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    if contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.5 expects ordered L_main,L_toe,R_main,R_toe contact bodies")

    asset = env.scene[asset_cfg.name]
    pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    vel = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :]
    if pos.shape[1] != 4 or vel.shape[1] != 4:
        raise ValueError("v6.5 expects ordered L_main,L_toe,R_main,R_toe robot bodies")

    num_envs = pos.shape[0]
    device = pos.device
    dtype = pos.dtype
    dt = float(getattr(env, "step_dt", 0.02))

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact
    full_plant = main_contact & toe_contact
    whole_air = torch.stack((torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1)

    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    load_share = foot_load / torch.clamp(torch.sum(foot_load, dim=1, keepdim=True), min=1.0e-6)
    opposite_share = torch.flip(load_share, dims=[1])

    # Relative whole-foot lift is conservative: the passive toe must rise with the
    # main foot and the opposite foot is the vertical reference.
    z = pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    whole_clear = torch.minimum(main_clear, toe_clear)

    vz = vel[:, :, 2]
    opposite_mean_vz = torch.stack((0.5 * (vz[:, 2] + vz[:, 3]), 0.5 * (vz[:, 0] + vz[:, 1])), dim=1)
    main_vz = torch.stack((vz[:, 0], vz[:, 2]), dim=1) - opposite_mean_vz
    toe_vz = torch.stack((vz[:, 1], vz[:, 3]), dim=1) - opposite_mean_vz
    coherent_rise_vz = torch.minimum(main_vz, toe_vz)

    center_xy = torch.stack((0.5 * (pos[:, 0, :2] + pos[:, 1, :2]), 0.5 * (pos[:, 2, :2] + pos[:, 3, :2])), dim=1)
    command_xy = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )

    def _state(name: str, shape, default, tdtype=None):
        value = getattr(env, name, None)
        use_dtype = tdtype if tdtype is not None else dtype
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            if callable(default):
                value = default()
            else:
                value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    active = _state("_littlegreen_v65_active", (num_envs, 2), False, torch.bool)
    armed = _state("_littlegreen_v65_armed", (num_envs, 2), True, torch.bool)
    level = _state("_littlegreen_v65_milestone_level", (num_envs, 2), 0, torch.long)
    swing_multiplier = _state("_littlegreen_v65_swing_multiplier", (num_envs, 2), 1.0)
    liftoff_xy = _state("_littlegreen_v65_liftoff_xy", (num_envs, 2, 2), 0.0)
    liftoff_dir = _state("_littlegreen_v65_liftoff_dir", (num_envs, 2, 2), 0.0)
    best_progress = _state("_littlegreen_v65_best_progress", (num_envs, 2), 0.0)
    peak_clear = _state("_littlegreen_v65_peak_clearance", (num_envs, 2), 0.0)
    max_air = _state("_littlegreen_v65_max_air_time", (num_envs, 2), 0.0)
    replant_hold = _state("_littlegreen_v65_replant_hold", (num_envs, 2), 0.0)
    rearm_hold = _state("_littlegreen_v65_rearm_hold", (num_envs, 2), 0.0)
    last_attempt = _state("_littlegreen_v65_last_attempt_foot", (num_envs,), -1, torch.long)
    last_completed = _state("_littlegreen_v65_last_completed_foot", (num_envs,), -1, torch.long)
    initiation_hold = _state("_littlegreen_v65_initiation_hold", (num_envs,), 0.0)
    completion_hold = _state("_littlegreen_v65_completion_hold", (num_envs,), 0.0)
    alternation_hold = _state("_littlegreen_v65_alternation_hold", (num_envs,), 0.0)
    repeat_hold = _state("_littlegreen_v65_repeat_hold", (num_envs,), 0.0)
    initiation_value = _state("_littlegreen_v65_initiation_value", (num_envs,), 0.0)
    completion_value = _state("_littlegreen_v65_completion_value", (num_envs,), 0.0)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v65_last_common_step", -1))
    if common_step != last_step:
        start_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        completion_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        alternation_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
        repeat_event = torch.zeros(num_envs, device=device, dtype=torch.bool)
        reset = _v10_episode_reset_mask(env, num_envs, device)
        if torch.any(reset):
            active[reset] = False
            armed[reset] = True
            level[reset] = 0
            swing_multiplier[reset] = 1.0
            liftoff_xy[reset] = 0.0
            liftoff_dir[reset] = 0.0
            best_progress[reset] = 0.0
            peak_clear[reset] = 0.0
            max_air[reset] = 0.0
            replant_hold[reset] = 0.0
            rearm_hold[reset] = 0.0
            last_attempt[reset] = -1
            last_completed[reset] = -1
            initiation_hold[reset] = 0.0
            completion_hold[reset] = 0.0
            alternation_hold[reset] = 0.0
            repeat_hold[reset] = 0.0
            initiation_value[reset] = 0.0
            completion_value[reset] = 0.0

        # Events decay in physical time.  A short hold makes one-shot milestones visible
        # to PPO without turning them back into indefinitely farmable state rewards.
        initiation_hold[:] = torch.clamp(initiation_hold - dt, min=0.0)
        completion_hold[:] = torch.clamp(completion_hold - dt, min=0.0)
        alternation_hold[:] = torch.clamp(alternation_hold - dt, min=0.0)
        repeat_hold[:] = torch.clamp(repeat_hold - dt, min=0.0)
        initiation_value[initiation_hold <= 0.0] = 0.0
        completion_value[completion_hold <= 0.0] = 0.0

        # Zero/near-zero command is a different regime.  Cancel unfinished swing state;
        # no v6.5 gait reward can leak into standing examples.
        not_moving = ~moving
        if torch.any(not_moving):
            active[not_moving] = False
            level[not_moving] = 0
            best_progress[not_moving] = 0.0
            peak_clear[not_moving] = 0.0
            max_air[not_moving] = 0.0

        # Fully replanted feet must accept meaningful support before they can re-arm.
        rearm_ok = full_plant & (load_share >= float(rearm_load_share)) & (~active)
        rearm_hold[:] = torch.where(rearm_ok, rearm_hold + dt, torch.zeros_like(rearm_hold))
        armed[:] = armed | (rearm_hold >= float(rearm_hold_s))

        # Start a swing only once.  The same physical foot cannot revisit the initiation
        # bridge until it has completed and then re-armed through a loaded full plant.
        start = (
            moving.unsqueeze(-1)
            & armed
            & (~active)
            & (viability.unsqueeze(-1) >= float(min_viability))
            & (load_share <= float(start_unload_share))
            & (opposite_share >= float(start_support_share))
            & (coherent_rise_vz >= float(start_rise_speed_mps))
        )
        for foot in (0, 1):
            sf = start[:, foot]
            if torch.any(sf):
                start_event[sf, foot] = True
                active[sf, foot] = True
                armed[sf, foot] = False
                level[sf, foot] = 1
                liftoff_xy[sf, foot] = center_xy[sf, foot]
                liftoff_dir[sf, foot] = command_dir[sf]
                best_progress[sf, foot] = 0.0
                peak_clear[sf, foot] = torch.clamp(whole_clear[sf, foot], min=0.0)
                max_air[sf, foot] = whole_air[sf, foot]
                # Discount a repeat after any previously rewarded lift attempt, even if
                # that attempt was only a toe tap and did not become a meaningful step.
                same = last_attempt[sf] == foot
                opposite = (last_attempt[sf] >= 0) & (last_attempt[sf] != foot)
                mult = torch.ones_like(best_progress[sf, foot]) * float(first_swing_multiplier)
                mult = torch.where(same, torch.full_like(mult, float(repeat_same_foot_multiplier)), mult)
                mult = torch.where(opposite, torch.full_like(mult, float(opposite_swing_multiplier)), mult)
                swing_multiplier[sf, foot] = mult
                # First finite milestone: useful unload + coherent upward motion.
                add = 0.20 * mult * viability[sf]
                initiation_value[sf] = initiation_value[sf] + add
                initiation_hold[sf] = float(event_hold_s)

        # Consume 2/5/10/15 mm coherent-clearance milestones exactly once per swing.
        milestone_weights = (0.15, 0.20, 0.20, 0.25)  # + start 0.20 = 1.00 total
        for foot in (0, 1):
            af = active[:, foot] & moving & (viability >= float(min_viability))
            if not torch.any(af):
                continue
            peak_clear[:, foot] = torch.where(af, torch.maximum(peak_clear[:, foot], whole_clear[:, foot]), peak_clear[:, foot])
            max_air[:, foot] = torch.where(af, torch.maximum(max_air[:, foot], whole_air[:, foot]), max_air[:, foot])
            for idx, (threshold, mw) in enumerate(zip(milestones, milestone_weights), start=2):
                crossed = af & (level[:, foot] < idx) & (peak_clear[:, foot] >= threshold) & (opposite_share[:, foot] >= float(start_support_share))
                if torch.any(crossed):
                    level[crossed, foot] = idx
                    add = float(mw) * swing_multiplier[crossed, foot] * viability[crossed]
                    initiation_value[crossed] = initiation_value[crossed] + add
                    initiation_hold[crossed] = float(event_hold_s)

        # Finite command-direction trajectory progress.  Only NEW best progress is paid;
        # holding a foot forward or hovering yields exactly zero additional credit.
        progress_delta_sum = torch.zeros(num_envs, device=device, dtype=dtype)
        for foot in (0, 1):
            af = active[:, foot] & moving & (~any_contact[:, foot]) & (peak_clear[:, foot] >= float(trajectory_start_clearance_m))
            if torch.any(af):
                progress = torch.sum((center_xy[:, foot] - liftoff_xy[:, foot]) * liftoff_dir[:, foot], dim=1)
                progress = torch.clamp(progress, min=0.0)
                delta = torch.relu(progress - best_progress[:, foot]) / float(full_trajectory_progress_m)
                delta = torch.clamp(delta, 0.0, 1.0)
                progress_delta_sum += delta * af.float() * swing_multiplier[:, foot] * viability
                best_progress[:, foot] = torch.where(af, torch.maximum(best_progress[:, foot], progress), best_progress[:, foot])
        env._littlegreen_v65_trajectory_progress_delta = progress_delta_sum.detach()

        # A swing finishes only after the foot returns to a full plant and takes load.
        # The same foot is then deliberately NOT rearmed immediately; it must remain a
        # loaded plant for rearm_hold_s, giving the opposite foot a clean opportunity.
        replant_ok = full_plant & (load_share >= float(completion_load_share))
        replant_hold[:] = torch.where(active & replant_ok, replant_hold + dt, torch.zeros_like(replant_hold))
        for foot in (0, 1):
            finished = active[:, foot] & (replant_hold[:, foot] >= float(completion_replant_s))
            if not torch.any(finished):
                continue
            # Any attempt that reached at least the 5 mm milestone hands the next
            # initiation opportunity to the opposite foot economically, even if its
            # air time was too short to count as a completed swing.
            rewarded_attempt = finished & (peak_clear[:, foot] >= float(trajectory_start_clearance_m))
            last_attempt[rewarded_attempt] = foot
            meaningful = finished & (peak_clear[:, foot] >= float(min_meaningful_clearance_m)) & (max_air[:, foot] >= float(min_meaningful_air_time_s))
            if torch.any(meaningful):
                prog_score = torch.clamp(best_progress[:, foot] / float(full_trajectory_progress_m), 0.0, 1.0)
                value = (0.35 + 0.65 * prog_score) * swing_multiplier[:, foot] * viability
                completion_value[meaningful] = value[meaningful]
                completion_hold[meaningful] = float(event_hold_s)
                same = meaningful & (last_completed == foot)
                alternating = meaningful & (last_completed >= 0) & (last_completed != foot)
                repeat_hold[same] = float(event_hold_s)
                alternation_hold[alternating] = float(event_hold_s)
                completion_event[meaningful, foot] = True
                repeat_event[same] = True
                alternation_event[alternating] = True
                last_completed[meaningful] = foot
            active[finished, foot] = False
            armed[finished, foot] = False
            level[finished, foot] = 0
            replant_hold[finished, foot] = 0.0
            rearm_hold[finished, foot] = 0.0
            best_progress[finished, foot] = 0.0
            peak_clear[finished, foot] = 0.0
            max_air[finished, foot] = 0.0

        env._littlegreen_v65_active = active
        env._littlegreen_v65_armed = armed
        env._littlegreen_v65_milestone_level = level
        env._littlegreen_v65_swing_multiplier = swing_multiplier
        env._littlegreen_v65_liftoff_xy = liftoff_xy
        env._littlegreen_v65_liftoff_dir = liftoff_dir
        env._littlegreen_v65_best_progress = best_progress
        env._littlegreen_v65_peak_clearance = peak_clear
        env._littlegreen_v65_max_air_time = max_air
        env._littlegreen_v65_replant_hold = replant_hold
        env._littlegreen_v65_rearm_hold = rearm_hold
        env._littlegreen_v65_last_attempt_foot = last_attempt
        env._littlegreen_v65_last_completed_foot = last_completed
        env._littlegreen_v65_initiation_hold = initiation_hold
        env._littlegreen_v65_completion_hold = completion_hold
        env._littlegreen_v65_alternation_hold = alternation_hold
        env._littlegreen_v65_repeat_hold = repeat_hold
        env._littlegreen_v65_initiation_value = initiation_value
        env._littlegreen_v65_completion_value = completion_value
        env._littlegreen_v65_start_event = start_event.detach()
        env._littlegreen_v65_completion_event = completion_event.detach()
        env._littlegreen_v65_alternation_event = alternation_event.detach()
        env._littlegreen_v65_repeat_event = repeat_event.detach()
        env._littlegreen_v65_last_common_step = common_step

    trajectory = getattr(env, "_littlegreen_v65_trajectory_progress_delta", torch.zeros(num_envs, device=device, dtype=dtype))
    return {
        "initiation": torch.where(initiation_hold > 0.0, initiation_value, torch.zeros_like(initiation_value)) * moving.float(),
        "trajectory": trajectory * moving.float(),
        "completion": torch.where(completion_hold > 0.0, completion_value, torch.zeros_like(completion_value)) * moving.float(),
        "alternation": (alternation_hold > 0.0).float() * moving.float(),
        "repeat": (repeat_hold > 0.0).float() * moving.float(),
        "active": active.float(),
        "armed": armed.float(),
        "milestone_level": level.float(),
        "last_attempt_foot": last_attempt,
        "last_completed_foot": last_completed,
    }


def finite_whole_foot_swing_initiation_v65(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    start_unload_share: float = 0.42,
    start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.015,
    clearance_milestones: tuple[float, float, float, float] = (0.002, 0.005, 0.010, 0.015),
    min_meaningful_clearance_m: float = 0.010,
    min_meaningful_air_time_s: float = 0.08,
    trajectory_start_clearance_m: float = 0.005,
    full_trajectory_progress_m: float = 0.035,
    completion_load_share: float = 0.30,
    completion_replant_s: float = 0.08,
    rearm_load_share: float = 0.40,
    rearm_hold_s: float = 0.12,
    first_swing_multiplier: float = 1.00,
    opposite_swing_multiplier: float = 1.35,
    repeat_same_foot_multiplier: float = 0.10,
    event_hold_s: float = 0.06,
    min_viability: float = 0.45,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """One-shot unload + 2/5/10/15 mm whole-foot lift progress.

    The explicit parameter list is intentional. Isaac Lab's ManagerBase validates
    reward callables with ``inspect.signature`` and does not treat ``**kwargs`` as
    a catch-all for configured term parameters. Keeping this signature aligned with
    ``_v65_finite_swing_state`` makes the term Hydra/RewardManager compatible.
    """
    return _v65_finite_swing_state(
        env,
        command_name=command_name,
        sensor_cfg=sensor_cfg,
        asset_cfg=asset_cfg,
        command_threshold=command_threshold,
        start_unload_share=start_unload_share,
        start_support_share=start_support_share,
        start_rise_speed_mps=start_rise_speed_mps,
        clearance_milestones=clearance_milestones,
        min_meaningful_clearance_m=min_meaningful_clearance_m,
        min_meaningful_air_time_s=min_meaningful_air_time_s,
        trajectory_start_clearance_m=trajectory_start_clearance_m,
        full_trajectory_progress_m=full_trajectory_progress_m,
        completion_load_share=completion_load_share,
        completion_replant_s=completion_replant_s,
        rearm_load_share=rearm_load_share,
        rearm_hold_s=rearm_hold_s,
        first_swing_multiplier=first_swing_multiplier,
        opposite_swing_multiplier=opposite_swing_multiplier,
        repeat_same_foot_multiplier=repeat_same_foot_multiplier,
        event_hold_s=event_hold_s,
        min_viability=min_viability,
        bodies_per_foot=bodies_per_foot,
        full_tilt_deg=full_tilt_deg,
        zero_tilt_deg=zero_tilt_deg,
        full_height_m=full_height_m,
        zero_height_m=zero_height_m,
    )["initiation"]


