        trajectory_start_clearance_m=trajectory_start_clearance_m,
        full_trajectory_progress_m=full_trajectory_progress_m,
        completion_load_share=completion_load_share,
        completion_replant_s=completion_replant_s,
        rearm_load_share=rearm_load_share,
        rearm_hold_s=rearm_hold_s,
        first_swing_multiplier=first_swing_multiplier,
        opposite_swing_multiplier=opposite_swing_multiplier,
        repeat_same_foot_multiplier=repeat_same_foot_multiplier,
        event_hold_s=event_hold_s,
