def standing_bilateral_full_plant_v65(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    force_threshold: float = 1.0,
    min_load_share: float = 0.20,
) -> torch.Tensor:
    """Reward a quiet-command bilateral main+toe plant with nontrivial load on both feet."""
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact = sensor.data.current_contact_time[:, sensor_cfg.body_ids] > 0.0
    if contact.shape[1] != 4:
        raise ValueError("v6.5 standing full plant expects L_main,L_toe,R_main,R_toe")
    full = contact[:, 0] & contact[:, 1] & contact[:, 2] & contact[:, 3]
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    lf = vertical[:, 0] + vertical[:, 1]
    rf = vertical[:, 2] + vertical[:, 3]
    total = lf + rf
    share_l = lf / torch.clamp(total, min=1.0e-6)
    share_r = rf / torch.clamp(total, min=1.0e-6)
    loaded = (total > float(force_threshold)) & (share_l >= float(min_load_share)) & (share_r >= float(min_load_share))
    command = env.command_manager.get_command(command_name)
    standing = torch.linalg.vector_norm(command, dim=1) <= float(command_threshold)
    return (full & loaded & standing).float()


def standing_whole_foot_load_imbalance_v65(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
    deadband: float = 0.12,
    scale: float = 0.35,
) -> torch.Tensor:
    """Standing-only left/right whole-foot load imbalance penalty.

    Unlike the older two-body helper, this explicitly groups the ordered four-body
    physical-foot representation as [L_main,L_toe] and [R_main,R_toe].
    """
    if not 0.0 <= float(deadband) < 1.0 or float(scale) <= 0.0:
        raise ValueError("v6.5 standing load-balance parameters invalid")
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    if vertical.shape[1] != 4:
        raise ValueError("v6.5 standing load balance expects L_main,L_toe,R_main,R_toe")
    lf = vertical[:, 0] + vertical[:, 1]
    rf = vertical[:, 2] + vertical[:, 3]
    imbalance = torch.abs(lf - rf) / torch.clamp(lf + rf, min=1.0e-6)
    excess = torch.relu(imbalance - float(deadband)) / float(scale)
    command = env.command_manager.get_command(command_name)
    standing = torch.linalg.vector_norm(command, dim=1) <= float(command_threshold)
    return torch.clamp(torch.square(excess), max=4.0) * standing.float()


def standing_actionable_joint_velocity_l2_v65(
    env: ManagerBasedRLEnv,
    command_name: str,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.05,
) -> torch.Tensor:
    """Penalize toe-tap/bracing joint motion only during zero/near-zero commands."""
    asset = env.scene[asset_cfg.name]
    vel = asset.data.joint_vel[:, asset_cfg.joint_ids]
    command = env.command_manager.get_command(command_name)
    standing = torch.linalg.vector_norm(command, dim=1) <= float(command_threshold)
    return torch.sum(torch.square(vel), dim=1) * standing.float()

# -----------------------------------------------------------------------------
# LittleGreen v6.6 event-driven support-baton gait bridge
# -----------------------------------------------------------------------------
def _v66_support_baton_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    start_unload_share: float = 0.45,
    start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.012,
    readiness_load_full: float = 0.68,
    readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float, float, float, float] = (0.002, 0.005, 0.010, 0.015),
    min_meaningful_clearance_m: float = 0.010,
    min_meaningful_air_time_s: float = 0.08,
    trajectory_start_clearance_m: float = 0.005,
    full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25,
    completion_replant_s: float = 0.06,
    takeover_load_full: float = 0.55,
    takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50,
    handoff_com_threshold: float = 0.56,
    handoff_hold_s: float = 0.08,
    takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04,
    release_clearance_m: float = 0.005,
    continuation_multiplier: float = 1.50,
    first_multiplier: float = 1.00,
    event_hold_s: float = 0.06,
    min_viability: float = 0.45,
    handoff_min_viability: float = 0.60,
    bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Unified event-driven gait bridge for v6.6.

    The state machine encodes only causal support mechanics, not a timed gait:

    ``support readiness -> swing -> loaded replant -> support takeover -> old-foot release``.

    The first swing side is free.  After a successful support handoff, the old stance
    foot becomes the *expected* next swing foot, so continuation is event-driven rather
    than phase-driven.  COM shaping is relative progress toward the actual supporting
    foot; no absolute COM coordinate, cadence, stride length, hip/knee pose, or ZMP
    trajectory is prescribed.
    """
    if int(bodies_per_foot) != 2:
        raise ValueError("v6.6 expects two ordered bodies per physical foot")
    if not 0.0 < float(start_unload_share) < 0.5 < float(start_support_share) < 1.0:
        raise ValueError("v6.6 start load shares must straddle 0.5")
    if not 0.5 < float(readiness_load_full) <= 1.0 or not 0.5 < float(readiness_com_full) <= 1.0:
        raise ValueError("v6.6 readiness targets must exceed 0.5")
    if not 0.0 < float(completion_load_share) < float(takeover_load_full) < 1.0:
        raise ValueError("v6.6 replant/takeover load targets invalid")
    if not 0.5 <= float(handoff_load_threshold) < 1.0 or not 0.5 <= float(handoff_com_threshold) < 1.0:
        raise ValueError("v6.6 handoff thresholds must be >= 0.5")
    if float(full_trajectory_progress_m) <= 0.0 or float(takeover_timeout_s) <= 0.0:
        raise ValueError("v6.6 progress and timeout scales must be positive")
    milestones = tuple(float(x) for x in clearance_milestones)
    if len(milestones) != 4 or not (0.0 < milestones[0] < milestones[1] < milestones[2] < milestones[3]):
        raise ValueError("v6.6 clearance milestones must be four increasing positive values")

    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    if contact_t.shape[1] != 4 or air_t.shape[1] != 4:
        raise ValueError("v6.6 expects L_main,L_toe,R_main,R_toe contact bodies")

    asset = env.scene[asset_cfg.name]
    pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    vel = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :]
    if pos.shape[1] != 4 or vel.shape[1] != 4:
        raise ValueError("v6.6 expects L_main,L_toe,R_main,R_toe robot bodies")

    num_envs = pos.shape[0]
    device = pos.device
    dtype = pos.dtype
    dt = float(getattr(env, "step_dt", 0.02))
    ids = torch.arange(num_envs, device=device)

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact
    full_plant = main_contact & toe_contact
    whole_air = torch.stack((torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1)

    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    total_load = torch.sum(foot_load, dim=1, keepdim=True)
    load_share = foot_load / torch.clamp(total_load, min=1.0e-6)

    z = pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    whole_clear = torch.minimum(main_clear, toe_clear)

    vz = vel[:, :, 2]
    opposite_mean_vz = torch.stack((0.5 * (vz[:, 2] + vz[:, 3]), 0.5 * (vz[:, 0] + vz[:, 1])), dim=1)
    coherent_rise = torch.minimum(
        torch.stack((vz[:, 0], vz[:, 2]), dim=1) - opposite_mean_vz,
        torch.stack((vz[:, 1], vz[:, 3]), dim=1) - opposite_mean_vz,
    )

    centers = torch.stack((0.5 * (pos[:, 0, :2] + pos[:, 1, :2]), 0.5 * (pos[:, 2, :2] + pos[:, 3, :2])), dim=1)
    com_xy = asset.data.root_com_pos_w[:, :2]
    d_left = torch.linalg.vector_norm(com_xy - centers[:, 0], dim=1)
    d_right = torch.linalg.vector_norm(com_xy - centers[:, 1], dim=1)
    dsum = torch.clamp(d_left + d_right, min=1.0e-6)
    # closeness[:, foot] = 0.5 at the equidistant midpoint and approaches 1 near that foot.
    closeness = torch.stack((d_right / dsum, d_left / dsum), dim=1)

    command_xy = env.command_manager.get_command(command_name)[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    moving = command_norm > float(command_threshold)
    command_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    stage = _state("_littlegreen_v66_stage", (num_envs,), 0, torch.long)  # 0 ready, 1 swing, 2 takeover
    expected_swing = _state("_littlegreen_v66_expected_swing", (num_envs,), -1, torch.long)
    swing_foot = _state("_littlegreen_v66_swing_foot", (num_envs,), -1, torch.long)
    stance_foot = _state("_littlegreen_v66_stance_foot", (num_envs,), -1, torch.long)
    milestone_level = _state("_littlegreen_v66_milestone_level", (num_envs,), 0, torch.long)
    swing_multiplier = _state("_littlegreen_v66_swing_multiplier", (num_envs,), 1.0)
    readiness_best = _state("_littlegreen_v66_readiness_best", (num_envs,), 0.0)
    liftoff_xy = _state("_littlegreen_v66_liftoff_xy", (num_envs, 2), 0.0)
    liftoff_dir = _state("_littlegreen_v66_liftoff_dir", (num_envs, 2), 0.0)
    best_progress = _state("_littlegreen_v66_best_progress", (num_envs,), 0.0)
    peak_clear = _state("_littlegreen_v66_peak_clearance", (num_envs,), 0.0)
    max_air = _state("_littlegreen_v66_max_air_time", (num_envs,), 0.0)
    replant_timer = _state("_littlegreen_v66_replant_timer", (num_envs,), 0.0)
    takeover_start_load = _state("_littlegreen_v66_takeover_start_load", (num_envs,), 0.0)
    takeover_start_closeness = _state("_littlegreen_v66_takeover_start_closeness", (num_envs,), 0.5)
    takeover_best = _state("_littlegreen_v66_takeover_best", (num_envs,), 0.0)
    takeover_hold = _state("_littlegreen_v66_takeover_hold", (num_envs,), 0.0)
    takeover_elapsed = _state("_littlegreen_v66_takeover_elapsed", (num_envs,), 0.0)
    pending_release = _state("_littlegreen_v66_pending_release", (num_envs,), False, torch.bool)

    initiation_hold = _state("_littlegreen_v66_initiation_hold", (num_envs,), 0.0)
    initiation_value = _state("_littlegreen_v66_initiation_value", (num_envs,), 0.0)
    replant_event_hold = _state("_littlegreen_v66_replant_event_hold", (num_envs,), 0.0)
    handoff_event_hold = _state("_littlegreen_v66_handoff_event_hold", (num_envs,), 0.0)
    release_event_hold = _state("_littlegreen_v66_release_event_hold", (num_envs,), 0.0)
    gait_step_hold = _state("_littlegreen_v66_gait_step_hold", (num_envs,), 0.0)
    gait_step_value = _state("_littlegreen_v66_gait_step_value", (num_envs,), 0.0)
    failure_hold = _state("_littlegreen_v66_failure_hold", (num_envs,), 0.0)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v66_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, num_envs, device)
        stop = (~moving) | reset

        # Event streams are one simulation-step impulses unless explicitly held.
        start_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        replant_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        handoff_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        release_event = torch.zeros((num_envs, 2), device=device, dtype=torch.bool)
        readiness_delta = torch.zeros(num_envs, device=device, dtype=dtype)
        trajectory_delta = torch.zeros(num_envs, device=device, dtype=dtype)
        takeover_delta = torch.zeros(num_envs, device=device, dtype=dtype)

        initiation_hold[:] = torch.clamp(initiation_hold - dt, min=0.0)
        replant_event_hold[:] = torch.clamp(replant_event_hold - dt, min=0.0)
        handoff_event_hold[:] = torch.clamp(handoff_event_hold - dt, min=0.0)
        release_event_hold[:] = torch.clamp(release_event_hold - dt, min=0.0)
        gait_step_hold[:] = torch.clamp(gait_step_hold - dt, min=0.0)
        failure_hold[:] = torch.clamp(failure_hold - dt, min=0.0)
        initiation_value[:] = torch.where(initiation_hold > 0.0, initiation_value, torch.zeros_like(initiation_value))
        gait_step_value[:] = torch.where(gait_step_hold > 0.0, gait_step_value, torch.zeros_like(gait_step_value))

        if torch.any(stop):
            stage[stop] = 0
            expected_swing[stop] = -1
            swing_foot[stop] = -1
            stance_foot[stop] = -1
            milestone_level[stop] = 0
            swing_multiplier[stop] = 1.0
            readiness_best[stop] = 0.0
            best_progress[stop] = 0.0
            peak_clear[stop] = 0.0
            max_air[stop] = 0.0
            replant_timer[stop] = 0.0
            takeover_best[stop] = 0.0
            takeover_hold[stop] = 0.0
            takeover_elapsed[stop] = 0.0
            pending_release[stop] = False

        # Stage 0: finite support-readiness shaping.  v2.4.2 showed that dense load
        # transfer + COM progress makes unloading reachable.  Here the candidate side
        # is chosen from actual load (or the support baton), and only NEW best progress
        # is paid, so a static one-leg brace cannot farm the term.
        ready = (stage == 0) & moving & (viability >= float(min_viability)) & full_plant[:, 0] & full_plant[:, 1]
        free_stance = torch.argmax(load_share, dim=1)
        baton_stance = 1 - torch.clamp(expected_swing, min=0, max=1)
        candidate_stance = torch.where(expected_swing >= 0, baton_stance, free_stance)
        candidate_swing = 1 - candidate_stance
        stance_share = load_share[ids, candidate_stance]
        stance_close = closeness[ids, candidate_stance]
        load_score = torch.clamp((stance_share - 0.5) / max(float(readiness_load_full) - 0.5, 1.0e-6), 0.0, 1.0)
        com_score = torch.clamp((stance_close - 0.5) / max(float(readiness_com_full) - 0.5, 1.0e-6), 0.0, 1.0)
        readiness = (0.65 * load_score + 0.35 * com_score) * ready.float() * viability
        readiness_delta = torch.relu(readiness - readiness_best) * ready.float()
        readiness_best[:] = torch.where(ready, torch.maximum(readiness_best, readiness), readiness_best)

        start = (
            ready
            & any_contact[ids, candidate_swing]
            & (load_share[ids, candidate_swing] <= float(start_unload_share))
            & (stance_share >= float(start_support_share))
            & (coherent_rise[ids, candidate_swing] >= float(start_rise_speed_mps))
        )
        if torch.any(start):
            sf = candidate_swing[start]
            st = candidate_stance[start]
            start_ids = ids[start]
            start_event[start_ids, sf] = True
            stage[start] = 1
            swing_foot[start] = sf
            stance_foot[start] = st
            milestone_level[start] = 1
            continuation = expected_swing[start] >= 0
            # v2.4.2/v2.4.3 lesson: lift should become increasingly valuable only
            # after the body has actually prepared the stance side.  Keep a 35%
            # bootstrap so imperfect exploratory lifts remain learnable, but scale
            # the rest by finite load+COM readiness rather than imposing a hard COM
            # gate or absolute pelvis target.
            readiness_factor = 0.35 + 0.65 * torch.clamp(readiness_best[start], 0.0, 1.0)
            base_multiplier = torch.where(
                continuation,
                torch.full_like(swing_multiplier[start], float(continuation_multiplier)),
                torch.full_like(swing_multiplier[start], float(first_multiplier)),
            )
            swing_multiplier[start] = base_multiplier * readiness_factor
            liftoff_xy[start] = centers[start_ids, sf]
            liftoff_dir[start] = command_dir[start]
            best_progress[start] = 0.0
            peak_clear[start] = torch.clamp(whole_clear[start_ids, sf], min=0.0)
            max_air[start] = whole_air[start_ids, sf]
            replant_timer[start] = 0.0
            readiness_best[start] = 0.0
            initiation_value[start] = 0.10 * swing_multiplier[start] * viability[start]
            initiation_hold[start] = float(event_hold_s)

        # Stage 1: finite whole-foot lift milestones + incremental directional motion.
        swing_active = (stage == 1) & moving & (viability >= float(min_viability)) & (swing_foot >= 0)
        sf = torch.clamp(swing_foot, min=0, max=1)
        st = torch.clamp(stance_foot, min=0, max=1)
        peak_clear[:] = torch.where(swing_active, torch.maximum(peak_clear, whole_clear[ids, sf]), peak_clear)
        max_air[:] = torch.where(swing_active, torch.maximum(max_air, whole_air[ids, sf]), max_air)
        milestone_weights = (0.15, 0.15, 0.25, 0.35)  # +0.10 start = 1.00 total
        for level_id, (threshold, milestone_weight) in enumerate(zip(milestones, milestone_weights), start=2):
            crossed = (
                swing_active
                & (milestone_level < level_id)
                & (peak_clear >= threshold)
                & (load_share[ids, st] >= float(start_support_share))
            )
            if torch.any(crossed):
                milestone_level[crossed] = level_id
                initiation_value[crossed] = initiation_value[crossed] + (
                    float(milestone_weight) * swing_multiplier[crossed] * viability[crossed]
                )
                initiation_hold[crossed] = float(event_hold_s)

        airborne_progress = (
            swing_active
            & (~any_contact[ids, sf])
            & (peak_clear >= float(trajectory_start_clearance_m))
        )
        if torch.any(airborne_progress):
            prog = torch.sum((centers[ids, sf] - liftoff_xy) * liftoff_dir, dim=1)
            prog = torch.clamp(prog, min=0.0)
            delta = torch.relu(prog - best_progress) / float(full_trajectory_progress_m)
            delta = torch.clamp(delta, 0.0, 1.0)
            trajectory_delta = delta * airborne_progress.float() * swing_multiplier * viability
            best_progress[:] = torch.where(airborne_progress, torch.maximum(best_progress, prog), best_progress)

        # After a successful handoff the old stance foot is explicitly the next swing
        # candidate.  Reward its genuine whole-foot release once, not a toe tap.
        release = (
            swing_active
            & pending_release
            & (whole_air[ids, sf] >= float(release_air_time_s))
            & (whole_clear[ids, sf] >= float(release_clearance_m))
            & full_plant[ids, st]
            & (load_share[ids, st] >= float(start_support_share))
        )
        if torch.any(release):
            release_event[ids[release], sf[release]] = True
            release_event_hold[release] = float(event_hold_s)
            pending_release[release] = False

        replanted = full_plant[ids, sf] & (load_share[ids, sf] >= float(completion_load_share))
        replant_timer[:] = torch.where(swing_active & replanted, replant_timer + dt, torch.zeros_like(replant_timer))
        replant_done = swing_active & (replant_timer >= float(completion_replant_s))
        if torch.any(replant_done):
            meaningful = (
                replant_done
                & (peak_clear >= float(min_meaningful_clearance_m))
                & (max_air >= float(min_meaningful_air_time_s))
            )
            if torch.any(meaningful):
                mf = sf[meaningful]
                mids = ids[meaningful]
                replant_event[mids, mf] = True
                replant_event_hold[meaningful] = float(event_hold_s)
                stage[meaningful] = 2
                takeover_start_load[meaningful] = load_share[mids, mf]
                takeover_start_closeness[meaningful] = closeness[mids, mf]
                takeover_best[meaningful] = 0.0
                takeover_hold[meaningful] = 0.0
                takeover_elapsed[meaningful] = 0.0
            failed_replant = replant_done & (~meaningful)
            if torch.any(failed_replant):
                stage[failed_replant] = 0
                swing_foot[failed_replant] = -1
                stance_foot[failed_replant] = -1
                milestone_level[failed_replant] = 0
                readiness_best[failed_replant] = 0.0
                best_progress[failed_replant] = 0.0
                peak_clear[failed_replant] = 0.0
                max_air[failed_replant] = 0.0
                replant_timer[failed_replant] = 0.0

        # Stage 2: a landing is not yet a step.  Progress is paid only as the newly
        # landed foot accepts load AND the COM becomes closer to that foot.  This is
        # the event-relative version of the successful v2.4 Transfer COM/support
        # shaping and the v6.1 takeover bridge.
        takeover_active = (stage == 2) & moving & (swing_foot >= 0) & (stance_foot >= 0)
        nf = torch.clamp(swing_foot, min=0, max=1)
        of = torch.clamp(stance_foot, min=0, max=1)
        new_share = load_share[ids, nf]
        old_share = load_share[ids, of]
        new_close = closeness[ids, nf]
        load_denom = torch.clamp(torch.full_like(new_share, float(takeover_load_full)) - takeover_start_load, min=0.05)
        com_denom = torch.clamp(torch.full_like(new_close, float(takeover_com_full)) - takeover_start_closeness, min=0.05)
        load_prog = torch.clamp((new_share - takeover_start_load) / load_denom, 0.0, 1.0)
        com_prog = torch.clamp((new_close - takeover_start_closeness) / com_denom, 0.0, 1.0)
        takeover_score = (0.65 * load_prog + 0.35 * com_prog) * takeover_active.float() * viability
        takeover_delta = torch.relu(takeover_score - takeover_best) * takeover_active.float()
        takeover_best[:] = torch.where(takeover_active, torch.maximum(takeover_best, takeover_score), takeover_best)
        takeover_elapsed[:] = torch.where(takeover_active, takeover_elapsed + dt, takeover_elapsed)

        handoff_ok = (
            takeover_active
            & full_plant[ids, nf]
            & (new_share >= float(handoff_load_threshold))
            & (old_share <= (1.0 - float(handoff_load_threshold) + 0.02))
            & (new_close >= float(handoff_com_threshold))
            & (viability >= float(handoff_min_viability))
        )
        takeover_hold[:] = torch.where(handoff_ok, takeover_hold + dt, torch.zeros_like(takeover_hold))
        handoff = takeover_active & (takeover_hold >= float(handoff_hold_s))
        if torch.any(handoff):
            hids = ids[handoff]
            newf = nf[handoff]
            oldf = of[handoff]
            handoff_event[hids, newf] = True
            handoff_event_hold[handoff] = float(event_hold_s)
            continuation = expected_swing[handoff] >= 0
            gait_step_value[handoff] = torch.where(
                continuation,
                torch.full_like(gait_step_value[handoff], float(continuation_multiplier)),
                torch.full_like(gait_step_value[handoff], float(first_multiplier)),
            )
            gait_step_hold[handoff] = float(event_hold_s)
            expected_swing[handoff] = oldf
            pending_release[handoff] = True
            stage[handoff] = 0
            swing_foot[handoff] = -1
            stance_foot[handoff] = -1
            milestone_level[handoff] = 0
            readiness_best[handoff] = 0.0
            best_progress[handoff] = 0.0
            peak_clear[handoff] = 0.0
            max_air[handoff] = 0.0
            replant_timer[handoff] = 0.0
            takeover_best[handoff] = 0.0
            takeover_hold[handoff] = 0.0
            takeover_elapsed[handoff] = 0.0

        timed_out = takeover_active & (~handoff) & (takeover_elapsed >= float(takeover_timeout_s))
        if torch.any(timed_out):
            failure_hold[timed_out] = float(event_hold_s)
            # A failed landing/takeover does not advance the support baton.  Clear the
            # expectation so the policy can recover instead of being forced into an
            # impossible next lift from the wrong support state.
            stage[timed_out] = 0
            expected_swing[timed_out] = -1
            pending_release[timed_out] = False
            swing_foot[timed_out] = -1
            stance_foot[timed_out] = -1
            milestone_level[timed_out] = 0
            readiness_best[timed_out] = 0.0
            best_progress[timed_out] = 0.0
            peak_clear[timed_out] = 0.0
            max_air[timed_out] = 0.0
            replant_timer[timed_out] = 0.0
            takeover_best[timed_out] = 0.0
            takeover_hold[timed_out] = 0.0
            takeover_elapsed[timed_out] = 0.0

        env._littlegreen_v66_stage = stage
        env._littlegreen_v66_expected_swing = expected_swing
        env._littlegreen_v66_swing_foot = swing_foot
        env._littlegreen_v66_stance_foot = stance_foot
        env._littlegreen_v66_milestone_level = milestone_level
        env._littlegreen_v66_swing_multiplier = swing_multiplier
        env._littlegreen_v66_readiness_best = readiness_best
        env._littlegreen_v66_liftoff_xy = liftoff_xy
        env._littlegreen_v66_liftoff_dir = liftoff_dir
        env._littlegreen_v66_best_progress = best_progress
        env._littlegreen_v66_peak_clearance = peak_clear
        env._littlegreen_v66_max_air_time = max_air
        env._littlegreen_v66_replant_timer = replant_timer
        env._littlegreen_v66_takeover_start_load = takeover_start_load
        env._littlegreen_v66_takeover_start_closeness = takeover_start_closeness
        env._littlegreen_v66_takeover_best = takeover_best
        env._littlegreen_v66_takeover_hold = takeover_hold
        env._littlegreen_v66_takeover_elapsed = takeover_elapsed
        env._littlegreen_v66_pending_release = pending_release
        env._littlegreen_v66_initiation_hold = initiation_hold
        env._littlegreen_v66_initiation_value = initiation_value
        env._littlegreen_v66_replant_event_hold = replant_event_hold
        env._littlegreen_v66_handoff_event_hold = handoff_event_hold
        env._littlegreen_v66_release_event_hold = release_event_hold
        env._littlegreen_v66_gait_step_hold = gait_step_hold
        env._littlegreen_v66_gait_step_value = gait_step_value
        env._littlegreen_v66_failure_hold = failure_hold
        env._littlegreen_v66_start_event = start_event.detach()
        env._littlegreen_v66_replant_event = replant_event.detach()
        env._littlegreen_v66_handoff_event = handoff_event.detach()
        env._littlegreen_v66_release_event = release_event.detach()
        env._littlegreen_v66_support_readiness_delta = readiness_delta.detach()
        env._littlegreen_v66_trajectory_delta = trajectory_delta.detach()
        env._littlegreen_v66_takeover_delta = takeover_delta.detach()
        env._littlegreen_v66_last_common_step = common_step

    zero = torch.zeros(num_envs, device=device, dtype=dtype)
    return {
        "support_readiness": getattr(env, "_littlegreen_v66_support_readiness_delta", zero) * moving.float(),
        "initiation": torch.where(initiation_hold > 0.0, initiation_value, zero) * moving.float(),
        "trajectory": getattr(env, "_littlegreen_v66_trajectory_delta", zero) * moving.float(),
        "replant": (replant_event_hold > 0.0).float() * moving.float(),
        "takeover_progress": getattr(env, "_littlegreen_v66_takeover_delta", zero) * moving.float(),
        "handoff": (handoff_event_hold > 0.0).float() * moving.float(),
        "opposite_release": (release_event_hold > 0.0).float() * moving.float(),
        "gait_step": torch.where(gait_step_hold > 0.0, gait_step_value, zero) * moving.float(),
        "takeover_failure": (failure_hold > 0.0).float() * moving.float(),
        "stage": stage,
        "expected_swing": expected_swing,
        "swing_foot": swing_foot,
        "stance_foot": stance_foot,
        "milestone_level": milestone_level,
        "pending_release": pending_release,
        "takeover_best": takeover_best,
    }


