# =============================================================================
# LittleGreen v6.7 swing-commitment / foot-relative command acquisition
# =============================================================================
# v6.7 deliberately reuses the proven v6.6 support-baton state machine with
# tighter swing thresholds, then adds stateless / minimally stateful terms that
# make the *foot* rather than the falling base carry more of the command signal.
# No gait clock, phase-selected leg, joint target, stride schedule, or absolute
# COM trajectory is introduced.


def _v67_whole_foot_kinematics(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Return ordered physical-foot state used by v6.7 swing-driven rewards.

    Body order is always ``L_main,L_toe,R_main,R_toe``.  Whole-foot clearance
    uses the least-cleared component so heel-only or toe-only motion cannot earn
    full lift credit.  COM motion is measured relative to the stance foot center
    where required, which prevents a moving/sliding foot from masquerading as a
    fast body-weight transfer.
    """
    sensor: ContactSensor = env.scene.sensors[sensor_cfg.name]
    asset = env.scene[asset_cfg.name]

    contact_t = sensor.data.current_contact_time[:, sensor_cfg.body_ids]
    air_t = sensor.data.current_air_time[:, sensor_cfg.body_ids]
    pos = asset.data.body_pos_w[:, asset_cfg.body_ids, :]
    vel = asset.data.body_lin_vel_w[:, asset_cfg.body_ids, :]
    if contact_t.shape[1] != 4 or air_t.shape[1] != 4 or pos.shape[1] != 4 or vel.shape[1] != 4:
        raise ValueError("v6.7 expects ordered L_main,L_toe,R_main,R_toe bodies")

    component_contact = contact_t > 0.0
    main_contact = torch.stack((component_contact[:, 0], component_contact[:, 2]), dim=1)
    toe_contact = torch.stack((component_contact[:, 1], component_contact[:, 3]), dim=1)
    any_contact = main_contact | toe_contact
    full_plant = main_contact & toe_contact
    whole_air = torch.stack(
        (torch.min(air_t[:, :2], dim=1).values, torch.min(air_t[:, 2:], dim=1).values), dim=1
    )

    forces = sensor.data.net_forces_w_history[:, :, sensor_cfg.body_ids, :]
    vertical = torch.clamp(forces[..., 2], min=0.0).mean(dim=1)
    foot_load = torch.stack((vertical[:, 0] + vertical[:, 1], vertical[:, 2] + vertical[:, 3]), dim=1)
    load_share = foot_load / torch.clamp(torch.sum(foot_load, dim=1, keepdim=True), min=1.0e-6)

    z = pos[:, :, 2]
    main_clear = torch.stack((z[:, 0] - z[:, 2], z[:, 2] - z[:, 0]), dim=1)
    toe_clear = torch.stack((z[:, 1] - z[:, 3], z[:, 3] - z[:, 1]), dim=1)
    whole_clear = torch.minimum(main_clear, toe_clear)

    centers = torch.stack(
        (0.5 * (pos[:, 0, :2] + pos[:, 1, :2]), 0.5 * (pos[:, 2, :2] + pos[:, 3, :2])), dim=1
    )
    center_vel = torch.stack(
        (0.5 * (vel[:, 0, :2] + vel[:, 1, :2]), 0.5 * (vel[:, 2, :2] + vel[:, 3, :2])), dim=1
    )

    vz = vel[:, :, 2]
    opposite_mean_vz = torch.stack(
        (0.5 * (vz[:, 2] + vz[:, 3]), 0.5 * (vz[:, 0] + vz[:, 1])), dim=1
    )
    coherent_rise = torch.minimum(
        torch.stack((vz[:, 0], vz[:, 2]), dim=1) - opposite_mean_vz,
        torch.stack((vz[:, 1], vz[:, 3]), dim=1) - opposite_mean_vz,
    )

    com_xy = asset.data.root_com_pos_w[:, :2]
    d_left = torch.linalg.vector_norm(com_xy - centers[:, 0], dim=1)
    d_right = torch.linalg.vector_norm(com_xy - centers[:, 1], dim=1)
    dsum = torch.clamp(d_left + d_right, min=1.0e-6)
    closeness = torch.stack((d_right / dsum, d_left / dsum), dim=1)

    command = env.command_manager.get_command(command_name)
    command_xy = command[:, :2]
    command_norm = torch.linalg.vector_norm(command_xy, dim=1)
    command_dir = command_xy / torch.clamp(command_norm.unsqueeze(-1), min=1.0e-6)
    # Commands are expressed in the robot/yaw frame, while foot positions and
    # velocities above are world-frame quantities.  Expose an explicit world-frame
    # command direction for v9.3+ directional swing teachers.  Historical callers
    # keep ``command_dir`` unchanged for compatibility.
    command_dir3 = torch.cat((command_dir, torch.zeros_like(command_dir[:, :1])), dim=1)
    command_dir_world = quat_apply(yaw_quat(asset.data.root_quat_w), command_dir3)[:, :2]
    viability = locomotion_viability_factor_v63(
        env, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, SceneEntityCfg(asset_cfg.name)
    )

    return {
        "asset": asset,
        "any_contact": any_contact,
        "full_plant": full_plant,
        "whole_air": whole_air,
        "load_share": load_share,
        "whole_clear": whole_clear,
        "coherent_rise": coherent_rise,
        "centers": centers,
        "center_vel": center_vel,
        "com_xy": com_xy,
        "closeness": closeness,
        "command": command,
        "command_xy": command_xy,
        "command_norm": command_norm,
        "command_dir": command_dir,
        "command_dir_world": command_dir_world,
        "viability": viability,
    }


def gait_conditioned_track_lin_vel_xy_v67(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    std: float = 0.50,
    command_threshold: float = 0.08,
    minimum_credit: float = 0.22,
    full_clearance_m: float = 0.040,
    clearance_credit: float = 0.48,
    single_support_credit: float = 0.20,
    load_asymmetry_credit: float = 0.10,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Base command tracking whose value grows with real whole-foot gait mechanics.

    A falling or rocking base with both physical feet effectively planted receives
    only ``minimum_credit`` of the normal v6.3 command reward.  As coherent whole-
    foot clearance and true single support appear, the full command objective is
    progressively restored.  This removes the economic shortcut of obtaining most
    command income from a forward fall before the swing foot has traveled.
    """
    if not 0.0 <= minimum_credit <= 1.0 or full_clearance_m <= 0.0:
        raise ValueError("v6.7 gait-conditioned tracking parameters invalid")
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    base = track_lin_vel_xy_acquisition_v63(
        env=env, command_name=command_name, std=std, command_threshold=command_threshold,
        full_tilt_deg=full_tilt_deg, zero_tilt_deg=zero_tilt_deg,
        full_height_m=full_height_m, zero_height_m=zero_height_m,
        asset_cfg=SceneEntityCfg(asset_cfg.name),
    )
    positive_clear = torch.clamp(torch.max(k["whole_clear"], dim=1).values, min=0.0)
    clear_score = torch.clamp(positive_clear / float(full_clearance_m), 0.0, 1.0)
    single_support = torch.logical_xor(k["any_contact"][:, 0], k["any_contact"][:, 1]).float()
    load_asymmetry = torch.clamp(2.0 * torch.abs(k["load_share"][:, 0] - 0.5), 0.0, 1.0)
    gate = (
        float(minimum_credit)
        + float(clearance_credit) * clear_score
        + float(single_support_credit) * single_support
        + float(load_asymmetry_credit) * load_asymmetry
    )
    gate = torch.clamp(gate, 0.0, 1.0)
    return base * gate


def stance_relative_com_drive_v67(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_stance_load_share: float = 0.54,
    target_com_closeness: float = 0.68,
    full_relative_speed_mps: float = 0.15,
    max_stance_speed_mps: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Reward a *snappy* COM shift toward the actually loaded stance foot.

    The rewarded velocity is base/COM motion **relative to the stance foot center**.
    A planted foot that slides under the body therefore cannot create the same signal.
    The term fades to zero as COM closeness reaches the finite stance target, so a
    static lateral brace cannot farm it.  This is a velocity bridge, not a prescribed absolute pelvis/COM path or gait phase.
    """
    if not 0.5 < min_stance_load_share < 1.0 or not 0.5 < target_com_closeness <= 1.0:
        raise ValueError("v6.7 COM-drive thresholds invalid")
    if full_relative_speed_mps <= 0.0 or max_stance_speed_mps <= 0.0:
        raise ValueError("v6.7 COM-drive velocity scales must be positive")
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    ids = torch.arange(n, device=k["load_share"].device)
    stance = torch.argmax(k["load_share"], dim=1)
    swing = 1 - stance
    stance_share = k["load_share"][ids, stance]
    stance_close = k["closeness"][ids, stance]
    stance_center = k["centers"][ids, stance]
    stance_vel = k["center_vel"][ids, stance]
    stance_speed = torch.linalg.vector_norm(stance_vel, dim=1)
    to_stance = stance_center - k["com_xy"]
    to_stance_dir = to_stance / torch.clamp(torch.linalg.vector_norm(to_stance, dim=1, keepdim=True), min=1.0e-6)
    base_vel = k["asset"].data.root_lin_vel_w[:, :2]
    relative_com_vel = base_vel - stance_vel
    toward_speed = torch.sum(relative_com_vel * to_stance_dir, dim=1)
    speed_score = torch.clamp(toward_speed / float(full_relative_speed_mps), 0.0, 1.0)
    # Fade the bridge as the target is reached; reward fast transfer, not staying there.
    remaining = torch.clamp(
        (float(target_com_closeness) - stance_close) / max(float(target_com_closeness) - 0.5, 1.0e-6), 0.0, 1.0
    )
    support_score = torch.clamp(
        (stance_share - 0.5) / max(float(min_stance_load_share) - 0.5, 1.0e-6), 0.0, 1.0
    )
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    moving = k["command_norm"] > float(command_threshold)
    bilateral = k["full_plant"][:, 0] & k["full_plant"][:, 1]
    candidate_unloaded = k["load_share"][ids, swing] <= (1.0 - float(min_stance_load_share) + 0.04)
    gate = moving & bilateral & candidate_unloaded & (stance_close < float(target_com_closeness))
    return speed_score * remaining * support_score * stance_anchor * k["viability"] * gate.float()


def body_yaw_lateral_support_transfer_v99(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_stance_load_share: float = 0.54,
    target_com_closeness: float = 0.68,
    full_relative_speed_mps: float = 0.15,
    max_stance_speed_mps: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Reward COM transfer only along the body-yaw lateral support axis.

    v9.9 keeps the v6.7 stance/load/anchor/viability economics but removes the
    sagittal component from COM-preparation velocity.  The active direction is
    the robot yaw-frame left/right axis, signed toward the currently loaded stance
    foot.  A trailing stance foot therefore cannot reward backward COM velocity,
    leaving command-parallel acceleration to the dense WORLD-rate objective.

    The finite transfer target is evaluated from left/right projected foot distances
    in the yaw frame so fore/aft foot placement cannot change how complete the
    lateral support transfer appears.  No vertical/3-D COM attraction is used.
    """
    if not 0.5 < min_stance_load_share < 1.0 or not 0.5 < target_com_closeness <= 1.0:
        raise ValueError("v9.9 lateral COM-transfer thresholds invalid")
    if full_relative_speed_mps <= 0.0 or max_stance_speed_mps <= 0.0:
        raise ValueError("v9.9 lateral COM-transfer velocity scales must be positive")
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    stance = torch.argmax(k["load_share"], dim=1)
    swing = 1 - stance
    stance_share = k["load_share"][ids, stance]
    stance_center = k["centers"][ids, stance]
    stance_vel = k["center_vel"][ids, stance]
    stance_speed = torch.linalg.vector_norm(stance_vel, dim=1)

    lateral_body = torch.zeros((n, 3), device=device, dtype=dtype)
    lateral_body[:, 1] = 1.0
    lateral_world = quat_apply(yaw_quat(k["asset"].data.root_quat_w), lateral_body)[:, :2]

    stance_offset = stance_center - k["com_xy"]
    stance_lateral_offset = torch.sum(stance_offset * lateral_world, dim=1)
    fallback_sign = torch.where(
        stance == 0, torch.ones_like(stance_lateral_offset), -torch.ones_like(stance_lateral_offset)
    )
    stance_side_sign = torch.sign(stance_lateral_offset)
    stance_side_sign = torch.where(stance_side_sign == 0.0, fallback_sign, stance_side_sign)
    toward_lateral = lateral_world * stance_side_sign.unsqueeze(-1)

    base_vel = k["asset"].data.root_lin_vel_w[:, :2]
    relative_com_vel = base_vel - stance_vel
    toward_speed = torch.sum(relative_com_vel * toward_lateral, dim=1)
    speed_score = torch.clamp(toward_speed / float(full_relative_speed_mps), 0.0, 1.0)

    foot_offsets = k["centers"] - k["com_xy"].unsqueeze(1)
    lateral_offsets = torch.abs(torch.sum(foot_offsets * lateral_world.unsqueeze(1), dim=2))
    d_left = lateral_offsets[:, 0]
    d_right = lateral_offsets[:, 1]
    dsum = torch.clamp(d_left + d_right, min=1.0e-6)
    lateral_closeness = torch.stack((d_right / dsum, d_left / dsum), dim=1)
    stance_close = lateral_closeness[ids, stance]

    remaining = torch.clamp(
        (float(target_com_closeness) - stance_close) / max(float(target_com_closeness) - 0.5, 1.0e-6),
        0.0, 1.0,
    )
    support_score = torch.clamp(
        (stance_share - 0.5) / max(float(min_stance_load_share) - 0.5, 1.0e-6), 0.0, 1.0
    )
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    moving = k["command_norm"] > float(command_threshold)
    bilateral = k["full_plant"][:, 0] & k["full_plant"][:, 1]
    candidate_unloaded = k["load_share"][ids, swing] <= (1.0 - float(min_stance_load_share) + 0.04)
    gate = moving & bilateral & candidate_unloaded & (stance_close < float(target_com_closeness))

    env._littlegreen_v99_com_lateral_gate = gate.detach()
    env._littlegreen_v99_com_lateral_toward_speed_mps = toward_speed.detach()
    env._littlegreen_v99_com_lateral_closeness = stance_close.detach()
    env._littlegreen_v99_com_lateral_offset_m = stance_lateral_offset.detach()
    env._littlegreen_v99_com_relative_world_xy_mps = relative_com_vel.detach()
    env._littlegreen_v99_com_lateral_axis_world = lateral_world.detach()

    return speed_score * remaining * support_score * stance_anchor * k["viability"] * gate.float()


def ready_no_liftoff_penalty_v67(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    ready_stance_load_share: float = 0.62,
    ready_com_closeness: float = 0.58,
    ready_swing_max_load_share: float = 0.38,
    lift_clearance_m: float = 0.003,
    lift_rise_speed_mps: float = 0.030,
    grace_s: float = 0.18,
    full_penalty_s: float = 0.45,
) -> torch.Tensor:
    """Small event-relative pressure to commit to lift after support is ready.

    The timer starts only after the robot itself establishes a credible support state.
    It immediately resets when coherent lift begins.  This is not a global cadence or
    left/right clock; it only removes the observed v6.6 loophole of waiting in a good
    brace until gravity carries the base forward.
    """
    if not 0.5 < ready_stance_load_share < 1.0 or not 0.5 < ready_com_closeness <= 1.0:
        raise ValueError("v6.7 ready-to-lift thresholds invalid")
    if not 0.0 <= ready_swing_max_load_share < 0.5 or not 0.0 <= grace_s < full_penalty_s:
        raise ValueError("v6.7 ready-to-lift timing/load parameters invalid")
    k = _v67_whole_foot_kinematics(env, command_name, sensor_cfg, asset_cfg)
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    stance = torch.argmax(k["load_share"], dim=1)
    swing = 1 - stance
    stance_share = k["load_share"][ids, stance]
    swing_share = k["load_share"][ids, swing]
    stance_close = k["closeness"][ids, stance]
    swing_clear = k["whole_clear"][ids, swing]
    swing_rise = k["coherent_rise"][ids, swing]
    moving = k["command_norm"] > float(command_threshold)
    reset = _v10_episode_reset_mask(env, n, device)
    ready = (
        moving
        & k["full_plant"][:, 0] & k["full_plant"][:, 1]
        & (stance_share >= float(ready_stance_load_share))
        & (swing_share <= float(ready_swing_max_load_share))
        & (stance_close >= float(ready_com_closeness))
        & (k["viability"] >= 0.45)
    )
    lift_started = (
        (swing_clear >= float(lift_clearance_m))
        | (swing_rise >= float(lift_rise_speed_mps))
        | (~k["any_contact"][ids, swing])
    )
    active = ready & (~lift_started) & (~reset)
    timer = getattr(env, "_littlegreen_v67_ready_no_lift_timer", None)
    if not isinstance(timer, torch.Tensor) or timer.shape != (n,) or timer.device != device:
        timer = torch.zeros(n, device=device, dtype=dtype)
    dt = float(getattr(env, "step_dt", 0.02))
    timer = torch.where(active, timer + dt, torch.zeros_like(timer))
    env._littlegreen_v67_ready_no_lift_timer = timer
    denom = max(float(full_penalty_s) - float(grace_s), 1.0e-6)
    return torch.clamp((timer - float(grace_s)) / denom, 0.0, 1.0) * k["viability"]


def coherent_swing_rise_velocity_v67(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    max_swing_load_share: float = 0.45,
    min_stance_load_share: float = 0.55,
    onset_speed_mps: float = 0.015,
    full_speed_mps: float = 0.15,
    full_clearance_m: float = 0.040,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Reward coherent main+toe vertical pickup of the unloaded physical foot.

    Credit is relative to the supporting foot's vertical motion and fades as 40 mm
    clearance is achieved.  This encourages thigh/knee participation without ever
    specifying a desired hip or knee angle.
    """
    if not 0.0 <= max_swing_load_share < 0.5 < min_stance_load_share <= 1.0:
        raise ValueError("v6.7 swing-rise load thresholds invalid")
    if not 0.0 <= onset_speed_mps < full_speed_mps or full_clearance_m <= 0.0:
        raise ValueError("v6.7 swing-rise scales invalid")
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    ids = torch.arange(n, device=k["load_share"].device)
    swing = torch.argmin(k["load_share"], dim=1)
    stance = 1 - swing
    rise = k["coherent_rise"][ids, swing]
    clear = torch.clamp(k["whole_clear"][ids, swing], min=0.0)
    speed_score = torch.clamp(
        (rise - float(onset_speed_mps)) / max(float(full_speed_mps) - float(onset_speed_mps), 1.0e-6), 0.0, 1.0
    )
    clearance_remaining = torch.clamp(1.0 - clear / float(full_clearance_m), 0.0, 1.0)
    gate = (
        (k["command_norm"] > float(command_threshold))
        & (k["load_share"][ids, swing] <= float(max_swing_load_share))
        & (k["load_share"][ids, stance] >= float(min_stance_load_share))
        & k["full_plant"][ids, stance]
    )
    return speed_score * clearance_remaining * k["viability"] * gate.float()


def swing_foot_command_velocity_v67(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018,
    max_swing_load_share: float = 0.45,
    min_stance_load_share: float = 0.55,
    full_relative_speed_mps: float = 0.25,
    max_stance_speed_mps: float = 0.12,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> torch.Tensor:
    """Track the planar command with swing-foot velocity relative to stance foot.

    A forward-falling robot whose two feet translate together receives essentially no
    signal.  A genuinely unloaded foot moving through space relative to an anchored
    stance foot does.  This keeps command direction while making the foot, not the
    pelvis, carry the main early-acquisition directional objective.
    """
    if full_relative_speed_mps <= 0.0 or not 0.0 <= min_clearance_m < full_clearance_factor_m:
        raise ValueError("v6.7 swing-foot command velocity scales invalid")
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    ids = torch.arange(n, device=k["load_share"].device)
    swing = torch.argmin(k["load_share"], dim=1)
    stance = 1 - swing
    swing_vel = k["center_vel"][ids, swing]
    stance_vel = k["center_vel"][ids, stance]
    relative_vel = swing_vel - stance_vel
    directional_speed = torch.sum(relative_vel * k["command_dir"], dim=1)
    speed_score = torch.clamp(directional_speed / float(full_relative_speed_mps), 0.0, 1.0)
    clear = torch.clamp(k["whole_clear"][ids, swing], min=0.0)
    clear_score = torch.clamp(
        (clear - float(min_clearance_m)) / max(float(full_clearance_factor_m) - float(min_clearance_m), 1.0e-6),
        0.0, 1.0,
    )
    # Preserve a small bootstrap at 3 mm, then make directional velocity substantially
    # more valuable once the whole physical foot reaches useful clearance.
    clearance_multiplier = 0.25 + 0.75 * clear_score
    stance_speed = torch.linalg.vector_norm(stance_vel, dim=1)
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    gate = (
        (k["command_norm"] > float(command_threshold))
        & (clear >= float(min_clearance_m))
        & (k["load_share"][ids, swing] <= float(max_swing_load_share))
        & (k["load_share"][ids, stance] >= float(min_stance_load_share))
        & k["full_plant"][ids, stance]
    )
    return speed_score * clearance_multiplier * stance_anchor * k["viability"] * gate.float()


# -----------------------------------------------------------------------------
# LittleGreen v6.8 command-conditioned stride / swing-frontier refinement
# -----------------------------------------------------------------------------
# v6.8 preserves the v6.6 support baton and the v6.7 pickup/foot-relative command
# breakthrough.  It only changes the economics inside an already-active swing:
# commanded planar speed softly scales the useful stride horizon and swing-foot
# velocity, positive velocity is frontier-aware so retreat/re-acceleration cannot be
# paid twice, excessive in-swing backtracking is mildly costly, and touchdown/gait-step
# value remembers how much of the achieved directional progress was retained.


def _v68_refinement_state(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040),
    min_meaningful_clearance_m: float = 0.018, min_meaningful_air_time_s: float = 0.08,
    trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06,
    takeover_load_full: float = 0.55, takeover_com_full: float = 0.68, handoff_load_threshold: float = 0.50,
    handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010,
    continuation_multiplier: float = 1.50, first_multiplier: float = 1.00, event_hold_s: float = 0.06,
    min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10,
    min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45,
    min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014,
    retention_min_progress_m: float = 0.010,
) -> dict[str, torch.Tensor]:
    """Return v6.8 swing-refinement state layered on the v6.6 support baton."""
    if not 0.0 < min_stride_horizon_m <= max_stride_horizon_m:
        raise ValueError("v6.8 stride horizon bounds invalid")
    if not 0.0 < min_swing_speed_mps <= max_swing_speed_mps:
        raise ValueError("v6.8 swing speed bounds invalid")
    if not 0.0 <= frontier_deadband_m < frontier_zero_credit_m:
        raise ValueError("v6.8 frontier deadband must be below zero-credit backtrack")
    if retention_min_progress_m < 0.0:
        raise ValueError("v6.8 retention minimum progress must be non-negative")

    baton = _v66_public_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share,
        start_support_share, start_rise_speed_mps, readiness_load_full, readiness_com_full,
        clearance_milestones, min_meaningful_clearance_m, min_meaningful_air_time_s,
        trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share,
        completion_replant_s, takeover_load_full, takeover_com_full, handoff_load_threshold,
        handoff_com_threshold, handoff_hold_s, takeover_timeout_s, release_air_time_s,
        release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s,
        min_viability, handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg,
        full_height_m, zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    sf = torch.clamp(baton["swing_foot"], min=0, max=1)
    st = torch.clamp(baton["stance_foot"], min=0, max=1)

    cmd_speed = k["command_norm"]
    stride_horizon = torch.clamp(
        float(stride_base_m) + float(stride_gain_s) * cmd_speed,
        min=float(min_stride_horizon_m), max=float(max_stride_horizon_m),
    )
    target_swing_speed = torch.clamp(
        float(swing_speed_base_mps) + float(swing_speed_gain) * cmd_speed,
        min=float(min_swing_speed_mps), max=float(max_swing_speed_mps),
    )

    liftoff_xy = getattr(env, "_littlegreen_v66_liftoff_xy", torch.zeros((n,2), device=device, dtype=dtype))
    liftoff_dir = getattr(env, "_littlegreen_v66_liftoff_dir", k["command_dir"])
    current_progress = torch.sum((k["centers"][ids, sf] - liftoff_xy) * liftoff_dir, dim=1)
    current_progress = torch.clamp(current_progress, min=0.0)
    best_progress = getattr(env, "_littlegreen_v66_best_progress", torch.zeros(n, device=device, dtype=dtype))
    backtrack = torch.relu(best_progress - current_progress)
    frontier_factor = torch.clamp(
        (float(frontier_zero_credit_m) - backtrack)
        / max(float(frontier_zero_credit_m) - float(frontier_deadband_m), 1.0e-6),
        0.0, 1.0,
    )
    frontier_factor = torch.where(backtrack <= float(frontier_deadband_m), torch.ones_like(frontier_factor), frontier_factor)

    # Snapshot touchdown retention exactly once per replant event, then carry it through
    # takeover/handoff so the completed gait step still knows whether the foot kept the
    # directional progress it had already earned in the air.
    retention = getattr(env, "_littlegreen_v68_replant_retention", None)
    touchdown_progress = getattr(env, "_littlegreen_v68_touchdown_progress", None)
    touchdown_peak = getattr(env, "_littlegreen_v68_touchdown_peak_progress", None)
    touchdown_horizon = getattr(env, "_littlegreen_v68_touchdown_stride_horizon", None)
    prev_replant = getattr(env, "_littlegreen_v68_prev_replant_active", None)
    for name, val, default in (
        ("retention", retention, 1.0), ("touchdown_progress", touchdown_progress, 0.0),
        ("touchdown_peak", touchdown_peak, 0.0), ("touchdown_horizon", touchdown_horizon, 0.0),
    ):
        if not isinstance(val, torch.Tensor) or val.shape != (n,) or val.device != device:
            val = torch.full((n,), default, device=device, dtype=dtype)
        if name == "retention": retention = val
        elif name == "touchdown_progress": touchdown_progress = val
        elif name == "touchdown_peak": touchdown_peak = val
        else: touchdown_horizon = val
    if not isinstance(prev_replant, torch.Tensor) or prev_replant.shape != (n,) or prev_replant.device != device:
        prev_replant = torch.zeros(n, device=device, dtype=torch.bool)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v68_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        start_event = getattr(env, "_littlegreen_v66_start_event", torch.zeros((n,2), device=device, dtype=torch.bool))
        new_swing = torch.any(start_event, dim=1)
        retention[:] = torch.where(reset | new_swing, torch.ones_like(retention), retention)
        touchdown_progress[:] = torch.where(reset | new_swing, torch.zeros_like(touchdown_progress), touchdown_progress)
        touchdown_peak[:] = torch.where(reset | new_swing, torch.zeros_like(touchdown_peak), touchdown_peak)
        touchdown_horizon[:] = torch.where(reset | new_swing, torch.zeros_like(touchdown_horizon), touchdown_horizon)

        replant_active = baton["replant"] > 0.0
        new_replant = replant_active & (~prev_replant) & (~reset)
        if torch.any(new_replant):
            peak = best_progress[new_replant]
            cur = current_progress[new_replant]
            good_peak = peak >= float(retention_min_progress_m)
            score = torch.where(
                good_peak,
                torch.clamp(cur / torch.clamp(peak, min=float(retention_min_progress_m)), 0.0, 1.0),
                torch.zeros_like(peak),
            )
            retention[new_replant] = score
            touchdown_progress[new_replant] = cur
            touchdown_peak[new_replant] = peak
            touchdown_horizon[new_replant] = stride_horizon[new_replant]
        prev_replant[:] = replant_active
        env._littlegreen_v68_last_common_step = common_step

    env._littlegreen_v68_replant_retention = retention
    env._littlegreen_v68_touchdown_progress = touchdown_progress
    env._littlegreen_v68_touchdown_peak_progress = touchdown_peak
    env._littlegreen_v68_touchdown_stride_horizon = touchdown_horizon
    env._littlegreen_v68_prev_replant_active = prev_replant
    env._littlegreen_v68_stride_horizon = stride_horizon.detach()
    env._littlegreen_v68_target_swing_speed = target_swing_speed.detach()
    env._littlegreen_v68_current_progress = current_progress.detach()
    env._littlegreen_v68_backtrack = backtrack.detach()
    env._littlegreen_v68_frontier_factor = frontier_factor.detach()

    return {
        "baton": baton, "k": k, "sf": sf, "st": st,
        "stride_horizon": stride_horizon, "target_swing_speed": target_swing_speed,
        "current_progress": current_progress, "best_progress": best_progress,
        "backtrack": backtrack, "frontier_factor": frontier_factor,
        "retention": retention,
    }


def swing_foot_command_velocity_v68(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    min_clearance_m: float = 0.003, full_clearance_factor_m: float = 0.018, max_stance_speed_mps: float = 0.12,
) -> torch.Tensor:
    """Command-conditioned, frontier-aware swing-foot velocity relative to stance."""
    s = _v68_refinement_state(env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m)
    k, sf, st = s["k"], s["sf"], s["st"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)
    rel_vel = k["center_vel"][ids, sf] - k["center_vel"][ids, st]
    directional_speed = torch.sum(rel_vel * k["command_dir"], dim=1)
    speed_score = torch.clamp(directional_speed / torch.clamp(s["target_swing_speed"], min=1.0e-6), 0.0, 1.0)
    clear = torch.clamp(k["whole_clear"][ids, sf], min=0.0)
    clear_score = torch.clamp((clear - float(min_clearance_m)) / max(float(full_clearance_factor_m)-float(min_clearance_m),1e-6),0.0,1.0)
    clearance_multiplier = 0.25 + 0.75 * clear_score
    stance_speed = torch.linalg.vector_norm(k["center_vel"][ids, st], dim=1)
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    gate = ((s["baton"]["stage"] == 1) & (k["command_norm"] > float(command_threshold)) &
            (clear >= float(min_clearance_m)) & (k["load_share"][ids, sf] <= float(start_unload_share)) &
            (k["load_share"][ids, st] >= float(start_support_share)) & k["full_plant"][ids, st])
    return speed_score * s["frontier_factor"] * clearance_multiplier * stance_anchor * k["viability"] * gate.float()



def swing_foot_command_velocity_signed_v92(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    min_clearance_m: float = 0.001, full_clearance_factor_m: float = 0.018, max_stance_speed_mps: float = 0.12,
    wrong_way_scale: float = 0.30, wrong_way_deadband_ratio: float = 0.05,
    require_whole_foot_airborne: bool = True,
) -> torch.Tensor:
    """Signed command-relative swing velocity for v9.2, gated by genuine whole-foot liftoff.

    Positive command-direction motion receives the familiar v6.8 frontier-aware score.
    Command-opposing motion receives only a *mild* signed-negative score so exploratory
    recovery motion remains possible but a lifted foot drifting backward is worse than
    holding still.  Orthogonal motion remains near zero rather than being punished.

    When ``require_whole_foot_airborne`` is true (the v9.2 contract), both the main foot
    and passive toe must be out of contact.  Clearance is the least-cleared component,
    so heel-only or toe-only pickup cannot earn either directional or wrong-way credit.
    """
    if not 0.0 <= float(wrong_way_scale) <= 1.0:
        raise ValueError("v9.2 wrong-way scale must be in [0,1]")
    if not 0.0 <= float(wrong_way_deadband_ratio) < 1.0:
        raise ValueError("v9.2 wrong-way deadband ratio must be in [0,1)")

    s = _v68_refinement_state(env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m)
    k, sf, st = s["k"], s["sf"], s["st"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)

    rel_vel = k["center_vel"][ids, sf] - k["center_vel"][ids, st]
    directional_speed = torch.sum(rel_vel * k["command_dir"], dim=1)
    normalized_speed = directional_speed / torch.clamp(s["target_swing_speed"], min=1.0e-6)

    # Preserve the historical positive frontier-retention semantics.
    positive_score = torch.clamp(normalized_speed, 0.0, 1.0) * s["frontier_factor"]

    # A small deadband avoids charging harmless velocity jitter.  Negative magnitude
    # saturates at wrong_way_scale when command-opposing speed reaches target speed.
    wrong_mag = torch.relu(-normalized_speed - float(wrong_way_deadband_ratio))
    wrong_mag = wrong_mag / max(1.0 - float(wrong_way_deadband_ratio), 1.0e-6)
    negative_score = -float(wrong_way_scale) * torch.clamp(wrong_mag, 0.0, 1.0)
    signed_score = positive_score + negative_score

    clear = torch.clamp(k["whole_clear"][ids, sf], min=0.0)
    clear_score = torch.clamp(
        (clear - float(min_clearance_m)) / max(float(full_clearance_factor_m) - float(min_clearance_m), 1.0e-6),
        0.0, 1.0,
    )
    clearance_multiplier = 0.25 + 0.75 * clear_score
    stance_speed = torch.linalg.vector_norm(k["center_vel"][ids, st], dim=1)
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    whole_foot_airborne = ~k["any_contact"][ids, sf]

    gate = (
        (s["baton"]["stage"] == 1)
        & (k["command_norm"] > float(command_threshold))
        & (clear >= float(min_clearance_m))
        & (k["load_share"][ids, sf] <= float(start_unload_share))
        & (k["load_share"][ids, st] >= float(start_support_share))
        & k["full_plant"][ids, st]
    )
    if require_whole_foot_airborne:
        gate = gate & whole_foot_airborne

    # Analyzer-visible diagnostics; detached so reward bookkeeping cannot retain graphs.
    env._littlegreen_v92_signed_swing_normalized_speed = normalized_speed.detach()
    env._littlegreen_v92_signed_swing_directional_speed = directional_speed.detach()
    env._littlegreen_v92_signed_swing_wrong_way = ((normalized_speed < -float(wrong_way_deadband_ratio)) & gate).detach()
    env._littlegreen_v92_signed_swing_whole_airborne = (whole_foot_airborne & gate).detach()
    env._littlegreen_v92_signed_swing_gate = gate.detach()

    return signed_score * clearance_multiplier * stance_anchor * k["viability"] * gate.float()


# -----------------------------------------------------------------------------
# LittleGreen v9.3 world-frame directional onset / missed-swing adoption
# -----------------------------------------------------------------------------
# v9.2 revealed that the directional on-ramp mixed robot-yaw-frame commands with
# WORLD-frame foot kinematics.  v9.3 fixes that only for the active v9.3 path and
# deliberately leaves historical v6.6-v9.2 task semantics untouched.  It also lets
# the current support baton adopt an already-genuine whole-foot single-support state,
# so a recovery-induced lift is not invisible simply because the exact stage-0 onset
# edge was missed.  No cadence, phase, prescribed leg, or target foothold is added.


def _v93_directional_refinement_state(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    onset_min_clearance_m: float = 0.001,
) -> dict[str, torch.Tensor]:
    """Return v6.8 refinement state after correcting/adopting the v9.3 swing onset.

    The v6.6 support baton remains the owner of support mechanics and alternation.  This
    adapter only guarantees that every v9.3 swing onset has a WORLD-frame direction and
    that an already-airborne physical foot can be adopted when the opposite physical
    foot is a credible planted support.  An adopted state must still satisfy strict
    main+toe whole-foot airborne contact and the existing load/viability constraints.
    """
    if float(onset_min_clearance_m) < 0.0:
        raise ValueError("v9.3 onset clearance must be non-negative")

    baton = _v66_public_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share,
        start_support_share, start_rise_speed_mps, readiness_load_full, readiness_com_full,
        clearance_milestones, min_meaningful_clearance_m, min_meaningful_air_time_s,
        trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share,
        completion_replant_s, takeover_load_full, takeover_com_full, handoff_load_threshold,
        handoff_com_threshold, handoff_hold_s, takeover_timeout_s, release_air_time_s,
        release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s,
        min_viability, handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg,
        full_height_m, zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    moving = k["command_norm"] > float(command_threshold)
    reset = _v10_episode_reset_mask(env, n, device)
    common_step = int(getattr(env, "common_step_counter", 0))
    last_v93_step = int(getattr(env, "_littlegreen_v93_last_directional_common_step", -1))
    first_v93_call_this_step = common_step != last_v93_step

    # State tensors are created by the v6.6 baton above.  Keep a v9.3-only marker so
    # old tasks never reinterpret their historical body-frame liftoff direction.
    stage = getattr(env, "_littlegreen_v66_stage")
    expected_swing = getattr(env, "_littlegreen_v66_expected_swing")
    swing_foot = getattr(env, "_littlegreen_v66_swing_foot")
    stance_foot = getattr(env, "_littlegreen_v66_stance_foot")
    liftoff_xy = getattr(env, "_littlegreen_v66_liftoff_xy")
    liftoff_dir = getattr(env, "_littlegreen_v66_liftoff_dir")
    best_progress = getattr(env, "_littlegreen_v66_best_progress")
    peak_clear = getattr(env, "_littlegreen_v66_peak_clearance")
    max_air = getattr(env, "_littlegreen_v66_max_air_time")
    replant_timer = getattr(env, "_littlegreen_v66_replant_timer")
    milestone_level = getattr(env, "_littlegreen_v66_milestone_level")
    swing_multiplier = getattr(env, "_littlegreen_v66_swing_multiplier")
    readiness_best = getattr(env, "_littlegreen_v66_readiness_best")

    dir_valid = getattr(env, "_littlegreen_v93_liftoff_dir_world_valid", None)
    if not isinstance(dir_valid, torch.Tensor) or dir_valid.shape != (n,) or dir_valid.device != device:
        dir_valid = torch.zeros(n, device=device, dtype=torch.bool)
        env._littlegreen_v93_liftoff_dir_world_valid = dir_valid

    start_event = getattr(env, "_littlegreen_v66_start_event", None)
    if not isinstance(start_event, torch.Tensor) or start_event.shape != (n, 2) or start_event.device != device:
        start_event = torch.zeros((n, 2), device=device, dtype=torch.bool)

    # Natural v6.6 onset: overwrite only the v9.3-active liftoff direction with the
    # yaw-rotated WORLD direction before downstream v6.8/v7.2 geometry sees it.
    # This adapter is called by several RewardManager terms in the same simulation
    # step, so onset mutation/diagnostics are performed exactly once per common step.
    natural_start_event = torch.zeros((n, 2), device=device, dtype=torch.bool)
    if first_v93_call_this_step:
        natural_start_event = start_event.clone()
        natural_start = torch.any(natural_start_event, dim=1) & moving & (~reset)
        if torch.any(natural_start):
            liftoff_dir[natural_start] = k["command_dir_world"][natural_start]
            dir_valid[natural_start] = True

    whole_airborne = ~k["any_contact"]  # both main and toe are out of contact
    exactly_one_airborne = torch.logical_xor(whole_airborne[:, 0], whole_airborne[:, 1])
    candidate_swing = torch.argmax(whole_airborne.long(), dim=1)
    candidate_stance = 1 - candidate_swing
    candidate_clear = k["whole_clear"][ids, candidate_swing]
    candidate_swing_share = k["load_share"][ids, candidate_swing]
    candidate_stance_share = k["load_share"][ids, candidate_stance]
    expected_ok = (expected_swing < 0) | (candidate_swing == expected_swing)

    # Adopt a legitimate whole-foot single-support state that the edge-triggered baton
    # missed.  This is especially useful for recovery-induced liftoff.  We do NOT award
    # retroactive initiation milestones: milestone_level is initialized to the highest
    # clearance milestone already crossed, so only future progress can earn new credit.
    adopt = (
        first_v93_call_this_step
        & (stage == 0)
        & moving
        & (~reset)
        & exactly_one_airborne
        & expected_ok
        & (k["viability"] >= float(min_viability))
        & (candidate_clear >= float(onset_min_clearance_m))
        & (candidate_swing_share <= float(start_unload_share))
        & (candidate_stance_share >= float(start_support_share))
        & k["full_plant"][ids, candidate_stance]
    )

    # Rare fallback: if a stage-1 state exists without a v9.3 world-direction marker
    # (for example after a hot-started environment), re-anchor it at the current whole-
    # foot position rather than allowing an unknown body/world projection to persist.
    sf_now = torch.clamp(swing_foot, min=0, max=1)
    st_now = torch.clamp(stance_foot, min=0, max=1)
    fallback = (
        first_v93_call_this_step
        & (stage == 1)
        & moving
        & (~reset)
        & (~dir_valid)
        & (k["viability"] >= float(min_viability))
        & whole_airborne[ids, sf_now]
        & (k["whole_clear"][ids, sf_now] >= float(onset_min_clearance_m))
        & (k["load_share"][ids, sf_now] <= float(start_unload_share))
        & (k["load_share"][ids, st_now] >= float(start_support_share))
        & k["full_plant"][ids, st_now]
    )
    adopt = adopt | fallback

    adopted_start_event = torch.zeros((n, 2), device=device, dtype=torch.bool)
    if torch.any(adopt):
        aid = ids[adopt]
        af = torch.where(fallback[adopt], sf_now[adopt], candidate_swing[adopt])
        ast = 1 - af
        stage[adopt] = 1
        swing_foot[adopt] = af
        stance_foot[adopt] = ast
        swing_multiplier[adopt] = 1.0
        readiness_best[adopt] = 0.0
        liftoff_xy[adopt] = k["centers"][aid, af]
        liftoff_dir[adopt] = k["command_dir_world"][adopt]
        best_progress[adopt] = 0.0
        peak_clear[adopt] = torch.clamp(k["whole_clear"][aid, af], min=0.0)
        max_air[adopt] = k["whole_air"][aid, af]
        replant_timer[adopt] = 0.0

        # Do not back-pay lift milestones already achieved before adoption.
        level = torch.ones_like(af, dtype=torch.long)
        for level_id, threshold in enumerate(tuple(float(x) for x in clearance_milestones), start=2):
            level = torch.where(peak_clear[adopt] >= threshold, torch.full_like(level, level_id), level)
        milestone_level[adopt] = level
        adopted_start_event[aid, af] = True
        start_event = start_event | adopted_start_event
        dir_valid[adopt] = True

    # Clear the v9.3 frame marker only when no swing/takeover is active.  Keeping it
    # through stage 2 lets replant-retention and passage completion use the same onset
    # direction that governed the airborne trajectory.
    clear_marker = ((stage == 0) & (~adopt)) | (~moving) | reset
    dir_valid[clear_marker] = False

    env._littlegreen_v66_stage = stage
    env._littlegreen_v66_swing_foot = swing_foot
    env._littlegreen_v66_stance_foot = stance_foot
    env._littlegreen_v66_liftoff_xy = liftoff_xy
    env._littlegreen_v66_liftoff_dir = liftoff_dir
    env._littlegreen_v66_best_progress = best_progress
    env._littlegreen_v66_peak_clearance = peak_clear
    env._littlegreen_v66_max_air_time = max_air
    env._littlegreen_v66_replant_timer = replant_timer
    env._littlegreen_v66_milestone_level = milestone_level
    env._littlegreen_v66_swing_multiplier = swing_multiplier
    env._littlegreen_v66_readiness_best = readiness_best
    env._littlegreen_v66_start_event = start_event.detach()
    env._littlegreen_v93_liftoff_dir_world_valid = dir_valid
    if first_v93_call_this_step:
        env._littlegreen_v93_adopted_start_event = adopted_start_event.detach()
        env._littlegreen_v93_natural_start_event = natural_start_event.detach()
        env._littlegreen_v93_last_directional_common_step = common_step

    # Recompute the v6.8 refinement state *after* the direction repair/adoption.  Since
    # the v6.6 common-step state is already current, this is inexpensive and guarantees
    # its progress/backtrack/retention projections use the corrected WORLD direction.
    ref = _v68_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m,
    )

    sf = ref["sf"]
    st = ref["st"]
    signed_progress = torch.sum(
        (ref["k"]["centers"][ids, sf] - getattr(env, "_littlegreen_v66_liftoff_xy"))
        * getattr(env, "_littlegreen_v66_liftoff_dir"),
        dim=1,
    )
    frame_cos = torch.sum(
        getattr(env, "_littlegreen_v66_liftoff_dir") * ref["k"]["command_dir_world"], dim=1
    )
    env._littlegreen_v93_signed_liftoff_progress_m = signed_progress.detach()
    env._littlegreen_v93_direction_frame_cosine = frame_cos.detach()
    return ref


def swing_foot_command_velocity_signed_v93(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    min_clearance_m: float = 0.001, full_clearance_factor_m: float = 0.018, max_stance_speed_mps: float = 0.12,
    wrong_way_scale: float = 0.30, wrong_way_deadband_ratio: float = 0.05, onset_min_clearance_m: float = 0.001,
    require_whole_foot_airborne: bool = True,
) -> torch.Tensor:
    """v9.3 signed swing velocity in one consistent WORLD-frame onset direction."""
    if not 0.0 <= float(wrong_way_scale) <= 1.0:
        raise ValueError("v9.3 wrong-way scale must be in [0,1]")
    if not 0.0 <= float(wrong_way_deadband_ratio) < 1.0:
        raise ValueError("v9.3 wrong-way deadband ratio must be in [0,1)")
    if full_clearance_factor_m <= min_clearance_m:
        raise ValueError("v9.3 clearance factor must exceed minimum clearance")

    s = _v93_directional_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m, onset_min_clearance_m,
    )
    k, sf, st = s["k"], s["sf"], s["st"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)
    liftoff_dir_world = getattr(env, "_littlegreen_v66_liftoff_dir")
    rel_vel = k["center_vel"][ids, sf] - k["center_vel"][ids, st]
    directional_speed = torch.sum(rel_vel * liftoff_dir_world, dim=1)
    normalized_speed = directional_speed / torch.clamp(s["target_swing_speed"], min=1.0e-6)

    positive_score = torch.clamp(normalized_speed, 0.0, 1.0) * s["frontier_factor"]
    wrong_mag = torch.relu(-normalized_speed - float(wrong_way_deadband_ratio))
    wrong_mag = wrong_mag / max(1.0 - float(wrong_way_deadband_ratio), 1.0e-6)
    negative_score = -float(wrong_way_scale) * torch.clamp(wrong_mag, 0.0, 1.0)
    signed_score = positive_score + negative_score

    clear = torch.clamp(k["whole_clear"][ids, sf], min=0.0)
    clear_score = torch.clamp(
        (clear - float(min_clearance_m)) / max(float(full_clearance_factor_m) - float(min_clearance_m), 1.0e-6),
        0.0, 1.0,
    )
    clearance_multiplier = 0.25 + 0.75 * clear_score
    stance_speed = torch.linalg.vector_norm(k["center_vel"][ids, st], dim=1)
    stance_anchor = torch.clamp(1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0)
    whole_foot_airborne = ~k["any_contact"][ids, sf]
    gate = (
        (s["baton"]["stage"] == 1)
        & (k["command_norm"] > float(command_threshold))
        & (clear >= float(min_clearance_m))
        & (k["load_share"][ids, sf] <= float(start_unload_share))
        & (k["load_share"][ids, st] >= float(start_support_share))
        & k["full_plant"][ids, st]
    )
    if require_whole_foot_airborne:
        gate = gate & whole_foot_airborne

    env._littlegreen_v93_signed_swing_normalized_speed = normalized_speed.detach()
    env._littlegreen_v93_signed_swing_directional_speed = directional_speed.detach()
    env._littlegreen_v93_signed_swing_wrong_way = ((normalized_speed < -float(wrong_way_deadband_ratio)) & gate).detach()
    env._littlegreen_v93_signed_swing_whole_airborne = (whole_foot_airborne & gate).detach()
    env._littlegreen_v93_signed_swing_gate = gate.detach()
    return signed_score * clearance_multiplier * stance_anchor * k["viability"] * gate.float()


def command_conditioned_directional_swing_progress_v93(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    onset_min_clearance_m: float = 0.001,
) -> torch.Tensor:
    """v9.3 finite new-best progress after WORLD-frame onset repair/adoption."""
    s = _v93_directional_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m, onset_min_clearance_m,
    )
    base_delta = s["baton"]["trajectory"]
    mult = getattr(env, "_littlegreen_v66_swing_multiplier", torch.ones_like(base_delta))
    denom = torch.clamp(mult * s["k"]["viability"], min=1.0e-6)
    raw_increment = base_delta * float(full_trajectory_progress_m) / denom
    prev_best = torch.relu(s["best_progress"] - raw_increment)
    available = torch.relu(s["stride_horizon"] - prev_best)
    used = torch.minimum(raw_increment, available)
    return (used / torch.clamp(s["stride_horizon"], min=1.0e-6)) * mult * s["k"]["viability"]


def swing_backtrack_penalty_v93(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    min_frontier_m: float = 0.020, full_backtrack_m: float = 0.025, onset_min_clearance_m: float = 0.001,
) -> torch.Tensor:
    """Historical backtrack protection after v9.3 WORLD-frame onset repair."""
    s = _v93_directional_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m, onset_min_clearance_m,
    )
    if not frontier_deadband_m < full_backtrack_m:
        raise ValueError("v9.3 full backtrack must exceed the deadband")
    score = torch.clamp(
        (s["backtrack"] - float(frontier_deadband_m)) /
        max(float(full_backtrack_m) - float(frontier_deadband_m), 1.0e-6),
        0.0, 1.0,
    )
    ids = torch.arange(s["k"]["load_share"].shape[0], device=s["k"]["load_share"].device)
    whole_airborne = ~s["k"]["any_contact"][ids, s["sf"]]
    gate = (
        (s["baton"]["stage"] == 1)
        & (s["best_progress"] >= float(min_frontier_m))
        & (s["k"]["command_norm"] > float(command_threshold))
        & whole_airborne
    )
    return score * s["k"]["viability"] * gate.float()


def whole_foot_swing_behind_liftoff_penalty_v93(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.45, start_support_share: float = 0.55,
    start_rise_speed_mps: float = 0.030, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.003,0.010,0.022,0.040), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.008, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.50, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.400, zero_height_m: float = 0.340,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.45, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.34,
    frontier_deadband_m: float = 0.006, frontier_zero_credit_m: float = 0.014, retention_min_progress_m: float = 0.010,
    onset_min_clearance_m: float = 0.001, behind_deadband_m: float = 0.002, full_behind_m: float = 0.020,
) -> torch.Tensor:
    """Penalize a genuinely airborne physical foot for moving behind its liftoff point.

    Signed displacement is measured in WORLD space along the command direction captured
    at liftoff.  A 2 mm deadband ignores harmless jitter; the raw penalty ramps to 1 by
    20 mm behind onset.  Unlike the historical backtrack term this works even if the
    foot never established any positive frontier first, closing the slow-backward-drift
    loophole observed in v9.1/v9.2.
    """
    if not 0.0 <= float(behind_deadband_m) < float(full_behind_m):
        raise ValueError("v9.3 behind-liftoff bounds invalid")
    s = _v93_directional_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m, onset_min_clearance_m,
    )
    k, sf, st = s["k"], s["sf"], s["st"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)
    signed_progress = getattr(env, "_littlegreen_v93_signed_liftoff_progress_m")
    behind = torch.relu(-signed_progress - float(behind_deadband_m))
    raw = torch.clamp(
        behind / max(float(full_behind_m) - float(behind_deadband_m), 1.0e-6), 0.0, 1.0
    )
    clear = torch.clamp(k["whole_clear"][ids, sf], min=0.0)
    whole_airborne = ~k["any_contact"][ids, sf]
    gate = (
        (s["baton"]["stage"] == 1)
        & (k["command_norm"] > float(command_threshold))
        & whole_airborne
        & (clear >= float(onset_min_clearance_m))
        & (k["load_share"][ids, sf] <= float(start_unload_share))
        & (k["load_share"][ids, st] >= float(start_support_share))
        & k["full_plant"][ids, st]
    )
    env._littlegreen_v93_behind_liftoff_raw = (raw * gate.float()).detach()
    env._littlegreen_v93_behind_liftoff_gate = gate.detach()
    return raw * k["viability"] * gate.float()




# =============================================================================
# LittleGreen v9.4 prepared-onset whole-foot swing / COM-transfer correction
# =============================================================================
# v9.3 fixed the command/world-frame mismatch, but analysis + video showed that most
# recognized swing onsets were recovery-induced adoptions rather than deliberate gait
# onsets.  v9.4 removes arbitrary recovery adoption from the positive gait path.  A
# missed edge may be rescued only if bilateral support was credibly PREPARED first:
# load transferred to one planted physical foot and COM moved toward that same support.
# Instantaneous swing velocity follows the LIVE world command; displacement/frontier
# terms retain the fixed world command captured at the prepared liftoff event.


def _v94_prepared_directional_state(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, start_unload_share: float = 0.40, start_support_share: float = 0.60,
    start_rise_speed_mps: float = 0.020, readiness_load_full: float = 0.68, readiness_com_full: float = 0.68,
    clearance_milestones: tuple[float,float,float,float] = (0.001,0.004,0.010,0.018), min_meaningful_clearance_m: float = 0.018,
    min_meaningful_air_time_s: float = 0.08, trajectory_start_clearance_m: float = 0.006, full_trajectory_progress_m: float = 0.040,
    completion_load_share: float = 0.25, completion_replant_s: float = 0.06, takeover_load_full: float = 0.55, takeover_com_full: float = 0.68,
    handoff_load_threshold: float = 0.50, handoff_com_threshold: float = 0.56, handoff_hold_s: float = 0.08, takeover_timeout_s: float = 0.80,
    release_air_time_s: float = 0.04, release_clearance_m: float = 0.010, continuation_multiplier: float = 1.00, first_multiplier: float = 1.00,
    event_hold_s: float = 0.06, min_viability: float = 0.45, handoff_min_viability: float = 0.60, bodies_per_foot: int = 2,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.395, zero_height_m: float = 0.335,
    stride_base_m: float = 0.025, stride_gain_s: float = 0.10, min_stride_horizon_m: float = 0.030, max_stride_horizon_m: float = 0.070,
    swing_speed_base_mps: float = 0.12, swing_speed_gain: float = 0.60, min_swing_speed_mps: float = 0.15, max_swing_speed_mps: float = 0.38,
    frontier_deadband_m: float = 0.005, frontier_zero_credit_m: float = 0.012, retention_min_progress_m: float = 0.010,
    onset_min_clearance_m: float = 0.001,
    prepared_stance_load_share: float = 0.60, prepared_swing_max_load_share: float = 0.40,
    prepared_com_closeness: float = 0.56, prepared_hold_s: float = 0.12,
) -> dict[str, torch.Tensor]:
    """Return v6.8 refinement state, but only after a prepared gait onset.

    Natural v6.6 onsets are accepted only when the robot has already shifted load and
    COM toward the chosen planted stance foot.  A missed contact edge can be rescued for
    a short window only when that same prepared state was observed immediately before
    whole-foot departure.  Arbitrary recovery-induced single support is diagnostic only
    and receives no v9.4 swing/passage/air-time income.
    """
    if not 0.5 < float(prepared_stance_load_share) < 1.0:
        raise ValueError("v9.4 prepared stance load must exceed 0.5")
    if not 0.0 <= float(prepared_swing_max_load_share) < 0.5:
        raise ValueError("v9.4 prepared swing load must be below 0.5")
    if not 0.5 < float(prepared_com_closeness) <= 1.0 or float(prepared_hold_s) <= 0.0:
        raise ValueError("v9.4 prepared COM/hold parameters invalid")

    baton = _v66_public_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share,
        start_support_share, start_rise_speed_mps, readiness_load_full, readiness_com_full,
        clearance_milestones, min_meaningful_clearance_m, min_meaningful_air_time_s,
        trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share,
        completion_replant_s, takeover_load_full, takeover_com_full, handoff_load_threshold,
        handoff_com_threshold, handoff_hold_s, takeover_timeout_s, release_air_time_s,
        release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s,
        min_viability, handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg,
        full_height_m, zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    moving = k["command_norm"] > float(command_threshold)
    reset = _v10_episode_reset_mask(env, n, device)
    dt = float(getattr(env, "step_dt", 0.02))
    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v94_last_directional_common_step", -1))
    first_call = common_step != last_step

    stage = getattr(env, "_littlegreen_v66_stage")
    expected_swing = getattr(env, "_littlegreen_v66_expected_swing")
    swing_foot = getattr(env, "_littlegreen_v66_swing_foot")
    stance_foot = getattr(env, "_littlegreen_v66_stance_foot")
    liftoff_xy = getattr(env, "_littlegreen_v66_liftoff_xy")
    liftoff_dir = getattr(env, "_littlegreen_v66_liftoff_dir")
    best_progress = getattr(env, "_littlegreen_v66_best_progress")
    peak_clear = getattr(env, "_littlegreen_v66_peak_clearance")
    max_air = getattr(env, "_littlegreen_v66_max_air_time")
    replant_timer = getattr(env, "_littlegreen_v66_replant_timer")
    milestone_level = getattr(env, "_littlegreen_v66_milestone_level")
    swing_multiplier = getattr(env, "_littlegreen_v66_swing_multiplier")
    readiness_best = getattr(env, "_littlegreen_v66_readiness_best")

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    gait_valid = _state("_littlegreen_v94_prepared_gait_valid", (n,), False, torch.bool)
    dir_valid = _state("_littlegreen_v94_liftoff_dir_world_valid", (n,), False, torch.bool)
    prepared_swing = _state("_littlegreen_v94_prepared_swing", (n,), -1, torch.long)
    prepared_stance = _state("_littlegreen_v94_prepared_stance", (n,), -1, torch.long)
    prepared_ttl = _state("_littlegreen_v94_prepared_ttl", (n,), 0.0)
    prepared_quality = _state("_littlegreen_v94_prepared_quality", (n,), 0.0)

    start_event = getattr(env, "_littlegreen_v66_start_event", None)
    if not isinstance(start_event, torch.Tensor) or start_event.shape != (n, 2) or start_event.device != device:
        start_event = torch.zeros((n, 2), device=device, dtype=torch.bool)

    accepted_natural_event = torch.zeros((n, 2), device=device, dtype=torch.bool)
    prepared_rescue_event = torch.zeros((n, 2), device=device, dtype=torch.bool)
    rejected_unprepared_event = torch.zeros((n, 2), device=device, dtype=torch.bool)
    unprepared_recovery_mask = torch.zeros(n, device=device, dtype=torch.bool)

    if first_call:
        prepared_ttl[:] = torch.clamp(prepared_ttl - dt, min=0.0)
        prepared_quality[:] = torch.where(prepared_ttl > 0.0, prepared_quality, torch.zeros_like(prepared_quality))
        prepared_swing[:] = torch.where(prepared_ttl > 0.0, prepared_swing, torch.full_like(prepared_swing, -1))
        prepared_stance[:] = torch.where(prepared_ttl > 0.0, prepared_stance, torch.full_like(prepared_stance, -1))

        natural_any = torch.any(start_event, dim=1) & moving & (~reset)
        free_stance = torch.argmax(k["load_share"], dim=1)
        baton_stance = 1 - torch.clamp(expected_swing, min=0, max=1)
        cand_stance = torch.where(expected_swing >= 0, baton_stance, free_stance)
        cand_swing = 1 - cand_stance
        stance_share = k["load_share"][ids, cand_stance]
        swing_share = k["load_share"][ids, cand_swing]
        stance_close = k["closeness"][ids, cand_stance]
        bilateral = k["full_plant"][:, 0] & k["full_plant"][:, 1]
        prep = (
            moving & (~reset) & bilateral & (k["viability"] >= float(min_viability))
            & (stance_share >= float(prepared_stance_load_share))
            & (swing_share <= float(prepared_swing_max_load_share))
            & (stance_close >= float(prepared_com_closeness))
        )
        load_score = torch.clamp(
            (stance_share - 0.5) / max(float(readiness_load_full) - 0.5, 1.0e-6), 0.0, 1.0
        )
        com_score = torch.clamp(
            (stance_close - 0.5) / max(float(readiness_com_full) - 0.5, 1.0e-6), 0.0, 1.0
        )
        prep_quality_now = torch.clamp(0.65 * load_score + 0.35 * com_score, 0.0, 1.0)
        if torch.any(prep):
            prepared_swing[prep] = cand_swing[prep]
            prepared_stance[prep] = cand_stance[prep]
            prepared_ttl[prep] = float(prepared_hold_s)
            prepared_quality[prep] = prep_quality_now[prep]

        # Accept the ordinary v6.6 onset only when the actual chosen support already
        # satisfies the same causal load+COM preparation.  This prevents a recovery
        # unload from being re-labelled as a gait step merely because a foot left ground.
        natural_sf = torch.argmax(start_event.long(), dim=1)
        natural_st = 1 - natural_sf
        natural_prepared = (
            natural_any
            & (k["load_share"][ids, natural_st] >= float(prepared_stance_load_share))
            & (k["load_share"][ids, natural_sf] <= float(prepared_swing_max_load_share))
            & (k["closeness"][ids, natural_st] >= float(prepared_com_closeness))
            & k["full_plant"][ids, natural_st]
        )
        if torch.any(natural_prepared):
            nid = ids[natural_prepared]
            nf = natural_sf[natural_prepared]
            accepted_natural_event[nid, nf] = True
            liftoff_dir[natural_prepared] = k["command_dir_world"][natural_prepared]
            dir_valid[natural_prepared] = True
            gait_valid[natural_prepared] = True
            prepared_ttl[natural_prepared] = 0.0

        rejected = natural_any & (~natural_prepared)
        if torch.any(rejected):
            rid = ids[rejected]
            rf = natural_sf[rejected]
            rejected_unprepared_event[rid, rf] = True
            stage[rejected] = 0
            swing_foot[rejected] = -1
            stance_foot[rejected] = -1
            milestone_level[rejected] = 0
            swing_multiplier[rejected] = 1.0
            readiness_best[rejected] = 0.0
            best_progress[rejected] = 0.0
            peak_clear[rejected] = 0.0
            max_air[rejected] = 0.0
            replant_timer[rejected] = 0.0
            gait_valid[rejected] = False
            dir_valid[rejected] = False
            start_event[rejected] = False

        # Rescue only a missed contact edge from a recently prepared bilateral state.
        # Unlike v9.3, arbitrary recovery single support is never adopted.
        whole_airborne = ~k["any_contact"]
        exactly_one_airborne = torch.logical_xor(whole_airborne[:, 0], whole_airborne[:, 1])
        airborne_foot = torch.argmax(whole_airborne.long(), dim=1)
        support_foot = 1 - airborne_foot
        expected_ok = (expected_swing < 0) | (airborne_foot == expected_swing)
        rescue = (
            (stage == 0) & moving & (~reset) & exactly_one_airborne & expected_ok
            & (prepared_ttl > 0.0) & (prepared_swing == airborne_foot)
            & (prepared_stance == support_foot)
            & (k["viability"] >= float(min_viability))
            & (k["whole_clear"][ids, airborne_foot] >= float(onset_min_clearance_m))
            & (k["load_share"][ids, airborne_foot] <= float(start_unload_share))
            & (k["load_share"][ids, support_foot] >= float(start_support_share))
            & k["full_plant"][ids, support_foot]
        )
        if torch.any(rescue):
            q = torch.clamp(prepared_quality[rescue], 0.35, 1.0)
            aid = ids[rescue]
            af = airborne_foot[rescue]
            ast = support_foot[rescue]
            stage[rescue] = 1
            swing_foot[rescue] = af
            stance_foot[rescue] = ast
            swing_multiplier[rescue] = q
            readiness_best[rescue] = 0.0
            liftoff_xy[rescue] = k["centers"][aid, af]
            liftoff_dir[rescue] = k["command_dir_world"][rescue]
            best_progress[rescue] = 0.0
            peak_clear[rescue] = torch.clamp(k["whole_clear"][aid, af], min=0.0)
            max_air[rescue] = k["whole_air"][aid, af]
            replant_timer[rescue] = 0.0
            level = torch.ones_like(af, dtype=torch.long)
            for level_id, threshold in enumerate(tuple(float(x) for x in clearance_milestones), start=2):
                level = torch.where(peak_clear[rescue] >= threshold, torch.full_like(level, level_id), level)
            milestone_level[rescue] = level
            prepared_rescue_event[aid, af] = True
            start_event = start_event | prepared_rescue_event
            gait_valid[rescue] = True
            dir_valid[rescue] = True
            prepared_ttl[rescue] = 0.0

        # If a stage-1 swing somehow exists without a prepared v9.4 marker, drop it
        # immediately.  This is the explicit v9.4 rejection of recovery-step credit.
        orphan = (stage == 1) & (~gait_valid)
        if torch.any(orphan):
            stage[orphan] = 0
            swing_foot[orphan] = -1
            stance_foot[orphan] = -1
            milestone_level[orphan] = 0
            swing_multiplier[orphan] = 1.0
            readiness_best[orphan] = 0.0
            best_progress[orphan] = 0.0
            peak_clear[orphan] = 0.0
            max_air[orphan] = 0.0
            replant_timer[orphan] = 0.0
            dir_valid[orphan] = False

        whole_airborne_now = ~k["any_contact"]
        one_air_now = torch.logical_xor(whole_airborne_now[:, 0], whole_airborne_now[:, 1])
        unprepared_recovery_mask = (
            moving & (~reset) & one_air_now & (stage == 0) & (prepared_ttl <= 0.0)
        )

        clear = (stage == 0) | (~moving) | reset
        gait_valid[clear] = False
        dir_valid[clear] = False
        prepared_ttl[(~moving) | reset] = 0.0
        prepared_swing[(~moving) | reset] = -1
        prepared_stance[(~moving) | reset] = -1
        prepared_quality[(~moving) | reset] = 0.0

        env._littlegreen_v66_stage = stage
        env._littlegreen_v66_swing_foot = swing_foot
        env._littlegreen_v66_stance_foot = stance_foot
        env._littlegreen_v66_liftoff_xy = liftoff_xy
        env._littlegreen_v66_liftoff_dir = liftoff_dir
        env._littlegreen_v66_best_progress = best_progress
        env._littlegreen_v66_peak_clearance = peak_clear
        env._littlegreen_v66_max_air_time = max_air
        env._littlegreen_v66_replant_timer = replant_timer
        env._littlegreen_v66_milestone_level = milestone_level
        env._littlegreen_v66_swing_multiplier = swing_multiplier
        env._littlegreen_v66_readiness_best = readiness_best
        env._littlegreen_v66_start_event = start_event.detach()
        env._littlegreen_v94_prepared_gait_valid = gait_valid
        env._littlegreen_v94_liftoff_dir_world_valid = dir_valid
        env._littlegreen_v94_prepared_swing = prepared_swing
        env._littlegreen_v94_prepared_stance = prepared_stance
        env._littlegreen_v94_prepared_ttl = prepared_ttl
        env._littlegreen_v94_prepared_quality = prepared_quality
        env._littlegreen_v94_accepted_natural_start_event = accepted_natural_event.detach()
        env._littlegreen_v94_prepared_rescue_start_event = prepared_rescue_event.detach()
        env._littlegreen_v94_rejected_unprepared_start_event = rejected_unprepared_event.detach()
        env._littlegreen_v94_unprepared_recovery_single_support = unprepared_recovery_mask.detach()
        env._littlegreen_v94_preparation_gate = prep.detach()
        env._littlegreen_v94_preparation_quality = prep_quality_now.detach()
        env._littlegreen_v94_last_directional_common_step = common_step

    ref = _v68_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, start_unload_share, start_support_share,
        start_rise_speed_mps, readiness_load_full, readiness_com_full, clearance_milestones, min_meaningful_clearance_m,
        min_meaningful_air_time_s, trajectory_start_clearance_m, full_trajectory_progress_m, completion_load_share, completion_replant_s,
        takeover_load_full, takeover_com_full, handoff_load_threshold, handoff_com_threshold, handoff_hold_s, takeover_timeout_s,
        release_air_time_s, release_clearance_m, continuation_multiplier, first_multiplier, event_hold_s, min_viability,
        handoff_min_viability, bodies_per_foot, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m, stride_base_m, stride_gain_s,
        min_stride_horizon_m, max_stride_horizon_m, swing_speed_base_mps, swing_speed_gain, min_swing_speed_mps, max_swing_speed_mps,
        frontier_deadband_m, frontier_zero_credit_m, retention_min_progress_m,
    )
    sf = ref["sf"]
    signed_progress = torch.sum(
        (ref["k"]["centers"][ids, sf] - getattr(env, "_littlegreen_v66_liftoff_xy"))
        * getattr(env, "_littlegreen_v66_liftoff_dir"), dim=1,
    )
    frame_cos = torch.sum(
        getattr(env, "_littlegreen_v66_liftoff_dir") * ref["k"]["command_dir_world"], dim=1
    )
    env._littlegreen_v94_signed_liftoff_progress_m = signed_progress.detach()
    env._littlegreen_v94_onset_to_live_direction_cosine = frame_cos.detach()
    ref["gait_valid"] = getattr(env, "_littlegreen_v94_prepared_gait_valid")
    return ref


