def completed_gait_step_translation_v69(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, support_progress_base_m: float = 0.010, support_progress_gain_s: float = 0.067,
    min_support_progress_horizon_m: float = 0.015, max_support_progress_horizon_m: float = 0.040,
    com_progress_base_m: float = 0.010, com_progress_gain_s: float = 0.067,
    min_com_progress_horizon_m: float = 0.015, max_com_progress_horizon_m: float = 0.040,
    post_touchdown_deadband_m: float = 0.005, post_touchdown_full_retreat_m: float = 0.015,
    handoff_retention_min_progress_m: float = 0.010, direction_continuity_cos_min: float = 0.50,
    translation_event_hold_s: float = 0.06, minimum_multiplier: float = 0.60,
) -> torch.Tensor:
    """Preserve the high-value gait-step event but evaluate retention at handoff."""
    if not 0.0 <= minimum_multiplier <= 1.0:
        raise ValueError("v6.9 gait-step retention multiplier must lie in [0,1]")
    s = _v69_translation_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, support_progress_base_m, support_progress_gain_s,
        min_support_progress_horizon_m, max_support_progress_horizon_m, com_progress_base_m, com_progress_gain_s,
        min_com_progress_horizon_m, max_com_progress_horizon_m, post_touchdown_deadband_m, post_touchdown_full_retreat_m,
        handoff_retention_min_progress_m, direction_continuity_cos_min, translation_event_hold_s,
    )
    mult = float(minimum_multiplier) + (1.0 - float(minimum_multiplier)) * s["handoff_retention"]
    return s["baton"]["gait_step"] * mult



# =============================================================================
# LittleGreen v9.5 v6.8 rebase: frame-corrected directional gait acquisition
# =============================================================================
# v9.5 intentionally returns to the proven v6.8 support-baton gait acquisition
# rather than extending the v9.1-v9.4 sparse/prepared-only reward stack.  The only
# structural correction inside the v6.8 swing chain is coordinate-frame hygiene:
# velocity commands are yaw/body-frame, while foot positions and velocities are
# world-frame.  At each v6.6/v6.8 start event we replace the historical local
# liftoff direction with the equivalent WORLD direction before any later swing
# displacement is accumulated.  Historical v6.x tasks are left untouched.


def _v95_frame_corrected_v68_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
) -> dict[str, torch.Tensor]:
    """Return v6.8 state with the active swing's liftoff direction in WORLD XY.

    The v6.6 baton stores ``_littlegreen_v66_liftoff_dir`` at the instant a swing
    starts.  Historical v6.8 stored the body/yaw-frame command directly even though
    later foot displacement is measured from ``body_pos_w``.  v9.5 repairs the
    state exactly on the start event, before the first whole-foot airborne
    trajectory sample can occur.  This preserves the successful v6.8 gait state
    machine and economics while making forward/reverse/lateral/diagonal commands
    yaw-invariant.
    """
    params = dict(v68_params)
    s = _v68_refinement_state(
        env, command_name, sensor_cfg, asset_cfg, **params
    )
    k = s["k"]
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    ids = torch.arange(n, device=device)

    start_event = getattr(
        env, "_littlegreen_v66_start_event",
        torch.zeros((n, 2), device=device, dtype=torch.bool),
    )
    new_start = torch.any(start_event, dim=1)
    liftoff_dir = getattr(env, "_littlegreen_v66_liftoff_dir", None)
    if isinstance(liftoff_dir, torch.Tensor) and liftoff_dir.shape == (n, 2):
        if torch.any(new_start):
            liftoff_dir[new_start] = k["command_dir_world"][new_start]
            env._littlegreen_v66_liftoff_dir = liftoff_dir

        # Recompute the public v6.8 frontier diagnostics from the corrected fixed
        # world direction.  The v6.6 trajectory event is zero on the start frame
        # because start requires the physical foot to still have contact, so no
        # directional reward is lost before this correction is installed.
        sf = s["sf"]
        liftoff_xy = getattr(
            env, "_littlegreen_v66_liftoff_xy",
            torch.zeros((n, 2), device=device, dtype=k["centers"].dtype),
        )
        raw_progress = torch.sum(
            (k["centers"][ids, sf] - liftoff_xy) * liftoff_dir, dim=1
        )
        current_progress = torch.clamp(raw_progress, min=0.0)
        best_progress = getattr(
            env, "_littlegreen_v66_best_progress",
            torch.zeros(n, device=device, dtype=current_progress.dtype),
        )
        deadband = float(params.get("frontier_deadband_m", 0.006))
        zero_credit = float(params.get("frontier_zero_credit_m", 0.014))
        backtrack = torch.relu(best_progress - current_progress)
        frontier_factor = torch.clamp(
            (zero_credit - backtrack) / max(zero_credit - deadband, 1.0e-6),
            0.0, 1.0,
        )
        frontier_factor = torch.where(
            backtrack <= deadband, torch.ones_like(frontier_factor), frontier_factor
        )
        s["current_progress"] = current_progress
        s["backtrack"] = backtrack
        s["frontier_factor"] = frontier_factor
        env._littlegreen_v68_current_progress = current_progress.detach()
        env._littlegreen_v68_backtrack = backtrack.detach()
        env._littlegreen_v68_frontier_factor = frontier_factor.detach()
        env._littlegreen_v95_signed_progress_from_liftoff_m = raw_progress.detach()
        env._littlegreen_v95_liftoff_dir_world = liftoff_dir.detach()
        env._littlegreen_v95_live_command_dir_world = k["command_dir_world"].detach()

    return s


def swing_foot_command_velocity_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
    min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018,
    max_stance_speed_mps: float = 0.12,
    wrong_way_deadband_mps: float = 0.020,
    wrong_way_scale: float = 0.18,
) -> torch.Tensor:
    """Frame-corrected v6.8 swing velocity with a mild wrong-way signed tail.

    Positive scoring is the original v6.8 saturation logic.  Only the negative side
    is new and deliberately small: sustained command-opposing whole-foot swing is
    mildly worse than stationary swing, but recovery motion is not catastrophically
    punished.  The swing main body *and* passive toe must both be airborne.
    """
    if min_clearance_m < 0.0 or full_clearance_factor_m <= min_clearance_m:
        raise ValueError("v9.5 swing-clearance scales invalid")
    if max_stance_speed_mps <= 0.0 or wrong_way_deadband_mps < 0.0:
        raise ValueError("v9.5 swing-speed scales invalid")
    if not 0.0 <= wrong_way_scale <= 1.0:
        raise ValueError("v9.5 wrong-way scale must lie in [0,1]")

    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    k, sf, st = s["k"], s["sf"], s["st"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)
    rel_vel = k["center_vel"][ids, sf] - k["center_vel"][ids, st]
    directional_speed = torch.sum(rel_vel * k["command_dir_world"], dim=1)
    target = torch.clamp(s["target_swing_speed"], min=1.0e-6)

    positive = torch.clamp(directional_speed / target, 0.0, 1.0)
    wrong = torch.relu(-directional_speed - float(wrong_way_deadband_mps))
    negative = -float(wrong_way_scale) * torch.clamp(wrong / target, 0.0, 1.0)
    speed_score = positive + negative

    clear = torch.clamp(k["whole_clear"][ids, sf], min=0.0)
    clear_score = torch.clamp(
        (clear - float(min_clearance_m))
        / max(float(full_clearance_factor_m) - float(min_clearance_m), 1.0e-6),
        0.0, 1.0,
    )
    clearance_multiplier = 0.25 + 0.75 * clear_score
    stance_speed = torch.linalg.vector_norm(k["center_vel"][ids, st], dim=1)
    stance_anchor = torch.clamp(
        1.0 - stance_speed / float(max_stance_speed_mps), 0.0, 1.0
    )
    whole_airborne = ~k["any_contact"][ids, sf]
    command_threshold = float(v68_params.get("command_threshold", 0.08))
    start_unload_share = float(v68_params.get("start_unload_share", 0.45))
    start_support_share = float(v68_params.get("start_support_share", 0.55))
    gate = (
        (s["baton"]["stage"] == 1)
        & (k["command_norm"] > command_threshold)
        & whole_airborne
        & (clear >= float(min_clearance_m))
        & (k["load_share"][ids, sf] <= start_unload_share)
        & (k["load_share"][ids, st] >= start_support_share)
        & k["full_plant"][ids, st]
    )
    value = (
        speed_score * s["frontier_factor"] * clearance_multiplier
        * stance_anchor * k["viability"] * gate.float()
    )
    env._littlegreen_v95_swing_directional_speed_mps = directional_speed.detach()
    env._littlegreen_v95_swing_velocity_gate = gate.detach()
    env._littlegreen_v95_swing_whole_airborne = whole_airborne.detach()
    return value


def command_conditioned_directional_swing_progress_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
) -> torch.Tensor:
    """Original v6.8 finite frontier after installing the world-frame liftoff direction."""
    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    full_progress = float(v68_params.get("full_trajectory_progress_m", 0.040))
    base_delta = s["baton"]["trajectory"]
    mult = getattr(env, "_littlegreen_v66_swing_multiplier", torch.ones_like(base_delta))
    denom = torch.clamp(mult * s["k"]["viability"], min=1.0e-6)
    raw_increment = base_delta * full_progress / denom
    prev_best = torch.relu(s["best_progress"] - raw_increment)
    available = torch.relu(s["stride_horizon"] - prev_best)
    used = torch.minimum(raw_increment, available)
    return (
        used / torch.clamp(s["stride_horizon"], min=1.0e-6)
    ) * mult * s["k"]["viability"]


def swing_backtrack_penalty_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
    min_frontier_m: float = 0.020,
    full_backtrack_m: float = 0.025,
) -> torch.Tensor:
    """Historical v6.8 backtrack protection evaluated in the corrected world frame."""
    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    deadband = float(v68_params.get("frontier_deadband_m", 0.006))
    if not deadband < float(full_backtrack_m):
        raise ValueError("v9.5 full backtrack must exceed frontier deadband")
    score = torch.clamp(
        (s["backtrack"] - deadband) / max(float(full_backtrack_m) - deadband, 1.0e-6),
        0.0, 1.0,
    )
    command_threshold = float(v68_params.get("command_threshold", 0.08))
    gate = (
        (s["baton"]["stage"] == 1)
        & (s["best_progress"] >= float(min_frontier_m))
        & (s["k"]["command_norm"] > command_threshold)
    )
    return score * s["k"]["viability"] * gate.float()


def swing_behind_liftoff_penalty_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
    free_deadband_m: float = 0.002,
    full_penalty_behind_m: float = 0.020,
) -> torch.Tensor:
    """Mildly penalize a whole airborne swing foot retreating behind its own liftoff.

    This complements the historical backtrack term, which only becomes meaningful
    after positive frontier progress has first been established.
    """
    if not 0.0 <= free_deadband_m < full_penalty_behind_m:
        raise ValueError("v9.5 behind-liftoff scales invalid")
    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    k, sf = s["k"], s["sf"]
    ids = torch.arange(k["load_share"].shape[0], device=k["load_share"].device)
    liftoff_xy = getattr(env, "_littlegreen_v66_liftoff_xy")
    liftoff_dir = getattr(env, "_littlegreen_v66_liftoff_dir")
    signed = torch.sum((k["centers"][ids, sf] - liftoff_xy) * liftoff_dir, dim=1)
    behind = torch.relu(-signed - float(free_deadband_m))
    score = torch.clamp(
        behind / max(float(full_penalty_behind_m) - float(free_deadband_m), 1.0e-6),
        0.0, 1.0,
    )
    command_threshold = float(v68_params.get("command_threshold", 0.08))
    whole_airborne = ~k["any_contact"][ids, sf]
    gate = (
        (s["baton"]["stage"] == 1)
        & (k["command_norm"] > command_threshold)
        & whole_airborne
    )
    env._littlegreen_v95_signed_progress_from_liftoff_m = signed.detach()
    env._littlegreen_v95_behind_liftoff_raw = score.detach()
    return score * k["viability"] * gate.float()


def loaded_replant_retention_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
    minimum_multiplier: float = 0.25,
) -> torch.Tensor:
    """v6.8 loaded-replant retention with frame correction guaranteed upstream."""
    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    mult = float(minimum_multiplier) + (1.0 - float(minimum_multiplier)) * s["retention"]
    return s["baton"]["replant"] * mult


def completed_gait_step_retention_v95(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    v68_params: dict,
    minimum_multiplier: float = 0.55,
) -> torch.Tensor:
    """v6.8 completed-step retention with frame correction guaranteed upstream."""
    s = _v95_frame_corrected_v68_state(
        env, command_name, sensor_cfg, asset_cfg, v68_params
    )
    mult = float(minimum_multiplier) + (1.0 - float(minimum_multiplier)) * s["retention"]
    return s["baton"]["gait_step"] * mult


# =============================================================================
# LittleGreen v7.1 support-capture refinement (branched directly from v6.9)
# =============================================================================
# v7.0 demonstrated that dense commanded COM velocity can be satisfied by a forward
# fall.  v7.1 therefore waits for a real v6.6 loaded-replant event, identifies that
# exact new support foot, and only then rewards COM motion toward the planted support.


def _v71_support_capture_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    min_touchdown_progress_m: float = 0.008,
    full_touchdown_progress_m: float = 0.020,
    min_new_support_load_share: float = 0.30,
    full_new_support_load_share: float = 0.55,
    target_com_closeness: float = 0.68,
    full_relative_speed_mps: float = 0.15,
    max_new_support_speed_mps: float = 0.10,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.395,
    zero_height_m: float = 0.335,
) -> dict[str, torch.Tensor]:
    """Track COM capture only after a meaningful loaded replant.

    The target is not an absolute COM path.  The newly planted physical foot defines
    the target online.  COM/base velocity is measured relative to that support foot
    and projected toward its center.  The bridge fades as support closeness reaches
    the existing takeover target, so a static brace cannot farm it.
    """
    if not 0.0 <= min_touchdown_progress_m < full_touchdown_progress_m:
        raise ValueError("v7.1 touchdown progress scales invalid")
    if not 0.0 < min_new_support_load_share < full_new_support_load_share <= 1.0:
        raise ValueError("v7.1 new-support load scales invalid")
    if not 0.5 < target_com_closeness <= 1.0:
        raise ValueError("v7.1 COM capture closeness invalid")
    if full_relative_speed_mps <= 0.0 or max_new_support_speed_mps <= 0.0:
        raise ValueError("v7.1 COM capture velocity scales must be positive")

    # Reuse the proven v6.8/v6.9 baton implementation to update replant/handoff
    # events, but evaluate viability using v7.1's only-slightly-relaxed height band.
    ref = _v68_refinement_state(
        env=env, command_name=command_name, sensor_cfg=sensor_cfg, asset_cfg=asset_cfg,
        command_threshold=command_threshold, full_tilt_deg=full_tilt_deg,
        zero_tilt_deg=zero_tilt_deg, full_height_m=full_height_m,
        zero_height_m=zero_height_m,
    )
    baton = ref["baton"]
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["load_share"].shape[0]
    device = k["load_share"].device
    dtype = k["load_share"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    cmd_dir3 = torch.cat((k["command_dir"], torch.zeros((n, 1), device=device, dtype=dtype)), dim=1)
    command_dir_world = quat_apply(yaw_quat(k["asset"].data.root_quat_w), cmd_dir3)[:, :2]
    moving = k["command_norm"] > float(command_threshold)

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    active = _state("_littlegreen_v71_capture_active", (n,), False, torch.bool)
    support_foot = _state("_littlegreen_v71_capture_foot", (n,), -1, torch.long)
    touchdown_progress = _state("_littlegreen_v71_touchdown_progress_m", (n,), 0.0)
    capture_timer = _state("_littlegreen_v71_touchdown_to_handoff_timer_s", (n,), 0.0)
    last_handoff_valid = _state("_littlegreen_v71_last_capture_handoff_valid", (n,), False, torch.bool)
    last_handoff_time = _state("_littlegreen_v71_last_touchdown_to_handoff_s", (n,), 0.0)
    last_handoff_distance = _state("_littlegreen_v71_last_com_distance_at_handoff_m", (n,), 0.0)
    last_handoff_closeness = _state("_littlegreen_v71_last_com_closeness_at_handoff", (n,), 0.0)
    last_handoff_touchdown_progress = _state("_littlegreen_v71_last_touchdown_progress_m", (n,), 0.0)

    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v71_capture_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        stop = reset | (~moving)
        capture_timer[:] = torch.where(active, capture_timer + dt, torch.zeros_like(capture_timer))
        last_handoff_valid[:] = False
        if torch.any(stop):
            active[stop] = False
            support_foot[stop] = -1
            capture_timer[stop] = 0.0
            touchdown_progress[stop] = 0.0

        replant_event = getattr(env, "_littlegreen_v66_replant_event", torch.zeros((n, 2), device=device, dtype=torch.bool))
        new_replant = torch.any(replant_event, dim=1) & (~reset) & moving
        if torch.any(new_replant):
            rf_all = torch.argmax(replant_event.long(), dim=1)
            rid = ids[new_replant]
            rf = rf_all[new_replant]
            liftoff_xy = getattr(env, "_littlegreen_v66_liftoff_xy", torch.zeros((n, 2), device=device, dtype=dtype))
            replant_xy = k["centers"][rid, rf]
            progress = torch.sum((replant_xy - liftoff_xy[new_replant]) * command_dir_world[new_replant], dim=1)
            active[new_replant] = True
            support_foot[new_replant] = rf
            touchdown_progress[new_replant] = progress
            capture_timer[new_replant] = 0.0

        failed = baton["takeover_failure"] > 0.0
        if torch.any(failed):
            active[failed] = False
            support_foot[failed] = -1
            capture_timer[failed] = 0.0

        handoff_event = getattr(env, "_littlegreen_v66_handoff_event", torch.zeros((n, 2), device=device, dtype=torch.bool))
        new_handoff = torch.any(handoff_event, dim=1) & (~reset) & moving
        if torch.any(new_handoff):
            hf_all = torch.argmax(handoff_event.long(), dim=1)
            hid = ids[new_handoff]
            hf = hf_all[new_handoff]
            valid = active[new_handoff] & (support_foot[new_handoff] == hf)
            distance = torch.linalg.vector_norm(k["centers"][hid, hf] - k["com_xy"][new_handoff], dim=1)
            close = k["closeness"][hid, hf]
            last_handoff_valid[new_handoff] = valid
            last_handoff_time[new_handoff] = capture_timer[new_handoff]
            last_handoff_distance[new_handoff] = distance
            last_handoff_closeness[new_handoff] = close
            last_handoff_touchdown_progress[new_handoff] = touchdown_progress[new_handoff]
            active[new_handoff] = False
            support_foot[new_handoff] = -1
            capture_timer[new_handoff] = 0.0

        env._littlegreen_v71_capture_last_common_step = common_step

    foot = torch.clamp(support_foot, min=0, max=1)
    center = k["centers"][ids, foot]
    foot_vel = k["center_vel"][ids, foot]
    foot_speed = torch.linalg.vector_norm(foot_vel, dim=1)
    load_share = k["load_share"][ids, foot]
    closeness = k["closeness"][ids, foot]
    full_plant = k["full_plant"][ids, foot]
    to_support = center - k["com_xy"]
    com_distance = torch.linalg.vector_norm(to_support, dim=1)
    to_support_dir = to_support / torch.clamp(com_distance.unsqueeze(1), min=1.0e-6)
    relative_com_vel = k["asset"].data.root_lin_vel_w[:, :2] - foot_vel
    toward_speed = torch.sum(relative_com_vel * to_support_dir, dim=1)

    speed_score = torch.clamp(toward_speed / float(full_relative_speed_mps), 0.0, 1.0)
    remaining = torch.clamp(
        (float(target_com_closeness) - closeness) / max(float(target_com_closeness) - 0.5, 1.0e-6),
        0.0, 1.0,
    )
    load_score = torch.clamp(
        (load_share - float(min_new_support_load_share))
        / max(float(full_new_support_load_share) - float(min_new_support_load_share), 1.0e-6),
        0.0, 1.0,
    )
    anchor = torch.clamp(1.0 - foot_speed / float(max_new_support_speed_mps), 0.0, 1.0)
    prog_score = torch.clamp(
        (touchdown_progress - float(min_touchdown_progress_m))
        / max(float(full_touchdown_progress_m) - float(min_touchdown_progress_m), 1.0e-6),
        0.0, 1.0,
    )
    progress_multiplier = 0.35 + 0.65 * prog_score
    gate = (
        active & (baton["stage"] == 2) & moving & full_plant
        & (load_share >= float(min_new_support_load_share))
        & (touchdown_progress >= float(min_touchdown_progress_m))
    )
    score = speed_score * remaining * load_score * anchor * progress_multiplier * k["viability"] * gate.float()

    env._littlegreen_v71_capture_active_mask = gate.detach()
    env._littlegreen_v71_capture_com_distance_m = com_distance.detach()
    env._littlegreen_v71_capture_toward_speed_mps = toward_speed.detach()
    env._littlegreen_v71_capture_support_load_share = load_share.detach()
    env._littlegreen_v71_capture_com_closeness = closeness.detach()
    env._littlegreen_v71_capture_support_foot_speed_mps = foot_speed.detach()
    env._littlegreen_v71_capture_score = score.detach()

    return {
        "score": score,
        "active": gate,
        "distance": com_distance,
        "toward_speed": toward_speed,
        "load_share": load_share,
        "closeness": closeness,
        "foot_speed": foot_speed,
        "touchdown_progress": touchdown_progress,
        "last_handoff_valid": last_handoff_valid,
        "last_handoff_time": last_handoff_time,
        "last_handoff_distance": last_handoff_distance,
        "last_handoff_closeness": last_handoff_closeness,
        "last_handoff_touchdown_progress": last_handoff_touchdown_progress,
    }


def new_support_com_capture_v71(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, min_touchdown_progress_m: float = 0.008,
    full_touchdown_progress_m: float = 0.020, min_new_support_load_share: float = 0.30,
    full_new_support_load_share: float = 0.55, target_com_closeness: float = 0.68,
    full_relative_speed_mps: float = 0.15, max_new_support_speed_mps: float = 0.10,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.395, zero_height_m: float = 0.335,
) -> torch.Tensor:
    """Reward COM motion toward the exact newly replanted support foot, and nowhere else."""
    return _v71_support_capture_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, min_touchdown_progress_m,
        full_touchdown_progress_m, min_new_support_load_share, full_new_support_load_share,
        target_com_closeness, full_relative_speed_mps, max_new_support_speed_mps,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )["score"]


def support_regression_penalty_v71(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, support_progress_base_m: float = 0.010, support_progress_gain_s: float = 0.067,
    min_support_progress_horizon_m: float = 0.015, max_support_progress_horizon_m: float = 0.040,
    com_progress_base_m: float = 0.010, com_progress_gain_s: float = 0.067,
    min_com_progress_horizon_m: float = 0.015, max_com_progress_horizon_m: float = 0.040,
    post_touchdown_deadband_m: float = 0.005, post_touchdown_full_retreat_m: float = 0.015,
    handoff_retention_min_progress_m: float = 0.010, direction_continuity_cos_min: float = 0.50,
    translation_event_hold_s: float = 0.06, regression_deadband_m: float = 0.005,
    regression_full_m: float = 0.020,
) -> torch.Tensor:
    """Mild signed correction when a completed new support is behind the old support."""
    if not 0.0 <= regression_deadband_m < regression_full_m:
        raise ValueError("v7.1 support regression scales invalid")
    s = _v69_translation_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, support_progress_base_m, support_progress_gain_s,
        min_support_progress_horizon_m, max_support_progress_horizon_m, com_progress_base_m, com_progress_gain_s,
        min_com_progress_horizon_m, max_com_progress_horizon_m, post_touchdown_deadband_m, post_touchdown_full_retreat_m,
        handoff_retention_min_progress_m, direction_continuity_cos_min, translation_event_hold_s,
    )
    advance = getattr(env, "_littlegreen_v69_last_support_advance_m", torch.zeros_like(s["k"]["command_norm"]))
    regression = torch.relu(-advance)
    score = torch.clamp(
        (regression - float(regression_deadband_m))
        / max(float(regression_full_m) - float(regression_deadband_m), 1.0e-6),
        0.0, 1.0,
    )
    active = s["handoff_hold"] > 0.0
    score = score * active.float() * s["k"]["viability"]
    env._littlegreen_v71_support_regression_m = regression.detach()
    env._littlegreen_v71_support_regression_score = score.detach()
    env._littlegreen_v71_support_regression_active = active.detach()
    return score


# =============================================================================
# LittleGreen v7.2 stance-relative swing passage / natural lead reversal
# =============================================================================

def _v72_pass_score(passage_m: torch.Tensor, lead_margin_m: torch.Tensor, approach_window_m: float, approach_credit_fraction: float) -> torch.Tensor:
    """Smooth catch-up -> lead-reversal score with no exact stride target.

    ``approach_credit_fraction`` of the score is available while a trailing foot closes
    the gap to the stance foot.  The remainder is available only after the swing foot
    passes the stance foot along the command direction.  The positive lead margin is a
    small command-conditioned saturation horizon, not a landing target.
    """
    approach = torch.clamp((passage_m + float(approach_window_m)) / max(float(approach_window_m), 1.0e-6), 0.0, 1.0)
    lead = torch.clamp(passage_m / torch.clamp(lead_margin_m, min=1.0e-6), 0.0, 1.0)
    a = float(approach_credit_fraction)
    return a * approach + (1.0 - a) * lead


def _v72_stance_pass_state(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, approach_window_m: float = 0.035,
    pass_margin_base_m: float = 0.004, pass_margin_gain_s: float = 0.040,
    min_pass_margin_m: float = 0.008, max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.45, min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018, min_stance_load_share: float = 0.55,
    max_stance_speed_mps: float = 0.12, pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.395, zero_height_m: float = 0.335,
) -> dict[str, torch.Tensor]:
    """Track a leg-agnostic swing foot relative to the current stance frontier.

    Direction is captured in world XY when the v6.6 support baton starts a swing, so
    reset-yaw randomization and live lateral/reverse commands are handled correctly.
    Only new-best passage score is paid; oscillating behind/ahead cannot recycle reward.
    """
    if approach_window_m <= 0.0 or not 0.0 <= approach_credit_fraction < 1.0:
        raise ValueError("v7.2 passage gradient parameters invalid")
    if not 0.0 < min_pass_margin_m <= max_pass_margin_m:
        raise ValueError("v7.2 pass-margin bounds invalid")
    if full_clearance_factor_m <= min_clearance_m or max_stance_speed_mps <= 0.0:
        raise ValueError("v7.2 passage clearance/anchor scales invalid")

    ref = _v68_refinement_state(
        env=env, command_name=command_name, sensor_cfg=sensor_cfg, asset_cfg=asset_cfg,
        command_threshold=command_threshold, frontier_deadband_m=0.005, frontier_zero_credit_m=0.012,
        full_tilt_deg=full_tilt_deg, zero_tilt_deg=zero_tilt_deg, full_height_m=full_height_m, zero_height_m=zero_height_m,
    )
    baton, k = ref["baton"], ref["k"]
    n = k["load_share"].shape[0]; device=k["load_share"].device; dtype=k["load_share"].dtype
    ids=torch.arange(n,device=device); dt=float(getattr(env,"step_dt",0.02))
    sf=torch.clamp(baton["swing_foot"],min=0,max=1); st=torch.clamp(baton["stance_foot"],min=0,max=1)

    cmd_dir3=torch.cat((k["command_dir"],torch.zeros((n,1),device=device,dtype=dtype)),dim=1)
    command_dir_world=quat_apply(yaw_quat(k["asset"].data.root_quat_w),cmd_dir3)[:,:2]
    lead_margin=torch.clamp(float(pass_margin_base_m)+float(pass_margin_gain_s)*k["command_norm"], min=float(min_pass_margin_m), max=float(max_pass_margin_m))

    def state(name,shape,default,tdtype=None):
        use=tdtype if tdtype is not None else dtype
        v=getattr(env,name,None)
        if not isinstance(v,torch.Tensor) or tuple(v.shape)!=tuple(shape) or v.device!=device:
            v=torch.full(shape,default,device=device,dtype=use); setattr(env,name,v)
        return v

    swing_dir=state("_littlegreen_v72_swing_dir_world",(n,2),0.0)
    best_score=state("_littlegreen_v72_best_pass_score",(n,),0.0)
    delta_value=state("_littlegreen_v72_pass_delta",(n,),0.0)
    touchdown_margin=state("_littlegreen_v72_last_touchdown_pass_margin_m",(n,),0.0)
    touchdown_event=state("_littlegreen_v72_touchdown_pass_event",(n,),False,torch.bool)
    touchdown_foot=state("_littlegreen_v72_touchdown_foot",(n,),-1,torch.long)
    handoff_margin=state("_littlegreen_v72_last_handoff_pass_margin_m",(n,),0.0)
    handoff_score_value=state("_littlegreen_v72_handoff_pass_score",(n,),0.0)
    handoff_event_mask=state("_littlegreen_v72_handoff_pass_event",(n,),False,torch.bool)
    handoff_foot=state("_littlegreen_v72_handoff_foot",(n,),-1,torch.long)
    handoff_hold=state("_littlegreen_v72_handoff_pass_hold_s",(n,),0.0)

    current_passage=torch.sum((k["centers"][ids,sf]-k["centers"][ids,st])*swing_dir,dim=1)
    current_score=_v72_pass_score(current_passage,lead_margin,approach_window_m,approach_credit_fraction)

    common_step=int(getattr(env,"common_step_counter",0)); last_step=int(getattr(env,"_littlegreen_v72_pass_last_common_step",-1))
    if common_step!=last_step:
        reset=_v10_episode_reset_mask(env,n,device); moving=k["command_norm"]>float(command_threshold)
        stop=reset|(~moving); delta_value[:]=0.0; touchdown_event[:]=False; handoff_event_mask[:]=False
        handoff_hold[:]=torch.clamp(handoff_hold-dt,min=0.0)
        handoff_score_value[:]=torch.where(handoff_hold>0.0,handoff_score_value,torch.zeros_like(handoff_score_value))
        if torch.any(stop):
            best_score[stop]=0.0; swing_dir[stop]=0.0; handoff_hold[stop]=0.0; handoff_score_value[stop]=0.0

        start_event=getattr(env,"_littlegreen_v66_start_event",torch.zeros((n,2),device=device,dtype=torch.bool))
        start=torch.any(start_event,dim=1)&(~reset)&moving
        if torch.any(start):
            start_sf=torch.argmax(start_event.long(),dim=1); start_st=1-start_sf; sid=ids[start]
            swing_dir[start]=command_dir_world[start]
            initial_passage=torch.sum((k["centers"][sid,start_sf[start]]-k["centers"][sid,start_st[start]])*swing_dir[start],dim=1)
            best_score[start]=_v72_pass_score(initial_passage,lead_margin[start],approach_window_m,approach_credit_fraction)

        # Recompute after a possible start-direction capture.
        current_passage=torch.sum((k["centers"][ids,sf]-k["centers"][ids,st])*swing_dir,dim=1)
        current_score=_v72_pass_score(current_passage,lead_margin,approach_window_m,approach_credit_fraction)
        clear=torch.clamp(k["whole_clear"][ids,sf],min=0.0)
        stance_speed=torch.linalg.vector_norm(k["center_vel"][ids,st],dim=1)
        swing_gate=(baton["stage"]==1)&moving&(clear>=float(min_clearance_m))&k["full_plant"][ids,st]&(k["load_share"][ids,st]>=float(min_stance_load_share))
        delta=torch.relu(current_score-best_score)*swing_gate.float()
        best_score[:]=torch.where(swing_gate,torch.maximum(best_score,current_score),best_score)
        delta_value[:]=delta

        replant_event=getattr(env,"_littlegreen_v66_replant_event",torch.zeros((n,2),device=device,dtype=torch.bool))
        repl=torch.any(replant_event,dim=1)&(~reset)&moving
        if torch.any(repl):
            rf=torch.argmax(replant_event.long(),dim=1); rid=ids[repl]; old=1-rf[repl]
            margin=torch.sum((k["centers"][rid,rf[repl]]-k["centers"][rid,old])*swing_dir[repl],dim=1)
            touchdown_margin[repl]=margin; touchdown_event[repl]=True; touchdown_foot[repl]=rf[repl]

        handoff_event=getattr(env,"_littlegreen_v66_handoff_event",torch.zeros((n,2),device=device,dtype=torch.bool))
        hand=torch.any(handoff_event,dim=1)&(~reset)&moving
        if torch.any(hand):
            hf=torch.argmax(handoff_event.long(),dim=1); hid=ids[hand]; old=1-hf[hand]
            # The swing-start direction is retained through takeover.
            margin=torch.sum((k["centers"][hid,hf[hand]]-k["centers"][hid,old])*swing_dir[hand],dim=1)
            score=_v72_pass_score(margin,lead_margin[hand],approach_window_m,approach_credit_fraction)
            handoff_margin[hand]=margin; handoff_score_value[hand]=score; handoff_event_mask[hand]=True; handoff_foot[hand]=hf[hand]; handoff_hold[hand]=float(pass_event_hold_s)

        env._littlegreen_v72_pass_last_common_step=common_step

    clear=torch.clamp(k["whole_clear"][ids,sf],min=0.0)
    clear_score=torch.clamp((clear-float(min_clearance_m))/max(float(full_clearance_factor_m)-float(min_clearance_m),1.0e-6),0.0,1.0)
    clearance_multiplier=0.25+0.75*clear_score
    stance_speed=torch.linalg.vector_norm(k["center_vel"][ids,st],dim=1)
    stance_anchor=torch.clamp(1.0-stance_speed/float(max_stance_speed_mps),0.0,1.0)
    swing_mult=getattr(env,"_littlegreen_v66_swing_multiplier",torch.ones(n,device=device,dtype=dtype))
    reward=delta_value*clearance_multiplier*stance_anchor*swing_mult*k["viability"]

    env._littlegreen_v72_current_pass_margin_m=current_passage.detach()
    env._littlegreen_v72_current_pass_score=current_score.detach()
    env._littlegreen_v72_pass_margin_horizon_m=lead_margin.detach()
    env._littlegreen_v72_pass_reward_delta=delta_value.detach()
    env._littlegreen_v72_pass_ahead_mask=(current_passage>0.0).detach()

    return {"reward":reward,"current_margin":current_passage,"current_score":current_score,"lead_margin":lead_margin,
            "touchdown_margin":touchdown_margin,"touchdown_event":touchdown_event,"touchdown_foot":touchdown_foot,
            "handoff_margin":handoff_margin,"handoff_score":handoff_score_value,"handoff_event":handoff_event_mask,"handoff_foot":handoff_foot}


def stance_relative_swing_pass_progress_v72(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, approach_window_m: float = 0.035, pass_margin_base_m: float = 0.004,
    pass_margin_gain_s: float = 0.040, min_pass_margin_m: float = 0.008, max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.45, min_clearance_m: float = 0.003, full_clearance_factor_m: float = 0.018,
    min_stance_load_share: float = 0.55, max_stance_speed_mps: float = 0.12, pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.395, zero_height_m: float = 0.335,
) -> torch.Tensor:
    """Finite new-best reward for catching and then passing the current stance foot."""
    return _v72_stance_pass_state(env,command_name,sensor_cfg,asset_cfg,command_threshold,approach_window_m,pass_margin_base_m,pass_margin_gain_s,min_pass_margin_m,max_pass_margin_m,approach_credit_fraction,min_clearance_m,full_clearance_factor_m,min_stance_load_share,max_stance_speed_mps,pass_event_hold_s,full_tilt_deg,zero_tilt_deg,full_height_m,zero_height_m)["reward"]


def _v72_completion_quality(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg, command_threshold: float,
    support_progress_base_m: float, support_progress_gain_s: float, min_support_progress_horizon_m: float, max_support_progress_horizon_m: float,
    com_progress_base_m: float, com_progress_gain_s: float, min_com_progress_horizon_m: float, max_com_progress_horizon_m: float,
    post_touchdown_deadband_m: float, post_touchdown_full_retreat_m: float, handoff_retention_min_progress_m: float,
    direction_continuity_cos_min: float, translation_event_hold_s: float, approach_window_m: float, pass_margin_base_m: float,
    pass_margin_gain_s: float, min_pass_margin_m: float, max_pass_margin_m: float, approach_credit_fraction: float, min_clearance_m: float,
    full_clearance_factor_m: float, min_stance_load_share: float, max_stance_speed_mps: float, pass_event_hold_s: float,
    full_tilt_deg: float, zero_tilt_deg: float, full_height_m: float, zero_height_m: float, retention_weight: float, passage_weight: float,
) -> tuple[dict[str,torch.Tensor],torch.Tensor]:
    if retention_weight<0.0 or passage_weight<0.0 or retention_weight+passage_weight<=0.0:
        raise ValueError("v7.2 completion quality weights invalid")
    s69=_v69_translation_state(env,command_name,sensor_cfg,asset_cfg,command_threshold,support_progress_base_m,support_progress_gain_s,min_support_progress_horizon_m,max_support_progress_horizon_m,com_progress_base_m,com_progress_gain_s,min_com_progress_horizon_m,max_com_progress_horizon_m,post_touchdown_deadband_m,post_touchdown_full_retreat_m,handoff_retention_min_progress_m,direction_continuity_cos_min,translation_event_hold_s)
    p=_v72_stance_pass_state(env,command_name,sensor_cfg,asset_cfg,command_threshold,approach_window_m,pass_margin_base_m,pass_margin_gain_s,min_pass_margin_m,max_pass_margin_m,approach_credit_fraction,min_clearance_m,full_clearance_factor_m,min_stance_load_share,max_stance_speed_mps,pass_event_hold_s,full_tilt_deg,zero_tilt_deg,full_height_m,zero_height_m)
    total=float(retention_weight)+float(passage_weight)
    quality=(float(retention_weight)*s69["handoff_retention"]+float(passage_weight)*p["handoff_score"])/total
    return s69,torch.clamp(quality,0.0,1.0)


