def loaded_replant_pass_retention_v73(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08, approach_window_m: float = 0.035, pass_margin_base_m: float = 0.004,
    pass_margin_gain_s: float = 0.040, min_pass_margin_m: float = 0.008, max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.35, min_clearance_m: float = 0.003, full_clearance_factor_m: float = 0.018,
    min_stance_load_share: float = 0.55, max_stance_speed_mps: float = 0.12, pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0, full_height_m: float = 0.395, zero_height_m: float = 0.335,
    minimum_multiplier: float = 0.25, directional_weight: float = 0.25, passage_weight: float = 0.75,
) -> torch.Tensor:
    """Reward loaded replant while preferring passage that survives the late-swing plant.

    The policy chooses its own peak passage.  v7.3 only asks that useful passage not be
    thrown away before loaded replant.  Passage quality is the replant passage score
    multiplied by the fraction of the best swing passage score retained.  This avoids
    turning a perfectly retained but still-trailing catch-up plant into a high-value step.
    """
    if not 0.0 <= minimum_multiplier <= 1.0:
        raise ValueError("v7.3 replant minimum multiplier invalid")
    if directional_weight < 0.0 or passage_weight < 0.0 or directional_weight + passage_weight <= 0.0:
        raise ValueError("v7.3 replant quality weights invalid")
    p = _v72_stance_pass_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, approach_window_m,
        pass_margin_base_m, pass_margin_gain_s, min_pass_margin_m, max_pass_margin_m,
        approach_credit_fraction, min_clearance_m, full_clearance_factor_m, min_stance_load_share,
        max_stance_speed_mps, pass_event_hold_s, full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    device = p["current_score"].device
    best = getattr(env, "_littlegreen_v72_best_pass_score", torch.zeros_like(p["current_score"]))
    replant_score = _v72_pass_score(p["touchdown_margin"], p["lead_margin"], approach_window_m, approach_credit_fraction)
    retention_ratio = torch.clamp(replant_score / torch.clamp(best, min=0.05), 0.0, 1.0)
    passage_quality = torch.clamp(replant_score * retention_ratio, 0.0, 1.0)
    directional_retention = getattr(env, "_littlegreen_v68_replant_retention", torch.ones_like(passage_quality))
    total = float(directional_weight) + float(passage_weight)
    quality = torch.clamp((float(directional_weight) * directional_retention + float(passage_weight) * passage_quality) / total, 0.0, 1.0)

    snap = getattr(env, "_littlegreen_v73_replant_quality", None)
    if not isinstance(snap, torch.Tensor) or snap.shape != quality.shape or snap.device != device:
        snap = torch.zeros_like(quality)
    event = p["touchdown_event"]
    snap[:] = torch.where(event, quality, snap)
    env._littlegreen_v73_replant_quality = snap
    env._littlegreen_v73_replant_pass_score = torch.where(event, replant_score, torch.zeros_like(replant_score)).detach()
    env._littlegreen_v73_replant_best_pass_score = torch.where(event, best, torch.zeros_like(best)).detach()
    env._littlegreen_v73_replant_pass_retention_ratio = torch.where(event, retention_ratio, torch.zeros_like(retention_ratio)).detach()
    env._littlegreen_v73_replant_passage_quality = torch.where(event, passage_quality, torch.zeros_like(passage_quality)).detach()
    env._littlegreen_v73_replant_event = event.detach()
    env._littlegreen_v73_replant_foot = p["touchdown_foot"].detach()

    hold = getattr(env, "_littlegreen_v66_replant_event_hold", torch.zeros_like(quality))
    active = hold > 0.0
    mult = float(minimum_multiplier) + (1.0 - float(minimum_multiplier)) * snap
    return active.float() * mult


