def completed_gait_step_pass_scaled_v78(
    env: ManagerBasedRLEnv, command_name: str, sensor_cfg: SceneEntityCfg, asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    support_progress_base_m: float = 0.010, support_progress_gain_s: float = 0.067,
    min_support_progress_horizon_m: float = 0.015, max_support_progress_horizon_m: float = 0.040,
    com_progress_base_m: float = 0.010, com_progress_gain_s: float = 0.067,
    min_com_progress_horizon_m: float = 0.015, max_com_progress_horizon_m: float = 0.040,
    post_touchdown_deadband_m: float = 0.005, post_touchdown_full_retreat_m: float = 0.015,
    handoff_retention_min_progress_m: float = 0.010, direction_continuity_cos_min: float = 0.50,
    translation_event_hold_s: float = 0.06, approach_window_m: float = 0.035,
    pass_margin_base_m: float = 0.004, pass_margin_gain_s: float = 0.040,
    min_pass_margin_m: float = 0.008, max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.35, min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018, min_stance_load_share: float = 0.55,
    max_stance_speed_mps: float = 0.12, pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0, zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.395, zero_height_m: float = 0.335,
    minimum_multiplier: float = 0.44, retention_weight: float = 0.25, passage_weight: float = 0.75,
    baton_params: dict | None = None,
) -> torch.Tensor:
    """v7.8 completed-step reward with explicit ownership of the v6.6 baton economics.

    v7.2/v7.3 completion wrappers recover the shared baton through the v6.9 translation
    helper, whose historical defaults use a 1.50 continuation multiplier.  v7.8 lowers
    that multiplier to 1.10 as part of the reward-arithmetic cleanup, so the completed
    step term must establish the shared baton with the v7.8 parameters explicitly rather
    than depending on RewardManager call order.
    """
    if not 0.0 <= minimum_multiplier <= 1.0:
        raise ValueError("v7.8 gait-step minimum multiplier invalid")
    bp = dict(baton_params or {})
    bp.setdefault("command_threshold", float(command_threshold))
    baton = _v66_public_state(
        env=env, command_name=command_name, sensor_cfg=sensor_cfg, asset_cfg=asset_cfg, **bp
    )
    _, q = _v72_completion_quality(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        support_progress_base_m, support_progress_gain_s, min_support_progress_horizon_m,
        max_support_progress_horizon_m, com_progress_base_m, com_progress_gain_s,
        min_com_progress_horizon_m, max_com_progress_horizon_m, post_touchdown_deadband_m,
        post_touchdown_full_retreat_m, handoff_retention_min_progress_m,
        direction_continuity_cos_min, translation_event_hold_s, approach_window_m,
        pass_margin_base_m, pass_margin_gain_s, min_pass_margin_m, max_pass_margin_m,
        approach_credit_fraction, min_clearance_m, full_clearance_factor_m,
        min_stance_load_share, max_stance_speed_mps, pass_event_hold_s, full_tilt_deg,
        zero_tilt_deg, full_height_m, zero_height_m, retention_weight, passage_weight,
    )
    return baton["gait_step"] * (float(minimum_multiplier) + (1.0 - float(minimum_multiplier)) * q)

