# =============================================================================
# LittleGreen v9.6 locomotion-economics refinement
# =============================================================================
# v9.6 deliberately leaves the successful v9.5/v6.8 gait-acquisition chain alone.
# These helpers operate only on completed support handoffs.  They make the weaker
# leg economically relevant without prescribing joint angles or equal stride length,
# and make completed gait cycles answer directly to commanded WORLD translation rate.


def _v96_command_epoch_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    command_threshold: float = 0.08,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> dict[str, torch.Tensor]:
    """Return a per-environment command-change pulse for v9.6 event memories.

    Passage pairs and same-foot support-rate baselines are meaningful only while the
    requested command is stable.  Any material planar/yaw command change, moving to
    standing, episode reset, or first use starts a new measurement epoch.
    """
    if command_change_linear_mps <= 0.0 or command_change_yaw_rps <= 0.0:
        raise ValueError("v9.6 command-change thresholds must be positive")

    command = env.command_manager.get_command(command_name)
    n = command.shape[0]
    device = command.device
    common_step = int(getattr(env, "common_step_counter", 0))

    previous = getattr(env, "_littlegreen_v96_epoch_command", None)
    if not isinstance(previous, torch.Tensor) or previous.shape != command.shape or previous.device != device:
        previous = command.clone()
        env._littlegreen_v96_epoch_command = previous
        env._littlegreen_v96_epoch_valid = torch.zeros((n,), device=device, dtype=torch.bool)
    valid = getattr(env, "_littlegreen_v96_epoch_valid")

    changed = getattr(env, "_littlegreen_v96_epoch_changed", None)
    if not isinstance(changed, torch.Tensor) or changed.shape != (n,) or changed.device != device:
        changed = torch.ones((n,), device=device, dtype=torch.bool)
        env._littlegreen_v96_epoch_changed = changed

    last_step = int(getattr(env, "_littlegreen_v96_epoch_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        linear_delta = torch.linalg.vector_norm(command[:, :2] - previous[:, :2], dim=1)
        if command.shape[1] > 2:
            yaw_delta = torch.abs(command[:, 2] - previous[:, 2])
        else:
            yaw_delta = torch.zeros((n,), device=device, dtype=command.dtype)
        previous_moving = torch.linalg.vector_norm(previous[:, :2], dim=1) > float(command_threshold)
        current_moving = torch.linalg.vector_norm(command[:, :2], dim=1) > float(command_threshold)
        changed[:] = (
            (~valid)
            | reset
            | (linear_delta >= float(command_change_linear_mps))
            | (yaw_delta >= float(command_change_yaw_rps))
            | (previous_moving != current_moving)
        )
        previous[:] = command
        valid[:] = True
        env._littlegreen_v96_epoch_last_common_step = common_step

        reset_count = getattr(env, "_littlegreen_v96_epoch_reset_count", None)
        if not isinstance(reset_count, torch.Tensor) or reset_count.shape != (n,) or reset_count.device != device:
            reset_count = torch.zeros((n,), device=device, dtype=torch.long)
        reset_count[:] = reset_count + changed.to(torch.long)
        env._littlegreen_v96_epoch_reset_count = reset_count

    return {
        "command": command,
        "command_norm": torch.linalg.vector_norm(command[:, :2], dim=1),
        "changed": changed,
    }


def bilateral_passage_balance_bonus_v96(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    approach_window_m: float = 0.035,
    pass_margin_base_m: float = 0.004,
    pass_margin_gain_s: float = 0.040,
    min_pass_margin_m: float = 0.008,
    max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.35,
    min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018,
    min_stance_load_share: float = 0.55,
    max_stance_speed_mps: float = 0.12,
    pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    quality_softness_m: float = 0.025,
    pair_neutral_quality: float = 0.50,
    pair_event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Weak-leg-sensitive bilateral passage with no catch-up dead zone.

    Each successful support handoff receives a smooth quality from its signed
    stance-relative margin.  Consecutive *opposite-foot* qualities are combined by
    geometric mean, so one excellent leg cannot hide a trailing/short-stepping leg.
    Equal stride lengths are not requested: both feet merely need to contribute
    useful command-relative passage.  The pair is centered at the quality of a
    zero-margin handoff, making a both-feet-even pair neutral rather than rewarding
    stationary catch-up.
    """
    if quality_softness_m <= 0.0 or pair_event_hold_s <= 0.0:
        raise ValueError("v9.6 bilateral passage scales must be positive")
    if not 0.0 < pair_neutral_quality < 1.0:
        raise ValueError("v9.6 bilateral neutral quality must be in (0,1)")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.6 passage direction continuity cosine invalid")

    p = _v72_stance_pass_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, approach_window_m,
        pass_margin_base_m, pass_margin_gain_s, min_pass_margin_m, max_pass_margin_m,
        approach_credit_fraction, min_clearance_m, full_clearance_factor_m,
        min_stance_load_share, max_stance_speed_mps, pass_event_hold_s,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    epoch = _v96_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    previous_foot = _state("_littlegreen_v96_pass_previous_foot", (n,), -1, torch.long)
    previous_quality = _state("_littlegreen_v96_pass_previous_quality", (n,), 0.0)
    previous_direction = _state("_littlegreen_v96_pass_previous_direction", (n, 2), 0.0)
    pair_hold = _state("_littlegreen_v96_pass_pair_hold_s", (n,), 0.0)
    pair_value = _state("_littlegreen_v96_pass_pair_value", (n,), 0.0)
    pair_event = _state("_littlegreen_v96_pass_pair_event", (n,), False, torch.bool)
    pair_quality_snap = _state("_littlegreen_v96_pass_pair_quality", (n,), 0.0)
    previous_quality_snap = _state("_littlegreen_v96_pass_previous_quality_snap", (n,), 0.0)
    current_quality_snap = _state("_littlegreen_v96_pass_current_quality_snap", (n,), 0.0)
    current_margin_snap = _state("_littlegreen_v96_pass_current_margin_m", (n,), 0.0)
    current_foot_snap = _state("_littlegreen_v96_pass_current_foot", (n,), -1, torch.long)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_step = int(getattr(env, "_littlegreen_v96_pass_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        pair_hold[:] = torch.clamp(pair_hold - dt, min=0.0)
        pair_value[:] = torch.where(pair_hold > 0.0, pair_value, torch.zeros_like(pair_value))
        pair_event[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            previous_foot[stop] = -1
            previous_quality[stop] = 0.0
            previous_direction[stop] = 0.0
            pair_hold[stop] = 0.0
            pair_value[stop] = 0.0

        hand = p["handoff_event"] & (~reset) & moving & (~epoch["changed"])
        if torch.any(hand):
            ids = torch.arange(n, device=device)
            hid = ids[hand]
            current_foot = p["handoff_foot"][hand]
            current_margin = p["handoff_margin"][hand]
            current_quality = torch.sigmoid(current_margin / float(quality_softness_m))
            prev_foot = previous_foot[hand]
            prev_quality = previous_quality[hand]
            prev_dir = previous_direction[hand]
            current_dir = current_direction[hand]
            direction_ok = torch.sum(prev_dir * current_dir, dim=1) >= float(direction_continuity_cos_min)
            valid = (prev_foot >= 0) & (current_foot != prev_foot) & direction_ok

            bilateral = torch.sqrt(torch.clamp(prev_quality * current_quality, min=0.0))
            center = float(pair_neutral_quality)
            pair_score = torch.where(
                bilateral >= center,
                (bilateral - center) / max(1.0 - center, 1.0e-6),
                (bilateral - center) / max(center, 1.0e-6),
            )
            pair_score = torch.clamp(pair_score, -1.0, 1.0) * valid.float() * k["viability"][hand]
            if torch.any(valid):
                vid = hid[valid]
                pair_event[vid] = True
                pair_hold[vid] = float(pair_event_hold_s)
                pair_value[vid] = pair_score[valid]
                pair_quality_snap[vid] = bilateral[valid]
                previous_quality_snap[vid] = prev_quality[valid]
                current_quality_snap[vid] = current_quality[valid]
                current_margin_snap[vid] = current_margin[valid]
                current_foot_snap[vid] = current_foot[valid]

            previous_foot[hand] = current_foot
            previous_quality[hand] = current_quality
            previous_direction[hand] = current_dir

        env._littlegreen_v96_pass_last_common_step = common_step

    env._littlegreen_v96_pass_pair_event = pair_event.detach()
    env._littlegreen_v96_pass_pair_quality = pair_quality_snap.detach()
    env._littlegreen_v96_pass_previous_quality_snap = previous_quality_snap.detach()
    env._littlegreen_v96_pass_current_quality_snap = current_quality_snap.detach()
    env._littlegreen_v96_pass_current_margin_m = current_margin_snap.detach()
    env._littlegreen_v96_pass_current_foot = current_foot_snap.detach()
    return torch.where(pair_hold > 0.0, pair_value, torch.zeros_like(pair_value))


def same_foot_commanded_world_rate_v96(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    approach_window_m: float = 0.035,
    pass_margin_base_m: float = 0.004,
    pass_margin_gain_s: float = 0.040,
    min_pass_margin_m: float = 0.008,
    max_pass_margin_m: float = 0.024,
    approach_credit_fraction: float = 0.35,
    min_clearance_m: float = 0.003,
    full_clearance_factor_m: float = 0.018,
    min_stance_load_share: float = 0.55,
    max_stance_speed_mps: float = 0.12,
    pass_event_hold_s: float = 0.10,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    neutral_rate_ratio: float = 0.20,
    rate_softness_ratio: float = 0.12,
    rate_event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Score each foot's completed support cycle against commanded WORLD speed.

    LEFT handoff A -> RIGHT handoff -> LEFT handoff B yields one left-foot rate
    measurement; the right foot is measured independently in the same way.  The
    resulting signed logistic score is neutral at 20% of commanded planar speed,
    so the mature v9.5 ~10% velocity solution remains economically inadequate while
    backward/near-stationary cycles are explicitly worse than useful translation.

    No cadence or stride length is prescribed: stride and timing remain free so long
    as the completed physical support cycles transport the robot through world space.
    """
    if not 0.0 <= neutral_rate_ratio < 1.0 or rate_softness_ratio <= 0.0:
        raise ValueError("v9.6 world-rate scales invalid")
    if rate_event_hold_s <= 0.0:
        raise ValueError("v9.6 world-rate hold must be positive")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.6 world-rate direction continuity invalid")

    p = _v72_stance_pass_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold, approach_window_m,
        pass_margin_base_m, pass_margin_gain_s, min_pass_margin_m, max_pass_margin_m,
        approach_credit_fraction, min_clearance_m, full_clearance_factor_m,
        min_stance_load_share, max_stance_speed_mps, pass_event_hold_s,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    epoch = _v96_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    last_valid = _state("_littlegreen_v96_rate_last_valid", (n, 2), False, torch.bool)
    last_xy = _state("_littlegreen_v96_rate_last_xy", (n, 2, 2), 0.0)
    last_direction = _state("_littlegreen_v96_rate_last_direction", (n, 2, 2), 0.0)
    last_step = _state("_littlegreen_v96_rate_last_step", (n, 2), -1, torch.long)
    last_command = _state("_littlegreen_v96_rate_last_command_mps", (n, 2), 0.0)
    hold = _state("_littlegreen_v96_rate_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v96_rate_value", (n,), 0.0)
    event = _state("_littlegreen_v96_rate_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v96_rate_foot", (n,), -1, torch.long)
    advance_snap = _state("_littlegreen_v96_rate_advance_m", (n,), 0.0)
    elapsed_snap = _state("_littlegreen_v96_rate_elapsed_s", (n,), 0.0)
    rate_snap = _state("_littlegreen_v96_rate_mps", (n,), 0.0)
    ratio_snap = _state("_littlegreen_v96_rate_ratio", (n,), 0.0)
    score_snap = _state("_littlegreen_v96_rate_score", (n,), 0.0)
    command_snap = _state("_littlegreen_v96_rate_command_mps", (n,), 0.0)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v96_rate_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            last_valid[stop] = False
            last_xy[stop] = 0.0
            last_direction[stop] = 0.0
            last_step[stop] = -1
            last_command[stop] = 0.0
            hold[stop] = 0.0
            value[stop] = 0.0

        hand = p["handoff_event"] & (~reset) & moving & (~epoch["changed"])
        if torch.any(hand):
            hid = ids[hand]
            foot = p["handoff_foot"][hand]
            current_xy = k["centers"][hid, foot]
            current_dir = current_direction[hand]
            current_cmd = k["command_norm"][hand]
            prev_valid = last_valid[hid, foot]
            prev_xy = last_xy[hid, foot]
            prev_dir = last_direction[hid, foot]
            prev_step = last_step[hid, foot]
            prev_cmd = last_command[hid, foot]
            direction_ok = torch.sum(prev_dir * current_dir, dim=1) >= float(direction_continuity_cos_min)
            command_ok = torch.abs(prev_cmd - current_cmd) < float(command_change_linear_mps)
            valid = prev_valid & (prev_step >= 0) & direction_ok & command_ok

            elapsed = torch.clamp((float(common_step) - prev_step.float()) * dt, min=dt)
            advance = torch.sum((current_xy - prev_xy) * current_dir, dim=1)
            world_rate = advance / elapsed
            rate_ratio = world_rate / torch.clamp(current_cmd, min=float(command_threshold))
            rate_score = 2.0 * torch.sigmoid(
                (rate_ratio - float(neutral_rate_ratio)) / float(rate_softness_ratio)
            ) - 1.0
            event_value = rate_score * valid.float() * k["viability"][hand]

            if torch.any(valid):
                vid = hid[valid]
                event[vid] = True
                hold[vid] = float(rate_event_hold_s)
                value[vid] = event_value[valid]
                foot_snap[vid] = foot[valid]
                advance_snap[vid] = advance[valid]
                elapsed_snap[vid] = elapsed[valid]
                rate_snap[vid] = world_rate[valid]
                ratio_snap[vid] = rate_ratio[valid]
                score_snap[vid] = rate_score[valid]
                command_snap[vid] = current_cmd[valid]

            # Every successful handoff seeds/updates that same foot's next full-cycle baseline.
            last_valid[hid, foot] = True
            last_xy[hid, foot] = current_xy
            last_direction[hid, foot] = current_dir
            last_step[hid, foot] = common_step
            last_command[hid, foot] = current_cmd

        env._littlegreen_v96_rate_last_common_step = common_step

    env._littlegreen_v96_rate_event = event.detach()
    env._littlegreen_v96_rate_foot = foot_snap.detach()
    env._littlegreen_v96_rate_advance_m = advance_snap.detach()
    env._littlegreen_v96_rate_elapsed_s = elapsed_snap.detach()
    env._littlegreen_v96_rate_mps = rate_snap.detach()
    env._littlegreen_v96_rate_ratio = ratio_snap.detach()
    env._littlegreen_v96_rate_score = score_snap.detach()
    env._littlegreen_v96_rate_command_mps = command_snap.detach()
    return torch.where(hold > 0.0, value, torch.zeros_like(value))

# =============================================================================
# LittleGreen v9.7 dense per-handoff locomotion credit
# =============================================================================
# v9.7 preserves the complete v9.6/v9.5/v6.8 gait-acquisition stack and changes
# only the timing/density of the downstream locomotion economics.  Every *confirmed
# v6.6 support handoff* now immediately reports (1) signed command-relative passage
# and (2) support-frontier WORLD rate.  The joints remain entirely unconstrained.


def _v97_command_epoch_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    command_threshold: float = 0.08,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> dict[str, torch.Tensor]:
    """Return command state plus a one-step pulse when v9.7 measurement memory resets."""
    if command_change_linear_mps <= 0.0 or command_change_yaw_rps <= 0.0:
        raise ValueError("v9.7 command-change thresholds must be positive")

    command = env.command_manager.get_command(command_name)
    n = command.shape[0]
    device = command.device
    common_step = int(getattr(env, "common_step_counter", 0))

    previous = getattr(env, "_littlegreen_v97_epoch_command", None)
    if not isinstance(previous, torch.Tensor) or previous.shape != command.shape or previous.device != device:
        previous = command.clone()
        env._littlegreen_v97_epoch_command = previous
        env._littlegreen_v97_epoch_valid = torch.zeros((n,), device=device, dtype=torch.bool)
    valid = getattr(env, "_littlegreen_v97_epoch_valid")

    changed = getattr(env, "_littlegreen_v97_epoch_changed", None)
    if not isinstance(changed, torch.Tensor) or changed.shape != (n,) or changed.device != device:
        changed = torch.ones((n,), device=device, dtype=torch.bool)
        env._littlegreen_v97_epoch_changed = changed

    last_step = int(getattr(env, "_littlegreen_v97_epoch_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        linear_delta = torch.linalg.vector_norm(command[:, :2] - previous[:, :2], dim=1)
        if command.shape[1] > 2:
            yaw_delta = torch.abs(command[:, 2] - previous[:, 2])
        else:
            yaw_delta = torch.zeros((n,), device=device, dtype=command.dtype)
        previous_moving = torch.linalg.vector_norm(previous[:, :2], dim=1) > float(command_threshold)
        current_moving = torch.linalg.vector_norm(command[:, :2], dim=1) > float(command_threshold)
        changed[:] = (
            (~valid)
            | reset
            | (linear_delta >= float(command_change_linear_mps))
            | (yaw_delta >= float(command_change_yaw_rps))
            | (previous_moving != current_moving)
        )
        previous[:] = command
        valid[:] = True
        env._littlegreen_v97_epoch_last_common_step = common_step

        reset_count = getattr(env, "_littlegreen_v97_epoch_reset_count", None)
        if not isinstance(reset_count, torch.Tensor) or reset_count.shape != (n,) or reset_count.device != device:
            reset_count = torch.zeros((n,), device=device, dtype=torch.long)
        reset_count[:] = reset_count + changed.to(torch.long)
        env._littlegreen_v97_epoch_reset_count = reset_count

    return {
        "command": command,
        "command_norm": torch.linalg.vector_norm(command[:, :2], dim=1),
        "changed": changed,
    }


def _v97_dense_handoff_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    gait_params: dict,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Expose the raw one-step v6.6 handoff pulse with current whole-foot geometry.

    Calling the public v6.6 handoff term with the *same gait parameters* guarantees
    that v9.7 measures the exact support exchange already used by the preserved gait
    chain.  No second touchdown detector or alternative gait state machine is added.
    """
    if not isinstance(gait_params, dict):
        raise ValueError("v9.7 gait_params must be a dict matching the v6.6 support-baton contract")

    # Force/update the canonical v6.6 support-baton state.  Its common-step cache
    # makes this idempotent when the normal support_handoff reward has already run.
    support_handoff_event_v66(
        env=env,
        command_name=command_name,
        sensor_cfg=sensor_cfg,
        asset_cfg=asset_cfg,
        **gait_params,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["command_norm"].shape[0]
    device = k["command_norm"].device
    raw = getattr(
        env,
        "_littlegreen_v66_handoff_event",
        torch.zeros((n, 2), device=device, dtype=torch.bool),
    )
    if raw.shape != (n, 2):
        raise ValueError("v9.7 expects the v6.6 handoff pulse to have shape [num_envs, 2]")

    # Keep an explicit public diagnostic alias so the analyzer can compare v9.7
    # locomotion-event density directly with the preserved v6.6 handoff stream.
    env._littlegreen_v97_dense_handoff_event = raw.detach()
    return {"kin": k, "handoff": raw}


def dense_handoff_bilateral_passage_v97(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    gait_params: dict,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    quality_softness_m: float = 0.025,
    bilateral_mix: float = 0.50,
    event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Give every legitimate support exchange immediate weak-leg-sensitive passage credit.

    The newly supporting foot is compared with the old support foot along the active
    WORLD command direction.  Its current signed score is available on *every* validated v6.3
    mechanical support-takeover handoff.  Once an opposite-foot predecessor exists, half of the event value is
    additionally coupled through a geometric-mean bilateral quality.  Consequently a
    trailing weak leg is negative immediately and also reduces the value of the next
    strong-leg exchange, while no equal-stride, cadence, hip, knee, or ankle target is
    introduced.
    """
    if quality_softness_m <= 0.0 or event_hold_s <= 0.0:
        raise ValueError("v9.7 dense passage scales must be positive")
    if not 0.0 <= bilateral_mix <= 1.0:
        raise ValueError("v9.7 bilateral_mix must be in [0,1]")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.7 passage direction continuity cosine invalid")

    d = _v97_dense_handoff_state(
        env, command_name, sensor_cfg, asset_cfg, gait_params, command_threshold,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = d["kin"]
    epoch = _v97_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    prev_valid = _state("_littlegreen_v97_pass_prev_valid", (n,), False, torch.bool)
    prev_foot = _state("_littlegreen_v97_pass_prev_foot", (n,), -1, torch.long)
    prev_quality = _state("_littlegreen_v97_pass_prev_quality", (n,), 0.0)
    prev_direction = _state("_littlegreen_v97_pass_prev_direction", (n, 2), 0.0)
    hold = _state("_littlegreen_v97_pass_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v97_pass_value", (n,), 0.0)

    event = _state("_littlegreen_v97_pass_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v97_pass_foot", (n,), -1, torch.long)
    margin_snap = _state("_littlegreen_v97_pass_margin_m", (n,), 0.0)
    current_quality_snap = _state("_littlegreen_v97_pass_current_quality", (n,), 0.0)
    current_score_snap = _state("_littlegreen_v97_pass_current_score", (n,), 0.0)
    pair_valid_snap = _state("_littlegreen_v97_pass_pair_valid", (n,), False, torch.bool)
    pair_quality_snap = _state("_littlegreen_v97_pass_pair_quality", (n,), 0.0)
    pair_score_snap = _state("_littlegreen_v97_pass_pair_score", (n,), 0.0)
    dense_score_snap = _state("_littlegreen_v97_pass_dense_score", (n,), 0.0)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v97_pass_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False
        pair_valid_snap[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            prev_valid[stop] = False
            prev_foot[stop] = -1
            prev_quality[stop] = 0.0
            prev_direction[stop] = 0.0
            hold[stop] = 0.0
            value[stop] = 0.0

        raw = d["handoff"] & (~reset).unsqueeze(-1) & moving.unsqueeze(-1)
        exactly_one = torch.sum(raw.to(torch.int32), dim=1) == 1
        dense = exactly_one & (~epoch["changed"])
        if torch.any(dense):
            hid = ids[dense]
            foot = torch.argmax(raw.to(torch.long), dim=1)[dense]
            old = 1 - foot
            cur_dir = current_direction[dense]
            margin = torch.sum((k["centers"][hid, foot] - k["centers"][hid, old]) * cur_dir, dim=1)
            current_quality = torch.sigmoid(margin / float(quality_softness_m))
            current_score = torch.clamp(2.0 * current_quality - 1.0, -1.0, 1.0)

            pv = prev_valid[dense]
            pf = prev_foot[dense]
            pq = prev_quality[dense]
            pd = prev_direction[dense]
            direction_ok = torch.sum(pd * cur_dir, dim=1) >= float(direction_continuity_cos_min)
            pair_valid = pv & (foot != pf) & direction_ok
            pair_quality = torch.sqrt(torch.clamp(pq * current_quality, min=0.0))
            pair_score = torch.clamp(2.0 * pair_quality - 1.0, -1.0, 1.0)
            coupled = (1.0 - float(bilateral_mix)) * current_score + float(bilateral_mix) * pair_score
            dense_score = torch.where(pair_valid, coupled, current_score)
            event_value = dense_score * k["viability"][dense]

            event[hid] = True
            hold[hid] = float(event_hold_s)
            value[hid] = event_value
            foot_snap[hid] = foot
            margin_snap[hid] = margin
            current_quality_snap[hid] = current_quality
            current_score_snap[hid] = current_score
            pair_valid_snap[hid] = pair_valid
            pair_quality_snap[hid] = pair_quality
            pair_score_snap[hid] = pair_score
            dense_score_snap[hid] = dense_score

            prev_valid[dense] = True
            prev_foot[dense] = foot
            prev_quality[dense] = current_quality
            prev_direction[dense] = cur_dir

        env._littlegreen_v97_pass_last_common_step = common_step

    env._littlegreen_v97_pass_event = event.detach()
    env._littlegreen_v97_pass_foot = foot_snap.detach()
    env._littlegreen_v97_pass_margin_m = margin_snap.detach()
    env._littlegreen_v97_pass_current_quality = current_quality_snap.detach()
    env._littlegreen_v97_pass_current_score = current_score_snap.detach()
    env._littlegreen_v97_pass_pair_valid = pair_valid_snap.detach()
    env._littlegreen_v97_pass_pair_quality = pair_quality_snap.detach()
    env._littlegreen_v97_pass_pair_score = pair_score_snap.detach()
    env._littlegreen_v97_pass_dense_score = dense_score_snap.detach()
    return torch.where(hold > 0.0, value, torch.zeros_like(value))


def dense_handoff_commanded_world_rate_v97(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    gait_params: dict,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    neutral_rate_ratio: float = 0.20,
    rate_softness_ratio: float = 0.12,
    event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Score the WORLD support-frontier rate at every consecutive confirmed handoff.

    Unlike v9.6's LEFT->RIGHT->LEFT same-foot cycle, v9.7 compares the newly
    supporting foot with the support frontier captured at the immediately preceding
    legitimate handoff.  Therefore every alternating support exchange after the first
    baseline yields command-normalized rate feedback.  A catch-up foot that remains
    behind is negative immediately; a foot that passes but does so too slowly remains
    below the neutral command ratio.  No stride or cadence is prescribed.
    """
    if not 0.0 <= neutral_rate_ratio < 1.0 or rate_softness_ratio <= 0.0:
        raise ValueError("v9.7 dense world-rate scales invalid")
    if event_hold_s <= 0.0:
        raise ValueError("v9.7 dense world-rate hold must be positive")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.7 dense world-rate direction continuity invalid")

    d = _v97_dense_handoff_state(
        env, command_name, sensor_cfg, asset_cfg, gait_params, command_threshold,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = d["kin"]
    epoch = _v97_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    prev_valid = _state("_littlegreen_v97_rate_prev_valid", (n,), False, torch.bool)
    prev_xy = _state("_littlegreen_v97_rate_prev_xy", (n, 2), 0.0)
    prev_direction = _state("_littlegreen_v97_rate_prev_direction", (n, 2), 0.0)
    prev_step = _state("_littlegreen_v97_rate_prev_step", (n,), -1, torch.long)
    prev_command = _state("_littlegreen_v97_rate_prev_command_mps", (n,), 0.0)
    prev_foot = _state("_littlegreen_v97_rate_prev_foot", (n,), -1, torch.long)
    hold = _state("_littlegreen_v97_rate_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v97_rate_value", (n,), 0.0)

    event = _state("_littlegreen_v97_rate_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v97_rate_foot", (n,), -1, torch.long)
    prev_foot_snap = _state("_littlegreen_v97_rate_previous_foot", (n,), -1, torch.long)
    advance_snap = _state("_littlegreen_v97_rate_advance_m", (n,), 0.0)
    elapsed_snap = _state("_littlegreen_v97_rate_elapsed_s", (n,), 0.0)
    rate_snap = _state("_littlegreen_v97_rate_mps", (n,), 0.0)
    ratio_snap = _state("_littlegreen_v97_rate_ratio", (n,), 0.0)
    score_snap = _state("_littlegreen_v97_rate_score", (n,), 0.0)
    command_snap = _state("_littlegreen_v97_rate_command_mps", (n,), 0.0)
    alternating_snap = _state("_littlegreen_v97_rate_alternating", (n,), False, torch.bool)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v97_rate_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False
        alternating_snap[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            prev_valid[stop] = False
            prev_xy[stop] = 0.0
            prev_direction[stop] = 0.0
            prev_step[stop] = -1
            prev_command[stop] = 0.0
            prev_foot[stop] = -1
            hold[stop] = 0.0
            value[stop] = 0.0

        raw = d["handoff"] & (~reset).unsqueeze(-1) & moving.unsqueeze(-1)
        exactly_one = torch.sum(raw.to(torch.int32), dim=1) == 1
        dense = exactly_one & (~epoch["changed"])
        if torch.any(dense):
            hid = ids[dense]
            foot = torch.argmax(raw.to(torch.long), dim=1)[dense]
            current_xy = k["centers"][hid, foot]
            current_dir = current_direction[dense]
            current_cmd = k["command_norm"][dense]

            pv = prev_valid[dense]
            pxy = prev_xy[dense]
            pdir = prev_direction[dense]
            pstep = prev_step[dense]
            pcmd = prev_command[dense]
            pfoot = prev_foot[dense]
            direction_ok = torch.sum(pdir * current_dir, dim=1) >= float(direction_continuity_cos_min)
            command_ok = torch.abs(pcmd - current_cmd) < float(command_change_linear_mps)
            alternating = pfoot >= 0
            alternating = alternating & (foot != pfoot)
            valid = pv & (pstep >= 0) & direction_ok & command_ok & alternating

            elapsed = torch.clamp((float(common_step) - pstep.float()) * dt, min=dt)
            advance = torch.sum((current_xy - pxy) * current_dir, dim=1)
            world_rate = advance / elapsed
            rate_ratio = world_rate / torch.clamp(current_cmd, min=float(command_threshold))
            rate_score = 2.0 * torch.sigmoid(
                (rate_ratio - float(neutral_rate_ratio)) / float(rate_softness_ratio)
            ) - 1.0
            event_value = rate_score * valid.float() * k["viability"][dense]

            if torch.any(valid):
                vid = hid[valid]
                event[vid] = True
                hold[vid] = float(event_hold_s)
                value[vid] = event_value[valid]
                foot_snap[vid] = foot[valid]
                prev_foot_snap[vid] = pfoot[valid]
                advance_snap[vid] = advance[valid]
                elapsed_snap[vid] = elapsed[valid]
                rate_snap[vid] = world_rate[valid]
                ratio_snap[vid] = rate_ratio[valid]
                score_snap[vid] = rate_score[valid]
                command_snap[vid] = current_cmd[valid]
                alternating_snap[vid] = alternating[valid]

            # Every legitimate handoff becomes the next support-frontier baseline,
            # even if the preceding pair could not be scored (e.g. first in epoch).
            prev_valid[dense] = True
            prev_xy[dense] = current_xy
            prev_direction[dense] = current_dir
            prev_step[dense] = common_step
            prev_command[dense] = current_cmd
            prev_foot[dense] = foot

        env._littlegreen_v97_rate_last_common_step = common_step

    env._littlegreen_v97_rate_event = event.detach()
    env._littlegreen_v97_rate_foot = foot_snap.detach()
    env._littlegreen_v97_rate_previous_foot = prev_foot_snap.detach()
    env._littlegreen_v97_rate_advance_m = advance_snap.detach()
    env._littlegreen_v97_rate_elapsed_s = elapsed_snap.detach()
    env._littlegreen_v97_rate_mps = rate_snap.detach()
    env._littlegreen_v97_rate_ratio = ratio_snap.detach()
    env._littlegreen_v97_rate_score = score_snap.detach()
    env._littlegreen_v97_rate_command_mps = command_snap.detach()
    env._littlegreen_v97_rate_alternating = alternating_snap.detach()
    return torch.where(hold > 0.0, value, torch.zeros_like(value))


# =============================================================================
# LittleGreen v9.8 gait-frequency confirmed-step/support-takeover locomotion credit
# =============================================================================
# Reward arithmetic is identical to v9.7.  Only the event source is re-clocked from
# the restrictive v6.6 baton handoff to the validated v6.3 confirmed-step mechanical
# support-takeover stream that the analyzer observes at physical gait frequency.
def _v98_command_epoch_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    command_threshold: float = 0.08,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> dict[str, torch.Tensor]:
    """Return command state plus a one-step pulse when v9.8 measurement memory resets."""
    if command_change_linear_mps <= 0.0 or command_change_yaw_rps <= 0.0:
        raise ValueError("v9.8 command-change thresholds must be positive")

    command = env.command_manager.get_command(command_name)
    n = command.shape[0]
    device = command.device
    common_step = int(getattr(env, "common_step_counter", 0))

    previous = getattr(env, "_littlegreen_v98_epoch_command", None)
    if not isinstance(previous, torch.Tensor) or previous.shape != command.shape or previous.device != device:
        previous = command.clone()
        env._littlegreen_v98_epoch_command = previous
        env._littlegreen_v98_epoch_valid = torch.zeros((n,), device=device, dtype=torch.bool)
    valid = getattr(env, "_littlegreen_v98_epoch_valid")

    changed = getattr(env, "_littlegreen_v98_epoch_changed", None)
    if not isinstance(changed, torch.Tensor) or changed.shape != (n,) or changed.device != device:
        changed = torch.ones((n,), device=device, dtype=torch.bool)
        env._littlegreen_v98_epoch_changed = changed

    last_step = int(getattr(env, "_littlegreen_v98_epoch_last_common_step", -1))
    if common_step != last_step:
        reset = _v10_episode_reset_mask(env, n, device)
        linear_delta = torch.linalg.vector_norm(command[:, :2] - previous[:, :2], dim=1)
        if command.shape[1] > 2:
            yaw_delta = torch.abs(command[:, 2] - previous[:, 2])
        else:
            yaw_delta = torch.zeros((n,), device=device, dtype=command.dtype)
        previous_moving = torch.linalg.vector_norm(previous[:, :2], dim=1) > float(command_threshold)
        current_moving = torch.linalg.vector_norm(command[:, :2], dim=1) > float(command_threshold)
        changed[:] = (
            (~valid)
            | reset
            | (linear_delta >= float(command_change_linear_mps))
            | (yaw_delta >= float(command_change_yaw_rps))
            | (previous_moving != current_moving)
        )
        previous[:] = command
        valid[:] = True
        env._littlegreen_v98_epoch_last_common_step = common_step

        reset_count = getattr(env, "_littlegreen_v98_epoch_reset_count", None)
        if not isinstance(reset_count, torch.Tensor) or reset_count.shape != (n,) or reset_count.device != device:
            reset_count = torch.zeros((n,), device=device, dtype=torch.long)
        reset_count[:] = reset_count + changed.to(torch.long)
        env._littlegreen_v98_epoch_reset_count = reset_count

    return {
        "command": command,
        "command_norm": torch.linalg.vector_norm(command[:, :2], dim=1),
        "changed": changed,
    }




def _v98_dense_step_support_state(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
) -> dict[str, torch.Tensor]:
    """Expose the validated v6.3 confirmed-step/support-takeover event stream.

    v9.7 mistakenly clocked locomotion economics from the much stricter v6.6
    support-baton handoff pulse.  The v6.3 detector is already fall-neutral: it
    requires whole-foot release, meaningful main+toe clearance, viable landing,
    0.16 s landing confirmation, then mechanical load acceptance by the new foot.
    Its handoff pulse occurs at actual gait frequency in the v9.7 analyzer.

    v9.8 does not alter this detector or the preserved v6.6 gait-acquisition chain;
    it only uses the existing v6.3 mechanical handoff as the clock for passage and
    WORLD-rate economics.
    """
    _directional_confirmed_step_state_v63(
        env=env, command_name=command_name, asset_cfg=asset_cfg, sensor_cfg=sensor_cfg,
        command_threshold=command_threshold,
        min_air_time_s=0.09, min_main_clearance_m=0.010, min_toe_clearance_m=0.010,
        full_progress_m=0.035, min_sequence_progress_m=0.008,
        first_step_multiplier=1.00, opposite_step_multiplier=2.00,
        repeat_same_foot_multiplier=0.10, velocity_bootstrap_fraction=0.35,
        coherence_full_diff_m=0.020, coherence_zero_diff_m=0.060,
        landing_window_s=0.30, immediate_credit_fraction=0.30,
        confirmation_duration_s=0.16, confirmation_min_viability=0.55,
        min_swing_viability=0.45, event_hold_s=0.06,
        takeover_window_s=0.50, takeover_load_start=0.30, takeover_load_full=0.55,
        takeover_com_improvement_full_m=0.050, handoff_load_threshold=0.47,
        handoff_min_viability=0.60, handoff_event_hold_s=0.08,
        opposite_release_window_s=0.45, opposite_release_min_viability=0.45,
        bodies_per_foot=2, full_tilt_deg=full_tilt_deg, zero_tilt_deg=zero_tilt_deg,
        full_height_m=full_height_m, zero_height_m=zero_height_m,
    )
    k = _v67_whole_foot_kinematics(
        env, command_name, sensor_cfg, asset_cfg,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    n = k["command_norm"].shape[0]
    device = k["command_norm"].device
    confirmed = getattr(
        env, "_littlegreen_v63_confirmed_event",
        torch.zeros((n, 2), device=device, dtype=torch.bool),
    )
    handoff = getattr(
        env, "_littlegreen_v63_handoff_event",
        torch.zeros((n, 2), device=device, dtype=torch.bool),
    )
    if confirmed.shape != (n, 2) or handoff.shape != (n, 2):
        raise ValueError("v9.8 expects v6.3 confirmed/handoff pulses shaped [num_envs,2]")
    env._littlegreen_v98_confirmed_step_event = confirmed.detach()
    env._littlegreen_v98_dense_step_support_event = handoff.detach()
    return {"kin": k, "confirmed": confirmed, "handoff": handoff}
def dense_step_support_bilateral_passage_v98(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    quality_softness_m: float = 0.025,
    bilateral_mix: float = 0.50,
    event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Give every legitimate support exchange immediate weak-leg-sensitive passage credit.

    The newly supporting foot is compared with the old support foot along the active
    WORLD command direction.  Its current signed score is available on *every* validated v6.3
    mechanical support-takeover handoff.  Once an opposite-foot predecessor exists, half of the event value is
    additionally coupled through a geometric-mean bilateral quality.  Consequently a
    trailing weak leg is negative immediately and also reduces the value of the next
    strong-leg exchange, while no equal-stride, cadence, hip, knee, or ankle target is
    introduced.
    """
    if quality_softness_m <= 0.0 or event_hold_s <= 0.0:
        raise ValueError("v9.8 dense passage scales must be positive")
    if not 0.0 <= bilateral_mix <= 1.0:
        raise ValueError("v9.8 bilateral_mix must be in [0,1]")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.8 passage direction continuity cosine invalid")

    d = _v98_dense_step_support_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = d["kin"]
    epoch = _v98_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    prev_valid = _state("_littlegreen_v98_pass_prev_valid", (n,), False, torch.bool)
    prev_foot = _state("_littlegreen_v98_pass_prev_foot", (n,), -1, torch.long)
    prev_quality = _state("_littlegreen_v98_pass_prev_quality", (n,), 0.0)
    prev_direction = _state("_littlegreen_v98_pass_prev_direction", (n, 2), 0.0)
    hold = _state("_littlegreen_v98_pass_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v98_pass_value", (n,), 0.0)

    event = _state("_littlegreen_v98_pass_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v98_pass_foot", (n,), -1, torch.long)
    margin_snap = _state("_littlegreen_v98_pass_margin_m", (n,), 0.0)
    current_quality_snap = _state("_littlegreen_v98_pass_current_quality", (n,), 0.0)
    current_score_snap = _state("_littlegreen_v98_pass_current_score", (n,), 0.0)
    pair_valid_snap = _state("_littlegreen_v98_pass_pair_valid", (n,), False, torch.bool)
    pair_quality_snap = _state("_littlegreen_v98_pass_pair_quality", (n,), 0.0)
    pair_score_snap = _state("_littlegreen_v98_pass_pair_score", (n,), 0.0)
    dense_score_snap = _state("_littlegreen_v98_pass_dense_score", (n,), 0.0)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v98_pass_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False
        pair_valid_snap[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            prev_valid[stop] = False
            prev_foot[stop] = -1
            prev_quality[stop] = 0.0
            prev_direction[stop] = 0.0
            hold[stop] = 0.0
            value[stop] = 0.0

        raw = d["handoff"] & (~reset).unsqueeze(-1) & moving.unsqueeze(-1)
        exactly_one = torch.sum(raw.to(torch.int32), dim=1) == 1
        dense = exactly_one & (~epoch["changed"])
        if torch.any(dense):
            hid = ids[dense]
            foot = torch.argmax(raw.to(torch.long), dim=1)[dense]
            old = 1 - foot
            cur_dir = current_direction[dense]
            margin = torch.sum((k["centers"][hid, foot] - k["centers"][hid, old]) * cur_dir, dim=1)
            current_quality = torch.sigmoid(margin / float(quality_softness_m))
            current_score = torch.clamp(2.0 * current_quality - 1.0, -1.0, 1.0)

            pv = prev_valid[dense]
            pf = prev_foot[dense]
            pq = prev_quality[dense]
            pd = prev_direction[dense]
            direction_ok = torch.sum(pd * cur_dir, dim=1) >= float(direction_continuity_cos_min)
            pair_valid = pv & (foot != pf) & direction_ok
            pair_quality = torch.sqrt(torch.clamp(pq * current_quality, min=0.0))
            pair_score = torch.clamp(2.0 * pair_quality - 1.0, -1.0, 1.0)
            coupled = (1.0 - float(bilateral_mix)) * current_score + float(bilateral_mix) * pair_score
            dense_score = torch.where(pair_valid, coupled, current_score)
            event_value = dense_score * k["viability"][dense]

            event[hid] = True
            hold[hid] = float(event_hold_s)
            value[hid] = event_value
            foot_snap[hid] = foot
            margin_snap[hid] = margin
            current_quality_snap[hid] = current_quality
            current_score_snap[hid] = current_score
            pair_valid_snap[hid] = pair_valid
            pair_quality_snap[hid] = pair_quality
            pair_score_snap[hid] = pair_score
            dense_score_snap[hid] = dense_score

            prev_valid[dense] = True
            prev_foot[dense] = foot
            prev_quality[dense] = current_quality
            prev_direction[dense] = cur_dir

        env._littlegreen_v98_pass_last_common_step = common_step

    env._littlegreen_v98_pass_event = event.detach()
    env._littlegreen_v98_pass_foot = foot_snap.detach()
    env._littlegreen_v98_pass_margin_m = margin_snap.detach()
    env._littlegreen_v98_pass_current_quality = current_quality_snap.detach()
    env._littlegreen_v98_pass_current_score = current_score_snap.detach()
    env._littlegreen_v98_pass_pair_valid = pair_valid_snap.detach()
    env._littlegreen_v98_pass_pair_quality = pair_quality_snap.detach()
    env._littlegreen_v98_pass_pair_score = pair_score_snap.detach()
    env._littlegreen_v98_pass_dense_score = dense_score_snap.detach()
    return torch.where(hold > 0.0, value, torch.zeros_like(value))


def dense_step_support_commanded_world_rate_v98(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    neutral_rate_ratio: float = 0.20,
    rate_softness_ratio: float = 0.12,
    event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Score the WORLD support-frontier rate at every consecutive confirmed-step support-takeover handoff.

    Using the same signed rate arithmetic as v9.7, v9.8 compares the newly
    supporting foot with the support frontier captured at the immediately preceding
    legitimate handoff; only the event clock changes from the restrictive v6.6 baton
    handoff to the validated v6.3 mechanical support-takeover stream.  Therefore every alternating support exchange after the first
    baseline yields command-normalized rate feedback.  A catch-up foot that remains
    behind is negative immediately; a foot that passes but does so too slowly remains
    below the neutral command ratio.  No stride or cadence is prescribed.
    """
    if not 0.0 <= neutral_rate_ratio < 1.0 or rate_softness_ratio <= 0.0:
        raise ValueError("v9.8 dense world-rate scales invalid")
    if event_hold_s <= 0.0:
        raise ValueError("v9.8 dense world-rate hold must be positive")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v9.8 dense world-rate direction continuity invalid")

    d = _v98_dense_step_support_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = d["kin"]
    epoch = _v98_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    prev_valid = _state("_littlegreen_v98_rate_prev_valid", (n,), False, torch.bool)
    prev_xy = _state("_littlegreen_v98_rate_prev_xy", (n, 2), 0.0)
    prev_direction = _state("_littlegreen_v98_rate_prev_direction", (n, 2), 0.0)
    prev_step = _state("_littlegreen_v98_rate_prev_step", (n,), -1, torch.long)
    prev_command = _state("_littlegreen_v98_rate_prev_command_mps", (n,), 0.0)
    prev_foot = _state("_littlegreen_v98_rate_prev_foot", (n,), -1, torch.long)
    hold = _state("_littlegreen_v98_rate_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v98_rate_value", (n,), 0.0)

    event = _state("_littlegreen_v98_rate_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v98_rate_foot", (n,), -1, torch.long)
    prev_foot_snap = _state("_littlegreen_v98_rate_previous_foot", (n,), -1, torch.long)
    advance_snap = _state("_littlegreen_v98_rate_advance_m", (n,), 0.0)
    elapsed_snap = _state("_littlegreen_v98_rate_elapsed_s", (n,), 0.0)
    rate_snap = _state("_littlegreen_v98_rate_mps", (n,), 0.0)
    ratio_snap = _state("_littlegreen_v98_rate_ratio", (n,), 0.0)
    score_snap = _state("_littlegreen_v98_rate_score", (n,), 0.0)
    command_snap = _state("_littlegreen_v98_rate_command_mps", (n,), 0.0)
    alternating_snap = _state("_littlegreen_v98_rate_alternating", (n,), False, torch.bool)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v98_rate_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False
        alternating_snap[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            prev_valid[stop] = False
            prev_xy[stop] = 0.0
            prev_direction[stop] = 0.0
            prev_step[stop] = -1
            prev_command[stop] = 0.0
            prev_foot[stop] = -1
            hold[stop] = 0.0
            value[stop] = 0.0

        raw = d["handoff"] & (~reset).unsqueeze(-1) & moving.unsqueeze(-1)
        exactly_one = torch.sum(raw.to(torch.int32), dim=1) == 1
        dense = exactly_one & (~epoch["changed"])
        if torch.any(dense):
            hid = ids[dense]
            foot = torch.argmax(raw.to(torch.long), dim=1)[dense]
            current_xy = k["centers"][hid, foot]
            current_dir = current_direction[dense]
            current_cmd = k["command_norm"][dense]

            pv = prev_valid[dense]
            pxy = prev_xy[dense]
            pdir = prev_direction[dense]
            pstep = prev_step[dense]
            pcmd = prev_command[dense]
            pfoot = prev_foot[dense]
            direction_ok = torch.sum(pdir * current_dir, dim=1) >= float(direction_continuity_cos_min)
            command_ok = torch.abs(pcmd - current_cmd) < float(command_change_linear_mps)
            alternating = pfoot >= 0
            alternating = alternating & (foot != pfoot)
            valid = pv & (pstep >= 0) & direction_ok & command_ok & alternating

            elapsed = torch.clamp((float(common_step) - pstep.float()) * dt, min=dt)
            advance = torch.sum((current_xy - pxy) * current_dir, dim=1)
            world_rate = advance / elapsed
            rate_ratio = world_rate / torch.clamp(current_cmd, min=float(command_threshold))
            rate_score = 2.0 * torch.sigmoid(
                (rate_ratio - float(neutral_rate_ratio)) / float(rate_softness_ratio)
            ) - 1.0
            event_value = rate_score * valid.float() * k["viability"][dense]

            if torch.any(valid):
                vid = hid[valid]
                event[vid] = True
                hold[vid] = float(event_hold_s)
                value[vid] = event_value[valid]
                foot_snap[vid] = foot[valid]
                prev_foot_snap[vid] = pfoot[valid]
                advance_snap[vid] = advance[valid]
                elapsed_snap[vid] = elapsed[valid]
                rate_snap[vid] = world_rate[valid]
                ratio_snap[vid] = rate_ratio[valid]
                score_snap[vid] = rate_score[valid]
                command_snap[vid] = current_cmd[valid]
                alternating_snap[vid] = alternating[valid]

            # Every legitimate handoff becomes the next support-frontier baseline,
            # even if the preceding pair could not be scored (e.g. first in epoch).
            prev_valid[dense] = True
            prev_xy[dense] = current_xy
            prev_direction[dense] = current_dir
            prev_step[dense] = common_step
            prev_command[dense] = current_cmd
            prev_foot[dense] = foot

        env._littlegreen_v98_rate_last_common_step = common_step

    env._littlegreen_v98_rate_event = event.detach()
    env._littlegreen_v98_rate_foot = foot_snap.detach()
    env._littlegreen_v98_rate_previous_foot = prev_foot_snap.detach()
    env._littlegreen_v98_rate_advance_m = advance_snap.detach()
    env._littlegreen_v98_rate_elapsed_s = elapsed_snap.detach()
    env._littlegreen_v98_rate_mps = rate_snap.detach()
    env._littlegreen_v98_rate_ratio = ratio_snap.detach()
    env._littlegreen_v98_rate_score = score_snap.detach()
    env._littlegreen_v98_rate_command_mps = command_snap.detach()
    env._littlegreen_v98_rate_alternating = alternating_snap.detach()
    return torch.where(hold > 0.0, value, torch.zeros_like(value))


# =============================================================================
# LittleGreen v10.1 bilateral / pair-sensitive dense WORLD-rate economics
# =============================================================================
def dense_step_support_bilateral_commanded_world_rate_v101(
    env: ManagerBasedRLEnv,
    command_name: str,
    sensor_cfg: SceneEntityCfg,
    asset_cfg: SceneEntityCfg,
    command_threshold: float = 0.08,
    full_tilt_deg: float = 25.0,
    zero_tilt_deg: float = 55.0,
    full_height_m: float = 0.400,
    zero_height_m: float = 0.340,
    direction_continuity_cos_min: float = 0.60,
    neutral_rate_ratio: float = 0.20,
    rate_softness_ratio: float = 0.12,
    bilateral_mix: float = 0.50,
    event_hold_s: float = 0.06,
    command_change_linear_mps: float = 0.015,
    command_change_yaw_rps: float = 0.020,
) -> torch.Tensor:
    """Make dense commanded WORLD-rate feedback bilateral without changing its arithmetic.

    The current support exchange is scored exactly as in v9.8/v10.0:
    WORLD support-frontier rate divided by commanded planar speed is passed through
    the same signed sigmoid with the same 20% neutral point and 0.12 softness.

    v10.1 additionally remembers the previous *valid opposite-leg* rate quality.
    Once both legs have contributed a valid exchange in the current command epoch,
    their qualities are coupled with a geometric mean.  The returned event score is
    a configurable blend of the current per-step score and that bilateral pair score.
    With the default 50% mix, a strong propulsion leg can no longer fully compensate
    for a catch-up/backward opposite leg, while the first valid exchange in an epoch
    still receives its ordinary v10.0 score.  No cadence, stride, phase, joint-angle,
    or left/right equality target is introduced.
    """
    if not 0.0 <= neutral_rate_ratio < 1.0 or rate_softness_ratio <= 0.0:
        raise ValueError("v10.1 bilateral world-rate scales invalid")
    if not 0.0 <= bilateral_mix <= 1.0:
        raise ValueError("v10.1 bilateral world-rate mix must be in [0,1]")
    if event_hold_s <= 0.0:
        raise ValueError("v10.1 bilateral world-rate hold must be positive")
    if not -1.0 <= direction_continuity_cos_min <= 1.0:
        raise ValueError("v10.1 bilateral world-rate direction continuity invalid")

    d = _v98_dense_step_support_state(
        env, command_name, sensor_cfg, asset_cfg, command_threshold,
        full_tilt_deg, zero_tilt_deg, full_height_m, zero_height_m,
    )
    k = d["kin"]
    epoch = _v98_command_epoch_state(
        env, command_name, command_threshold,
        command_change_linear_mps, command_change_yaw_rps,
    )
    n = k["command_norm"].shape[0]
    device, dtype = k["command_norm"].device, k["command_norm"].dtype
    ids = torch.arange(n, device=device)
    dt = float(getattr(env, "step_dt", 0.02))

    def _state(name: str, shape, default, tdtype=None):
        use_dtype = tdtype if tdtype is not None else dtype
        value = getattr(env, name, None)
        if not isinstance(value, torch.Tensor) or tuple(value.shape) != tuple(shape) or value.device != device:
            value = torch.full(shape, default, device=device, dtype=use_dtype)
            setattr(env, name, value)
        return value

    # Immediate support-frontier baseline (same measurement as v9.8/v10.0).
    prev_valid = _state("_littlegreen_v101_rate_prev_valid", (n,), False, torch.bool)
    prev_xy = _state("_littlegreen_v101_rate_prev_xy", (n, 2), 0.0)
    prev_direction = _state("_littlegreen_v101_rate_prev_direction", (n, 2), 0.0)
    prev_step = _state("_littlegreen_v101_rate_prev_step", (n,), -1, torch.long)
    prev_command = _state("_littlegreen_v101_rate_prev_command_mps", (n,), 0.0)
    prev_foot = _state("_littlegreen_v101_rate_prev_foot", (n,), -1, torch.long)

    # Previous *valid rate event* for bilateral pair coupling.
    pair_prev_valid = _state("_littlegreen_v101_rate_pair_prev_valid", (n,), False, torch.bool)
    pair_prev_foot = _state("_littlegreen_v101_rate_pair_prev_foot", (n,), -1, torch.long)
    pair_prev_quality = _state("_littlegreen_v101_rate_pair_prev_quality", (n,), 0.0)

    hold = _state("_littlegreen_v101_rate_hold_s", (n,), 0.0)
    value = _state("_littlegreen_v101_rate_value", (n,), 0.0)

    # Diagnostic snapshots.
    event = _state("_littlegreen_v101_rate_event", (n,), False, torch.bool)
    foot_snap = _state("_littlegreen_v101_rate_foot", (n,), -1, torch.long)
    prev_foot_snap = _state("_littlegreen_v101_rate_previous_foot", (n,), -1, torch.long)
    advance_snap = _state("_littlegreen_v101_rate_advance_m", (n,), 0.0)
    elapsed_snap = _state("_littlegreen_v101_rate_elapsed_s", (n,), 0.0)
    rate_snap = _state("_littlegreen_v101_rate_mps", (n,), 0.0)
    ratio_snap = _state("_littlegreen_v101_rate_ratio", (n,), 0.0)
    current_quality_snap = _state("_littlegreen_v101_rate_current_quality", (n,), 0.0)
    current_score_snap = _state("_littlegreen_v101_rate_current_score", (n,), 0.0)
    pair_valid_snap = _state("_littlegreen_v101_rate_pair_valid", (n,), False, torch.bool)
    pair_quality_snap = _state("_littlegreen_v101_rate_pair_quality", (n,), 0.0)
    pair_score_snap = _state("_littlegreen_v101_rate_pair_score", (n,), 0.0)
    dense_score_snap = _state("_littlegreen_v101_rate_dense_score", (n,), 0.0)
    command_snap = _state("_littlegreen_v101_rate_command_mps", (n,), 0.0)
    alternating_snap = _state("_littlegreen_v101_rate_alternating", (n,), False, torch.bool)

    current_direction = k["command_dir_world"]
    common_step = int(getattr(env, "common_step_counter", 0))
    last_common = int(getattr(env, "_littlegreen_v101_rate_last_common_step", -1))
    if common_step != last_common:
        reset = _v10_episode_reset_mask(env, n, device)
        moving = k["command_norm"] > float(command_threshold)
        hold[:] = torch.clamp(hold - dt, min=0.0)
        value[:] = torch.where(hold > 0.0, value, torch.zeros_like(value))
        event[:] = False
        alternating_snap[:] = False
        pair_valid_snap[:] = False

        stop = reset | (~moving) | epoch["changed"]
        if torch.any(stop):
            prev_valid[stop] = False
            prev_xy[stop] = 0.0
            prev_direction[stop] = 0.0
            prev_step[stop] = -1
            prev_command[stop] = 0.0
            prev_foot[stop] = -1
            pair_prev_valid[stop] = False
            pair_prev_foot[stop] = -1
            pair_prev_quality[stop] = 0.0
            hold[stop] = 0.0
            value[stop] = 0.0

        raw = d["handoff"] & (~reset).unsqueeze(-1) & moving.unsqueeze(-1)
        exactly_one = torch.sum(raw.to(torch.int32), dim=1) == 1
        dense = exactly_one & (~epoch["changed"])
        if torch.any(dense):
            hid = ids[dense]
            foot = torch.argmax(raw.to(torch.long), dim=1)[dense]
            current_xy = k["centers"][hid, foot]
            current_dir = current_direction[dense]
            current_cmd = k["command_norm"][dense]

            pv = prev_valid[dense]
            pxy = prev_xy[dense]
            pdir = prev_direction[dense]
            pstep = prev_step[dense]
            pcmd = prev_command[dense]
            pfoot = prev_foot[dense]
            direction_ok = torch.sum(pdir * current_dir, dim=1) >= float(direction_continuity_cos_min)
            command_ok = torch.abs(pcmd - current_cmd) < float(command_change_linear_mps)
            alternating = (pfoot >= 0) & (foot != pfoot)
            valid = pv & (pstep >= 0) & direction_ok & command_ok & alternating

            elapsed = torch.clamp((float(common_step) - pstep.float()) * dt, min=dt)
            advance = torch.sum((current_xy - pxy) * current_dir, dim=1)
            world_rate = advance / elapsed
            rate_ratio = world_rate / torch.clamp(current_cmd, min=float(command_threshold))
            current_quality = torch.sigmoid(
                (rate_ratio - float(neutral_rate_ratio)) / float(rate_softness_ratio)
            )
            current_score = torch.clamp(2.0 * current_quality - 1.0, -1.0, 1.0)

            ppv = pair_prev_valid[dense]
            ppf = pair_prev_foot[dense]
            ppq = pair_prev_quality[dense]
            pair_valid = valid & ppv & (foot != ppf)
            pair_quality = torch.sqrt(torch.clamp(ppq * current_quality, min=0.0))
            pair_score = torch.clamp(2.0 * pair_quality - 1.0, -1.0, 1.0)
            coupled_score = (1.0 - float(bilateral_mix)) * current_score + float(bilateral_mix) * pair_score
            dense_score = torch.where(pair_valid, coupled_score, current_score)
            event_value = dense_score * valid.float() * k["viability"][dense]

            if torch.any(valid):
                vid = hid[valid]
                event[vid] = True
                hold[vid] = float(event_hold_s)
                value[vid] = event_value[valid]
                foot_snap[vid] = foot[valid]
                prev_foot_snap[vid] = pfoot[valid]
                advance_snap[vid] = advance[valid]
                elapsed_snap[vid] = elapsed[valid]
                rate_snap[vid] = world_rate[valid]
                ratio_snap[vid] = rate_ratio[valid]
                current_quality_snap[vid] = current_quality[valid]
                current_score_snap[vid] = current_score[valid]
                pair_valid_snap[vid] = pair_valid[valid]
                pair_quality_snap[vid] = pair_quality[valid]
                pair_score_snap[vid] = pair_score[valid]
                dense_score_snap[vid] = dense_score[valid]
                command_snap[vid] = current_cmd[valid]
                alternating_snap[vid] = alternating[valid]

                # A valid current rate event becomes the opposite-leg predecessor
                # for the next event.  This memory is reset on command epoch/reset.
                pair_prev_valid[vid] = True
                pair_prev_foot[vid] = foot[valid]
                pair_prev_quality[vid] = current_quality[valid]

            # Every legitimate handoff becomes the next support-frontier baseline,
            # exactly as in the v9.8/v10.0 rate function.
            prev_valid[dense] = True
            prev_xy[dense] = current_xy
            prev_direction[dense] = current_dir
            prev_step[dense] = common_step
            prev_command[dense] = current_cmd
            prev_foot[dense] = foot

        env._littlegreen_v101_rate_last_common_step = common_step

    # v10.1 diagnostics.
    env._littlegreen_v101_rate_event = event.detach()
    env._littlegreen_v101_rate_foot = foot_snap.detach()
    env._littlegreen_v101_rate_previous_foot = prev_foot_snap.detach()
    env._littlegreen_v101_rate_advance_m = advance_snap.detach()
    env._littlegreen_v101_rate_elapsed_s = elapsed_snap.detach()
    env._littlegreen_v101_rate_mps = rate_snap.detach()
    env._littlegreen_v101_rate_ratio = ratio_snap.detach()
    env._littlegreen_v101_rate_current_quality = current_quality_snap.detach()
    env._littlegreen_v101_rate_current_score = current_score_snap.detach()
    env._littlegreen_v101_rate_pair_valid = pair_valid_snap.detach()
    env._littlegreen_v101_rate_pair_quality = pair_quality_snap.detach()
    env._littlegreen_v101_rate_pair_score = pair_score_snap.detach()
    env._littlegreen_v101_rate_dense_score = dense_score_snap.detach()
    env._littlegreen_v101_rate_command_mps = command_snap.detach()
    env._littlegreen_v101_rate_alternating = alternating_snap.detach()

    # Preserve the long-standing v9.8 diagnostic names for tooling that only needs
    # per-exchange kinematics.  ``_rate_score`` remains the uncoupled current score;
    # v10.1 pair-sensitive score is exposed explicitly as ``_v101_rate_dense_score``.
    env._littlegreen_v98_rate_event = event.detach()
    env._littlegreen_v98_rate_foot = foot_snap.detach()
    env._littlegreen_v98_rate_previous_foot = prev_foot_snap.detach()
    env._littlegreen_v98_rate_advance_m = advance_snap.detach()
    env._littlegreen_v98_rate_elapsed_s = elapsed_snap.detach()
    env._littlegreen_v98_rate_mps = rate_snap.detach()
    env._littlegreen_v98_rate_ratio = ratio_snap.detach()
    env._littlegreen_v98_rate_score = current_score_snap.detach()
    env._littlegreen_v98_rate_command_mps = command_snap.detach()
    env._littlegreen_v98_rate_alternating = alternating_snap.detach()

    return torch.where(hold > 0.0, value, torch.zeros_like(value))
